test('parseDice — reroll rK parses and validates its combinations', () => {
  assert.equal(c.parseDice('4d6r1')[0].reroll, 1);
  const t = c.parseDice('4d6r1kh3')[0];           // canonical: reroll then keep
  assert.equal(t.reroll, 1); assert.equal(t.keepMode, 'kh'); assert.equal(t.keepCount, 3);
  assert.equal(c.parseDice('4d6r1>=4'), null);     // reroll + success pool → null
  assert.equal(c.parseDice('4dFr1'), null);        // reroll + Fate → null
  assert.equal(c.parseDice('4d6!r1'), null);       // reroll + exploding → null (v1)
  assert.equal(c.parseDice('4d6r0'), null);        // threshold < 1 → null
  assert.equal(c.parseDice('4d6r6'), null);        // threshold ≥ sides → null
});

test('rollParsed — reroll replaces a die ≤K once, keeping the new value', () => {
  c.seedSequence([0, 0.9, 0.5, 0.5, 0.5]); // die0: 1→reroll→6; dice 1–3: 4,4,4
  try {
    const res = c.rollParsed(c.parseDice('4d6r1'));
    assert.equal(res.total, 18);                   // 6+4+4+4 (the 1 was rerolled away)
    assert.deepEqual(host(res.parts[0].rolls), [[6], [4], [4], [4]]);
    assert.deepEqual(host(res.parts[0].rerolledFrom), [1, null, null, null]);
    assert.equal(res.parts[0].reroll, 1);
  } finally { c.resetRandom(); }
});

test('rollParsed — reroll composes with keep-high (4d6r1kh3)', () => {
  c.seedSequence([0, 0.9, 0.5, 0.5, 0.5]); // reroll die0 (1→6) → [6,4,4,4]; keep top 3
  try {
    assert.equal(c.rollParsed(c.parseDice('4d6r1kh3')).total, 14); // 6+4+4
  } finally { c.resetRandom(); }
});

test('rollParsed — total stays within bounds, with the exact min and max pinned', () => {
  // Deterministic boundary pins (seeded), instead of looping against the live RNG: all dice
  // rolling their lowest face → the min (3×1+2 = 5), highest face → the max (3×6+2 = 20).
  try {
    c.seedSequence([0]);          // Math.random → 0 → every d6 lands on 1
    assert.equal(c.rollParsed(c.parseDice('3d6+2')).total, 5, '3d6+2 minimum');
    c.seedSequence([0.999999]);   // → every d6 lands on 6
    assert.equal(c.rollParsed(c.parseDice('3d6+2')).total, 20, '3d6+2 maximum');
  } finally {
    c.resetRandom();
  }
  // and the bounds property holds across seeded mid values
  for (const r of [0.1, 0.3, 0.5, 0.7, 0.9]) {
    c.seedSequence([r]);
    const total = c.rollParsed(c.parseDice('3d6+2')).total;
    assert.ok(total >= 5 && total <= 20, `3d6+2 out of range: ${total}`);
  }
  c.resetRandom();
});

// ── math evaluator ─────────────────────────────────────────────────────────
test('evalMath — precedence, associativity, operators', () => {
  assert.equal(c.evalMath('2+3*4'), 14);
  assert.equal(c.evalMath('(2+3)*4'), 20);
  assert.equal(c.evalMath('2^3^2'), 512); // right-associative
  assert.equal(c.evalMath('10%3'), 1);
});

test('evalMath — functions, constants, variables', () => {
  assert.equal(c.evalMath('sqrt(16)'), 4);
  assert.equal(c.evalMath('min(3,5,1)'), 1);
  assert.equal(c.evalMath('max(2,9)'), 9);
  assert.equal(c.evalMath('log(100)'), 2);
  assert.equal(c.evalMath('ln(e)'), 1);
  assert.equal(c.evalMath('x*2', { x: 5 }), 10);
});

test('evalMath — comparisons and ternary return 0/1', () => {
  assert.equal(c.evalMath('3>2 ? 10 : 20'), 10);
  assert.equal(c.evalMath('3>=3'), 1);
  assert.equal(c.evalMath('1==2'), 0);
  assert.equal(c.evalMath('1!=2'), 1);
});

test('evalMath — division by zero: Infinity is valid, NaN is null', () => {
  assert.equal(c.evalMath('1/0'), Infinity);
  assert.equal(c.evalMath('0/0'), null);
});

test('evalMath — malformed input returns null (callers branch on null)', () => {
  assert.equal(c.evalMath(''), null);
  assert.equal(c.evalMath('1+'), null);
  assert.equal(c.evalMath('2+2x'), null); // unconsumed trailing token
});

test('evalMath — and/or/not: 0/1 logic over nonzero-is-true operands (#539)', () => {
  assert.equal(c.evalMath('and(1,1)'), 1);
  assert.equal(c.evalMath('and(1,0)'), 0);
  assert.equal(c.evalMath('or(0,0)'), 0);
  assert.equal(c.evalMath('or(0,2)'), 1);
  assert.equal(c.evalMath('not(0)'), 1);
  assert.equal(c.evalMath('not(3)'), 0);
  assert.equal(c.evalMath('not(-2)'), 0);            // any nonzero is true, sign irrelevant
  // variadic like min/max
  assert.equal(c.evalMath('and(1,2,3)'), 1);
  assert.equal(c.evalMath('and(1,0,3)'), 0);
  assert.equal(c.evalMath('or(0,0,5)'), 1);
  // composition with comparisons, ternary, if(), and variables
  assert.equal(c.evalMath('and(2>1, 3<5)'), 1);
  assert.equal(c.evalMath('and(a>1, b>1)', { a: 2, b: 3 }), 1);
  assert.equal(c.evalMath('or(a>9, b>9)', { a: 2, b: 3 }), 0);
  assert.equal(c.evalMath('if(and(x>0, y>0), 7, 9)', { x: 1, y: 2 }), 7);
  assert.equal(c.evalMath('not(x==5)', { x: 5 }), 0);
});

test('evalMath — and/or/not: arity errors and NaN operands fail to null (#539)', () => {
  assert.equal(c.evalMath('and(1)'), null);          // < 2 args, like min/max
  assert.equal(c.evalMath('or(1)'), null);
  assert.equal(c.evalMath('and()'), null);
  assert.equal(c.evalMath('not()'), null);           // not is strictly unary
  assert.equal(c.evalMath('not(1,2)'), null);
  // a NaN operand must fail the whole test, never read as a false/true verdict
  assert.equal(c.evalMath('and(sqrt(-1), 1)'), null);
  assert.equal(c.evalMath('or(sqrt(-1), 1)'), null);
  assert.equal(c.evalMath('not(sqrt(-1))'), null);
  // an unknown name inside still fails the expression (existing contract)
  assert.equal(c.evalMath('and(nope>1, 1)'), null);
});

test('evalCheck — a compound and(…) check passes the comparison gate and verdicts correctly (#539)', () => {
  const node = { text: 'x', props: [{ key: 'check', val: 'and(sum(cost) <= 10, count(cost) >= 2)' }],
    children: [
      { text: 'a', props: [{ key: 'cost', val: '4' }], children: [] },
      { text: 'b', props: [{ key: 'cost', val: '5' }], children: [] },
    ] };
  assert.equal(c.evalCheck(node, {}), 'pass');
  node.children[1].props[0].val = '9';               // sum 13 > 10 → the and() fails
  assert.equal(c.evalCheck(node, {}), 'fail');
  // a compound with no comparison anywhere is still not a test (P4 gate unchanged)
  const bare = { text: 'x', props: [{ key: 'check', val: 'and(1, 2)' }], children: [] };
  assert.equal(c.evalCheck(bare, {}), 'error');
});

// #1195: checkQuery extracts the search query embedded in a check, so a FAILING query-check can reveal
// the points it flags. Reuses the SAME two patterns expandAggExpr substitutes.
test('#1195 checkQuery: extracts the embedded query, scope and reducer, null for a pure-numeric check', () => {
  // Field-by-field, not deepEqual: a load-cores object lives in another realm, so its prototype differs
  // and deepStrictEqual reports "same structure but not reference-equal".
  const cq = (e, q, s, f) => { const r = c.checkQuery(e); assert.ok(r, `${e} → non-null`);
    assert.equal(r.query, q); assert.equal(r.scope, s); assert.equal(r.fn, f); };
  cq('count("#claim -has:footnote") == 0', '#claim -has:footnote', 'subtree', 'count');
  cq('sum("is:task", cost) <= budget', 'is:task', 'subtree', 'sum');
  cq('avg("#risk", severity) < 3', '#risk', 'subtree', 'avg');
  // wideners
  assert.equal(c.checkQuery('count("x", document) == 0').scope, 'document');
  assert.equal(c.checkQuery('count("x", doc) == 0').scope, 'document');
  assert.equal(c.checkQuery('count("x", folder) == 0').scope, 'folder');
  // pure-numeric checks (no quoted arg) → null, so the affordance never shows on them
  assert.equal(c.checkQuery('sum(cost) <= budget'), null, 'a bare child-prop rollup is not a query');
  assert.equal(c.checkQuery('count(children) == 0'), null, 'bare count(identifier) is not a query');
  assert.equal(c.checkQuery('hp > 10'), null);
  assert.equal(c.checkQuery(''), null);
  assert.equal(c.checkQuery(null), null);
  // multiple embedded queries → the first in source order (min-index across both regexes)
  assert.equal(c.checkQuery('count("a") + count("b") == 0').query, 'a', 'first count wins');
  assert.equal(c.checkQuery('sum("s", c) > count("t")').query, 's', 'the earliest in source order wins across reducers');
  // an empty query is returned as-is (the call site guards it, nothing to reveal)
  assert.equal(c.checkQuery('count("") == 0').query, '');
});

test('#1195 checkQuery stays in sync with expandAggExpr (same query patterns)', () => {
  // The extractor must read exactly what expandAggExpr substitutes, or the reveal would target a
  // different set than the pill counted. Pin the shared regex source in BOTH function bodies.
  const cq = fnBody(_src, 'checkQuery');
  const ax = fnBody(_src, 'expandAggExpr');
  const countPat = '\\bcount\\s*\\(\\s*"([^"]*)"';
  const reducePat = '(sum|avg|min|max)\\s*\\(\\s*"([^"]*)"';
  assert.ok(cq.includes(countPat) && ax.includes(countPat), 'both use the count("query") pattern');
  assert.ok(cq.includes(reducePat) && ax.includes(reducePat), 'both use the reduce("query") pattern');
});

test('evalMath — names colliding with Object.prototype fail to null, not the inherited member', () => {
  // On plain-object tables `'constructor' in MATH_CONSTS` was true via the prototype, so
  // `constructor*2` resolved to the Object function (NaN) and `constructor(5)`
  // dispatched it as a unary FN1. Both must be unknown names → null.
  assert.equal(c.evalMath('constructor*2', {}), null);
  assert.equal(c.evalMath('constructor(5)', {}), null);
  // …but a DECLARED variable with that name works (resolved by collectVars)
  assert.equal(c.evalMath('constructor*2', { constructor: 5 }), 10);
});

// ── markov ─────────────────────────────────────────────────────────────────
test('parseMarkov — declaration order and weighted targets', () => {
  const p = c.parseMarkov('A -> B 2, C 1');
  assert.deepEqual(host(p.order), ['A', 'B', 'C']);
  assert.deepEqual(host(p.trans.A), [{ to: 'B', w: 2 }, { to: 'C', w: 1 }]);
});

test('walkMarkov — stops early at a terminal state', () => {
  const p = c.parseMarkov('A -> B\nB -> C'); // C has no outgoing rule
  assert.deepEqual(host(c.walkMarkov(p, 'A', 5)), ['A', 'B', 'C']);
});

test('parseMarkov — an empty RHS declares a terminal, not a dead chain (B4)', () => {
  const p = c.parseMarkov('a -> b\nb ->'); // `b ->` registers b as a known terminal
  assert.notEqual(p, null);                // the whole chain stays valid (was: null)
  assert.deepEqual(host(p.order), ['a', 'b']);
  assert.ok(!p.trans.b || !p.trans.b.length, 'b has no outgoing transitions');
  assert.deepEqual(host(c.walkMarkov(p, 'a', 5)), ['a', 'b']); // walk ends at the terminal
  assert.deepEqual(host(c.walkMarkov(p, 'b', 5)), ['b']);      // starting at the terminal stays put
  // a missing FROM side is still rejected (the guard above the RHS check is unchanged)
  assert.equal(c.parseMarkov('-> b'), null);
});

// ── typed inline markov: {markov: a→b, b→c} ─────────────────────────────────
test('markovParts — sniffs a typed markov body, comma transitions → newline def', () => {
  assert.deepEqual(host(c.markovParts('markov: a→b, b→c')), { def: 'a→b\nb→c' });
  assert.deepEqual(host(c.markovParts('markov: a->b, b->a')), { def: 'a->b\nb->a' }); // ascii arrow too
  // weighted targets survive
  assert.deepEqual(host(c.markovParts('markov: sun→rain, sun→sun 2')), { def: 'sun→rain\nsun→sun 2' });
});
test('markovParts — a comma fragment with no arrow joins the previous transition', () => {
  // `a→b, c` = from a, two targets b and c (the second fragment has no arrow)
  assert.deepEqual(host(c.markovParts('markov: a→b, c, b→a')), { def: 'a→b, c\nb→a' });
});
test('markovParts — NOT a markov body (no false positives)', () => {
  assert.equal(c.markovParts('a | b'), null);            // alternation
  assert.equal(c.markovParts('x > 1: a | b'), null);     // conditional
  assert.equal(c.markovParts('shuffle: a | b'), null);   // sequence
  assert.equal(c.markovParts('weapon: sword | axe'), null); // a rule line
  assert.equal(c.markovParts('markov:'), null);          // empty body
  assert.equal(c.markovParts('markov: not an arrow'), null); // no valid transition
});
test('classifyBraceBody / braceTypeLabel — a typed markov is a valid markov artifact', () => {
  assert.equal(c.classifyBraceBody('markov: a→b, b→c', {}, {}), 'artifact');
  assert.deepEqual(host(c.braceTypeLabel('markov: a→b, b→c', {}, {})), ['markov', null]);
});
test('braceAttemptReason — explains why an INVALID {…} did not become a pill (the display cue)', () => {
  // Only ever called on bodies classifyBraceBody ruled 'invalid'; each returns a concrete phrase.
  // bare unknown name ({rumor}): names the missing rule/variable
  assert.equal(c.classifyBraceBody('rumor', {}, {}), 'invalid');
  assert.match(c.braceAttemptReason('rumor', {}, {}), /No rule or variable named "rumor"/);
  // dice-looking but unparseable ({2d6x})
  assert.equal(c.classifyBraceBody('2d6x', {}, {}), 'invalid');
  assert.match(c.braceAttemptReason('2d6x', {}, {}), /dice roll/i);
  // a die STARTED but with no sides ({2d}, {3d}, {10d}, {2d+3}) used to fall through to plain text
  // (the one true silent no-op); now it is an ATTEMPT that names the missing sides.
  for (const b of ['2d', '3d', '10d', '2d+3']) {
    assert.equal(c.classifyBraceBody(b, {}, {}), 'invalid', b + ' is a dice attempt, not literal text');
    assert.match(c.braceAttemptReason(b, {}, {}), /missing its number of sides/i, b + ' names the missing sides');
  }
  // prose that merely starts like a die stays literal (no false positive): {2days}, {2dogs}
  for (const b of ['2days', '2dogs']) assert.equal(c.classifyBraceBody(b, {}, {}), 'literal', b + ' is prose, not a dice attempt');
  // a real die still promotes ({2d6}); a bare {d} stays the bare-name path (undefined variable)
  assert.equal(c.classifyBraceBody('2d6', {}, {}), 'artifact');
  assert.equal(c.classifyBraceBody('d', {}, {}), 'invalid');
  assert.match(c.braceAttemptReason('d', {}, {}), /No rule or variable named "d"/);
  // a broken calculation ({= badname + 1}) borrows mathReasonPhrase (bad ref)
  assert.equal(c.classifyBraceBody('= badname + 1', {}, {}), 'invalid');
  // #1319: a COMPOSED aggregate ({= round(100*sum(a)/sum(b))}) is classified with a null node, so its
  // empty sums make 100*0/0 -> NaN -> null; it must still promote (it computes on the live node at render).
  assert.equal(c.classifyBraceBody('= round(100*sum(wins)/sum(games))', {}, {}), 'artifact');
  assert.equal(c.classifyBraceBody('= sum(a)/sum(b)', {}, {}), 'artifact');
  assert.equal(c.classifyBraceBody('= avg(cost) * 1.2', {}, {}), 'artifact');
  // but a genuinely-broken expr with no node-aggregate stays invalid (the fallback is aggregate-gated)
  assert.equal(c.classifyBraceBody('= nofunc(x) + 1', {}, {}), 'invalid');
  // #1159: "no value here" survives the reword, so this alone could not detect the fix either.
  const badRefCue = c.braceAttemptReason('= badname + 1', {}, {});
  assert.match(badRefCue, /calculation uses .*no value here/i);
  assert.match(badRefCue, /sibling/, 'the display cue carries the scope rule too, not just the miss');
  // an estimate crossing into a math formula ({= 5 to 10}) reads as 'estimate', not 'bad ref'
  assert.match(c.braceAttemptReason('= 5 to 10', {}, {}), /estimate/i);
  // a modifier on an unknown base ({beast.cap}) names the missing base
  assert.equal(c.classifyBraceBody('beast.cap', {}, {}), 'invalid');
  assert.match(c.braceAttemptReason('beast.cap', {}, {}), /No rule or variable named "beast"/);
  // a generator keyword typed with no argument ({oracle}/{roll}/{shuffle}/{deck}/{clock}) points at
  // the form it needs, instead of the generic "no rule named oracle" bare-name message.
  assert.match(c.braceAttemptReason('oracle', {}, {}), /\{oracle: likely\}/, '{oracle} names the odds form');
  assert.match(c.braceAttemptReason('roll', {}, {}), /\{roll: #tag\}/, '{roll} names the tag form');
  assert.match(c.braceAttemptReason('shuffle', {}, {}), /\{shuffle: a \| b \| c\}/, '{shuffle} names the list form');
  assert.match(c.braceAttemptReason('deck', {}, {}), /\{shuffle: a \| b \| c\}/, '{deck} points at shuffle');
  assert.match(c.braceAttemptReason('clock', {}, {}), /\[o 0\/6\]/, '{clock} points at the bracket clock');
  // the near-miss branch only fires when no rule/var owns the name (it runs on invalid bodies)
  assert.equal(c.classifyBraceBody('oracle', { oracle: ['x'] }, {}), 'artifact', 'a real rule named oracle still promotes');
  // AP-style copy: no em dashes in any of the user-facing reasons
  for (const b of ['rumor', '2d6x', '2d', 'oracle', 'roll', 'clock', '= badname + 1', 'beast.cap']) {
    assert.ok(!c.braceAttemptReason(b, {}, {}).includes('—'), 'no em dash in ' + b);
  }
  // a KNOWN name is a valid artifact, never flagged (the cue only fires on 'invalid')
  assert.equal(c.classifyBraceBody('rumor', { rumor: ['x'] }, {}), 'artifact');
  // prose braces classify 'literal' and are left entirely alone by the cue
  assert.equal(c.classifyBraceBody('note to self', {}, {}), 'literal');
  // ── Slice 1: query/count/roll/prop committed keyword + empty/bad tail is an ATTEMPT, not a raw-brace
  // leak. Before this they classified 'literal' and rendered the braces verbatim in prose with no cue.
  for (const b of ['count: ', 'query:', 'roll: ', 'count:', 'query: ', 'roll:']) {
    assert.equal(c.classifyBraceBody(b, {}, {}), 'invalid', `"${b}" is a committed keyword attempt, not prose`);
  }
  assert.match(c.braceAttemptReason('count: ', {}, {}), /\{count: is:todo\}/, 'a bad count names the search form');
  assert.match(c.braceAttemptReason('query:', {}, {}), /\{query: is:todo\}/, 'a bad query names the search form');
  assert.match(c.braceAttemptReason('roll: ', {}, {}), /\{roll: #tag\}/, 'a bad roll names the tag form');
  // {prop …} with no key:value is an attempt (was a silent literal leak or a mis-taught bad-ref)
  for (const b of ['prop hp', 'prop : 5', 'prop ']) assert.equal(c.classifyBraceBody(b, {}, {}), 'invalid', `"${b}" is a prop attempt`);
  assert.match(c.braceAttemptReason('prop hp', {}, {}), /\{prop hp: 12\}/, 'a bad prop names the key:value form');
  // committed but bad TAIL forms (oracle/meter/shuffle/markov) now get a SPECIFIC message, not the generic catch-all
  assert.match(c.braceAttemptReason('oracle: definitely', {}, {}), /certain, likely, even, unlikely/i, 'a bad oracle band lists the real odds words');
  assert.match(c.braceAttemptReason('meter: hp+hpmax', {}, {}), /\{meter: hp\/hpmax\}/, 'a bad meter recipe names value/max');
  assert.match(c.braceAttemptReason('markov: a b c', {}, {}), /→/, 'a bad markov names the arrow form');
  assert.match(c.braceAttemptReason('shuffle: ', {}, {}), /\{shuffle: a \| b \| c\}/, 'a bad shuffle names the list form');
  // none of these fall back to the generic sentence, and none carry an em dash
  for (const b of ['count: ', 'query:', 'roll: ', 'prop hp', 'oracle: definitely', 'meter: hp+hpmax', 'markov: a b c', 'shuffle: ']) {
    const r = c.braceAttemptReason(b, {}, {});
    assert.ok(!/looks like a pill but could not be created/.test(r), `"${b}" gets a specific reason, not the catch-all`);
    assert.ok(!r.includes('—'), 'no em dash in ' + b);
  }
  // a REAL query/count/roll/prop still promotes (the commit only fires when the tail fails)
  assert.equal(c.classifyBraceBody('count: is:todo', {}, {}), 'artifact');
  assert.equal(c.classifyBraceBody('roll: #tag', {}, {}), 'artifact');
  assert.equal(c.classifyBraceBody('prop hp: 12', {}, {}), 'artifact');
});

// #1199: braceAttemptReason is good copy, but it lived only in a `title`/`aria-label` on a
// non-focusable span, so on a laptop it was hover-only (the #1021 dead-element shape). The reason is
// now stashed at render as `data-reason` and flashed on click, so a keyboard/pointer user who reads
// the "not recognized" flash and clicks the underlined text sees the full explanation. Driven live
// (a click flashes the sentence); this pins the wiring, since a source-pin proves presence only.
test('#1199 wiring: the formula-error reason is stashed and flashed on click, not hover-only', () => {
  // both render sites (nested + top-level pass) carry the reason in data-reason
  const stashed = (_src.match(/class="\$\{cls\}" data-reason="\$\{escQ\(why\)\}"|class="brace-attempt" data-reason="\$\{escQ\(why\)\}"/g) || []);
  assert.ok(stashed.length >= 2, 'both .brace-attempt render sites must stash the reason in data-reason');
  // the delegated click handler flashes the stashed reason
  assert.ok(/const ba = e\.target\.closest\('\.brace-attempt'\);\s*\n\s*if \(ba && ba\.dataset\.reason\) flashHint\(ba\.dataset\.reason\);/.test(_src),
    'a click on .brace-attempt must flash its data-reason (surfacing the hover-only explanation)');
  // it sits in a CLICK delegate (not mousedown), so it never fights the caret placement / caret invariant
  const iHandler = _src.indexOf("const ba = e.target.closest('.brace-attempt')");
  const iDelegate = _src.lastIndexOf("getElementById('outline').addEventListener('click'", iHandler);
  assert.ok(iDelegate > -1 && iDelegate < iHandler, 'the flash lives in the outline CLICK delegate, so the caret still lands on click');
});
test('promoteBraceBody — {markov: …} builds an anonymous, typed markov record', () => {
  const node = { text: '', markov: [] };
  const tok = c.promoteBraceBody(node, 'markov: a→b, b→c');
  assert.match(tok, /^\[\[markov:[a-z0-9]+\]\]$/);
  const rec = node.markov[0];
  assert.equal(rec.typed, true);
  assert.equal(rec.name, undefined);            // anonymous — named markov stays a dialog feature
  assert.equal(rec.def, 'a→b\nb→c');
  assert.deepEqual(host(rec.path), ['a', 'b', 'c']); // deterministic walk from the first state
});
test('artifactToShorthand — a typed markov unfolds; a NAMED one stays atomic', () => {
  const typed = { key: 'k', typed: true, def: 'a→b\nb→c', start: 'a', steps: 5, path: ['a', 'b', 'c'] };
  assert.equal(c.artifactToShorthand('markov', typed), '{markov: a→b, b→c}');
  // a named (dialog) chain must NOT unfold — the name is doc-wide config the text can't carry
  assert.equal(c.artifactToShorthand('markov', { ...typed, name: 'weather' }), null);
  // a non-typed (legacy dialog) chain doesn't unfold either
  assert.equal(c.artifactToShorthand('markov', { ...typed, typed: false }), null);
});
test('typed markov — full edit-mode unfold/refold cycle preserves the token', () => {
  const node = { text: '', markov: [] };
  const tok = c.promoteBraceBody(node, 'markov: a→b, b→c');
  node.text = 'pre ' + tok;
  c.unfoldArtifacts(node);                          // enter edit: token → {markov: …} source
  assert.equal(node.text, 'pre {markov: a→b, b→c}');
  c.refoldArtifacts(node);                          // exit unchanged: source → the SAME token
  assert.equal(node.text, 'pre ' + tok);            // frozen walk + key preserved
  assert.equal(node.markov.length, 1);
});

// ── grammar engine ─────────────────────────────────────────────────────────
test('runGrammar — deterministic single-alternative expansion', () => {
  assert.equal(c.runGrammar('origin: hello', 'origin', {}, {}), 'hello');
});

test('runGrammar — unknown rule renders {name?} marker', () => {
  assert.equal(c.runGrammar('origin: {missing}', 'origin', {}, {}), '{missing?}');
});

test('runGrammar — reference cycle is caught (↻), not infinite', () => {
  assert.equal(c.runGrammar('a: {b}\nb: {a}', 'a', {}, {}), '↻');
});

test('runGrammar — embedded math and dice primitives', () => {
  assert.equal(c.runGrammar('origin: {= 2*3}', 'origin', {}, {}), '6');
  c.seedSequence([0]); // 2d6 → 2
  try {
    assert.equal(c.runGrammar('origin: roll {2d6}', 'origin', {}, {}), 'roll 2');
  } finally { c.resetRandom(); }
});

test('runGrammar — invalid definition returns null', () => {
  assert.equal(c.runGrammar('not a rule line', 'origin', {}, {}), null);
});

// ── conditional text: {cond: then | else} (Ink-style) ───────────────────────
test('condParts — splits a comparison into cond / then / else', () => {
  assert.deepEqual(host(c.condParts('hp > 0: alive | dead')), { cond: 'hp > 0', then: 'alive', else: 'dead' });
  assert.deepEqual(host(c.condParts('n == 1: one')), { cond: 'n == 1', then: 'one', else: '' }); // else optional
});

test('condParts — only a real comparison is a conditional (no false positives)', () => {
  assert.equal(c.condParts('a | b'), null);          // plain alternation
  assert.equal(c.condParts('name: value'), null);    // a colon without a comparison stays literal
  assert.equal(c.condParts('= 2*3'), null);          // {= expr} is an expression
  assert.equal(c.condParts('2d6'), null);            // a dice body
  assert.equal(c.condParts('x>0 | y: a|b'), null);   // a top-level `|` before the `:` → alternation wins
});

test('resolveBrace — conditional emits THEN when the comparison holds, else ELSE', () => {
  const ctx = (vars) => ({ rules: {}, vars, depth: 0, stack: [] });
  assert.equal(c.resolveBrace('hp > 0: alive | dead', ctx({ hp: 3 })), 'alive');
  assert.equal(c.resolveBrace('hp > 0: alive | dead', ctx({ hp: 0 })), 'dead');
  assert.equal(c.resolveBrace('hp > 0: alive', ctx({ hp: 0 })), ''); // no else → empty
});

test('#1356: the conditional arm gives the test the SAME scope a {= } on that point gets', () => {
  // CALL-SITE pin (#1133). resolveNodeScope has its own pure pins; they prove the layering, not that
  // the conditional calls it. This behaviour cannot be pinned purely: `cookieNode` is a render-time
  // module `let`, not on the ctx, so the vm sandbox cannot set it — hence a source pin here PLUS the
  // driven run recorded in UXP-288. A source pin proves presence, never behaviour.
  const arm = between(NC, 'const cp = condParts(body);', 'const sp = seqParts(body);');
  assert.ok(nonEmpty(arm.split('\n'), 'the conditional arm of resolveBrace').length > 4);
  assert.match(arm, /resolveNodeScope\(cookieNode, ancestorsOf\(cookieNode\), ctx\.vars\)/,
    'the test resolves against own props over ancestors over doc vars, like a math pill');
  assert.match(arm, /evalMath\(expandAggExpr\(cond, cookieNode, _scope\), _scope\)/,
    'and rollups/queries are pre-substituted, so evalMath stays number-only');
  assert.match(arm, /strCondVerdict\(cond, _scope\)/, 'the string arm reads the same scope');
  assert.doesNotMatch(arm, /evalMath\(cond, ctx\.vars\)/, 'the old document-only evaluation is gone');
  // a node-less caller (dialog preview) keeps the document-only scope
  assert.match(arm, /cookieNode \?[\s\S]{0,90}: ctx\.vars/, 'no node → the old scope, not a throw');
  // and the chosen BRANCH gets the widened scope too, or the form is half-alive
  assert.match(arm, /expandTemplate\(v \? cp\.then : cp\.else,[\s\S]{0,60}vars: _scope/,
    'the branch is expanded with the widened scope');
});

test('#1359: a body that reads as an attempted TEST is an attempt, never a coin flip', () => {
  // condParts requires a real comparison, and a body that misses that gate used to fall through to
  // the ALTERNATION branch: {COND: THEN | ELSE} froze as a 50/50 pick between the literal strings
  // "COND: THEN" and "ELSE", with an ordinary pill and a "Click to re-generate" tooltip. Same shape
  // the typed-rule note already recorded for {loot: sword | shield 2} and closed with a keyword.
  // NB the three logic-FUNCTION shapes used to live here as attempts. #1365 widened condParts to
  // accept a bare function call as a test — a rule name cannot contain a paren, so `{and(a, b): …}`
  // is unambiguous on its face and needs no marker — and they are REAL conditionals now. Moved to
  // their own pin below rather than deleted, so the reversal is recorded. What stays here is the set
  // whose tell is an operator, where no such syntactic escape exists.
  const attempts = ['a ≥ 3: yes | no', 'a ≤ 9: y|n', 'a ≠ 4: y|n',
                    'danger = 5: yes | no', 'danger > 9 || hp > 5: either | nope', 'a && b: y|n',
                    // NB `count("is:todo") > 0: …` used to live here. #1363 made the conditional's
                    // boundary split quote-aware, so the colon inside the query no longer splits the
                    // body and it is a REAL conditional now — moved to its own pin below rather than
                    // deleted, so the reversal is recorded rather than silently lost.
                    'count("is:todo) > 0: some | none'];   // still an attempt: the quote is unclosed
  for (const b of nonEmpty(attempts, 'attempted-test shapes')) {
    assert.equal(c.condAttempt(b), true, `${b}: reads as an attempted test`);
    assert.equal(c.classifyBraceBody(b, {}, {}), 'invalid', `${b}: classifies invalid, not artifact`);
    assert.match(c.resolveBrace(b, { rules:{}, vars:{a:1,b:1,danger:5,hp:9}, depth:0, stack:[] }), /^\{.*\?\}$/,
      `${b}: nested, degrades to a visible marker rather than a pick`);
    assert.ok(c.condAttemptReason(b).length > 30, `${b}: the cue says something followable`);
  }
});

test('#1363: a quoted query keeps its colon and its pipe, so predicates reach the test', () => {
  // splitTopLevel tracks brace depth alone, so `:` inside a quoted search split the conditional
  // before its own separator did — `#tag` queries were fine and every is:/has:/tag: filter was not.
  for (const [body, why] of nonEmpty([
    ['count("is:todo") > 0: some | none',   'a colon inside the query'],
    ['count("has:owner") == 0: all | some', 'another field filter'],
    ['count("#a | #b") > 0: yes | no',      'a pipe inside the query, which used to read as alternation'],
    ['mood == "a:b": yes | no',             'a colon inside a compared value'],
  ], 'quoted-query conditions')) {
    const cp = c.condParts(body);
    assert.ok(cp, `${body}: parses as a conditional (${why})`);
    assert.ok(cp.cond.includes('"'), `${body}: the quoted run survives into the test`);
    assert.equal(c.condAttempt(body), false, `${body}: and is not mistaken for an attempt`);
  }
  // the ARM split is deliberately NOT quote-aware: a quote in a branch is prose, not a delimiter
  assert.deepEqual(host(c.condParts('x > 1: he said "a | b" | none')),
    { cond: 'x > 1', then: 'he said "a', else: 'b" | none' },
    'arms still split on a top-level pipe, quoted or not (recorded, not accidental)');
  // and an UNBALANCED quote must still read as an attempt, or #1359 regresses
  assert.equal(c.condAttempt('count("is:todo) > 0: some | none'), true, 'an unclosed quote is still an attempt');
  // …and the case the fallback is actually LOAD-BEARING for. The string above also trips the `fn(`
  // tell, so removing the fallback left it green — a guard nobody can break. This one has an unclosed
  // quote and NO other tell (`==` is excluded from the single-equals pattern), so without the plain-
  // split fallback it stops being an attempt and goes back to being a coin flip. Found by mutation.
  assert.equal(c.condAttempt('mood == "angry: yes | no'), true,
    'an unclosed quote with no other tell is still an attempt');
});

test('#1367: a bracket in a search says so, instead of quietly searching for the bracket', () => {
  // Brackets carry no meaning in a search, so the whitespace split turns `(has:owner | #x)` into the
  // TEXT terms `(has:owner` and `#x)` and looks for those literally — a confident 0 where the writer
  // meant 3. searchTermProblems only inspected kind:'invalid' terms, so nothing complained.
  const P = q => c.searchTermProblems(c.parseSearchQuery(q), { states: [] });
  for (const q of nonEmpty(['(has:owner | #x)', 'is:todo -(has:owner #x)', '(a b)'], 'grouping attempts')) {
    const probs = P(q);
    assert.equal(probs.length, 1, `${q}: says it once, not once per split fragment`);
    assert.match(probs[0].message, /Round brackets do not group a search/, `${q}: names the cause`);
    assert.match(probs[0].message, /is:todo -has:owner \| is:todo -#x/, `${q}: and shows the form that works`);
  }
  // a BALANCED bracket term is a legitimate literal search and must be left alone
  for (const q of nonEmpty(['(a)', 'plain words', 'has:owner | #x', '#tag is:todo'], 'spared queries'))
    assert.equal(P(q).length, 0, `${q}: no bracket complaint`);
  // and the existing is: reason is untouched
  assert.match(P('is:bogus')[0].message, /is not a filter this app knows/, 'the invalid-filter arm still fires');
});

test('#1365: here("query") asks the search language about THIS point', () => {
  // The per-node matcher already existed (queryMatchesNode, which nodeMatchesSearch already calls for
  // a one-off check on a live node). here() is the door onto it from the expression layer, so the
  // predicate vocabulary is the SAME one — no second set of names to invent or keep in sync.
  const mk = (text, props) => ({ id: 'n' + text.length, text, children: [],
    props: Object.entries(props || {}).map(([k, v]) => ({ key: k, val: String(v) })) });
  const matches = (q, n) => c.queryMatchesNode(c.parseSearchQuery(q), n, [], {}, undefined, '');
  const tagged = mk('Ellen Marsden #unverified'), plain = mk('Hannah Sowerby #verified');
  assert.equal(matches('#unverified', tagged), true,  'the matcher answers for the node itself');
  assert.equal(matches('#unverified', plain),  false, 'and discriminates');
  assert.equal(matches('has:owner', mk('x', { owner: 'ana' })), true, 'a field predicate too');
  assert.equal(matches('has:owner', mk('x')), false);
  // BEHAVIOURAL, not a source pin. The first draft asserted the regex STRING was present in
  // expandAggExpr, and disabling the arm (`if (false)`) left it green — the replace line still
  // carried the string. expandAggExpr is drivable here, so drive it (#1133).
  const at = (q, n) => c.expandAggExpr(q, n, {});
  assert.equal(at('here("#risk")', mk('x #risk')), '(1)', 'here() substitutes to 1 for a match');
  assert.equal(at('here("#risk")', mk('x #calm')), '(0)', 'and to 0 for a miss');
  assert.equal(at('here("has:owner")', mk('x', { owner: 'ana' })), '(1)', 'field predicates work');
  // This one is the CONTRACT, not a guard-check: the code has no empty-query branch (a mutation
  // proved one dead, since queryMatchesNode already answers false for an empty term list). If the
  // matcher ever starts reading an empty query as vacuously true, this is what says so.
  assert.equal(at('here("")', mk('x #risk')), '(0)', 'an empty query asserts nothing, never everything');
  assert.equal(at('here("#risk")', null), '(0)', 'a node-less caller answers 0, like the rollups');
  // it substitutes to a NUMBER, which is what keeps evalMath number-only and lets it compose
  assert.equal(c.evalMath(at('and(here("#risk"), 1)', mk('x #risk')), {}), 1, 'composes with and()');
  assert.equal(c.evalMath(at('not(here("#risk"))', mk('x #calm')), {}), 1, 'and with not()');
  // scope is the host point ALONE — the subtree is count()'s job
  const parent = mk('Parent'); parent.children = [mk('kid #risk')];
  assert.equal(at('here("#risk")', parent), '(0)', 'a tagged CHILD does not make the parent match');
  // the door: the function list a user reads
  assert.match(NC, /here:'1 when THIS point matches a search, else 0'/, 'here is described beside count');
});

test('#1365: a bare function call is a legal test, because a rule name cannot contain a paren', () => {
  // The comparison requirement kept detection syntactic and stayed clear of `{name: a | b}`. That
  // ambiguity is only real for a BARE IDENTIFIER; a call carries its own tell, so these need no
  // marker. evalMath already evaluated them correctly — only the sniff was in the way.
  const V = { a: 1, b: 1 };
  for (const [body, want, why] of nonEmpty([
    ['and(a, b): both | not both', 'both',      'the logic functions, which always did evaluate'],
    ['or(a, 0): some | none',      'some',      'or'],
    ['not(0): off | on',           'off',       'not'],
    ['here("#risk"): flag | calm', null,        'a host-point predicate needs a node, so only the PARSE is asserted'],
  ], 'function-call conditions')) {
    const cp = c.condParts(body);
    assert.ok(cp, `${body}: parses as a conditional (${why})`);
    assert.equal(c.condAttempt(body), false, `${body}: and is no longer an attempt`);
    if (want !== null)
      assert.equal(c.resolveBrace(body, { rules:{}, vars:V, depth:0, stack:[] }), want, `${body}: and evaluates`);
  }
  // the bare identifier is STILL out — that is the ambiguity a marker would have to settle
  assert.equal(c.condParts('done: finished | still going'), null, 'a bare name is still the rule form');
  // and a call that will not evaluate still fails visibly rather than picking a branch
  assert.match(c.resolveBrace('nosuchfn(1): a | b', { rules:{}, vars:{}, depth:0, stack:[] }), /^\{.*\?\}$/,
    'an unknown function still shows its marker');
});

test('#1359: the shapes it must NOT claim — the rule-definition form above all', () => {
  // The tells are a closed set of characters a rule NAME can never contain, so {name: a | b} is
  // untouched by construction and no resolution lookup is involved (P1).
  for (const b of nonEmpty(['cost > 30: over | under',        // a real conditional
                            'mood == "angry": shout | drop',  // a real string conditional
                            'done: finished | still going',   // bare name: ambiguous, deliberately left
                            'loot: sword | shield 2',         // the inline rule definition
                            'note: remember the milk',
                            'name.sub: a | b',                // a dotted rule name
                            // a rule NAMED and/or/not is the case the rule-name exclusion exists for:
                            // the tells match its bare name, so without that guard these are claimed.
                            'and: x | y', 'or: a | b', 'not: p | q',
                            'roll: cost > 3', 'query: a = b', 'count: is:todo', 'oracle: likely',
                            'shuffle: a | b', 'markov: a→b', 'meter: hp/max',
                            'seq Flow: A | B', 'rule loot: a | b', 'prop cost: 5', 'date due: friday',
                            '3x: t', '2d4x: t', 'a|b', 'plain text'], 'spared shapes'))
    assert.equal(c.condAttempt(b), false, `${b}: must not be claimed as an attempted test`);
});

test('#1359: a mistyped test never becomes a data-MUTATING action pill', () => {
  // {danger = 5: yes | no} parsed as an action (target danger, rhs "5: yes | no") and rendered a
  // clickable "Click to apply: set danger to 5: yes | no" — a typo that writes to a variable.
  assert.equal(c.parseActionPill('danger = 5: yes | no'), null, 'a colon in the amount is not an amount');
  // and every legitimate action still parses, including one embedding a braced colon
  assert.deepEqual(host(c.parseActionPill('hp -= 3')), { target: 'hp', op: '-=', rhs: '3' });
  assert.deepEqual(host(c.parseActionPill('danger = 5')), { target: 'danger', op: '=', rhs: '5' });
  assert.deepEqual(host(c.parseActionPill('hp -= {roll: #trap}')), { target: 'hp', op: '-=', rhs: '{roll: #trap}' });
});

test('#1359: the guard sits in BOTH walks, and after every keyword form', () => {
  // classify decides the CUE, promoteBraceBodyIn decides the PILL, and they are separate walks with
  // separate orders — which is why wiring only classify left the live app still coin-flipping.
  const cls = fnBody(NC, 'classifyBraceBody'), pro = fnBody(NC, 'promoteBraceBodyIn');
  assert.ok(cls.includes("if (condAttempt(body)) return 'invalid';"), 'classify refuses an attempt');
  assert.ok(pro.includes('if (condAttempt(body)) return null;'), 'promotion refuses an attempt');
  for (const [name, body] of [['classifyBraceBody', cls], ['promoteBraceBodyIn', pro]])
    assert.ok(body.indexOf('condAttempt(body)') < body.indexOf("splitTopLevel(body, '|')"),
      `${name}: the guard precedes the alternation fall-through it exists to beat`);
  assert.match(fnBody(NC, 'braceAttemptReason'), /condAttempt\(body\)\) return condAttemptReason\(body\)/,
    'and the cue speaks a reason for it');
});

test('#1361: a conditional that cannot read its test answers in its OWN terms, not the roll family’s', () => {
  // Every {…?} marker funnelled through one branch shared with {roll:} (the CSS comment says so),
  // so a failed CONDITION read "no match yet" / "Nothing matched yet. Click to try again, or add
  // points that fit" — nothing was being matched, adding points cannot help, a conditional is not
  // random, and the term that failed was never named although the core had computed it.
  const cases = [
    ['hp > 0',            {},                 /Could not read the test .hp > 0.:/, 'names the failing test'],
    ['hp > 0',            { hp: 5 },          /has a value now.*Click to re-judge/, 'the declared-later case'],
    ['mood == "angry"',   {},                 /A text test compares a name with a quoted word/, 'the text arm'],
    ['mood == "angry"',   { mood: 'angry' },  /has a value now.*Click to re-judge/, 'text, declared later'],
  ];
  for (const [cond, vars, re, why] of nonEmpty(cases, 'condEmptyMessage cases')) {
    const m = c.condEmptyMessage(cond, vars);
    assert.equal(m.shown, 'can’t tell yet', `${cond}: stops claiming a match was attempted`);
    assert.match(m.cta, re, `${cond}: ${why}`);
    assert.doesNotMatch(m.cta, /Nothing matched|add points that fit|try again/, `${cond}: no roll copy`);
    assert.doesNotMatch(m.cta, /—/, `${cond}: AP punctuation, no em dash`);
  }
  // The reason is BORROWED, not minted: the same phrase the #ERR pill speaks for the same cause.
  assert.ok(c.condEmptyMessage('hp > 0', {}).cta.includes(c.mathReasonPhrase(c.mathErrorReason('hp > 0', {}), 'hp > 0')),
    'the explanation comes from mathReasonPhrase, so one cause reads one way everywhere');
});

test('#1361: the pill wires the conditional arm, and a roll keeps its own', () => {
  // CALL-SITE pin (#1133): condEmptyMessage is pure and pinned above; this is the half that proves
  // renderGrammarPill asks it, and asks it only for a conditional.
  const body = fnBody(NC, 'renderGrammarPill');
  assert.match(body, /condEmpty = condEmptyMessage\(cp\.cond, collectVars\(\)\)/, 'the pill computes a conditional reason');
  assert.match(body, /condEmpty \? condEmpty\.cta/, 'and it reaches the tooltip');
  assert.match(body, /condEmpty \? condEmpty\.shown/, 'and the shown text');
  assert.ok(body.indexOf('badFilter ?') < body.indexOf('condEmpty ? condEmpty.cta'),
    'a roll with an unreadable filter still wins, so its specific reason is not lost');
  assert.match(body, /emptyMark \? .Nothing matched yet/, 'and a plain empty ROLL keeps its own copy');
  // #1361: the cta reaches two ATTRIBUTES and now carries a quoted condition, so it must be escaped.
  // #1499 added a third title branch (the oracle band), so this checks EVERY branch instead of one
  // literal expression — a pin that names one shape goes quiet the moment a branch is added beside it.
  const titleExpr = between(body, 'title="', 'aria-label=');
  assert.ok(!/\$\{cta\}/.test(titleExpr), 'no title branch interpolates the raw cta');
  assert.equal((titleExpr.match(/escQ\(cta\)/g) || []).length, 3,
    'all three title branches escape it: a named rule, an oracle band, and a plain roll');
  assert.match(body, /aria-label="\$\{kindLabel\}: \$\{escQ\(shownResult\)\}\. \$\{escQ\(cta\)\}/,
    'aria-label escapes it too');
});

test('resolveBrace — an unresolvable condition fails visibly (P4), never silently', () => {
  // hp is undefined → evalMath returns null → a `{cond?}` marker, not a blank or a throw.
  assert.equal(c.resolveBrace('hp > 0: a | b', { rules: {}, vars: {}, depth: 0, stack: [] }), '{hp > 0?}');
});

// ── string equality in conditionals (#540) ──────────────────────────────────
test('strCondVerdict — quoted-side == / != compares as text, case-insensitive', () => {
  assert.equal(c.strCondVerdict('mood == "angry"', { mood: 'angry' }), 1);
  assert.equal(c.strCondVerdict('mood == "angry"', { mood: 'calm' }), 0);
  assert.equal(c.strCondVerdict('mood != "angry"', { mood: 'calm' }), 1);
  assert.equal(c.strCondVerdict('mood == "Angry"', { mood: 'angry' }), 1);   // case-insensitive by design
  assert.equal(c.strCondVerdict("mood == 'angry'", { mood: 'angry' }), 1);   // single quotes too
  assert.equal(c.strCondVerdict('"a" == "a"', {}), 1);                       // both sides quoted
  assert.equal(c.strCondVerdict('"left" == mood', { mood: 'left' }), 1);     // quote on either side
  assert.equal(c.strCondVerdict('r == "20"', { r: 20 }), 1);                 // numeric var stringifies
});

test('strCondVerdict — not-applicable and unresolvable are distinct outcomes', () => {
  assert.equal(c.strCondVerdict('a == b', { a: 1, b: 1 }), null);      // no quoted side → numeric path
  assert.equal(c.strCondVerdict('hp > 0', { hp: 1 }), null);           // no == / != at all
  assert.ok(Number.isNaN(c.strCondVerdict('mood == "x"', {})));        // unknown ref → NaN → {cond?}
  assert.ok(Number.isNaN(c.strCondVerdict('2 + x == "y"', {})));       // non-identifier side → NaN
});

test('resolveBrace — a text pick var drives a conditional branch (#540, the #429 text half)', () => {
  const ctx = (vars) => ({ rules: {}, vars, depth: 0, stack: [] });
  assert.equal(c.resolveBrace('mood == "angry": attacks | waits', ctx({ mood: 'angry' })), 'attacks');
  assert.equal(c.resolveBrace('mood == "angry": attacks | waits', ctx({ mood: 'calm' })), 'waits');
  assert.equal(c.resolveBrace('mood != "angry": talks | fights', ctx({ mood: 'calm' })), 'talks');
  // unresolvable string ref → the same visible {cond?} marker as the numeric path (P4)
  assert.equal(c.resolveBrace('mood == "angry": a | b', ctx({})), '{mood == "angry"?}');
  // numeric conditions are untouched by the new arm
  assert.equal(c.resolveBrace('hp > 0: alive | dead', ctx({ hp: 3 })), 'alive');
  assert.equal(c.resolveBrace('r == 20: crit | miss', ctx({ r: 20 })), 'crit');
});

test('resolveBrace — a roll can drive the conditional test (deep pass, the two-engine seam)', () => {
  const ctx = { rules: {}, vars: {}, depth: 0, stack: [] };
  // a braced roll in the test: over many rolls the result is always one of the two branches
  for (let i = 0; i < 24; i++) assert.match(c.resolveBrace('{2d6} > 3: hit | miss', ctx), /^(hit|miss)$/);
  // a BARE die in the test freezes and resolves too
  for (let i = 0; i < 24; i++) assert.match(c.resolveBrace('1d6 >= 4: high | low', ctx), /^(high|low)$/);
  // deterministic: seed so each d6 rolls its minimum (1) → 2d6 = 2, and 2 > 3 is false → the else branch
  c.seedSequence([0, 0, 0, 0]);
  try { assert.equal(c.resolveBrace('{2d6} > 3: hit | miss', ctx), 'miss', 'the min roll (2) fails 2 > 3 → else'); } finally { c.resetRandom(); }
  // a die combined with a stat in the test: {1d6 + str >= 5}
  for (let i = 0; i < 24; i++) assert.match(c.resolveBrace('1d6 + str >= 5: strong | weak', { rules: {}, vars: { str: 2 }, depth: 0, stack: [] }), /^(strong|weak)$/);
});

// ── {roll: query} — pick a random point from the live outline (the tree-reference generator) ──
test('rollParts — sniffs the reserved roll: keyword, keeps the query tail verbatim', () => {
  // assert on .expr (not the whole object) — cores run in a vm realm, so deepEqual trips on the
  // cross-realm Object.prototype even for structurally identical objects.
  assert.equal(c.rollParts('roll: is:todo').expr, 'is:todo');
  assert.equal(c.rollParts('roll:#thread/torn').expr, '#thread/torn');  // query has its own : and /
  assert.equal(c.rollParts('roll:'), null);        // no query → not a roll
  assert.equal(c.rollParts('shuffle: a|b'), null);  // a different keyword is not roll:
  assert.equal(c.rollParts('color'), null);         // a bare rule name is not roll:
});

test('pickFromQuery — picks one matching point title from the tree, uncapped + fair', () => {
  const kid = (id, text) => ({ id, text, children: [], props: [], seq: [] });
  const rootNode = { id: 'r', text: '', children: [
    kid('a', '#TODO chase the letter'),
    kid('b', 'just a note'),
    kid('c', '#TODO find the key'),
    kid('d', '#DONE closed thread'),
  ] };
  // is:todo matches a + c (2 open todos), not the note, not the done one
  c.setRandom(() => 0);   // floor(0 * 2) = index 0
  try { assert.equal(c.pickFromQuery('is:todo', rootNode, null), 'chase the letter'); }
  finally { c.resetRandom(); }
  c.setRandom(() => 0.99);  // floor(0.99 * 2) = index 1
  try { assert.equal(c.pickFromQuery('is:todo', rootNode, null), 'find the key'); }
  finally { c.resetRandom(); }
  // no match → '' (a visible empty, never a throw)
  assert.equal(c.pickFromQuery('is:todo #nonexistent', rootNode, null), '');
  // the host point is excluded from its own roll (so {roll:} on a point can't pick itself)
  c.setRandom(() => 0);
  try { assert.equal(c.pickFromQuery('is:todo', rootNode, 'a'), 'find the key'); }  // 'a' excluded → only c
  finally { c.resetRandom(); }
});

test('a roll shows a picked point\'s clean TITLE, not its pill/prop source', () => {
  // game-workbench: {roll: #card} froze "Gloamroot Toad {prop cost: 2} {prop focus: 5}" because at the
  // load promote pass the card's props were still raw {…}. rollLabel blanks raw brace source (and stripMd
  // already drops promoted [[…]] tokens + the matched tag), so the label is the title either way.
  const t = c.parseSearchQuery('#card');
  assert.equal(c.rollLabel({ text: 'Gloamroot Toad #card {prop cost: 2} {prop focus: 5}', type: 'ul', props: [] }, t), 'Gloamroot Toad');
  assert.equal(c.rollLabel({ text: 'Pale Widow {prop cost: 4} #card', type: 'ul', props: [] }, t), 'Pale Widow');
  // nested braces (a rule/dice inside) are blanked too; a title with no source is untouched
  assert.equal(c.rollLabel({ text: 'Cinderfang Wyrm #card', type: 'ul', props: [] }, t), 'Cinderfang Wyrm');
  assert.equal(c.rollLabel({ text: 'Loot {a {b} c} #card', type: 'ul', props: [] }, t), 'Loot');
});

test('#1237 a roll skips tag-inherited detail lines nested under a matched point', () => {
  const kid = (id, text, children = []) => ({ id, text, children, props: [], seq: [] });
  // A cast: each #character page hangs trait/debt detail children, which inherit #character.
  const cast = { id: 'r', text: '', children: [
    kid('alpha', 'ALPHA the mapmaker #character', [ kid('a1', 'trait: reads a coastline'), kid('a2', 'debt: owes the guild') ]),
    kid('beta', 'BETA the keeper #character', [ kid('b1', 'trait: never lies') ]),
  ] };
  // The pool is the two CHARACTERS, never their detail children (those matched only by inheritance).
  // (queryHits returns a sandbox-realm array, so compare joined strings, not deepEqual across realms.)
  const pool = (expr, r) => c.queryHits(expr, r, null).slice().sort().join(' | ');
  assert.equal(pool('#character', cast), 'ALPHA the mapmaker | BETA the keeper',
    'a #character roll draws the tagged pages, not the trait/debt lines nested under them');
  // A nested todo under a todo is KEPT: it matches on its OWN state, not by inheritance.
  const todos = { id: 'r', text: '', children: [
    kid('t1', '#TODO plan the trip', [ kid('t2', '#TODO book the flights') ]),
  ] };
  assert.equal(pool('is:todo', todos), 'book the flights | plan the trip',
    'a nested todo matches on its own state, so it stays in the pool');
  // {roll: #project is:todo}: the #project heading is not is:todo (not a hit), so its todo children are
  // KEPT even though they match #project only by inheritance — inherited cross-tag rolls still work.
  const proj = { id: 'r', text: '', children: [
    kid('p', 'Website #project', [ kid('p1', '#TODO write copy'), kid('p2', '#TODO pick a host') ]),
  ] };
  assert.equal(pool('#project is:todo', proj), 'pick a host | write copy',
    'a container tag inherited by a differently-filtered child still rolls (the container is not itself a hit)');
});

test('#1240 inferRowShape — reads the shared template from a list of sibling rows', () => {
  // node model (verified live): tags are literal #tag in .text; props are .props=[{key,val}] (a date lands
  // as a prop with an ISO-date val, a number as a numeric string). Shape returns a sandbox-realm object, so
  // compare via JSON string, not deepEqual across realms (the #1237 lesson).
  const row = (text, props = []) => ({ id: 'x', text, props, children: [] });
  const j = o => JSON.stringify(o);

  // Expenses: every row shares #august #groceries and a numeric `cost`.
  const expenses = [
    row('Aldi weekly shop #august #groceries', [{ key: 'cost', val: '92.4' }]),
    row('Costco run #august #groceries', [{ key: 'cost', val: '118.75' }]),
    row('Farmers market #august #groceries', [{ key: 'cost', val: '34.2' }]),
  ];
  assert.equal(j(c.inferRowShape(expenses)),
    j({ sharedTags: ['august', 'groceries'], props: [{ key: 'cost', type: 'number' }], todo: false }),
    'expenses: shared tags + a numeric cost prop, not a to-do');

  // Books: two numeric props + a year tag.
  const books = [
    row('Klara and the Sun #2026', [{ key: 'pages', val: '320' }, { key: 'rating', val: '4' }]),
    row('The Fifth Season #2026', [{ key: 'pages', val: '450' }, { key: 'rating', val: '5' }]),
  ];
  assert.equal(j(c.inferRowShape(books)),
    j({ sharedTags: ['2026'], props: [{ key: 'pages', type: 'number' }, { key: 'rating', type: 'number' }], todo: false }));

  // Tasks: checkbox to-dos with a shared date prop (ISO val → 'date' type).
  const tasks = [
    row('- [ ] Recruit fixers #chore', [{ key: 'due', val: '2026-08-06' }]),
    row('- [x] Book the hall #chore', [{ key: 'due', val: '2026-08-01' }]),
  ];
  assert.equal(j(c.inferRowShape(tasks)),
    j({ sharedTags: ['chore'], props: [{ key: 'due', type: 'date' }], todo: true }),
    'tasks: to-do detected, the date prop typed as date');

  // Cast: a tag, no props.
  const cast = [row('Sereth Vale, cartographer #character'), row('Marn Oakhollow #character')];
  assert.equal(j(c.inferRowShape(cast)), j({ sharedTags: ['character'], props: [], todo: false }));

  // A one-off tag/prop is NOT part of the shape (must be on EVERY row).
  const mixed = [
    row('Apples #shop', [{ key: 'cost', val: '3' }]),
    row('Bread #shop #urgent', [{ key: 'cost', val: '2' }, { key: 'note', val: 'wholegrain' }]),
  ];
  assert.equal(j(c.inferRowShape(mixed)),
    j({ sharedTags: ['shop'], props: [{ key: 'cost', type: 'number' }], todo: false }),
    'only #shop and cost are shared; #urgent and note are one-offs and excluded');

  // A leading ALL-CAPS #WORD is the status marker (→ to-do), never a content tag.
  const statusTodos = [row('#TODO Call the dentist #errand'), row('#TODO Renew the passport #errand')];
  assert.equal(j(c.inferRowShape(statusTodos)),
    j({ sharedTags: ['errand'], props: [], todo: true }),
    '#TODO is the status marker (to-do), #errand is the content tag');

  // No usable shape → null (under 2 rows, or nothing shared).
  assert.equal(c.inferRowShape([row('lonely #x')]), null, 'under 2 rows → null');
  assert.equal(c.inferRowShape([row('plain text'), row('other text')]), null, 'nothing shared → null');
});

// ── #1428: a commentary line above a list stops taking the list's door with it ───────────────────
// Every starter we ship writes a section the same way: the total or the note on top, the rows under
// it. A key only counts as a column when EVERY row carries it, so that one prose line took the shape
// to null and the + Add door with it. Measured across all 14 starters: 58 of 77 sections had no door.
test('#1428 inferRowShape — a commentary row is not a member of the list it sits above', () => {
  const j = o => JSON.stringify(o);
  const row = (text, props) => (props ? { text, props } : { text });

  // These fixtures use the FOLDED text, because that is what `node.text` holds once a pill exists
  // (rule 1: pills are opaque `[[type:key]]` tokens in text). Written unfolded, the first draft of
  // this pin put `{= sum("#task", hours, document)}` in a prose row -- and `rowContentTags` read the
  // `#task` INSIDE the expression as a tag on that row, so the row survived the filter and the pin
  // failed against correct code. Measuring the wrong text space, in a test about which rows are data.

  // My week / Habits, verbatim in shape: one generated prose line, then four tagged rows.
  const habits = [
    row('One small win, picked for me: [[grammar:g1]]'),
    row('Stretch for five minutes #habit'),
    row('Read ten pages #habit'),
    row('Walk after lunch #habit'),
  ];
  assert.equal(j(c.inferRowShape(habits)), j({ sharedTags: ['habit'], props: [], todo: false }),
    'the prose line carries no tags, props or checkbox, so it says nothing about the shape');

  // Freelance costing / Hours logged: prose AND a health-badge `check` row above the data rows.
  // Both must be dropped, which is why the two halves of this fix are separate (see the next test).
  const hours = [
    row('Logged: [[math:x1]] hrs, billed at [[math:x2]]'),
    row('Am I still inside the quote?', [{ key: 'check', val: 'total <= quote' }]),
    row('Headroom left: [[math:x3]] of the quote.'),
    row('Logo concepts, 3 routes #task', [{ key: 'hours', val: '9' }]),
    row('Brand guidelines PDF #task', [{ key: 'hours', val: '6' }]),
    row('Web mockups #task', [{ key: 'hours', val: '7' }]),
  ];
  assert.equal(j(c.inferRowShape(hours)),
    j({ sharedTags: ['task'], props: [{ key: 'hours', type: 'number' }], todo: false }),
    'the case #1428 reported: three non-data rows above three task rows');

  // THE NEGATIVE, which is the half that keeps this a kind test rather than a tolerance. Dropping a
  // row that carries nothing cannot INVENT a shape, so a section that is all prose still refuses.
  assert.equal(c.inferRowShape([row('Finished this year: {query}'), row('On track: {= pct}')]), null,
    'an all-prose section still has no shape, and therefore still no door');
  assert.equal(c.inferRowShape([row('Apples #shop'), row('a note'), row('another note')]), null,
    'one real row plus commentary is one row, and one row is never a shape');
  // #1281 must survive: the blank row a trailing Enter leaves is still dropped, for its own reason.
  assert.equal(j(c.inferRowShape([row('a #x'), row('b #x'), row('   ')])),
    j({ sharedTags: ['x'], props: [], todo: false }), '#1281: a placeholder row is still not a data row');
});

test('#1428 `check` is app machinery, not a user column — and that half is load-bearing', () => {
  // Reverting ONLY this (dropping 'check' from SHAPE_SKIP_KEYS) leaves the filed report broken: the
  // health-badge row survives the commentary filter, then fails the every-row test for `hours`.
  assert.ok(c.dataPropKeys({ props: [{ key: 'check', val: 'x' }] }).length === 0,
    'a check prop is never a data column');
  for (const k of ['created', 'edited'])
    assert.equal(c.dataPropKeys({ props: [{ key: k, val: '1' }] }).length, 0, `#1281: ${k} is bookkeeping`);
  // JSON, not deepEqual: the cores run in a vm realm, so their arrays fail deepStrictEqual's
  // prototype check even when the contents match. Same idiom the inferRowShape pins above use.
  assert.equal(JSON.stringify(c.dataPropKeys({ props: [{ key: 'hours', val: '9' }, { key: 'check', val: 'x' }] })),
    '["hours"]', 'and a real key beside it still counts');
  assert.equal(JSON.stringify(c.dataPropKeys({})), '[]', 'a node with no props yields none, not a throw');
  // A `check` row on its own can never form a shape, so a section of health badges grows no door.
  assert.equal(c.inferRowShape([{ text: 'A?', props: [{ key: 'check', val: 'a' }] },
    { text: 'B?', props: [{ key: 'check', val: 'b' }] }]), null, 'two check rows are not a list');
  // CALL SITE (#1133): a tested helper proves nothing about whether inferRowShape asks it. Both the
  // row filter and the column collector must go through it, or `check` returns as a column.
  const body = fnBody(NC, 'inferRowShape');
  assert.equal((body.match(/dataPropKeys\(/g) || []).length, 2,
    'both the row filter and the column collector read data props through the one helper');
  assert.ok(!/TIMESTAMP_KEYS/.test(body),
    'and neither reads the narrower timestamp set directly, which would let `check` back in');
});

// The SIBLINGS ratchet (CLAUDE.md). The five sections below are real lists that shipped doorless;
// the shape is inferred from the OPML we actually ship, so re-authoring a section back into the
// broken form fails here rather than silently removing its door again.
// ── #1443: the ancestor-chain walk must be SEEDED, never re-derived per row ─────────────────────
// termMatchesNode takes `ancTagText = ancestorTagText(ancestorsOf(node), …)` as a DEFAULT PARAMETER,
// so omitting the argument re-walks the whole chain. computeMatchSet passes '' on purpose and says
// so. Two siblings did not: pushSearchRows (once per matched row) and the announce counter in
// applySearch (once per node in the subtree) — measured together as 2 chain-walks per node,
// 453,275 stripStateTags calls over 25,000 points, ~54% of search self-time.
// ─── #1512: the outline's global keys leaked through open dialogs ─────────────────────────────
// A DATA-LOSS bug, not a nuisance. Inside the modal Link graph, Shift+ArrowDown built a 4-point
// selection behind the scrim and Backspace took the document from 5 points to 1, while focus never
// left BUTTON.graph-close. Measured again on the File menu. The arrow branch guarded on element
// TYPE (ae.tagName === 'INPUT') and the Delete/Backspace branch had NO focus guard at all.
test('#1512 the outline acts on arrows and Delete only when it owns the keyboard', () => {
  // the handler is an anonymous listener, so the predicate is sliced by its own markers
  const owns = between(_src, 'const outlineOwnsKeys = ()', '  };');

  // TYPE IS THE WRONG PREDICATE, and the old one is gone.
  assert.doesNotMatch(_src, /if \(ae && ae\.tagName === 'INPUT'\) return;/,
    'the tagName guard let every focused BUTTON, DIV and SVG node outside the outline through');

  // A modal layer owns its own keys wherever focus sits: focus SHOULD land inside it, and the
  // popup was measured open with focus still on <body>, which containment cannot tell apart from
  // the row cursor. Layer ROOTS, not one branch per dialog (#io-back is the shared scrim).
  for (const layer of nonEmpty(['bpop', 'io-back'], 'modal layer roots')) {
    assert.ok(owns.includes(`getElementById('${layer}')?.classList.contains('on')`),
      `an open ${layer} means the outline does not own the keys, whatever has focus`);
  }
  assert.match(owns, /graphOpen/, 'and the graph, which raises no shared scrim of its own');

  // CONTAINMENT, not identity. `<body>` is the row-cursor state so it must stay true, but a bare
  // `activeElement === document.body` gate (the Enter branch's rule, which the issue prescribed)
  // would BREAK bulk delete: measured, Shift+ArrowDown moves focus onto the selection action bar,
  // so at the moment Backspace is pressed in the legitimate flow the active element is
  // BUTTON.nsb-btn, not <body>.
  assert.match(owns, /a === document\.body\) return true/, 'the row-cursor state still owns the keys');
  assert.match(owns, /closest\('#outline, #node-sel-bar'\)/,
    'and so does the outline with its own selection chrome, or bulk delete stops working');

  // BOTH branches ask, or the one with no guard is still the one that deletes points.
  assert.match(_src, /\(e\.key==='Delete' \|\| e\.key==='Backspace'\)[^\n]*&& outlineOwnsKeys\(\)/,
    'the delete branch must ask -- it had no focus guard at all, and it is the destructive one');
  assert.match(_src, /if \(!outlineOwnsKeys\(\)\) return;/, 'and so must the arrow branch');
  // exactly the two branches ask (the arrow-key one and the destructive one). The declaration is
  // `const outlineOwnsKeys = () =>` and does not match, so this counts CALL SITES only.
  const asks = nonEmpty(_src.match(/outlineOwnsKeys\(\)/g) || [], 'outlineOwnsKeys call sites');
  assert.equal(asks.length, 2, `both branches ask and nothing else does; found ${asks.length}`);
});

// ─── #1511: a legend row that documents syntax is not a filter chip ───────────────────────────
// wireSearchExamples stamped role=button, roving tabindex and "Add <token> to the search" onto
// EVERY kbd in the legend. Five trailing rows document AUTHORING syntax -- {query:}, {count:},
// {roll:}, {roll folder:} and /querybase -- so activating one pasted a pill body into the search
// box. Measured: three then blamed a token the whitespace tokenizer manufactured ("is:todo} is not
// a filter this app knows... Try is:todo", advice already inside the failing string), and stacking
// one onto a live filter took 2 matching points to 0.
test('#1511 the legend separates its filter chips from its syntax samples', () => {
  // The markup is the source of truth for which rows are which, so read it rather than a count.
  const legend = nonEmpty(between(_src, 'id="search-hint"', '</div>\n      </div>'), 'the search legend markup');
  const kbds = nonEmpty([...legend.matchAll(/<kbd([^>]*)>([\s\S]*?)<\/kbd>/g)], 'legend kbd elements');
  const docs = kbds.filter(m => /\bdata-doc\b/.test(m[1])).map(m => m[2].trim());
  const chips = kbds.filter(m => !/\bdata-doc\b/.test(m[1])).map(m => m[2].trim());

  // IDENTITY, not a bare count: the previous comment said "48" against 49 present, which is exactly
  // what a number in prose does. Name the five, so adding a sixth syntax row has to come past here.
  assert.deepEqual(host(docs.sort()), host([
    '/querybase', '{count: is:todo}', '{query: is:todo}', '{roll folder: #npc}', '{roll: is:todo}',
  ].sort()), 'the syntax-documentation rows are exactly these five');
  assert.ok(chips.length > 30, `and the rest are real filter chips (${chips.length})`);

  // A sample must not LOOK like a door either: same cursor, hover and role was the whole confusion.
  for (const tok of nonEmpty(docs, 'documentation tokens')) {
    assert.ok(/^[{/]/.test(tok),
      `${tok} is documentation, so it should be authoring syntax rather than a filter operator`);
  }
  // ...and no real chip may be a brace body, which is what made these five wrong in the first place
  const braceChips = chips.filter(t => t.startsWith('{') || t.startsWith('/'));
  assert.deepEqual(host(braceChips), [],
    'a chip that pastes a pill body into the search box is not a filter: mark it data-doc');
});

test('#1511 every reader of the chip set honours the marker', () => {
  const wire = fnBody(_src, 'wireSearchExamples');
  // ONE selector, shared. Three handlers and two seeding reads used to name '.sh-row kbd'
  // independently, so a marker honoured by some and not others would be worse than none.
  assert.match(wire, /const CHIP_SEL = '\.sh-row kbd:not\(\[data-doc\]\)';/, 'the one selector exists');
  assert.doesNotMatch(wire, /querySelectorAll\('\.sh-row kbd'\)|closest\('\.sh-row kbd'\)/,
    'and nothing reads the unfiltered set any more: a doc row must not be seeded, roved or activated');
  const uses = nonEmpty(wire.match(/CHIP_SEL/g) || [], 'CHIP_SEL uses');
  assert.ok(uses.length >= 5,
    `the declaration plus every reader (2 seeding, 3 handlers); found ${uses.length}`);
  // the stale number is gone from the prose, since a number in a comment cannot be checked
  assert.doesNotMatch(wire, /These 48 chips/, 'the drift marker is not re-introduced');
});

// ─── #1510: a filter that changes the list under a caret that never moved ─────────────────────
// The concept guide went 94 nav entries -> 18 -> 0 with focus still in its search box and said
// NOTHING at any step: no announce(), no live region anywhere in the dialog. Two more halves came
// with it -- the reading pane kept the previous entry in full beside a "No results" nav, and
// ArrowDown/Enter on the empty state were total no-ops. The builder shipped this in #1474 and the
// document search has always had it; the guide and the File menu were the unbuilt members.
test('#1510 a filter says how many survived, or says the one sentence on screen', () => {
  const F = c.filterResultSay;
  assert.equal(F(18, 'x'), '18 results');
  assert.equal(F(1, 'x'), '1 result', 'singular');
  assert.equal(F(94, 'x'), '94 results');
  // the empty message is passed IN, never re-spelled here: that is what stops the announcement and
  // the screen drifting apart, which #1474 names as the smaller half of its own bug
  assert.equal(F(0, 'No topics match your search.'), 'No topics match your search.');
  assert.equal(F(0, 'No matching action. Clear the search to browse by category.'),
    'No matching action. Clear the search to browse by category.',
    'the File menu keeps its own words, from its own node');
  for (const say of nonEmpty([F(0, 'No topics match your search.'), F(1, 'x'), F(18, 'x')], 'filter sentences')) {
    assert.ok(!/—/.test(say), 'AP punctuation, no em dashes');
    assert.ok(!/\bnode\b/.test(say), 'user-facing copy says point');
  }
});

test('#1510 both filter surfaces speak, read their words off the node, and do not stutter', () => {
  // #1133: the core is pure and proves nothing about whether anything calls it.
  const g = fnBody(_src, 'openGuide');
  assert.match(g, /filterResultSay\(n, guideEmptyMessage\(\)\)/,
    'the guide announces through the shared core, with its own rendered words');
  assert.match(g, /sayFilter\(vis\.length\)/, 'and calls it when the filter changes');
  assert.match(fnBody(_src, 'fmApplySearch'), /fmSayFilter\(total, \(nores\?\.textContent \|\| 'No matching action\.'\)\.trim\(\)\)/,
    'the File menu does the same, from ITS rendered node');
  // read off the RENDERED node, never re-spelled (#1474's rule)
  assert.match(g, /nav\.querySelector\('\.guide-no-results'\)\?\.textContent/,
    'the empty words come from what the nav just painted');
  assert.match(fnBody(_src, 'fmEmptyMessage'), /getElementById\('fm-noresults'\)\?\.textContent/);
  // no stutter: the same result twice must not re-read
  for (const [fn, last] of nonEmpty([['sayFilter', '_lastSaid'], ['fmSayFilter', '_fmLastSaid']], 'say helpers')) {
    assert.ok(fnBody(_src, fn).includes(`if (msg === ${last}) return;`),
      `${fn} must not re-read an unchanged result on every keystroke`);
  }
  // ...and clearing the box must UNLATCH it, or retyping the same query says nothing at all
  assert.match(fnBody(_src, 'fmApplySearch'), /_fmLastSaid = null;/,
    'a cleared filter resets what was last said');

  // the pane must stop showing an entry the filter just excluded
  assert.match(g, /visibleEntries\(\)\.length \? 'Pick a topic on the left\.' : guideEmptyMessage\(\)/,
    'two different nothings: "pick one on the left" is advice the reader cannot take when the left is empty');
  assert.match(g, /else if \(!vis\.length\) activeId = null;/,
    'and the active topic is dropped when nothing matches, or renderPane finds it and paints it in full');

  // a key that cannot act says why, rather than doing nothing (#1474)
  const arrows = nonEmpty(g.match(/else announce\(guideEmptyMessage\(\)\);/g) || [], 'guide empty-key announcements');
  assert.ok(arrows.length >= 1, 'ArrowDown on an empty list speaks');
  assert.match(g, /if \(e\.key === 'Enter'\)[\s\S]{0,140}announce\(guideEmptyMessage\(\)\)/,
    'and so does Enter, which had no handler at all');
});

// ─── #1509: a search count that means something narrower than it says ─────────────────────────
// The count and the empty state were scoped to the zoom root by construction and neither said so.
// Measured: zoomed into "Admin", searching "propagation" announced "0 matching points" and painted
// "Nothing matches" while the document held one; a word present in both subtrees announced
// "1 matching point" while the document held three. Same shape as #1331's "0 here · N in document"
// and WS-2's "Found in other documents · N" -- the third member of a family already twice solved.
test('#1509 the count qualifies itself only when the zoom is actually hiding matches', () => {
  const S = c.searchScopeSay;
  // the two reported cases
  assert.equal(S(0, 1, true), '0 matching points here · 1 in this document');
  assert.equal(S(1, 3, true), '1 matching point here · 3 in this document');
  // THE NEGATIVES, which are what stop this becoming noise on every search
  assert.equal(S(1, 1, true), '1 matching point', 'zoomed with nothing elsewhere reads exactly as before');
  assert.equal(S(0, 0, true), '0 matching points', 'and a genuinely empty document is not qualified either');
  assert.equal(S(2, 9, false), '2 matching points', 'unzoomed never qualifies, whatever the numbers say');
  assert.equal(S(3, 3, false), '3 matching points');
  // singular/plural on both halves
  assert.equal(S(1, 1, false), '1 matching point');
  assert.equal(S(2, 2, false), '2 matching points');
  // a doc count BELOW the scope count cannot happen, and must not produce a nonsense sentence
  assert.equal(S(5, 2, true), '5 matching points', 'a document total under the scope total is not qualified');
  for (const say of nonEmpty([S(0, 1, true), S(1, 3, true), S(1, 1, true)], 'scope sentences')) {
    assert.ok(!/—/.test(say), 'AP punctuation, no em dashes');
    assert.ok(!/\bnode\b/.test(say), 'user-facing copy says point');
  }
});

test('#1509 the empty state says what the zoom is hiding, and only then', () => {
  const E = c.searchEmptySay;
  assert.match(E('propagation', 1, true, false), /^Nothing in this zoom matches/,
    'a zoomed empty state names the zoom, not the document');
  assert.match(E('propagation', 1, true, false), /1 match is elsewhere in this document/);
  assert.match(E('propagation', 3, true, false), /3 matches are elsewhere in this document/, 'and agrees in number');
  assert.match(E('propagation', 1, true, false), /Press Esc to clear$/, 'keeping the recovery it always had');
  // the negatives: unchanged wording everywhere the zoom is not the reason
  assert.equal(E('x', 0, false, false), 'Nothing matches “x”. Press Esc to clear');
  assert.equal(E('x', 0, false, true), 'Nothing in this note matches “x”. Press Esc to clear',
    'the workspace wording is untouched');
  assert.equal(E('x', 0, true, false), 'Nothing matches “x”. Press Esc to clear',
    'zoomed with nothing elsewhere is not blamed on the zoom');
});

test('#1509 the count, the empty state and the way out are all wired', () => {
  // #1133: the cores are pure and prove nothing about whether anything calls them.
  assert.match(fnBody(_src, 'applySearch'), /searchScopeSay\(n, docN, focusedId != null\)/,
    'the announcement uses the scope-aware sentence');
  const rend = fnBody(_src, 'render');
  assert.match(rend, /searchEmptySay\(searchQuery, seDoc, focusedId != null, !!workspaceDir\)/,
    'and so does the empty state');
  // the document count is paid for ONLY when the banner is about to show AND the view is zoomed,
  // so the common path keeps the walk it always had
  assert.match(rend, /const seDoc = \(seShow && focusedId != null\) \? searchMatchCounts\(vp\)\.inDoc : 0;/,
    'the extra walk is gated on the case that needs it');
  // the way out, and it is operable by keyboard: a mousedown-only control is #1021 all over again
  assert.match(rend, /out\.addEventListener\('mousedown'/, 'the zoom-out door works with a mouse');
  assert.match(rend, /out\.addEventListener\('keydown', e => \{ if \(e\.key === 'Enter' \|\| e\.key === ' '\)/,
    'and with a keyboard, beside the mousedown rather than instead of it (the caret invariant)');
  const act = between(rend, 'const act = ()', "out.addEventListener('mousedown'");
  assert.match(act, /focusedId = null/, 'it zooms out');
  assert.doesNotMatch(act, /searchQuery = ''|applySearch\(''\)/, 'and keeps the query, or the door undoes the search too');
  // one closure for both gestures, so they cannot drift into doing different things
  assert.equal((rend.match(/act\(\);/g) || []).length, 2, 'both gestures run the same closure');
});

test('#1443 every per-node search walk threads ancTagText instead of re-deriving it', () => {
  // #1509 moved the announce counter into searchMatchCounts (it now counts the zoom scope and the
  // document in one pass), so the threading rule is asserted on its new home and applySearch is
  // pinned to route through it -- otherwise this guard could go quiet by the counter simply moving.
  for (const fn of ['computeMatchSet', 'pushSearchRows', 'searchMatchCounts']) {
    const body = fnBody(_src, fn);
    assert.ok(/nodeMatchesSearch\(node, anc\)/.test(body),
      `${fn} must pass the threaded ancestor text — omitting it fires termMatchesNode's ancestorsOf default`);
    assert.ok(/needTags \? extendAncTagText\(anc, node\.text, states\) : ''/.test(body),
      `${fn} must extend the chain only when the query has a tag term`);
  }
  // The announce counter is the second bypass and the easiest to forget: it walks EVERY node.
  const apply = fnBody(_src, 'applySearch');
  assert.match(apply, /searchMatchCounts\(vp\)/,
    'the matching-points counter must thread the chain too — it walks every node, not just matches');
  assert.doesNotMatch(apply, /nodeMatchesSearch\(/,
    'and applySearch must not grow a second, unthreaded walk of its own');
  // And nothing may reintroduce a bare per-node call. The remaining bare calls are one-offs on a
  // single live node (an edit commit), which are correct and must stay legal.
  // Bare calls are legal ONLY as one-offs on a single live node (the edit-commit before/after
  // check), where there is no walk to seed and the default's cost is paid once. Pinned by COUNT so
  // a new bare call inside a walk has to come past this test and justify itself.
  const bare = (_src.match(/nodeMatchesSearch\(node\)/g) || []).length;
  assert.equal(bare, 1, 'the only bare call left is the edit-commit one-off; a new one inside a ' +
    'per-node walk reintroduces the ancestor re-walk this fix removed');
});

// ── #1440: the folder write follows the DOCUMENT, not the view ─────────────────────────────────
// Driven on a CLEAN document with a connected folder: toggling the agenda "Done" filter produced a
// full serialize + atomic temp+move write of notes.opml whose body was identical apart from a fresh
// <dateModified>. Ten of the twenty-four scheduleAutosave() call sites are pure view state.
test('#1440 a view-only autosave tick does not rewrite the document file', () => {
  const body = fnBody(_src, 'writeAutosavePayloadNow');
  assert.ok(/if \(workspaceFile && dirty\) flushWorkspaceFile\(\)/.test(body),
    'the folder write must be gated on `dirty` — an agenda filter or a Gantt drag changes no point ' +
    'text, and rewriting the file anyway churns its mtime, wakes folder sync, and re-anchors the ' +
    'staleness guard');
  // Gated at the CALL SITE only. flushWorkspaceFile's other callers are deliberate unconditional
  // writes, and pushing the gate inside would silently break all three.
  const fn = fnBody(_src, 'flushWorkspaceFile');
  assert.ok(!/^\s*if \(!dirty\) return;/m.test(fn),
    'flushWorkspaceFile itself must stay ungated: the reconcile "keep mine" overwrite and the docId ' +
    're-stamp call it directly and must still write');
  // And the deliberate callers are still there to be broken.
  assert.ok(nonEmpty(_src.match(/flushWorkspaceFile\(\)/g) || [], 'flushWorkspaceFile callers').length >= 4,
    'the reconcile, docId-restamp, _wsPending and autosave callers must all survive');
});

// ── #1438 / UXP-329: the keyboard route to "add a row like these" ──────────────────────────────
// The "+ Add" door was mouse-only: every affordance is tabindex="-1" with no keydown path, and
// driving Tab through the outline reaches `.node-content` and never a door. The guided-authoring
// proposal always specified the other half ("via `/` ... exactly like every other command") and it
// was never built -- openAddRowForm had exactly ONE caller, the door itself. So the capability the
// 2026-08 panel called its #1 barrier could not be reached without a mouse, at any verbosity tier.
test('#1438 addRowTarget resolves the list from either caret position', () => {
  const rows = [{ text: 'a' }, { text: 'b' }];
  const list = { text: '## Groceries', children: rows };
  // On the container itself.
  assert.equal(c.addRowTarget(list, null), list);
  // On a row inside it -> its parent owns the list.
  assert.equal(c.addRowTarget(rows[0], list), list);
  // A lone point is not a list, and neither is a one-row parent: two rows are the minimum a shape
  // can be inferred from, which is the same floor maybeAddRowAffordance uses.
  assert.equal(c.addRowTarget({ text: 'x' }, null), null);
  assert.equal(c.addRowTarget({ text: 'x' }, { text: 'p', children: [{ text: 'only' }] }), null);
  assert.equal(c.addRowTarget(null, null), null);
  // A childless node with a qualifying parent still resolves to the parent, not to itself.
  assert.equal(c.addRowTarget({ text: 'x', children: [] }, list), list);
});

test('#1438 the / verb is registered, dispatched, and refuses without a silent no-op', () => {
  const cmd = between(_src, "{ id:'addrow',", '},');
  assert.ok(/label:'Add another'/.test(cmd), 'the verb is named for what it does');
  assert.ok(/section:'Organize'/.test(cmd), 'and filed in a section, so it appears in the menu');
  // The dispatch, not just the registry entry: a command in the list that nothing routes is the
  // shape this whole issue is about.
  const disp = between(_src, "cmd.id === 'addrow'", 'return;\n  }');
  assert.ok(/addRowTarget\(/.test(disp), 'dispatch must resolve the target through the pure core');
  assert.ok(/openAddRowForm\(/.test(disp), 'and open the SAME form the + Add door opens');
  assert.ok(/flashHint\(/.test(disp), 'P4: refusing must say why, never no-op silently');
  // openAddRowForm must now have MORE than one caller -- the door and the verb. One caller was the
  // defect: a capability with a single mouse-only entrance.
  const callers = (_src.match(/openAddRowForm\(/g) || []).length;
  assert.ok(callers >= 3, `openAddRowForm needs the door AND the verb calling it (found ${callers} references)`);
});

// ── #1240 phase 4: the doors of the point you are LOOKING AT ───────────────────────────────────
// Every "+ Add"/"+ Total"/"+ Check"/"+ Variance" door hangs off its PARENT's rendered row. The point
// you are looking at has no row in its own view, so its doors had nowhere to hang. Measured by
// driving the app before building: zoom into "## Groceries" and its three doors vanish; a shaped
// list at the top level of a document never had them at all. The zoom case is the P1 break -- you
// zoom in to work on that list, and the controls for it disappear on arrival.
test('#1240 viewDoorHost: the view hosts the doors only when a row cannot', () => {
  const shaped = { text: 'x', children: [{ text: 'a' }, { text: 'b' }] };
  assert.equal(c.viewDoorHost(shaped), shaped, 'a 2+ row list earns a host');
  // maybeAddRowAffordance needs 2+ rows; anything less can have no shape to infer.
  assert.equal(c.viewDoorHost({ text: 'x', children: [{ text: 'a' }] }), null);
  assert.equal(c.viewDoorHost({ text: 'x', children: [] }), null);
  assert.equal(c.viewDoorHost(null), null);
  assert.equal(c.viewDoorHost(undefined), null);
  // Views that are not the outline: the board replaces the row list, a filtered view is not the
  // list you would be adding to, and a zoomed base is a table widget with its own controls.
  assert.equal(c.viewDoorHost(shaped, { corkOn: true }), null, 'corkboard hosts no row doors');
  assert.equal(c.viewDoorHost(shaped, { searchQuery: 'aldi' }), null, 'a filtered view hosts none');
  assert.equal(c.viewDoorHost({ ...shaped, type: 'base' }), null, 'a zoomed base hosts none');
  // Opts default: called with no second argument it must not throw on a missing options bag.
  assert.doesNotThrow(() => c.viewDoorHost(shaped));
});

test('#1240 phase 4 wiring: the view bar is rendered, refreshed, and reuses the row builders', () => {
  const fn = fnBody(_src, 'renderViewDoors');
  // It must call the SAME builders the row path calls. A copy of their gating would drift, which is
  // the sibling-divergence trap; pin the reuse so a future edit cannot quietly fork it.
  for (const b of ['maybeAddRowAffordance', 'maybeAddFieldAffordance', 'maybeAddCardAffordance'])
    assert.ok(fn.includes(b + '(host, bar)'), `renderViewDoors must reuse ${b}, not reimplement its gating`);
  assert.ok(/if \(!bar\.children\.length\) return null/.test(fn),
    'a bar that earned no doors must not be appended — an ordinary prose outline grows no chrome');
  assert.ok(/role', 'group'/.test(fn) && /aria-label/.test(fn),
    'out of row context the group must say which point it acts on (P3)');
  assert.ok(/#\{1,6\}/.test(fn),
    'the heading markers must be stripped from the label — a reader saying "hash hash Groceries" is syntax leaking into speech');
  // The call site, not just the function: a tested builder proves nothing about whether render calls it.
  assert.ok(/renderViewDoors\(vp, container, \{ corkOn, searchQuery \}\)/.test(_src),
    'render() must call renderViewDoors with the view parent and the view flags');
  // And the refresh path: an edit that makes a column totalable must reach a bar that has no row.
  assert.ok(/refreshViewDoors\(\)/.test(fnBody(_src, 'commitActiveEdit')) || _src.includes('refreshViewDoors();'),
    'a commit must refresh the view bar, which refreshRowChrome cannot reach');
});

// ── the staleness floor's second half: what a floor inside the tree cannot do ────────────────
// The floor ITSELF is already enforced, further down, by "CLAUDE.md's staleness floor stays within
// reach of the actual suite size": it parses the number out of CLAUDE.md, counts the suite's test
// blocks, and ratchets both directions. Do not add a second floor constant here — two floors that
// can disagree is worse than one.
//
// What that guard CANNOT do, by construction: notice that this entire checkout is stale. A base 500
// tests old carries the old CLAUDE.md floor with it, so it compares 1500 against 1400 and passes.
// The number has to come from OUTSIDE the tree. That is the `staleness-floor` CI job, and this pin
// is here so the in-tree half is never mistaken for the whole guard.
test('the CI half of the staleness guard exists and reads a number from outside the tree', () => {
  // The in-tree floor above is structurally blind to its own checkout being stale. That blindness is
  // only acceptable because a second check compares against origin/main. Pin that it is wired, or
  // the limitation quietly becomes the whole story.
  const wf = readFileSync(new URL('../.github/workflows/tests.yml', import.meta.url), 'utf8');
  const job = between(wf, 'staleness-floor:', 'browser-smoke:');
  // Assert on the SHELL LINE, not on prose: the job's own comment says "origin/main" too, so a
  // looser match would stay green if the comparison itself were deleted and only the rationale left.
  assert.ok(/git show origin\/main:tests\/test\.mjs/.test(job),
    'the staleness-floor job must actually read the test count out of origin/main — that external ' +
    'number is the only thing that can see a stale base');
  assert.ok(/exit 1/.test(job), 'and it must fail the build, not just print');
  assert.ok(/fetch-depth:\s*0|fetch --unshallow|git fetch origin main/.test(wf),
    'and it needs the history to read origin/main from, or the comparison silently degrades');
});

// ── #1430: the symbol index, and the two ways a generated map goes quietly wrong ────────────────
// tools/symbol-index.py emits guidance/code-index.md: every top-level declaration grouped by the
// section marker it sits under. CI regenerates it and fails on drift, so STALENESS is covered there.
// What CI's byte-compare cannot see is whether the index is meaningful, which fails two ways:
//   - it silently stops covering things (a registry the index does not know about)
//   - a section marker is deleted or renamed, and its declarations merge into the section above
//     with no diff anywhere that says a region of the file lost its name
// Both are pinned here, against the two real files.
const _codeIndex = readFileSync(new URL('../guidance/code-index.md', import.meta.url), 'utf8');
const _loadCoresSrc = readFileSync(new URL('./load-cores.mjs', import.meta.url), 'utf8');
const _symTool = readFileSync(new URL('../tools/symbol-index.py', import.meta.url), 'utf8');

// The kill-mutation registry (tests/mutants.json). tools/mutation-check.mjs applies each mutant and
// proves the guard it names goes red; this is the FAST half, so a registry that has drifted from the
// code fails in the normal suite instead of waiting for the mutation job.
//
// A mutant whose `find` string no longer matches applies NOTHING, the suite passes, and the runner
// would report the guard as unprotected for a reason that has nothing to do with the guard. That is
// the registry's own vacuity mode, and this is the guard against it.
//
// NOTE for anyone reading a mutation run: while a mutant is applied, THIS test fails too, because
// the tree really is mutated. The runner's contract is that the NAMED guard is among the failures,
// not that it is the only one, so a fail count above 1 is expected and not a problem.
const _mutants = JSON.parse(readFileSync(new URL('./mutants.json', import.meta.url), 'utf8')).mutants;

test('every kill-mutation still anchors to real code and a real guard', () => {
  const ms = nonEmpty(_mutants, 'kill-mutation registry');
  assert.ok(ms.length >= 5, `only ${ms.length} mutants registered; the existence-shaped guards need one each`);
  const sources = {
    'index.html': _src,
    'guidance/code-index.md': _codeIndex,
    // #1465: a CI job's own timeout is mutated too, so add its reader here rather than letting the
    // anchor go unchecked (which this very test exists to prevent).
    '.github/workflows/tests.yml': readFileSync(new URL('../.github/workflows/tests.yml', import.meta.url), 'utf8'),
    // #1559: the layout sweep is code now, so its guards get mutated like any other.
    'tools/layout-sweep.mjs': readFileSync(new URL('../tools/layout-sweep.mjs', import.meta.url), 'utf8'),
    // The solo-RPG census mutates shipped guide content, because that is where its defect lives:
    // a demo's rule declaration and the prose that teaches the form.
    'guide/solo-rpg/cairn/cairn-demo.opml': readFileSync(new URL('../guide/solo-rpg/cairn/cairn-demo.opml', import.meta.url), 'utf8'),
    'guide/solo-rpg/maze-rats/maze-rats-demo.opml': readFileSync(new URL('../guide/solo-rpg/maze-rats/maze-rats-demo.opml', import.meta.url), 'utf8'),
    'guide/solo-rpg/cairn/cairn.md': readFileSync(new URL('../guide/solo-rpg/cairn/cairn.md', import.meta.url), 'utf8'),
    'guide/solo-rpg/ironsworn/ironsworn.md': readFileSync(new URL('../guide/solo-rpg/ironsworn/ironsworn.md', import.meta.url), 'utf8'),
    'guide/solo-rpg/character-sheet/character-sheet-demo.opml': readFileSync(new URL('../guide/solo-rpg/character-sheet/character-sheet-demo.opml', import.meta.url), 'utf8'),
    'guide/solo-rpg/hex-crawl/hex-crawl-demo.opml': readFileSync(new URL('../guide/solo-rpg/hex-crawl/hex-crawl-demo.opml', import.meta.url), 'utf8'),
    'guide/solo-rpg/npc-faction/npc-faction-demo.opml': readFileSync(new URL('../guide/solo-rpg/npc-faction/npc-faction-demo.opml', import.meta.url), 'utf8'),
    'guide/solo-rpg/lonelog/lonelog-demo.opml': readFileSync(new URL('../guide/solo-rpg/lonelog/lonelog-demo.opml', import.meta.url), 'utf8'),
    'guide/solo-rpg/generators/generators-demo.opml': readFileSync(new URL('../guide/solo-rpg/generators/generators-demo.opml', import.meta.url), 'utf8'),
    'guide/solo-rpg/session-prep/session-prep.md': readFileSync(new URL('../guide/solo-rpg/session-prep/session-prep.md', import.meta.url), 'utf8'),
    'guide/solo-rpg/session-prep/session-prep-demo.opml': readFileSync(new URL('../guide/solo-rpg/session-prep/session-prep-demo.opml', import.meta.url), 'utf8'),
  };
  const testNames = readFileSync(new URL('./test.mjs', import.meta.url), 'utf8')
    + readFileSync(new URL('./browser.mjs', import.meta.url), 'utf8');
  const bad = [];
  for (const m of ms) {
    for (const k of ['id', 'suite', 'why', 'file', 'find', 'replace', 'kills'])
      // `replace` may legitimately be EMPTY: deleting a line is a mutation, and often the most
      // honest one -- "the guard is gone" rather than "the guard says something else". Requiring a
      // truthy value forced deletion mutants to anchor on a neighbouring line instead, which makes
      // them brittle to edits that have nothing to do with what they test (#1559). The field must
      // still be DECLARED, so an omitted `replace` is still caught.
      if (k === 'replace' ? !(k in m) : !m[k]) bad.push(`${m.id || '(no id)'}: missing ${k}`);
    if (m.find === m.replace) bad.push(`${m.id}: find and replace are identical, so it mutates nothing`);
    const src = sources[m.file];
    if (src === undefined) { bad.push(`${m.id}: no reader for ${m.file} — add one here or the anchor is unchecked`); continue; }
    const hits = src.split(m.find).length - 1;
    if (hits !== 1) bad.push(`${m.id}: its find string matches ${hits} times in ${m.file}, expected exactly 1`);
    // `kills` must name a guard that exists, or the runner is waiting for a failure that can never come
    if (!testNames.includes(m.kills)) bad.push(`${m.id}: no test name contains ${JSON.stringify(m.kills)}`);
  }
  assert.deepEqual(bad, [],
    'the kill-mutation registry has drifted from the code it mutates. A mutant that no longer ' +
    'applies makes its guard look protected when nothing tested it');

  // The field check above allows an empty `replace` (a deletion). Prove it still catches an
  // OMITTED one, or loosening it would have quietly turned the whole check off.
  const fieldsOf = m => ['id', 'suite', 'why', 'file', 'find', 'replace', 'kills']
    .filter(k => (k === 'replace' ? !(k in m) : !m[k]));
  assert.deepEqual(fieldsOf({ id: 'x', suite: 'unit', why: 'w', file: 'f', find: 'a', replace: '', kills: 'k' }), [],
    'an empty replace is a deletion mutant and must be accepted');
  assert.deepEqual(fieldsOf({ id: 'x', suite: 'unit', why: 'w', file: 'f', find: 'a', kills: 'k' }), ['replace'],
    'an OMITTED replace must still be caught');
  assert.deepEqual(fieldsOf({ id: 'x', suite: 'unit', why: 'w', file: 'f', find: '', replace: 'b', kills: 'k' }), ['find'],
    'an empty find is still a defect -- it would match everywhere');
});

test('#1430 the symbol index covers every pure core the test suite already knows about', () => {
  // Cross-registry parity. `need[]` in load-cores.mjs is the OTHER symbol registry in this repo,
  // and two registries that do not agree are worse than one: a name in `need[]` but absent from the
  // index means the extractor is missing a declaration FORM, not that the function does not exist.
  const needBlock = between(_loadCoresSrc, 'const need = [', '\n  ];');
  const names = nonEmpty([...needBlock.matchAll(/'([A-Za-z_$][\w$]*)'/g)].map(m => m[1]), 'load-cores need[]');
  const indexed = new Set([...nonEmpty([..._codeIndex.matchAll(/^- `([^`]+)`/gm)], 'index entries')]
    .map(m => m[1]));
  const missing = names.filter(n => !indexed.has(n));
  assert.deepEqual(missing, [],
    'every pure core in load-cores need[] must appear in the generated index — a gap here means the ' +
    'extractor cannot see a declaration form, so the map is silently partial');
});

test('#1430 a section losing its marker cannot pass unnoticed', () => {
  // A deleted or renamed marker does not fail the byte-compare in any visible way: the declarations
  // just move under the previous heading and the index still regenerates cleanly. This is the census
  // ratchet for that. Named, not counted -- a count stays green while the wrong sections pass.
  const heads = new Set(nonEmpty([..._codeIndex.matchAll(/^## (.+)$/gm)], 'index sections')
    .map(m => m[1].trim()));
  assert.ok(heads.size >= 120, `expected the file's section markers, found ${heads.size}`);
  for (const want of ['model', 'search', 'markdown', 'doc-cache registry', 'backlinks panel'])
    assert.ok(heads.has(want), `the "${want}" section lost its marker — its declarations have ` +
      'silently merged into the section above it');
  // And the index must actually be grouped: one giant section would regenerate and byte-compare
  // happily while telling a reader nothing.
  const biggest = Math.max(...[...heads].map(h =>
    (between(_codeIndex + '\n## ␀', `## ${h}\n`, '\n## ').match(/^- `/gm) || []).length));
  assert.ok(biggest < 200, `one section holds ${biggest} declarations; the index has stopped grouping`);
});

// #1431: the COARSE tier. The issue asked for banner sections plus a parity check that "every
// top-level declaration lives inside a bannered region". That check, as specified, cannot fail: the
// first banner precedes the first declaration, so every declaration inherits a region by
// construction, and a check that cannot fail is not a check (#1133).
//
// What CAN fail is the inverse, and it is what these pin:
//   - a DOMAIN banner is deleted or renamed, and its sections silently merge into the domain above
//   - a new section lands above the first banner, outside the spine entirely
//   - the tier stops partitioning: one domain swallowing the file regenerates and byte-compares
//     happily while telling a reader nothing, exactly as one giant section would
// Section-to-domain MOVES are caught by CI's byte-compare of the regenerated index, which is what
// makes placing new code a deliberate act rather than a silent inheritance -- the outcome #1431
// actually wanted.
test('#1431 the domain spine partitions the file, and a domain cannot lose its name', () => {
  const doms = nonEmpty([..._codeIndex.matchAll(/^# (?!Code index$)(.+)$/gm)], 'index domains')
    .map(m => m[1].trim());
  assert.equal(new Set(doms).size, doms.length,
    'a domain heading appears twice, so its sections are not contiguous — the spine has interleaved');
  assert.ok(doms.length >= 12 && doms.length <= 30,
    `${doms.length} domains: the coarse tier is meant to be scannable in one screen`);
  // Named, not counted. A count stays green while the wrong domains pass.
  for (const want of ['Document model & caches', 'Render & bases', 'Tree editing & history',
                      'Persistence, workspace & import/export'])
    assert.ok(doms.includes(want), `the "${want}" domain lost its banner — its sections have ` +
      'silently merged into the domain above it');
  // Nothing outside the spine. The extractor labels such sections "(no domain)" rather than
  // hiding them, so this reads that label instead of trusting the banners to cover everything.
  assert.ok(!doms.includes('(no domain)'),
    'a section sits above the first DOMAIN banner, so its declarations are outside the spine');
  // And the tier must actually partition: sections spread across domains, not pooled in one.
  const perDomain = doms.map(d =>
    (between(_codeIndex + '\n#  ', `# ${d}\n`, '\n# ').match(/^## /gm) || []).length);
  assert.ok(Math.min(...perDomain) >= 1, 'a domain holds no sections at all');
  assert.ok(Math.max(...perDomain) <= 40,
    `one domain holds ${Math.max(...perDomain)} sections; the coarse tier has stopped grouping`);
});

test('#1431 the banner spine in index.html is the source the index reads', () => {
  // The generated file could agree with itself forever while index.html carried no banners at all.
  // These read the APP, so the spine has to exist where a person opening the file would see it.
  const banners = nonEmpty([..._src.matchAll(/^\/\/ ═+ DOMAIN: (.+?) ═+$/gm)], 'DOMAIN banners in index.html')
    .map(m => m[1].trim());
  assert.ok(banners.length >= 12, `only ${banners.length} DOMAIN banners in index.html`);
  const doms = new Set(nonEmpty([..._codeIndex.matchAll(/^# (?!Code index$)(.+)$/gm)], 'index domains')
    .map(m => m[1].trim()));
  const drifted = banners.filter(b => !doms.has(b));
  assert.deepEqual(drifted, [],
    'a DOMAIN banner in index.html is absent from the generated index — regenerate it');
  // The two tiers must stay visually distinct, or the spine is unreadable and the regexes collide.
  assert.ok(!/^\/\/ ─+ DOMAIN:/m.test(_src),
    'a DOMAIN banner was written with the fine tier\'s ─ rule; the coarse tier uses ═');
});

test('#1430 the index tool reads the same app block as load-cores, and commits no line numbers', () => {
  // Two tools disagreeing about which <script> is the app is a bug neither would report, so the
  // block signature is pinned to match load-cores.mjs exactly.
  assert.ok(/use strict/.test(_symTool) && /function\\s\+mkNode/.test(_symTool),
    'the extractor must select the app block by the same signature load-cores uses');
  // The repo's navigation doctrine: names, never line numbers, because line numbers drift and names
  // do not. `--with-lines` exists for editing and must stay stdout-only.
  assert.ok(/--with-lines/.test(_symTool), 'the line-number mode exists for local jump-to-symbol');
  assert.ok(!/\(line \d+\)/.test(_codeIndex),
    'the COMMITTED index must carry no line numbers — they drift every edit (architecture-reference)');
  assert.ok(/Do not edit by hand/.test(_codeIndex), 'and it must say it is generated');
});

// ── #1429: a check chip must not assert an outcome its own icon can contradict ──────────────────
// A `check` prop renders as the point's text beside a ✓/✗ glyph, so the text is read AS the verdict.
// "All dates still safe" shipped beside a ✗ the moment a task went overdue: an affirmative claim and
// a failure icon in the same chip, which at a glance reads "everything is fine".
//
// The census is the argument for the fix being copy rather than machinery. Of the 10 shipped check
// labels, NINE already avoid this, in one of three ways -- and this guard is those three ways:
//   a question       "Still standing?"  "Am I still inside the quote?"  "Still within the cap?"
//   quantities       "Spent so far: {= sum(cost)} of {budget := 350}"
//   both states named "(the check goes green when every claim is cited)"
// So the app already had a convention and one line broke it. The issue's other suggestion -- have
// the label FLIP with the icon -- would mean two labels per check, new data model and new syntax,
// to solve a problem the other nine do not have. P5: reuse the convention, do not mint one.
//
// This DETECTS the shape rather than proving neutrality; "state-neutral" is not mechanically
// decidable and this guard does not pretend otherwise (the #1132 precedent for saying so in code).
// What it can do is refuse a bare affirmative declaration, which is exactly what shipped.
test('#1429 every shipped check label survives its own ✗', () => {
  const un = s => String(s).replace(/&quot;/g, '"').replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#39;/g, "'");
  const labels = [];
  for (const m of nonEmpty([..._src.matchAll(/opml:\s*`([\s\S]*?)`/g)], 'shipped starter OPML')) {
    for (const o of m[1].matchAll(/<outline\b([^>]*?)\/?>/g)) {
      const attrs = o[1] || '';
      if (!/\b_props="[^"]*&quot;key&quot;:&quot;check&quot;/.test(attrs)) continue;
      labels.push(un((attrs.match(/\btext="([^"]*)"/) || [])[1] || ''));
    }
  }
  assert.ok(labels.length >= 9, `expected the shipped check labels, found ${labels.length}`);
  for (const t of labels) {
    const asksAQuestion = /\?/.test(t);
    const showsQuantities = /\{/.test(t);
    const namesBothStates = /\b(goes|turns|stays|flips)\s+(green|red)\b/i.test(t);
    assert.ok(asksAQuestion || showsQuantities || namesBothStates,
      `check label "${t}" asserts an outcome its own ✗ can contradict. Ask a question, show the ` +
      `numbers, or say what each state means -- the shape the other shipped checks use.`);
  }
});

test('#1428 census: every shipped list section that should have a door still infers a shape', () => {
  const un = s => String(s).replace(/&quot;/g, '"').replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#39;/g, "'");
  // OPML holds AUTHORED text; the running app holds FOLDED text plus SIDECARS, because loading
  // promotes every `{…}`. Both halves matter and the first draft of this walker only did one:
  //   - `{count: #source}` becomes an opaque token, so its `#source` is NOT a tag on that row.
  //     Read unfolded, the Claims section infers a different shape than the app has.
  //   - `{prop hours: 9}` becomes an entry in `node.props`, NOT a token. Eating it (the first
  //     draft folded everything) silently reduced this ratchet to the tag half, and it went GREEN
  //     when a mutation stripped `#task` off a shipped row -- caught by mutation, which is the only
  //     reason to trust any of this (#1133).
  // So: lift prop/date declarations into props, THEN fold what is left.
  const promote = (t) => {
    const props = [];
    let s = String(t).replace(/\{(prop|date)\s+([^:}]+):\s*([^}]*)\}/gi,
      (_, __, k, v) => { props.push({ key: k.trim(), val: v.trim() }); return ''; });
    let p; do { p = s; s = s.replace(/\{[^{}]*\}/g, '[[x:k]]'); } while (s !== p);
    return { text: s, props };
  };
  // Walk the shipped starter OPML into (heading → its direct child rows), the same tokenising walk
  // the #1107 and child-rollup guards use, so this cannot drift from what ships.
  const sections = [];
  for (const m of nonEmpty([..._src.matchAll(/opml:\s*`([\s\S]*?)`/g)], 'shipped starter OPML')) {
    const toks = [...m[1].matchAll(/<outline\b([^>]*?)(\/?)>|<\/outline>/g)];
    const stack = [];
    for (const t of toks) {
      if (t[0] === '</outline>') { const f = stack.pop(); if (f) sections.push(f); continue; }
      const attrs = t[1] || '';
      const pro = promote(un((attrs.match(/\btext="([^"]*)"/) || [])[1] || ''));
      const text = pro.text;
      let props = pro.props.slice();
      const pm = attrs.match(/\b_props="([^"]*)"/);
      if (pm) { try { props = props.concat(JSON.parse(un(pm[1]))); } catch (_) {} }
      const node = { text, props, kids: [] };
      if (stack.length) stack[stack.length - 1].kids.push(node);
      if (t[2] !== '/') stack.push(node); else if (!stack.length) sections.push(node);
    }
    while (stack.length) sections.push(stack.pop());
  }
  const byHead = new Map();
  for (const s of nonEmpty(sections, 'parsed starter sections'))
    if (/^\s*#{1,6}\s/.test(s.text) && s.kids.length >= 2) byHead.set(s.text.trim(), s.kids);
  // Named rather than counted: a count would stay green while the wrong five passed.
  // Tag AND columns, because a section can keep its tag while silently losing the column that makes
  // its + Total door worth having -- and asserting only the tag is what let the M4 mutation pass.
  const WANT = [
    ['## Habits (tag one as a habit and the nudge learns it)', 'habit', []],
    ['## Claims and their sources (the check goes green when every claim is cited)', 'claim', []],
    ['## Open threads', 'thread', []],
    ['## Hours logged so far', 'task', ['hours']],
    ['## Prototype card set', 'card', ['cost', 'focus']],
  ];
  for (const [head, tag, cols] of WANT) {
    const kids = byHead.get(head);
    assert.ok(kids, `the shipped section "${head}" must still exist (renamed? update this ratchet)`);
    const shape = c.inferRowShape(kids.map(k => ({ text: k.text, props: k.props })));
    assert.ok(shape, `"${head}" is a real list and must infer a shape, or it ships with no + Add door`);
    assert.ok(shape.sharedTags.includes(tag), `"${head}" should share #${tag}, got [${shape.sharedTags}]`);
    const got = shape.props.map(p => p.key);
    for (const col of cols)
      assert.ok(got.includes(col), `"${head}" should offer a ${col} column, got [${got}]`);
  }
});

test('#1240 buildRow — assembles the bullet a filled form produces (fill values, we write the braces)', () => {
  const shape = t => c.inferRowShape(t);
  // expenses
  const exp = shape([
    { text: 'a #august #groceries', props: [{ key: 'cost', val: '1' }] },
    { text: 'b #august #groceries', props: [{ key: 'cost', val: '2' }] },
  ]);
  assert.equal(c.buildRow(exp, { cost: '92.40' }, 'Aldi weekly shop'),
    'Aldi weekly shop #august #groceries {prop cost: 92.40}',
    'the nurse types text + amount; we write the tags and the cost pill');
  // to-do with a date → checkbox prefix + {date …}
  const task = shape([
    { text: '- [ ] a #chore', props: [{ key: 'due', val: '2026-08-06' }] },
    { text: '- [x] b #chore', props: [{ key: 'due', val: '2026-08-01' }] },
  ]);
  assert.equal(c.buildRow(task, { due: '2026-08-10' }, 'Call the plumber'),
    '- [ ] Call the plumber #chore {date due: 2026-08-10}',
    'a to-do row gets the checkbox prefix and the date pill');
  // tag-only shape (cast)
  const cast = shape([{ text: 'A #character' }, { text: 'B #character' }]);
  assert.equal(c.buildRow(cast, {}, 'Lady Ysolde Crane'), 'Lady Ysolde Crane #character');
  // null shape → just the text (fail safe)
  assert.equal(c.buildRow(null, {}, 'just text'), 'just text');
});

test('#1281 "+ Total" door totals a number column with a child-scoped {= sum(KEY)} (no syntax)', () => {
  // the gate: inferRowShape must mark a numeric column as type:number so the door knows what to offer
  const shape = c.inferRowShape([
    { text: 'Hall hire', props: [{ key: 'cost', val: '60' }] },
    { text: 'Insurance', props: [{ key: 'cost', val: '85' }] },
  ]);
  assert.ok(shape.props.some(p => p.key === 'cost' && p.type === 'number'), 'a shared numeric prop is detected');
  // the door wiring (DOM can't run in Node — pin the source shape, like the + Add pins above)
  const aff = fnBody(_src, 'maybeAddRowAffordance');
  assert.match(aff, /filter\(p => p\.type === 'number'\)\.map\(p => p\.key\)/, 'it offers only the number columns');
  assert.match(aff, /node\.text\.replace\(\/\\s\+\$\/, ''\) \+ ' \{= sum\(' \+ key \+ '\)\}'/, 'a + Total appends a child-scoped sum for that column');
  assert.match(aff, /promoteLoadedShorthand\(node\)/, 'it promotes to a live math pill');
  assert.match(aff, /if \(summed\(key\)\) continue/, 'a column already totalled gets no duplicate door');
  // the two supporting doors: property entry surfaced (prim,lean) + a native key datalist
  assert.match(_src, /prim:true, lean:true, icon: PROPS_ICON/, 'Add property is above the fold');
  assert.match(_src, /datalist'\); dl\.id = 'propkey-suggest'[\s\S]{0,140}collectPropKeys\(root\)/, 'the props key input suggests keys already in the doc');
});

test('#1330 row-affordance doors fire on a plain-bullet parent with a number column, not only headings', () => {
  const aff = fnBody(_src, 'maybeAddRowAffordance');
  assert.ok(aff.includes('const isHeading = /^h[1-6]$/.test(deriveTypeFromText(node.text)'), 'heading is a FLAG now, not a hard gate');
  assert.ok(!aff.includes("if (!/^h[1-6]$/.test(deriveTypeFromText(node.text) || '')) return"), 'the heading-only early return is gone (the panel #7 blocker)');
  assert.ok(aff.includes('if (!isHeading && !numKeys.length) return'), 'a non-heading earns a door only when there is a number column to total');
  assert.ok(aff.includes("!node.children.some(c => (c.props || []).length || (c.math || []).length)"), 'a prose/tag outline (no props/math on children) bails cheaply — no door spam');
});

test('#1281 "+ Check" door opens the check dialog with sum(KEY) <= prefilled (the sum/check half)', () => {
  const aff = fnBody(_src, 'maybeAddRowAffordance');
  // A single + Check door on the first number column, only when the heading has no check yet.
  assert.match(aff, /if \(numKeys\.length && !checkExprOf\(node\)\)/, 'the + Check door appears for a number column with no existing check');
  assert.match(aff, /openCheckDialog\(node\.id, null, 'sum\(' \+ numKeys\[0\] \+ '\) <= '\)/, 'it opens the check dialog with the sum written and only the limit left to fill');
  // openCheckDialog accepts and uses that prefill, but an EXISTING check always wins.
  assert.match(_src, /function openCheckDialog\(nodeId, targets = null, prefill = ''\)/, 'openCheckDialog takes a prefill');
  assert.match(fnBody(_src, 'openCheckDialog'), /checkExprOf\(node\) \|\| prefill/, 'an existing check wins; the prefill only seeds a fresh one');
});

test('#1281 residual: reducer chips (avg/count/min/max) + property-key chips build a total by clicking', () => {
  // The five reducers are click chips, not just sum, each inserting fn(prop) with prop selected.
  assert.match(_src, /const REDUCER_CHIPS = \['sum', 'avg', 'count', 'min', 'max'\]\.map/, 'avg/count/min/max join sum as clickable reducers');
  // Property keys come from the document, so a key is picked, never typed; capped so the row never floods.
  assert.match(_src, /function propKeyChips\(\)[\s\S]{0,120}collectPropKeys\(root\)\.slice\(0, 8\)/, 'propKeyChips offers the doc\'s own property keys, capped');
  assert.match(fnBody(_src, 'propKeyChips'), /insertAndSelect\(el, '', k, ''\)/, 'a key chip replaces the selected prop placeholder with the real key');
  // Wired into all three compute dialogs.
  assert.ok(_src.includes('...MATH_CHIPS, ...REDUCER_CHIPS,') && _src.includes('...propKeyChips()]'), 'the math dialog gains the reducers and the keys');
  assert.ok(fnBody(_src, 'openCheckDialog').includes('...propKeyChips()'), 'the check dialog gains the key chips');
  assert.ok(_src.includes('[...EST_CHIPS, ...propKeyChips()]'), 'the estimate dialog gains the key chips');
});

test('#1322 a chip field opens caret-at-end so the first chip does not wipe a prefill', () => {
  // The dialog select-alls the first field on open (good for a name/alias you replace). A chip field is
  // BUILT incrementally, and a chip inserts over the current selection, so a full select-all made the
  // first chip click erase the door's `sum(KEY) <= ` prefill. A chip field must open caret-at-end instead.
  const io = fnBody(_src, 'openInsertDialog');
  assert.ok(io.includes("if (i === 0 && f.chips && f.chips.length) inp.dataset.caretEnd = '1'"),
    'the first field is marked caret-at-end when it carries chips');
  assert.ok(/if \(f\.dataset\.caretEnd\) \{ const p = f\.value\.length; f\.setSelectionRange\(p, p\); \} else f\.select\(\)/.test(io),
    'the focus pass honors the flag: caret-at-end for chip fields, select-all otherwise');
  // the chip inserters splice at the caret (so caret-at-end => append, not replace)
  assert.match(fnBody(_src, 'insertAtCaret'), /el\.value\.slice\(0, s\) \+ text \+ el\.value\.slice\(e\)/, 'insertAtCaret splices at the selection');
  assert.match(fnBody(_src, 'insertAndSelect'), /el\.value\.slice\(0, s\) \+ before/, 'insertAndSelect splices at the selection too');
});

test('#1323 date math gets a visible door: date chips in the @ Math dialog', () => {
  // date computation was syntax-only (the only date door being /due for scheduling). The @ Math dialog now
  // offers today / asdate / daysbetween / addmonths as click chips, beside the reducers, reusing the
  // existing functions (no new syntax).
  assert.ok(_src.includes('const DATE_CHIPS = ['), 'DATE_CHIPS is defined');
  const dc = between(_src, 'const DATE_CHIPS = [', '];');
  for (const fn of ['today', 'asdate(', 'daysbetween(', 'addmonths(']) {
    assert.ok(dc.includes(fn), `the date chips offer ${fn}`);
  }
  assert.ok(dc.includes("insertAndSelect(el, 'asdate(', 'today + 30', ')')"), 'asdate seeds a selected placeholder to replace');
  // wired into the math dialog, after the reducers, before the property keys
  assert.ok(_src.includes('[...MATH_CHIPS, ...REDUCER_CHIPS, ...DATE_CHIPS, ...propKeyChips()]'), 'the math dialog gains the date chips');
  // the functions the chips insert are real evalMath date functions (so a clicked chip computes, not #ERR)
  for (const fn of ['asdate', 'daysbetween', 'addmonths']) {
    assert.ok(c.evalMath(`${fn === 'asdate' ? 'asdate(today)' : fn === 'daysbetween' ? 'daysbetween(today, today)' : 'addmonths(today, 1)'}`, {}) !== null, `${fn} evaluates`);
  }
});

test('#1312 "+ Variance" door writes a per-row over/under and a total variance on a two-column section', () => {
  const aff = fnBody(_src, 'maybeAddRowAffordance');
  assert.match(aff, /if \(numKeys\.length === 2 && /, 'the door appears only on a section with exactly two number columns');
  assert.ok(aff.includes("+ b + ' - ' + a + '}'"), 'each row gets a {= B - A} over/under (a property is a variable, so it reads its own two numbers)');
  assert.ok(aff.includes("sum(' + b + ') - sum(' + a + ')}'"), 'the heading gets the total variance');
  assert.ok(aff.includes('/-\\s*sum\\(/.test'), 'a section that already has a variance (a `- sum(` on the heading) gets no duplicate door');
});

test('#1240 phase 1: the add-row dialog wires the cores to a promoted row (source pin)', () => {
  // The DOM half cannot run headless (it opens a dialog and mutates the live tree), so source-pin the
  // wiring — the pure cores it rides are unit-tested above, and the whole flow was live-driven (a 2-field
  // form produced `Corner shop milk run #august #groceries {prop cost: 13.46}` and moved the month total
  // 718.54 → 732.00). A pin proves the seams are connected; it never proves they run (that was the drive).
  const openForm = fnBody(_src, 'openAddRowForm');
  assert.match(openForm, /inferRowShape\(/, 'reads the shape from the context children');
  assert.match(openForm, /buildRow\(/, 'assembles the row via the pure builder');
  assert.match(openForm, /createPromotedRow\(/, 'and inserts it as a promoted point');
  assert.match(openForm, /openInsertDialog\(/,
    'built on the shared dialog shell (UXP-247), never a hand-rolled shell');
  const createRow = fnBody(_src, 'createPromotedRow');
  assert.match(createRow, /mkNode\(/, 'creates a canonical fresh point');
  assert.match(createRow, /promoteInlineShorthand\(/, 'promotes its {prop}/{date} shorthand to live pills');
  assert.match(createRow, /buildIndex\(/, 'and re-indexes so rollups/searches see the new point');
});

test('#1240 phase 1b: the "+ Add" affordance is wired + verbosity-gated (source pin)', () => {
  // The DOM render cannot run headless; the LIVE three-tier drive is the real proof (Lean must read
  // pixel-identical at rest). This pins the wiring's shape so a regression bites — it never proves it renders.
  const aff = fnBody(_src, 'maybeAddRowAffordance');
  assert.match(aff, /deriveTypeFromText\(node\.text\)/, 'only on a section heading (derived from text, not node.type)');
  assert.match(aff, /inferRowShape\(node\.children/, 'only when the children share a shape');
  assert.match(aff, /openAddRowForm\(node\.id\)/, 'opens the values-only dialog');
  // caret invariant (P3-3): the press must BOTH preventDefault (no focus theft) AND stopPropagation, or
  // the mousedown bubbles to the point's own edit-entry and drops the caret in (the "+ enters edit" bug).
  assert.match(aff, /addEventListener\('mousedown', e => \{ e\.preventDefault\(\); e\.stopPropagation\(\); \}\)/,
    'caret invariant (P3-3): press neither steals focus nor bubbles to the point (no edit-mode on click)');
  assert.match(aff, /'keydown'/, 'a keyboard path sits alongside the pointer one');
  assert.match(aff, /if \(isGuided\(\)\)[\s\S]{0,24}\.title =/, 'the tooltip is Guided-only (Standard/Lean strip it)');
  assert.match(aff, /setAttribute\('aria-label'/, 'the accessible name is kept in every tier');
  assert.match(aff, /fireNudge\(/, 'a Guided-only once-ever nudge points at it (#519)');
  assert.match(fnBody(_src, 'renderRow'), /maybeAddRowAffordance\(node, row\)/, 'renderRow appends it (non-search)');
  // CSS gating: the edit-pencil rule — Lean hides at rest and reveals on keyboard focus, always clickable.
  assert.match(_src, /body\.v-lean \.addrow-affordance\{opacity:0\}/, 'Lean: no at-rest chrome');
  assert.match(_src, /body\.v-lean \.addrow-affordance:focus-visible\{opacity:1\}/, 'Lean: focus reveals it, still clickable');
});

test('#1240 phase 2: blank-scaffold cores for the structured "Add another" (stamp path)', () => {
  const kid = (id, text, children = []) => ({ id, text, children, props: [], seq: [] });
  // richestStructuredSibling: the page with the MOST descendants is the implicit template; null if flat.
  const cast = [
    kid('a', 'Sereth #character', [ kid('a1', 'trait: reads coastlines'), kid('a2', 'debt: owes the guild') ]),
    kid('b', 'Marn #character', [ kid('b1', 'debt: forged papers') ]),
  ];
  assert.equal(c.richestStructuredSibling(cast).id, 'a', 'the richest page (most children) is the template');
  const flat = [ kid('x', 'Aldi #groceries'), kid('y', 'Costco #groceries') ];
  assert.equal(c.richestStructuredSibling(flat), null, 'a flat list has no structured template (→ values form)');
  // A markdown-heading child is a SECTION, not a list-item page — never a stamp template (so "+ Add" on a
  // doc title never offers to stamp a whole section).
  const sections = [ kid('s1', '## Cast', [ kid('s1a', 'a'), kid('s1b', 'b') ]), kid('s2', '## Threads', [ kid('s2a', 'c') ]) ];
  assert.equal(c.richestStructuredSibling(sections), null, 'section headings are excluded from stamp templates');
  // blankScaffoldText: the title keeps only its tags; a "label:" child keeps the label and blanks the value.
  assert.equal(c.blankScaffoldText('Sereth Vale, cartographer #character', true), '#character',
    'the title keeps its tags and drops the specific name');
  assert.equal(c.blankScaffoldText('trait: reads a coastline', false), 'trait: ', 'a label child keeps the label, blanks the value');
  assert.equal(c.blankScaffoldText('who is here:', false), 'who is here: ', 'a bare label ending in a colon is kept');
  assert.equal(c.blankScaffoldText('[[#sereth|]]', false), '', 'a non-label leaf empties');
  // blankScaffoldNode: mutates the whole subtree and clears the sidecars the clone carried.
  const page = kid('p', 'Sereth Vale #character', [ kid('p1', 'trait: reads coastlines') ]);
  page.props = [{ key: 'x', val: '1' }];
  c.blankScaffoldNode(page, true);
  assert.equal(page.text, '#character');
  assert.equal(page.children[0].text, 'trait: ');
  assert.equal(page.props.length, 0, 'sidecars are cleared on the scaffold');
});

