// #811: mtColumnLabel — the per-column label the bullet menu's Column options door
// lists (header text, markdown stripped; a blank or missing header falls back to
// the positional "Column N" so every column stays pickable).
test('mtColumnLabel: header text, markdown stripped, blank fallback', () => {
  const model = { aligns: ['left', 'left', 'left'], rows: [['Name', '**HP**', '  ']] };
  assert.equal(c.mtColumnLabel(model, 0), 'Name');
  assert.equal(c.mtColumnLabel(model, 1), 'HP');          // emphasis stripped
  assert.equal(c.mtColumnLabel(model, 2), 'Column 3');    // blank cell → positional
  assert.equal(c.mtColumnLabel(model, 5), 'Column 6');    // out of range → positional
  assert.equal(c.mtColumnLabel({ aligns: [], rows: [] }, 0), 'Column 1');   // no header row
});

// mtApplyAggregate is DOM-adjacent but its DOM calls no-op through vm stubs,
// so the node.text mutation is fully testable. We verify the stale-value fix:
// setting a column to None must blank its total cell, not leave a stale literal.
const { mtApplyAggregate } = c;
// Helper: minimal node object matching what mtApplyAggregate expects.
function makeTblNode(text) {
  return { id: 'n1', text, dice:[], markov:[], math:[], vars:[], grammar:[] };
}
// Table with two summed columns; footer row has computed values 8 and 10.
const TWO_SUM_TEXT =
  '| A | B |\n| --- | --- |\n| 3 | 4 |\n| 5 | 6 |\n| 8 | 10 |\n' +
  '#+TBLFM: @>$1=vsum(@2$1..@-1$1) :: @>$2=vsum(@2$2..@-1$2)';

test('mtApplyAggregate: None blanks total cell, footer row stays while other aggregate remains', () => {
  const node = makeTblNode(TWO_SUM_TEXT);
  mtApplyAggregate(node, 0, 'none');          // clear col A (0-based index 0 = col1 1)
  const tblfm = c.extractTblfm(node.text);
  const model = c.parseTable(c.stripTblfm(node.text));
  const last  = model.rows[model.rows.length - 1];
  assert.equal(last[0], '');                  // col A blanked — no stale '8'
  assert.equal(last[1], '10');                // col B still computed
  assert.equal(mtHasFooter(tblfm), true);     // footer row still present
  assert.equal(mtColAggKind(tblfm, 1), 'none');
  assert.equal(mtColAggKind(tblfm, 2), 'sum');
});

test('mtApplyAggregate: None on both columns removes the footer row entirely', () => {
  const node = makeTblNode(TWO_SUM_TEXT);
  mtApplyAggregate(node, 0, 'none');
  mtApplyAggregate(node, 1, 'none');
  const tblfm = c.extractTblfm(node.text);
  assert.equal(mtHasFooter(tblfm), false);    // no formulas left → row gone
  const model = c.parseTable(c.stripTblfm(node.text));
  assert.equal(model.rows.length, 3);         // header + 2 data rows only
});

// ── Bases PR 2b: portable copy serializers (frozen markdown vs live recipe) ────
const { baseFrozenMarkdown, baseRecipeMarkdown } = c;
// A base with a column formula computing Total = A*B; the target cells are stored
// blank so the two flavors are clearly distinguishable.
const BASE_COPY_TEXT =
  '| A | B | Total |\n| --- | --- | --- |\n| 2 | 5 |  |\n| 3 | 4 |  |\n#+TBLFM: $3=$1*$2';

test('base copy "as markdown": bakes computed values in, drops the #+TBLFM line', () => {
  const out = baseFrozenMarkdown(BASE_COPY_TEXT);
  assert.match(out, /\| 2 \| 5 \| 10 \|/);    // 2*5 computed into the cell
  assert.match(out, /\| 3 \| 4 \| 12 \|/);    // 3*4 computed into the cell
  assert.ok(!/#\+TBLFM/i.test(out));          // frozen snapshot — recipe removed
});

test('base copy "with TBLFM": keeps raw literals plus the #+TBLFM recipe', () => {
  const out = baseRecipeMarkdown(BASE_COPY_TEXT);
  assert.match(out, /#\+TBLFM: \$3=\$1\*\$2/); // the live recipe is preserved
  assert.ok(!/\b10\b/.test(out));              // target cells stay raw (uncomputed)
  assert.ok(!/\b12\b/.test(out));
});

// ── TODO states + priorities (Org-style headline keyword + [#A] priority) ──────
const { parseTodo, formatTodo, cyclePriority,
        cycleTodoState, cycleTodoPriority, todoSortKey, compareTodo,
        setTodoState, setTodoPriority } = c;

test('todo: parseTodo keyword + priority + body', () => {
  assert.deepEqual(host(parseTodo('#TODO [#A] Buy milk')), { keyword: 'TODO', priority: 'A', body: 'Buy milk' });
  assert.deepEqual(host(parseTodo('#NEXT Ship it')),       { keyword: 'NEXT', priority: null, body: 'Ship it' });
  assert.deepEqual(host(parseTodo('#DONE')),               { keyword: 'DONE', priority: null, body: '' });
  // bare DONE/TODO (no #) is plain text, never a keyword
  assert.deepEqual(host(parseTodo('TODO plain')), { keyword: '', priority: null, body: 'TODO plain' });
  assert.deepEqual(host(parseTodo('DONE shipped')), { keyword: '', priority: null, body: 'DONE shipped' });
});

test('todo: no keyword → empty keyword, whole text as body', () => {
  assert.deepEqual(host(parseTodo('Buy milk')), { keyword: '', priority: null, body: 'Buy milk' });
  assert.deepEqual(host(parseTodo('TODOlist cleanup')), { keyword: '', priority: null, body: 'TODOlist cleanup' });
});

test('todo: tolerant of extra whitespace + lowercase priority', () => {
  assert.deepEqual(host(parseTodo('#TODO   [#b]   tidy')), { keyword: 'TODO', priority: 'B', body: 'tidy' });
});

test('#947 parseTodo — a leading RUN of keywords collapses to the LAST (last typed wins)', () => {
  // typing #NEXT [#B] after a #TODO continuation → NEXT, priority B, clean body (no stray #NEXT hashtag)
  assert.deepEqual(host(parseTodo('#TODO #NEXT [#B] body')), { keyword: 'NEXT', priority: 'B', body: 'body' });
  assert.deepEqual(host(parseTodo('#TODO #WAITING #DONE x')), { keyword: 'DONE', priority: null, body: 'x' }, 'a run of three collapses to the last');
  // a keyword AFTER ordinary text is a mid-sentence hashtag, never collapsed
  assert.deepEqual(host(parseTodo('#TODO call #NEXT week')), { keyword: 'TODO', priority: null, body: 'call #NEXT week' });
  // a single keyword is unchanged
  assert.deepEqual(host(parseTodo('#TODO [#A] Buy milk')), { keyword: 'TODO', priority: 'A', body: 'Buy milk' });
});

test('#947 collapseDoubledKeyword — rewrites a doubled prefix on commit; leaves everything else alone', () => {
  assert.equal(c.collapseDoubledKeyword('#TODO #NEXT [#B] body'), '#NEXT [#B] body');
  assert.equal(c.collapseDoubledKeyword('#TODO body'), '#TODO body', 'a single keyword: unchanged (no whitespace touch)');
  assert.equal(c.collapseDoubledKeyword('#TODO   [#a]   tidy'), '#TODO   [#a]   tidy', 'a single keyword with extra spaces stays byte-for-byte');
  assert.equal(c.collapseDoubledKeyword('plain text'), 'plain text', 'no keyword → unchanged');
  assert.equal(c.collapseDoubledKeyword('#TODO call #NEXT week'), '#TODO call #NEXT week', 'a mid-sentence keyword is not a doubled prefix');
  // it is wired into exitEdit's commit
  assert.ok(/node\.text = collapseDoubledKeyword\(node\.text\);/.test(_src), 'exitEdit collapses a doubled keyword on commit');
});

// agent-review: the app's OTHER to-do dialect collision. Enter after a checkbox task ("- [ ] ")
// pre-fills that same marker into the new sibling; typing a real state keyword there ("#TODO body")
// used to be swallowed as inert task-body text — parseTodo only recognizes a keyword at the very
// start of a string, and the task marker sat in front of it, so the point silently stayed a plain
// unchecked checkbox with "#TODO" as decoration, no visible sign anything failed. Same "retyped
// marker replaces the stale continuation" principle as #947, extended to the OTHER marker pair.
test('agent-review: collapseTaskKeywordCollision — a retyped state keyword replaces a task-marker continuation', () => {
  assert.equal(c.collapseTaskKeywordCollision('- [ ] #TODO Call movers for quotes'), '#TODO Call movers for quotes');
  assert.equal(c.collapseTaskKeywordCollision('- [x] #DONE archived already'), '#DONE archived already', 'a checked box collapses too');
  assert.equal(c.collapseTaskKeywordCollision('- [ ] #TODO #NEXT [#B] body'), '#TODO #NEXT [#B] body',
    'strips only the task marker; a trailing doubled keyword is collapseDoubledKeyword\'s job');
  assert.equal(c.collapseTaskKeywordCollision('- [ ] TodoIsh but not a real keyword'), '- [ ] TodoIsh but not a real keyword',
    'an unrecognized word right after the box is ordinary task text, left alone');
  assert.equal(c.collapseTaskKeywordCollision('- [ ] plain task, no keyword'), '- [ ] plain task, no keyword', 'no keyword → unchanged');
  assert.equal(c.collapseTaskKeywordCollision('#TODO body'), '#TODO body', 'no task marker → nothing to strip (collapseDoubledKeyword\'s domain)');
  assert.equal(c.collapseTaskKeywordCollision('plain text'), 'plain text', 'neither marker → unchanged');
  // chained correctly at the exitEdit chokepoint: task-collision runs BEFORE doubled-keyword, so a
  // compound collision ("- [ ] #TODO #NEXT [#B] body") fully collapses to "#NEXT [#B] body"
  assert.equal(c.collapseDoubledKeyword(c.collapseTaskKeywordCollision('- [ ] #TODO #NEXT [#B] body')), '#NEXT [#B] body');
  assert.ok(/node\.text = collapseTaskKeywordCollision\(node\.text\);\s*\/\/[^\n]*\n\s*node\.text = collapseDoubledKeyword\(node\.text\);/.test(_src),
    'exitEdit runs collapseTaskKeywordCollision BEFORE collapseDoubledKeyword (order matters for the compound case)');
});

test('#941 agenda calendar hides the peeking months’ weekday headers (src pin)', () => {
  assert.ok(_src.includes('.agc-month-prev .agc-dow,.agc-month-next .agc-dow{visibility:hidden}'),
    'the prev/next weekday-header rows are hidden so only the centered month labels weekdays');
});

test('todo: priority bracket may directly abut the keyword (no space)', () => {
  // LEAD_WORD_RE lookahead must accept `[` so `#TODO[#A]` is recognized, not left as plain text.
  assert.deepEqual(host(parseTodo('#TODO[#A] buy milk')), { keyword: 'TODO', priority: 'A', body: 'buy milk' });
  assert.deepEqual(host(parseTodo('#DONE[#C]')), { keyword: 'DONE', priority: 'C', body: '' });
});

test('todo: formatTodo inverts parseTodo (normalized)', () => {
  const round = (s) => formatTodo(parseTodo(s));
  assert.equal(round('#TODO [#A] Buy milk'), '#TODO [#A] Buy milk');
  assert.equal(round('#TODO   [#b]   tidy'), '#TODO [#B] tidy');
  assert.equal(round('#DONE'), '#DONE');
  assert.equal(round('plain text'), 'plain text');
});

test('todo: cyclePriority none → A → B → C → none, and reverse', () => {
  assert.equal(cyclePriority(null), 'A');
  assert.equal(cyclePriority('A'), 'B');
  assert.equal(cyclePriority('C'), null);
  assert.equal(cyclePriority(null, -1), 'C');
});

test('todo: cycleTodoState rewrites text keyword, preserving body + priority', () => {
  assert.equal(cycleTodoState('#TODO [#A] Buy milk'), '#NEXT [#A] Buy milk');
  assert.equal(cycleTodoState('plain task'), '#TODO plain task');
  assert.equal(cycleTodoState('#DONE [#B] wrap up'), 'wrap up');   // clearing drops keyword + priority
});

test('todo: cycleTodoPriority no-op without a keyword', () => {
  assert.equal(cycleTodoPriority('just a note'), 'just a note');
  assert.equal(cycleTodoPriority('#TODO write tests'), '#TODO [#A] write tests');
  assert.equal(cycleTodoPriority('#TODO [#C] write tests'), '#TODO write tests');
});

test('todo: setTodoState direct jump to any state (picker), clamps garbage', () => {
  assert.equal(setTodoState('#TODO [#A] task', 'WAITING'), '#WAITING [#A] task');
  assert.equal(setTodoState('plain task', 'DONE'), '#DONE plain task');
  assert.equal(setTodoState('#TODO [#B] task', ''), 'task');
  assert.equal(setTodoState('#TODO x', 'BOGUS'), 'x');
});

test('todo: setTodoPriority direct jump, no-op without keyword, clamps garbage', () => {
  assert.equal(setTodoPriority('#TODO task', 'C'), '#TODO [#C] task');
  assert.equal(setTodoPriority('#TODO [#A] task', null), '#TODO task');
  assert.equal(setTodoPriority('plain task', 'A'), 'plain task');
  assert.equal(setTodoPriority('#TODO task', 'Z'), '#TODO task');
});

test('todo: todoSortKey + compareTodo (not-done before done, A<B<C<none)', () => {
  assert.deepEqual(host(todoSortKey('#TODO [#A] x')), [0, 0, 0]);
  assert.deepEqual(host(todoSortKey('#DONE x')),      [1, 3, 3]);
  // #510: a no-keyword/unrecognized point sorts after every known state — Infinity,
  // not the default set's length (the last hardcoded TODO_STATES coupling, now gone).
  // (Element-wise, not host()/deepEqual: JSON round-trips Infinity to null, and the
  // array is from the vm realm so deepEqual rejects it as not reference-equal.)
  assert.deepEqual([...todoSortKey('plain')], [0, 3, Infinity]);
  const items = ['#DONE done it', '#TODO [#C] low', '#NEXT [#A] hot', 'plain note'];
  assert.deepEqual(items.slice().sort(compareTodo),
    ['#NEXT [#A] hot', '#TODO [#C] low', 'plain note', '#DONE done it']);
});

test('sortChildrenByProp — sorts children by property, numeric-aware, nulls last', () => {
  const r = c.mkNode('');
  const a = c.mkNode('A'); a.props = [{ key: 'cost', val: '30' }]; r.children.push(a);
  const b = c.mkNode('B'); b.props = [{ key: 'cost', val: '10' }]; r.children.push(b);
  const c2 = c.mkNode('C'); r.children.push(c2);           // no cost prop
  const d = c.mkNode('D'); d.props = [{ key: 'cost', val: '5' }]; r.children.push(d);
  c.buildIndex(r, null);
  c.sortChildrenByProp(r, 'cost');
  assert.deepEqual(host(r.children.map(n => n.text)), ['D', 'B', 'A', 'C']);   // 5, 10, 30, null
});

// ── markdown-first to-dos: type/checked DERIVE from the text ───────────────────
// (only `paragraph` and `base` are special node types; a to-do is its markdown)

test('todo derive: deriveTypeFromText knows both to-do forms (and stays strict)', () => {
  assert.equal(c.deriveTypeFromText('- [ ] buy milk'), 'todo');    // task form
  assert.equal(c.deriveTypeFromText('- [x] done it'),  'todo');
  assert.equal(c.deriveTypeFromText('- [ ] '),         'todo');    // Enter-continuation stub
  assert.equal(c.deriveTypeFromText('#TODO write'),    'todo');    // #keyword form
  assert.equal(c.deriveTypeFromText('#WAITING [#A] x'), 'todo');
  assert.equal(c.deriveTypeFromText('TODO write'),     null);      // bare TODO is NOT a keyword
  assert.equal(c.deriveTypeFromText('WAITING [#A] x'), null);     // bare WAITING is NOT a keyword
  assert.equal(c.deriveTypeFromText('- plain item'),   null);      // plain list ≠ todo
  assert.equal(c.deriveTypeFromText('TODOx not a kw'), null);      // keyword needs a boundary
  assert.equal(c.deriveTypeFromText('# heading'),      'h1');      // existing derivations intact
  assert.equal(c.deriveTypeFromText('> quote'),        'quote');
});

test('starter/OPML load derives block type from text when _type is absent (checkbox bug)', () => {
  // A starter (or hand-written/foreign OPML) authored as `- [ ] task` / `## Heading` with NO _type
  // attribute must load as a NATIVE to-do / heading, not a bare 'ul' whose checkbox is only an
  // inline-markdown lookalike (rendered but without toggle / Show-Done / is:todo behavior). This is
  // exactly the shape the STARTERS use, so it is the shape the derivation must cover.
  assert.equal(c.deriveTypeFromText('- [ ] Recruit six fixers {date due: today+3}'), 'todo', 'a task with a trailing pill still derives to-do');
  assert.equal(c.deriveTypeFromText('- [x] Confirm the hall booking'), 'todo');
  assert.equal(c.todoDoneFromText('- [x] Confirm the hall booking', []), true, 'a `[x]` box loads already checked (empty seqs: box form is static)');
  assert.equal(c.todoDoneFromText('- [ ] Recruit six fixers {date due: today+3}', []), false);
  assert.equal(c.deriveTypeFromText('## The plan [/]'), 'h2', 'a heading with a progress cookie still derives a heading');
  // fromOpml wires it: derive only when _type is ABSENT (an explicit type — para, todo, base — is honored)
  assert.ok(/const typeAttr = el\.getAttribute\('_type'\)/.test(_src), 'fromOpml captures whether _type was present');
  assert.ok(/if \(typeAttr == null\) \{\s*const dt = deriveTypeFromText\(n\.text\);/.test(_src),
    'fromOpml derives the block type from text only when no explicit _type was saved');
  assert.ok(/if \(dt === 'todo'\) n\.checked = todoDoneFromText\(n\.text\)/.test(_src),
    'a derived to-do also derives its checked state from the text');
});

test('todo derive: todoDoneFromText — keyword wins; task form completes as a whole', () => {
  assert.equal(c.todoDoneFromText('#DONE shipped'), true);
  assert.equal(c.todoDoneFromText('#TODO open'),    false);
  assert.equal(c.todoDoneFromText('- [x] single'), true);
  assert.equal(c.todoDoneFromText('- [ ] single'), false);
  assert.equal(c.todoDoneFromText('- [x] a\n- [ ] b'), false); // checklist not complete
  assert.equal(c.todoDoneFromText('- [x] a\n- [x] b'), true);  // all checked → done
  assert.equal(c.todoDoneFromText('plain text'),   false);
  assert.equal(c.todoDoneFromText('DONE shipped'),  false);     // bare DONE is plain text
  assert.equal(c.todoDoneFromText('#DONE - [ ] composed'), true); // #keyword wins over markers
});

test('todo: continuationPrefix — Enter continues the format by writing markdown', () => {
  assert.equal(c.continuationPrefix('- [ ] buy milk'), '- [ ] ');
  assert.equal(c.continuationPrefix('- [x] done it'),  '- [ ] '); // new task starts unchecked
  assert.equal(c.continuationPrefix('#TODO write'),    '#TODO '); // same #keyword continues
  assert.equal(c.continuationPrefix('#WAITING [#A] x'), '#WAITING ');
  assert.equal(c.continuationPrefix('#DONE shipped'),  '#TODO '); // #DONE restarts as #TODO
  assert.equal(c.continuationPrefix('TODO write'),     '');       // bare TODO is plain text
  assert.equal(c.continuationPrefix('> a quote'),      '> ');     // quotes continue too
  assert.equal(c.continuationPrefix('plain text'),     '');       // no aid outside a format
  assert.equal(c.continuationPrefix('# heading'),      '');       // headings don't continue
});

test('todo render: `- [ ]` text renders exactly ONE checkbox via mdToHtml (no rail twin)', () => {
  const open = c.mdToHtml('- [ ] buy milk');
  assert.equal((open.match(/md-task-check/g) || []).length, 1);
  assert.ok(!open.includes('checked'));
  const done = c.mdToHtml('- [x] done it');
  assert.equal((done.match(/md-task-check/g) || []).length, 1);
  assert.ok(done.includes('checked'));
});

test('todo: migrateTodoText — legacy type-only todos get the marker written in', () => {
  assert.equal(c.migrateTodoText('buy milk', false), '- [ ] buy milk');
  assert.equal(c.migrateTodoText('done it', true),   '- [x] done it');
  assert.equal(c.migrateTodoText('- [ ] already', false), '- [ ] already');   // self-consistent → untouched
  assert.equal(c.migrateTodoText('#TODO already', true),  '#TODO already');   // #keyword form → untouched
});

test('todo: textForDisplay strips the task marker and keyword for breadcrumb/search', () => {
  assert.equal(c.textForDisplay({ type: 'todo', text: '- [ ] buy milk' }), 'buy milk');
  assert.equal(c.textForDisplay({ type: 'todo', text: '#WAITING [#A] call' }), 'call');
  assert.equal(c.textForDisplay({ type: 'todo', text: '- [x] TODO composed' }), 'TODO composed'); // bare TODO is body text
  assert.equal(c.textForDisplay({ type: 'h1', text: '# Title' }), 'Title'); // block prefixes intact
  assert.equal(c.textForDisplay({ type: 'ul', text: 'plain' }), 'plain');
});

test('todo OPML: derived type+checked round-trip through _type/_checked attributes', () => {
  const root = c.mkRoot();
  const n = c.mkNode('- [x] shipped', 'todo');
  n.checked = c.todoDoneFromText(n.text);
  root.children.push(n);
  const xml = c.toOpml(root);
  assert.ok(xml.includes('_type="todo"'));
  assert.ok(xml.includes('_checked="true"'));
  assert.ok(xml.includes('- [x] shipped')); // the markdown is the stored source of truth
});

// ── collectCallables / filterBraceCandidates ({ autocomplete data, UXP-9) ───

// One var, one grammar rule, one named table, one named chain.
const mkCallablesRoot = () => {
  const root = c.mkRoot();
  const varNode = c.mkNode('[[var:v1]]');
  varNode.vars = [{ key: 'v1', name: 'strength', expr: '18' }];
  root.children.push(varNode);
  const gramNode = c.mkNode('[[grammar:g1]]');
  gramNode.grammar = [{ key: 'g1', def: 'color: red | blue', origin: 'color', result: 'red' }];
  root.children.push(gramNode);
  // a "roll table" is a one-rule grammar since the collapse — registers as a rule
  const rtNode = c.mkNode('[[grammar:rt1]]');
  rtNode.grammar = [{ key: 'rt1', def: 'loot: 1 gold | 2 silver', origin: 'loot', result: '1 gold' }];
  root.children.push(rtNode);
  const chainNode = c.mkNode('[[markov:mk1]]');
  chainNode.markov = [{ key: 'mk1', name: 'weather', def: 'sunny -> cloudy\ncloudy -> rainy', start: 'sunny', steps: 3 }];
  root.children.push(chainNode);
  return root;
};

test('callables: three groups present, each with expected name (tables are rules since the rolltable collapse)', () => {
  const all = host(c.collectCallables(mkCallablesRoot()));
  assert.ok(all.some(x => x.group === 'var'   && x.name === 'strength'), 'var: strength');
  assert.ok(all.some(x => x.group === 'rule'  && x.name === 'color'),    'rule: color');
  assert.ok(all.some(x => x.group === 'rule'  && x.name === 'loot'),     'rule: loot (a named table IS a rule)');
  assert.ok(all.some(x => x.group === 'chain' && x.name === 'weather'),  'chain: weather');
});

test('callables: var entry carries the resolved numeric value', () => {
  const v = host(c.collectCallables(mkCallablesRoot())).find(x => x.group === 'var');
  assert.equal(v.name, 'strength');
  assert.equal(v.val, 18);
});

test('callables: group order is vars, rules, chains', () => {
  const groups = [...new Set(host(c.collectCallables(mkCallablesRoot())).map(x => x.group))];
  assert.deepEqual(groups, ['var', 'rule', 'chain']);
});

test('callables: a record without its token in node.text is excluded (pruned-data rule)', () => {
  const root = c.mkRoot();
  const n = c.mkNode('no token here');
  n.grammar = [{ key: 'rt9', def: 'ghost: 1 boo', origin: 'ghost', result: '1 boo' }];
  root.children.push(n);
  assert.ok(!host(c.collectCallables(root)).some(x => x.name === 'ghost'));
});

test('callables: empty root yields an empty list', () => {
  assert.equal(host(c.collectCallables(c.mkRoot())).length, 0);
});

test('filterBraceCandidates: empty prefix returns the full list', () => {
  const all = host(c.collectCallables(mkCallablesRoot()));
  assert.equal(host(c.filterBraceCandidates(all, '')).length, all.length);
});

test('filterBraceCandidates: prefix narrows, anchored + case-insensitive', () => {
  const all = host(c.collectCallables(mkCallablesRoot()));
  const r = host(c.filterBraceCandidates(all, 'STR'));
  assert.equal(r.length, 1);
  assert.equal(r[0].name, 'strength');
  // anchored: 'oot' is a substring of 'loot' but not a prefix
  assert.equal(host(c.filterBraceCandidates(all, 'oot')).length, 0);
});

test('filterBraceCandidates: narrowing is monotone as the prefix grows', () => {
  const all = host(c.collectCallables(mkCallablesRoot()));
  const c1 = host(c.filterBraceCandidates(all, 'w')).length;
  const c2 = host(c.filterBraceCandidates(all, 'we')).length;
  const c3 = host(c.filterBraceCandidates(all, 'weather')).length;
  assert.ok(c1 >= c2 && c2 >= c3 && c3 === 1);
  assert.equal(host(c.filterBraceCandidates(all, 'zzz')).length, 0);
});

// ── edit-mode caret anchors + grammar-span bounding (atomic-pill caret) ──
// anchorEditInlines turns the post-inline sentinel (U+0000, emitted after each ATOMIC
// pill span — and ONLY pills, never editable .gr-src spans: an anchor there made
// picker-applied {name} references undeletable, see UXP-28) into a ZWSP caret anchor
// ONLY when no text node follows (next char is another element or end-of-string);
// otherwise it drops the sentinel. The anchor gives the caret a text node to render
// in after a trailing atomic pill. ZWSP = U+200B (stripped by all caret math).
const ZWSP = '​';
const SENT = '␀';

test('anchorEditInlines: trailing sentinel (end of string) -> ZWSP anchor', () => {
  assert.equal(c.anchorEditInlines('<span>x</span>' + SENT), '<span>x</span>' + ZWSP);
});

test('anchorEditInlines: sentinel before another element -> ZWSP anchor (caret between two pills)', () => {
  assert.equal(c.anchorEditInlines('<span>a</span>' + SENT + '<span>b</span>' + SENT),
                                   '<span>a</span>' + ZWSP + '<span>b</span>' + ZWSP);
});

test('anchorEditInlines: sentinel before a text node -> dropped (no dead arrow-stop mid-text)', () => {
  assert.equal(c.anchorEditInlines('<span>x</span>' + SENT + ' beta'), '<span>x</span> beta');
  // escaped text (entity) also counts as following text -> sentinel dropped
  assert.equal(c.anchorEditInlines('<span>x</span>' + SENT + '&lt;tag'), '<span>x</span>&lt;tag');
});

test('anchorEditInlines: no sentinels -> unchanged', () => {
  assert.equal(c.anchorEditInlines('plain <b>text</b>'), 'plain <b>text</b>');
});

test('highlightGrammarText: a promotable {…} is bounded at }, with NO sentinel/anchor', () => {
  // {a|b} promotes (alternation) without needing document vars; the span ends at }
  // and is followed by NOTHING extra — no U+0000 sentinel, no ZWSP anchor. The #45
  // gr-src anchor is reverted (it made picker-applied refs undeletable, UXP-28);
  // anchors are for atomic pills only (emitted by editModeHTML, not here).
  const out = c.highlightGrammarText('{a|b} hello');
  assert.equal(out, '<span class="gr-src">{a|b}</span> hello');
  assert.ok(!out.includes(SENT), 'no U+0000 sentinel after a gr-src span');
  assert.ok(!out.includes(ZWSP), 'no ZWSP anchor after a gr-src span');
  // trailing-span form: still no sentinel/anchor even at end-of-string
  const tail = c.highlightGrammarText('say {a|b}');
  assert.equal(tail, 'say <span class="gr-src">{a|b}</span>');
});

test('highlightGrammarText: an attempted-but-unknown {name} is marked gr-bad (UXP-6)', () => {
  // {nope} reads as a reference attempt but matches no rule/var — it will NOT
  // promote, and that must be visible (a typo signal), not silent.
  const out = c.highlightGrammarText('{nope} tail');
  assert.ok(out.includes('class="gr-src gr-bad"'), 'unknown-name brace gets the gr-bad marker');
  assert.ok(out.includes('>{nope}</span> tail'), 'marker is bounded at }; tail stays plain');
  assert.ok(!out.includes(SENT) && !out.includes(ZWSP), 'no sentinel/anchor after the span');
});

test('highlightGrammarText: prose braces stay literal (no span, no marker)', () => {
  // a body that reads as plain prose (spaces, no formula shape) is the deliberate
  // escape hatch — it gets neither gr-src styling nor the gr-bad marker
  const out = c.highlightGrammarText('{hello world} tail').split(SENT).join('').split(ZWSP).join('');
  assert.ok(!out.includes('gr-src'), 'no span for an intentional literal brace');
});

test('agent-review (#942): checkInlineHighlight restores the caret SYNCHRONOUSLY after the innerHTML rebuild', () => {
  // The live-highlight innerHTML rebuild collapses the selection to offset 0; at very fast typing
  // the next keystrokes arrive before the deferred rAF and insert at 0, scrambling a multi-pill
  // line. A synchronous setCaretByOffset right after the rebuild closes that window. Verified in
  // headless Chromium: 0/30 scrambled at 3ms/char (was ~4/12); this pin guards the fix from regressing.
  // Anchor on checkInlineHighlight's own innerHTML rebuild (the one followed by showBracePreview).
  const anchor = _src.indexOf('content.innerHTML = editModeHTML(node);\n  // #942');
  assert.ok(anchor >= 0, 'the #942 sync-restore comment tags checkInlineHighlight’s innerHTML rebuild');
  const region = _src.slice(anchor, anchor + 900);   // #1133: the last fixed window; no natural end marker here
  const syncIdx = region.indexOf('setCaretByOffset(content, off)');
  const rafIdx = region.indexOf('requestAnimationFrame');
  assert.ok(syncIdx >= 0 && rafIdx >= 0 && syncIdx < rafIdx,
    'a synchronous setCaretByOffset sits between the innerHTML rebuild and the deferred rAF');
});

// ── grSrcSpanClean (UXP-28 normalization predicate) ──
// A live .gr-src span is clean iff its text is exactly one balanced {…} — the only
// shape highlightGrammarText ever emits. Dirty = the browser merged typed/pasted
// chars into the span past }, or the closing } was deleted; normalizeGrSrcSpans
// then re-renders from node.text so the tail re-binds as plain prose.

test('grSrcSpanClean: exactly one balanced brace is clean (incl. nesting)', () => {
  assert.equal(c.grSrcSpanClean('{asas}'), true);
  assert.equal(c.grSrcSpanClean('{a|b 2|c}'), true);
  assert.equal(c.grSrcSpanClean('{= 2*r}'), true);
  assert.equal(c.grSrcSpanClean('{a {b} c}'), true);   // nested braces balance at the end
});

test('grSrcSpanClean: merged tail after } is dirty (the UXP-28 bleed shape)', () => {
  assert.equal(c.grSrcSpanClean('{asas} x'), false);   // typed text joined the span
  assert.equal(c.grSrcSpanClean('{asas}{x}'), false);  // a second brace joined the span
});

test('grSrcSpanClean: broken or misplaced brace is dirty', () => {
  assert.equal(c.grSrcSpanClean('{asas'), false);      // closing } deleted
  assert.equal(c.grSrcSpanClean('x{asas}'), false);    // text before the brace
  assert.equal(c.grSrcSpanClean(''), false);
  assert.equal(c.grSrcSpanClean('plain'), false);
});

// ── Sequences: user-definable state sets (declare via @, apply via /) ────────
// A sequence is { name, states[], doneFrom }: states left of the | are active,
// right of it are done. The built-in TODO/NEXT/WAITING/DONE is the DEFAULT
// sequence; done-ness generalizes from keyword===DONE to "right of the |".

const FLOW = { key: 'q1', name: 'Flow', states: ['BACKLOG', 'DOING', 'SHIPPED'], doneFrom: 2, heldFrom: 2 };
const DEFAULT_SEQ = { key: 'default', name: 'To-do', states: ['TODO', 'NEXT', 'WAITING', 'DONE'], doneFrom: 3 };

test('parseSequence: pipe splits active from done; states uppercased', () => {
  // a one-pipe sequence has no held band → heldFrom === doneFrom (UXP-158)
  assert.deepEqual(host(c.parseSequence('TODO NEXT WAITING | DONE CANCELLED')),
    { states: ['TODO', 'NEXT', 'WAITING', 'DONE', 'CANCELLED'], doneFrom: 3, heldFrom: 3 });
  assert.deepEqual(host(c.parseSequence('backlog doing | shipped')),
    { states: ['BACKLOG', 'DOING', 'SHIPPED'], doneFrom: 2, heldFrom: 2 });
});

test('parseSequence: an optional middle band declares HELD (active | held | done) (UXP-158)', () => {
  assert.deepEqual(host(c.parseSequence('BACKLOG DOING | BLOCKED | SHIPPED')),
    { states: ['BACKLOG', 'DOING', 'BLOCKED', 'SHIPPED'], heldFrom: 2, doneFrom: 3 });
  // multiple held states, multiple done states
  assert.deepEqual(host(c.parseSequence('TODO | WAITING PAUSED | DONE CANCELLED')),
    { states: ['TODO', 'WAITING', 'PAUSED', 'DONE', 'CANCELLED'], heldFrom: 1, doneFrom: 3 });
});

test('keywordIsHeld — structural held-band membership, not a WAITING string match (UXP-158)', () => {
  const def = [{ states: ['TODO', 'NEXT', 'WAITING', 'DONE'], heldFrom: 2, doneFrom: 3 }];  // built-in shape
  assert.equal(c.keywordIsHeld('WAITING', def), true);    // in [heldFrom, doneFrom)
  assert.equal(c.keywordIsHeld('TODO', def), false);      // active
  assert.equal(c.keywordIsHeld('DONE', def), false);      // done, not held
  // a custom sequence's OWN held state works the same way — the whole point of UXP-158
  const flow = [{ states: ['BACKLOG', 'DOING', 'BLOCKED', 'SHIPPED'], heldFrom: 2, doneFrom: 3 }];
  assert.equal(c.keywordIsHeld('BLOCKED', flow), true);
  assert.equal(c.keywordIsHeld('DOING', flow), false);
  // a one-pipe sequence (heldFrom === doneFrom) has NO held states
  const plain = [{ states: ['A', 'B', 'C'], heldFrom: 2, doneFrom: 2 }];
  assert.equal(c.keywordIsHeld('B', plain), false);
});

test('openSeqDialog onSubmit forwards heldFrom, so a dialog-authored held band survives (UXP-160)', () => {
  // the dialog builds its record from parseSequence(def); the onSubmit must carry heldFrom through.
  // src-pin: the onSubmit object includes heldFrom (the regression was it being dropped).
  assert.ok(_src.includes('heldFrom: p.heldFrom }'),
    'openSeqDialog onSubmit must forward heldFrom (UXP-160 regression guard)');
  // contract: the record the dialog produces from a 3-band def carries a live held band,
  // and editing down to one pipe re-derives heldFrom === doneFrom (no stale held band).
  const created = host(c.parseSequence('DOING | BLOCKED | SHIPPED'));
  assert.equal(created.heldFrom, 1);
  assert.equal(created.doneFrom, 2);
  assert.equal(c.keywordIsHeld('BLOCKED', [created]), true);   // BLOCKED reads as held, the whole point
  const edited = host(c.parseSequence('DOING | SHIPPED'));      // edited down to one pipe
  assert.equal(edited.heldFrom, edited.doneFrom);              // no held band survives
});

test('parseSequence: invalid forms return null (callers branch on null)', () => {
  assert.equal(c.parseSequence('TODO DONE'), null);          // no pipe
  assert.equal(c.parseSequence('A | B | C | D'), null);      // three pipes (four bands) — too many
  assert.equal(c.parseSequence(' | DONE'), null);            // empty active side
  assert.equal(c.parseSequence('TODO | '), null);            // empty done side
  assert.equal(c.parseSequence('A | | C'), null);            // empty held band
  assert.equal(c.parseSequence('TO DO! | DONE'), null);      // bad token
  assert.equal(c.parseSequence('A B | A'), null);            // duplicate state
  assert.equal(c.parseSequence('A | A | B'), null);          // duplicate across bands
  assert.equal(c.parseSequence(''), null);
});

test('sequenceLint: flags a whitespace-split state, quiet for single-word states (C5)', () => {
  // tokenizer is unchanged — "IN PROGRESS" silently became 2 states; the lint surfaces it
  const w = c.sequenceLint('OPEN IN PROGRESS | RESOLVED');
  assert.ok(w, 'a multi-word side is flagged');
  assert.match(w, /4 states/);
  assert.match(w, /OPEN, IN, PROGRESS, RESOLVED/);
  // single-word states on each side: nothing to warn about
  assert.equal(c.sequenceLint('BACKLOG | DONE'), null);
  // a parse failure is the dialog's hard error, not the lint's job → null
  assert.equal(c.sequenceLint('no pipe here'), null);
  assert.equal(c.sequenceLint('TODO | '), null);
  // a legit multi-STATE side (the canonical default) reports the split as an informational
  // message (4 states enumerated), NOT a hard error — pin the actual content, not just truthiness
  const lint = c.sequenceLint('TODO NEXT WAITING | DONE');
  assert.match(lint, /4 states: TODO, NEXT, WAITING, DONE/);
});

// ── typed sequence declaration: {seq Flow: BACKLOG DOING | SHIPPED} ──────────
test('seqDeclParts: a named sequence declaration → { name, states, doneFrom, heldFrom }', () => {
  assert.deepEqual(host(c.seqDeclParts('seq Flow: BACKLOG DOING | SHIPPED')),
    { name: 'Flow', states: ['BACKLOG', 'DOING', 'SHIPPED'], doneFrom: 2, heldFrom: 2 });
  assert.deepEqual(host(c.seqDeclParts('seq Review: DRAFT | DONE')),
    { name: 'Review', states: ['DRAFT', 'DONE'], doneFrom: 1, heldFrom: 1 });
  // UXP-158: a held band carries through the declaration
  assert.deepEqual(host(c.seqDeclParts('seq Flow: BACKLOG DOING | BLOCKED | SHIPPED')),
    { name: 'Flow', states: ['BACKLOG', 'DOING', 'BLOCKED', 'SHIPPED'], doneFrom: 3, heldFrom: 2 });
  assert.match(c.seqDeclParts('seq Flow: a | b').name, /Flow/); // name preserves case
});
test('seqDeclParts: NOT a sequence declaration (no false positives)', () => {
  assert.equal(c.seqDeclParts('shuffle: a | b'), null);       // a deck/sequence-mode
  assert.equal(c.seqDeclParts('markov: a→b'), null);          // a typed markov
  assert.equal(c.seqDeclParts('x > 1: a | b'), null);         // a conditional
  assert.equal(c.seqDeclParts('weapon: sword | axe'), null);  // a grammar rule line (no `seq `)
  assert.equal(c.seqDeclParts('seq : A | B'), null);          // no name
  assert.equal(c.seqDeclParts('seq A B: X | Y'), null);       // multi-word name rejected
  assert.equal(c.seqDeclParts('seq Flow: TODO DONE'), null);  // no pipe → not a valid states def
  assert.equal(c.seqDeclParts('seq Flow:'), null);            // empty states
});
test('#1404 both seq doors store the SAME record — spread, never enumerate', () => {
  // Two doors onto one authoring language: `{seq Flow: A | B | C}` typed inline, and the same
  // states entered in the @sequence dialog. The typed door LISTED the parser's fields and so lost
  // heldFrom, while the dialog door spread them and kept it. Driven, before: the typed record had
  // {key,name,states,doneFrom} and the dialog's had those plus heldFrom, and seqDefString handed the
  // author back `CALM WAITING | BROKEN` for a `Calm | Waiting | Broken` they had just typed.
  //
  // This is UXP-160 recurring on the untouched door, so the guard is structural rather than a
  // field list: BOTH builders spread, which makes drift impossible and carries any field the
  // parser gains later.
  const typed = between(NC, 'const sd = seqDeclParts(body);', 'return `[[seq:${rec.key}]]`;');
  assert.ok(/const rec = \{ key: seqKey\(\), \.\.\.sd \};/.test(typed),
    'the typed door spreads the parser record whole');
  assert.ok(!/name: sd\.name/.test(typed), 'and does NOT enumerate its fields, which is how heldFrom was lost');
  assert.ok(/const rec = \{ key: seqKey\(\), \.\.\.r \};/.test(NC),
    'the dialog door still spreads its result too');
  // the parser has carried heldFrom since UXP-158; the record must therefore have it
  const p3 = host(c.seqDeclParts('seq Flow: Calm | Waiting | Broken'));
  assert.equal(p3.heldFrom, 1, 'a two-pipe declaration has a held band');
  assert.equal(p3.doneFrom, 2);
  const p1 = host(c.seqDeclParts('seq Simple: Backlog Doing | Shipped'));
  assert.equal(p1.heldFrom, p1.doneFrom, 'a one-pipe declaration has no held band, and says so structurally');
  // the visible cost: the round trip back to the author's own text
  assert.equal(c.seqDefString({ name: 'Flow', states: ['CALM','WAITING','BROKEN'], doneFrom: 2, heldFrom: 1 }),
    'CALM | WAITING | BROKEN', 'three bands round-trip as three bands');
  assert.equal(c.seqDefString({ name: 'Flow', states: ['CALM','WAITING','BROKEN'], doneFrom: 2 }),
    'CALM WAITING | BROKEN', 'and a record with heldFrom missing is exactly what the author got back before');
});

test('classifyBraceBody / braceTypeLabel — a typed seq decl is a valid seq artifact', () => {
  assert.equal(c.classifyBraceBody('seq Flow: BACKLOG DOING | SHIPPED', {}, {}), 'artifact');
  assert.deepEqual(host(c.braceTypeLabel('seq Flow: BACKLOG DOING | SHIPPED', {}, {})), ['seq', null]);
});

// The separators are the whole difficulty with a sequence: states split on SPACES, bands on `|`.
// Get either wrong and the old behavior was one of two silent failures, depending on whether the
// tail happened to contain a pipe.
const SEQ_BAD = [
  ['seq Growth: Seed, Sprout | Bloom', /spaces, not commas/],        // the reported case
  ['seq Growth: Seed, Sprout, Bud | Bloom', /spaces, not commas/],
  ['seq Flow: TODO DONE', /\| to mark where done begins/],
  ['seq : A | B', /needs a name before the colon/],
  ['seq A B: X | Y', /name has to be one word/],
  ['seq Flow:', /needs its states/],
];

test('a malformed {seq …} is INVALID, not a nonsense pill and not silence', () => {
  for (const [body] of SEQ_BAD) {
    // Before: a tail WITH a pipe reached the alternation branch and promoted to a grammar pill whose
    // two alternatives were the literal strings "seq Growth: Seed, Sprout" and "Bloom" (a coin flip
    // that re-rolled on click). A tail WITHOUT a pipe classified 'literal' and said nothing at all.
    assert.equal(c.classifyBraceBody(body, {}, {}), 'invalid', `${body} must classify invalid`);
    const n = { id: 'n', text: '', grammar: [], seq: [], dice: [], math: [], vars: [], est: [], markov: [], children: [] };
    assert.equal(c.promoteBraceBody(n, body), null, `${body} must not promote`);
    assert.equal((n.grammar || []).length, 0, `${body} must not leave a grammar pill`);
    assert.equal((n.seq || []).length, 0, `${body} must not leave a seq record`);
  }
  // the keyword-commit must not over-reach past its own keyword
  assert.equal(c.classifyBraceBody('shuffle: a | b', {}, {}), 'artifact', 'a deck is untouched');
  assert.equal(c.classifyBraceBody('sequence of events', {}, {}), 'literal', 'prose that merely starts with seq- is prose');
  assert.equal(c.classifyBraceBody('seq Flow: A B | C', {}, {}), 'artifact', 'a valid declaration still promotes');
});

test('the {seq …} cue names the separator, and every form it suggests really parses', () => {
  for (const [body, shape] of SEQ_BAD) {
    const why = c.braceAttemptReason(body, {}, {});
    assert.match(why, shape, `${body}: the cue names the actual fault`);
    assert.ok(!why.includes('—'), `no em dash in the cue for ${body}`);
    // The PR-3 lesson: advice pinned by string match alone is how false copy survives. Feed the
    // suggested form back through the real parser instead.
    const sug = (why.match(/\{seq ([^}]+)\}/) || [])[1];
    assert.ok(sug, `${body}: the cue hands back a concrete form`);
    assert.ok(c.seqDeclParts('seq ' + sug), `${body}: the suggested {seq ${sug}} must actually parse`);
  }
  // the comma fix is mechanical, so the suggestion should be the user's own line, corrected
  assert.match(c.braceAttemptReason('seq Growth: Seed, Sprout | Bloom', {}, {}), /\{seq Growth: Seed Sprout \| Bloom\}/);
  const fixed = c.seqDeclParts('seq Growth: Seed Sprout | Bloom');
  assert.deepEqual(host(fixed.states), ['SEED', 'SPROUT', 'BLOOM'], 'and applying it gives the states the user meant');
  assert.equal(fixed.doneFrom, 2, 'with the band split where they put the bar');
});
test('promoteBraceBody — {seq Name: …} builds a named [[seq:KEY]] record, registered doc-wide', () => {
  const node = { id: 'n1', text: '', seq: [], children: [] };
  const tok = c.promoteBraceBody(node, 'seq Flow: BACKLOG DOING | SHIPPED');
  assert.match(tok, /^\[\[seq:[a-z0-9]+\]\]$/);
  const rec = node.seq[0];
  assert.equal(rec.name, 'Flow');
  assert.deepEqual(host(rec.states), ['BACKLOG', 'DOING', 'SHIPPED']);
  assert.equal(rec.doneFrom, 2);
  // collectSequences picks it up (token in text + named), so its states drive the / menu
  node.text = 'process ' + tok;
  const root = { id: 'r', text: '', seq: [], children: [node] };
  const seqs = c.collectSequences(root);
  assert.equal(seqs.length, 1);
  assert.equal(seqs[0].name, 'Flow');
  // done-ness: right of the | is done, left is not
  const all = [{ key: 'default', name: 'To-do', states: ['TODO', 'DONE'], doneFrom: 1 }, ...seqs];
  assert.equal(c.keywordIsDone('SHIPPED', all), true);
  assert.equal(c.keywordIsDone('BACKLOG', all), false);
});
// ── {rule Name: a | b} — the typed NAMED grammar declaration ──
test('ruleDeclParts — the reserved rule keyword, a name, then a real rule tail', () => {
  assert.deepEqual(host(c.ruleDeclParts('rule rumor: a stranger | a fire')), { name: 'rumor', rhs: 'a stranger | a fire' });
  // nested braces in the tail are the whole point (this body matched NO branch before, and was shredded)
  assert.deepEqual(host(c.ruleDeclParts('rule tavern: The {adj} {noun}')), { name: 'tavern', rhs: 'The {adj} {noun}' });
  // parseRules owns the name charset, so dotted sub-rule fields work for free (A6)
  assert.deepEqual(host(c.ruleDeclParts('rule sword.damage: 1d8')), { name: 'sword.damage', rhs: '1d8' });
  // the name is lowercased to match parseRules' own key normalisation, so {Rumor} and {rumor} agree
  assert.equal(c.ruleDeclParts('rule Rumor: a | b').name, 'rumor');
  // no false positives
  assert.equal(c.ruleDeclParts('rule : a | b'), null, 'a missing name is not a rule');
  assert.equal(c.ruleDeclParts('rule loot:'), null, 'an empty tail is not a rule');
  assert.equal(c.ruleDeclParts('rule 9lives: a | b'), null, 'parseRules rejects a name starting with a digit');
  assert.equal(c.ruleDeclParts('loot: sword | shield 2'), null, 'the keyword is required — a bare rule line is not claimed');
  assert.equal(c.ruleDeclParts('ruler: a | b'), null, 'the keyword needs its space (ruler is a name, not `rule r`)');
  assert.equal(c.ruleDeclParts('rule a: x\nrule b: y'), null, 'multi-rule stays a dialog job (one rule per brace)');
});

test('{rule …} classifies keyword-commit: a broken tail is INVALID, never prose', () => {
  assert.equal(c.classifyBraceBody('rule rumor: a | b', {}, {}), 'artifact');
  assert.equal(c.classifyBraceBody('rule tavern: The {adj} {noun}', {}, {}), 'artifact');
  // committing on the keyword is what stops the shred: 'literal' would let promoteInlineShorthand
  // descend and promote {adj}/{noun} as orphan pills out of a rule the user meant as one unit.
  assert.equal(c.classifyBraceBody('rule : a', {}, {}), 'invalid');
  assert.equal(c.classifyBraceBody('rule loot:', {}, {}), 'invalid');
  assert.equal(c.classifyBraceBody('rule 9x: a', {}, {}), 'invalid');
  // and the cue explains each failure distinctly, in AP style
  assert.match(c.braceAttemptReason('rule : a', {}, {}), /needs a name before the colon/);
  assert.match(c.braceAttemptReason('rule loot:', {}, {}), /needs something after the colon/);
  assert.match(c.braceAttemptReason('rule loot:', {}, {}), /\{rule loot: option \| option\}/);
  for (const b of ['rule : a', 'rule loot:', 'rule 9x: a'])
    assert.ok(!c.braceAttemptReason(b, {}, {}).includes('—'), 'no em dash in ' + b);
  // braceTypeLabel stays in lockstep with classify and names the rule
  assert.deepEqual(host(c.braceTypeLabel('rule rumor: a | b', {}, {})), ['grammar', 'rumor']);
});

test('promoteBraceBody — {rule Name: …} registers a DOCUMENT-WIDE callable rule (the seam)', () => {
  const node = { id: 'n1', text: '', grammar: [], children: [] };
  const tok = c.promoteBraceBody(node, 'rule rumor: a stranger | a fire');
  assert.match(tok, /^\[\[grammar:[a-z0-9]+\]\]$/);
  const rec = node.grammar[0];
  assert.equal(rec.origin, 'rumor');
  assert.equal(rec.typed, true, 'typed marks a text-authored declaration, so it can unfold');
  assert.ok(!rec.anon, 'NOT anon — anon is exactly what keeps a name out of the document namespace');
  // the payoff: another point can call it
  node.text = 'rumors ' + tok;
  const rootNode = { id: 'r', text: '', children: [node] };
  const rules = c.collectRules(rootNode);
  assert.ok(rules.rumor, 'the declared name is registered document-wide');
  const out = c.runGrammar('origin: {rumor}', 'origin', rules, {});
  assert.ok(['a stranger', 'a fire'].includes(out), `{rumor} expands from anywhere, got ${out}`);
  // an anonymous alternation still must NOT leak its synthetic origin (UXP-33 unchanged)
  const anonNode = { id: 'n2', text: '', grammar: [], children: [] };
  const anonTok = c.promoteBraceBody(anonNode, 'a | b');
  anonNode.text = anonTok;
  assert.ok(!('origin' in c.collectRules({ id: 'r2', text: '', children: [anonNode] })),
    'UXP-33 holds: the flag, not the name, is what gates registration');
});

test('{rule …} with nested braces promotes as ONE pill, never shredded into orphans', () => {
  // the pre-fix behavior for this exact body: no branch claimed it, it classified prose, and the
  // walk descended to leave `{tavern: [[grammar:..]] [[grammar:..]]}` — 2 pills + dead braces.
  const node = { id: 'n', text: 'a {rule tavern: The {Rusty|Gilded} {Flagon|Crown}}', grammar: [], dice: [], math: [], vars: [], est: [], markov: [], seq: [], children: [] };
  c.promoteInlineShorthand(node);
  assert.match(node.text, /^a \[\[grammar:[a-z0-9]+\]\]$/, 'exactly one pill, no orphaned braces');
  assert.equal(node.grammar.length, 1);
  assert.equal(node.grammar[0].origin, 'tavern');
  assert.match(node.grammar[0].result, /^The (Rusty|Gilded) (Flagon|Crown)$/);
});

test('the { picker offers the rule form (P2: a visible front door, not syntax-only)', () => {
  const hit = c.filterBraceForms('rule').find(r => r.name === 'rule');
  assert.ok(hit, 'typing {rule offers the rule row');
  assert.equal(hit.insert, '{rule name: a | b | c}');
  assert.equal(hit.guide, 'gen-rules', 'the row deep-links to the entry that documents the form');
  assert.ok(hit.desc && !hit.desc.includes('—'), 'a description, AP-punctuated');
  // the type-to-replace span must cover the NAME, so the first thing you type replaces it
  assert.deepEqual(host(hit.sel), [6, 10]);
  assert.equal(hit.insert.slice(6, 10), 'name', 'the selected span is the placeholder name');
  // reachable by the words a user would actually try
  for (const q of ['rule', 'named', 'table', 'grammar'])
    assert.ok(c.filterBraceForms(q).some(r => r.name === 'rule'), `"${q}" finds the rule form`);
});

test('artifactToShorthand — a TYPED rule pill unfolds; a dialog-named one stays atomic', () => {
  const typed = { key: 'k', def: 'rumor: a | b', origin: 'rumor', result: 'a', typed: true };
  assert.equal(c.artifactToShorthand('grammar', typed), '{rule rumor: a | b}');
  // dotted sub-rule names survive the round trip
  assert.equal(c.artifactToShorthand('grammar', { key: 'k', def: 'sword.damage: 1d8', origin: 'sword.damage', result: '4', typed: true }), '{rule sword.damage: 1d8}');
  // a DIALOG-declared grammar has no `typed` flag: its name lives only on the record, so unfolding
  // would lose it on re-promotion. Unchanged behavior.
  assert.equal(c.artifactToShorthand('grammar', { key: 'k', def: 'rumor: a | b', origin: 'rumor', result: 'a' }), null);
  // multi-rule cannot round-trip through one brace
  assert.equal(c.artifactToShorthand('grammar', { key: 'k', def: 'a: x\nb: y', origin: 'a', result: 'x', typed: true }), null);
  // an anonymous pill still unfolds to its bare source, not to a {rule …}
  assert.equal(c.artifactToShorthand('grammar', { key: 'k', def: 'origin: a | b', origin: 'origin', result: 'a', anon: true }), '{a | b}');
});

test('a typed rule round-trips through unfold and re-promote without losing its name', () => {
  const node = { id: 'n', text: '', grammar: [], dice: [], math: [], vars: [], est: [], markov: [], seq: [], children: [] };
  const tok = c.promoteBraceBody(node, 'rule rumor: a stranger | a fire');
  node.text = 'rumors ' + tok;
  c.unfoldArtifacts(node);
  assert.equal(node.text, 'rumors {rule rumor: a stranger | a fire}', 'unfolds to editable source');
  c.refoldArtifacts(node);
  assert.equal(node.text, 'rumors ' + tok, 'an untouched rule refolds to its original token');
  // and re-promoting the unfolded text still registers the SAME name (the reason unfold is safe)
  const n2 = { id: 'n2', text: '', grammar: [], children: [] };
  c.promoteBraceBody(n2, 'rule rumor: a stranger | a fire');
  assert.equal(n2.grammar[0].origin, 'rumor');
});

test('artifactToShorthand — a seq pill unfolds to its {seq Name: …} source (LEAN FLOOR: edit inline)', () => {
  // a sequence now unfolds so it can be edited keyboard-only. It round-trips LOSSLESSLY: seqDefString
  // re-emits the states/bands, the name comes back via seqDeclParts. No draw state to lose.
  assert.equal(c.artifactToShorthand('seq', { key: 'k', name: 'Flow', states: ['A', 'B'], doneFrom: 1 }), '{seq Flow: A | B}');
  // held band survives too (UXP-158): active | held | done
  assert.equal(c.artifactToShorthand('seq', { key: 'k', name: 'Kanban', states: ['A', 'B', 'C', 'D'], heldFrom: 2, doneFrom: 3 }), '{seq Kanban: A B | C | D}');
  assert.equal(c.artifactToShorthand('seq', { key: 'k' }), null);   // a malformed record (no name/states) doesn't unfold
});
test('LEAN FLOOR: a seq token unfolds in edit mode and refolds losslessly (no dialog to edit)', () => {
  const node = { id: 'n', text: '', seq: [], dice: [], math: [], vars: [], grammar: [], est: [], markov: [], children: [] };
  const tok = c.promoteBraceBody(node, 'seq Flow: BACKLOG DOING | SHIPPED');
  node.text = 'process ' + tok;
  c.unfoldArtifacts(node);                                    // enter edit → the token becomes {seq …} text
  assert.match(node.text, /^process \{seq Flow: BACKLOG DOING \| SHIPPED\}$/, 'seq unfolds to editable {seq …} source');
  c.refoldArtifacts(node);                                    // leave edit untouched → back to the exact token
  assert.equal(node.text, 'process ' + tok, 'an untouched seq refolds to its original token (lossless)');
});

test('artifactToShorthand — a query pill unfolds to its {query: expr} source (LEAN FLOOR: edit inline)', () => {
  assert.equal(c.artifactToShorthand('query', { key: 'k', expr: 'is:todo | due:week' }), '{query: is:todo | due:week}');
  assert.equal(c.artifactToShorthand('query', { key: 'k' }), null);   // no expr → nothing to unfold
});
test('LEAN FLOOR: a query token unfolds in edit mode and refolds losslessly (no dialog to edit)', () => {
  const node = { id: 'n', text: '', query: [], seq: [], dice: [], math: [], vars: [], grammar: [], est: [], markov: [], children: [] };
  const tok = c.promoteBraceBody(node, 'query: is:todo | due:week');
  node.text = 'tasks ' + tok;
  c.unfoldArtifacts(node);                                    // enter edit → the token becomes {query: …} text
  assert.match(node.text, /^tasks \{query: is:todo \| due:week\}$/, 'query unfolds to editable {query: …} source');
  c.refoldArtifacts(node);                                    // leave edit untouched → back to the exact token
  assert.equal(node.text, 'tasks ' + tok, 'an untouched query refolds to its original token (lossless)');
});

test('sequenceForKeyword: first-match across default + declared; default wins collisions', () => {
  const seqs = [DEFAULT_SEQ, FLOW, { key: 'q2', name: 'Clash', states: ['DONE', 'DOING2'], doneFrom: 1 }];
  assert.equal(c.sequenceForKeyword('DOING', seqs).name, 'Flow');
  assert.equal(c.sequenceForKeyword('DONE', seqs).name, 'To-do');  // default first
  assert.equal(c.sequenceForKeyword('NOPE', seqs), null);
  assert.equal(c.sequenceForKeyword('', seqs), null);
});

test('keywordIsDone: done = at-or-right-of the | split, in ANY sequence', () => {
  const seqs = [DEFAULT_SEQ, FLOW];
  assert.equal(c.keywordIsDone('SHIPPED', seqs), true);
  assert.equal(c.keywordIsDone('DOING', seqs), false);
  assert.equal(c.keywordIsDone('BACKLOG', seqs), false);
  assert.equal(c.keywordIsDone('DONE', seqs), true);          // default still works
  assert.equal(c.keywordIsDone('TODO', seqs), false);
  assert.equal(c.keywordIsDone('NOPE', seqs), false);         // non-state is never done
});

test('collectSequences: token-gated walk over node.seq, document order', () => {
  const root = c.mkRoot();
  const a = c.mkNode('[[seq:q1]]');
  a.seq = [FLOW];
  const b = c.mkNode('no token here');                        // record without token → dropped
  b.seq = [{ key: 'q9', name: 'Ghost', states: ['X', 'Y'], doneFrom: 1 }];
  root.children.push(a, b);
  const got = host(c.collectSequences(root));
  assert.equal(got.length, 1);
  assert.equal(got[0].name, 'Flow');
});

test('parseTodo: custom states recognized via an explicit states set', () => {
  const states = new Set(['TODO', 'NEXT', 'WAITING', 'DONE', 'BACKLOG', 'DOING', 'SHIPPED']);
  assert.deepEqual(host(c.parseTodo('#DOING [#A] ship it', states)),
    { keyword: 'DOING', priority: 'A', body: 'ship it' });
  // bare DOING (no #) is not a keyword even when it's in the states set
  assert.deepEqual(host(c.parseTodo('DOING ship it', states)),
    { keyword: '', priority: null, body: 'DOING ship it' });
  // a capitalized word that is NO state in any sequence is not a keyword
  assert.deepEqual(host(c.parseTodo('#URGENT call mom', states)),
    { keyword: '', priority: null, body: '#URGENT call mom' });
});

test('todoDoneFromText: generalized — custom done-state via explicit sequences', () => {
  const seqs = [DEFAULT_SEQ, FLOW];
  assert.equal(c.todoDoneFromText('#SHIPPED v1 release', seqs), true);
  assert.equal(c.todoDoneFromText('#DOING v1 release', seqs), false);
  assert.equal(c.todoDoneFromText('#DONE old way', seqs), true);    // default unchanged
  assert.equal(c.todoDoneFromText('- [x] task', seqs), true);       // task form unchanged
  assert.equal(c.todoDoneFromText('SHIPPED v1 release', seqs), false); // bare SHIPPED is plain text
});

test('continuationPrefix: a done custom state restarts at its sequence FIRST state', () => {
  const seqs = [DEFAULT_SEQ, FLOW];
  assert.equal(c.continuationPrefix('#SHIPPED v1', seqs), '#BACKLOG ');
  assert.equal(c.continuationPrefix('#DOING v1', seqs), '#DOING ');
  assert.equal(c.continuationPrefix('#DONE x', seqs), '#TODO ');   // default pin intact
  assert.equal(c.continuationPrefix('SHIPPED v1', seqs), '');      // bare SHIPPED is plain text
});

test('seqDefString: inverse of parseSequence (modulo spacing)', () => {
  assert.equal(c.seqDefString(FLOW), 'BACKLOG DOING | SHIPPED');
  assert.deepEqual(host(c.parseSequence(c.seqDefString(FLOW))),
    { states: FLOW.states, doneFrom: FLOW.doneFrom, heldFrom: FLOW.heldFrom });
  // UXP-158: a held-band sequence round-trips its middle pipe
  const held = { states: ['BACKLOG', 'DOING', 'BLOCKED', 'SHIPPED'], heldFrom: 2, doneFrom: 3 };
  assert.equal(c.seqDefString(held), 'BACKLOG DOING | BLOCKED | SHIPPED');
  assert.deepEqual(host(c.parseSequence(c.seqDefString(held))), held);
});

test('OPML: a [[seq:KEY]] record serializes into the _seq attribute', () => {
  const root = c.mkRoot();
  const n = c.mkNode('My flow [[seq:q1]]');
  n.seq = [FLOW];
  root.children.push(n);
  const xml = c.toOpml(root);
  assert.ok(xml.includes('_seq='), 'seq sidecar should serialize');
  assert.ok(xml.includes('BACKLOG'), 'states should appear in the attribute');
});

// ── Random variables: a variable whose value is a frozen random pick ─────────
// (guidance/generation-direction.md v1 / brief-pick-variables.md §6)
// The pick rolls via the grammar engine ONLY at declaration / explicit re-roll;
// collectVars returns the stored `rolled` string unchanged on every pass.

test('rollPickSource: alternation source picks deterministically (seeded)', () => {
  c.seedSequence([0]);
  assert.equal(c.rollPickSource('dragon|wyrm|drake', {}, {}), 'dragon');
  c.seedSequence([0.99]);
  assert.equal(c.rollPickSource('dragon|wyrm|drake', {}, {}), 'drake');
  c.resetRandom();
});

test('rollPickSource: weighted alternation respects weights', () => {
  c.seedSequence([0.5]); // weight mass: dragon 3, wyrm 1 → 0.5*4=2 lands in dragon
  assert.equal(c.rollPickSource('dragon 3|wyrm', {}, {}), 'dragon');
  c.resetRandom();
});

// ── A5: item-weight expressions ({a | b {= expr}}) — dynamic odds over vars ──
test('parseAlt: trailing {= expr} is a weight; a bare {= expr} alt stays content', () => {
  assert.deepEqual(host(c.parseAlt('shield {= str}')), { template: 'shield', weightExpr: 'str' });
  assert.deepEqual(host(c.parseAlt('b 2')), { template: 'b', weight: 2 });           // literal weight unchanged
  assert.deepEqual(host(c.parseAlt('plain')), { template: 'plain', weight: 1 });     // default weight
  // a bare computed-value alt has no preceding template → it is NOT a weight
  assert.deepEqual(host(c.parseAlt('{= 2d6}')), { template: '{= 2d6}', weight: 1 });
});

test('pickWeightedAlt: a {= expr} weight resolves against vars at pick time', () => {
  const alts = [c.parseAlt('rare {= luck}'), c.parseAlt('common 1')];
  // luck = 9 → weights 9 vs 1; 0.5*10 = 5 lands in the first (rare)
  c.seedSequence([0.5]);
  try { assert.equal(c.pickWeightedAlt(alts, { luck: 9 }).template, 'rare'); }
  finally { c.resetRandom(); }
  // luck = 0 (via expression) → weight 0 disables it; only 'common' remains
  const alts2 = [c.parseAlt('rare {= luck}'), c.parseAlt('common 1')];
  c.seedSequence([0.0]);
  try { assert.equal(c.pickWeightedAlt(alts2, { luck: 0 }).template, 'common'); }
  finally { c.resetRandom(); }
});

test('pickWeightedAlt: an unresolved weight expr falls back to neutral 1 (alt not dropped)', () => {
  const alts = [c.parseAlt('a {= missing}'), c.parseAlt('b {= missing}')];
  c.seedSequence([0.25]); // both neutral weight 1 → 0.25*2=0.5 lands in the first
  try { assert.equal(c.pickWeightedAlt(alts, {}).template, 'a'); }
  finally { c.resetRandom(); }
});

test('#1354: a weight expression may not span a brace, so a computed value inside a branch survives', () => {
  // The bug: `[\s\S]+?` let the weight capture cross `}`. A conditional/repeat is promoted as
  // `origin: {BODY}`, so the body's OWN closing brace sits at the end of the string and the lazy
  // capture swallowed everything from the first ` {=` to it, truncating the template — which then
  // rendered as a well-formed pill showing a brace-unbalanced fragment, silently (P4).
  const one = s => c.parseRules('origin: ' + s).rules.origin;
  for (const body of [
    '{cost > budget: OVER by {= cost - budget} | under}',   // the persona sentence
    '{1 > 0: {= 1+1} | x}',
    '{1 > 0: x | {= 1+1}}',                                  // the ELSE arm too
    '{2x: {= 1+1}}',                                         // repeat, not just conditional
    '{1 > 0: {= sum(cost)} | x}',
  ]) {
    const alts = one(body);
    assert.equal(alts.length, 1, `${body}: one whole alternative`);
    assert.equal(alts[0].template, body, `${body}: template is the WHOLE body, not a truncated head`);
    assert.equal(alts[0].weightExpr, undefined, `${body}: the inner {= } is a value, not a weight`);
  }
  // The whitespace sensitivity that made it so odd to diagnose: these already worked and must stay working.
  assert.equal(one('{1 > 0:{= 1+1}|x}')[0].template, '{1 > 0:{= 1+1}|x}');
  assert.equal(one('{1 > 0: ({= 1+1}) | x}')[0].template, '{1 > 0: ({= 1+1}) | x}');
});

test('#1354: the A5 dynamic weight itself is untouched — this narrows the capture, it does not remove it', () => {
  // If this goes red the fix has over-reached and killed dynamic odds.
  assert.deepEqual(host(c.parseAlt('shield {= str}')), { template: 'shield', weightExpr: 'str' });
  assert.deepEqual(host(c.parseAlt('The {beast} {= hp}')), { template: 'The {beast}', weightExpr: 'hp' });
  const p = c.parseRules('origin: aa {= hp}|bb 2');   // NB a `0` weight is filtered out by parseRules
  assert.deepEqual(host(p.rules.origin[0]), { template: 'aa', weightExpr: 'hp' });
  assert.deepEqual(host(p.rules.origin[1]), { template: 'bb', weight: 2 });
});

test('#1354: parseAlt and templateAttempt keep the same [^{}] fence (two sites, one rule)', () => {
  // templateAttempt guards the SAME pattern ("trailing {= …} = parseAlt's weight form"). If one
  // site is narrowed and the other is not they disagree about what a weight is, so pin the pair.
  // Assert the WHOLE regex fragment at each site, not just `[^{}]`. A bare `[^{}]` is a string my
  // own explanatory comment also contains, so the first draft of this pin stayed green while the
  // code was reverted — a pin that cannot fail (#1133). Caught by mutation; both arms now bite.
  const body = between(NC, 'function parseAlt(', 'function parseRules(');
  assert.ok(body.includes('{=\\s*([^{}]+?)\\s*\\}'), 'parseAlt fences the weight expression with [^{}]');
  assert.ok(!body.includes('{=\\s*([\\s\\S]+?)'), 'the old brace-spanning capture is gone from parseAlt');
  const ta = fnBody(NC, 'templateAttempt');
  assert.ok(ta.includes('{=\\s*[^{}]*\\}'), 'templateAttempt mirrors the same [^{}] fence');
  assert.ok(!ta.includes('{=\\s*[\\s\\S]*\\}'), 'and does not keep the brace-spanning form');
});

test('parseRules: a rule-level {= expr} dynamic weight is KEPT, not silently dropped', () => {
  // Regression: the filter `a.weight >= 1` dropped dynamic-weight alts (which carry
  // weightExpr, not weight), so `p: peace | war {= w}` lost the war alt entirely.
  const p = c.parseRules('p: peace | war {= w}');
  assert.equal(p.rules.p.length, 2, 'both alternatives survive parse');
  assert.deepEqual(host(p.rules.p[1]), { template: 'war', weightExpr: 'w' });
  // and it actually weights at runtime, matching the inline {a|b {= w}} form
  c.seedSequence([0.5]); // war weight 50 vs peace 1 → mass lands in war
  try { assert.equal(c.runGrammar('p: peace | war {= w}', 'p', null, { w: 50 }), 'war'); }
  finally { c.resetRandom(); }
  // a static 0-weight alt is still dropped (unchanged behavior)
  assert.equal(c.parseRules('p: a | b 0').rules.p.length, 1);
});

test('resolveBrace: a {= expr} weight drives a live alternation through the engine', () => {
  // strong=10 vs weak default 1 → with 0.5 the mass lands in the heavy alt
  c.seedSequence([0.5]);
  try {
    const ctx = { rules: {}, vars: { strong: 10 }, depth: 0, stack: [] };
    assert.equal(c.resolveBrace('hit {= strong} | miss', ctx), 'hit');
  } finally { c.resetRandom(); }
});

// ── yes/no oracle (a weighted-alt recipe; reuses A5 for dynamic odds) ────────
test('oracle: every band is a valid weighted Yes/No alternation with the right bias', () => {
  const bands = ['Yes 19 | No 1', 'Yes 3 | No 1', 'Yes 1 | No 1', 'Yes 1 | No 3', 'Yes 1 | No 19'];
  for (const body of bands) {
    c.seedSequence([0.0]); assert.match(c.rollPickSource(body, {}, {}), /^(Yes|No)$/, body);
    c.resetRandom();
  }
  // "Certain" (Yes 19 | No 1): the low end of the mass is Yes; only the top sliver is No
  c.seedSequence([0.0]);  try { assert.equal(c.rollPickSource('Yes 19 | No 1', {}, {}), 'Yes'); } finally { c.resetRandom(); }
  c.seedSequence([0.99]); try { assert.equal(c.rollPickSource('Yes 19 | No 1', {}, {}), 'No'); }  finally { c.resetRandom(); }
  // "Impossible" inverts the bias
  c.seedSequence([0.99]); try { assert.equal(c.rollPickSource('Yes 1 | No 19', {}, {}), 'No'); }  finally { c.resetRandom(); }
});

test('oracle: dynamic odds — a {= expr} weight reads a variable (A5 inside the oracle body)', () => {
  // luck=20 vs No 1 → almost always Yes; with 0.0 the mass lands in Yes
  c.seedSequence([0.0]);
  try { assert.equal(c.rollPickSource('Yes {= luck} | No 1', {}, { luck: 20 }), 'Yes'); }
  finally { c.resetRandom(); }
});

test('oracle: front-door wiring (src pins)', () => {
  assert.ok(_src.includes("id:'oracle'"), 'oracle @ menu entry missing');
  assert.ok(_src.includes("id === 'oracle'"), 'oracle insert dispatch missing');
  assert.ok(_src.includes('function openOracleDialog('), 'oracle dialog missing');
  assert.ok(_src.includes('ORACLE_BANDS'), 'oracle likelihood bands missing');
});

test('deck door uses its own dialog (regression: openSeqDialog name collision)', () => {
  // A4 named the deck dialog `openSeqDialog`, colliding with the pre-existing
  // state-set sequence dialog of the same name. Function declarations hoist, so the
  // later (state-set) one won and the deck @-door silently opened the WRONG dialog —
  // its Insert button stayed disabled (the deck `body` param was ignored). The deck
  // dialog is now `openDeckDialog`; these pins keep the names from colliding again.
  assert.equal((_src.match(/function openSeqDialog\(/g) || []).length, 1, 'exactly one openSeqDialog (no shadowing)');
  assert.equal((_src.match(/function openDeckDialog\(/g) || []).length, 1, 'exactly one openDeckDialog');
  assert.match(_src, /id === 'deck'[\s\S]{0,120}openDeckDialog\(/, 'deck dispatch must call openDeckDialog, not openSeqDialog');
});

test('@-dialog insert keeps its sidecar record (regression: mid-insert prune dropped it)', () => {
  // Every @-menu dialog door (dice/grammar/deck/oracle/…) pushes a sidecar record then
  // calls applyInlineInsertion. That flushes the active edit via ed.blur() → exitEdit,
  // which serialized the BUFFER (without the not-yet-spliced token) to node.text and
  // pruned the just-pushed record → a broken "missing data" pill that only entered edit
  // mode on click. The flush now suppresses pruning; the next real exit prunes normally.
  assert.ok(_src.includes('_suppressPruneOnFlush'), 'prune-suppression flag missing');
  assert.match(_src, /_suppressPruneOnFlush = true;\s*ed\.blur\(\);\s*_suppressPruneOnFlush = false;/, 'flush must wrap ed.blur() in the suppression flag');
  // #1507 kept the flag and captured what the prune dropped, so the shape moved from a bare `if` to a
  // ternary that yields the dropped records. Same claim: a mid-insert flush must not prune.
  assert.match(_src, /_suppressPruneOnFlush \? null : pruneArtifacts\(node\)/, 'exitEdit prune must honor the flag');
  assert.match(fnBody(_src, 'pruneArtifacts'), /pruneGrammar\(node\)/, 'pruneArtifacts bundles the per-type prunes incl. pruneGrammar');
});

test('rollPickSource: dice source rolls through the dice core', () => {
  c.seedSequence([0]); // every die rolls its minimum
  assert.equal(c.rollPickSource('2d6', {}, {}), '2');
  c.resetRandom();
});

test('rollPickSource: template source expands embedded braces', () => {
  const rules = {
    color: [{ template: 'red', weight: 1 }],
    beast: [{ template: 'cat', weight: 1 }],
  };
  c.seedSequence([0]);
  assert.equal(c.rollPickSource('{color} {beast}', rules, {}), 'red cat');
  c.resetRandom();
});

test('agent-review: rollPickSource expands a brace-wrapped GLUE template value ({{a|b}{c|d}}), not the raw grammar', () => {
  // A glue-template var value ({hero := {{Ael|Bor}{ric|wyn}}}) stores the source fully brace-wrapped;
  // the outer wrapper must be stripped so the inner glue expands (was frozen as raw `{Ael|Bor}{ric|wyn}`).
  c.seedSequence([0, 0]);
  assert.equal(c.rollPickSource('{{Ael|Bor}{ric|wyn}}', {}, {}), 'Aelric');
  c.resetRandom();
  // a fully-wrapped simple body is untouched (inner has no brace): {a|b} still alternates, {2d6} still rolls
  c.seedSequence([0]); assert.equal(c.rollPickSource('{dragon|wyrm}', {}, {}), 'dragon'); c.resetRandom();
});

test('rollPickSource: bare name resolves a rule, then a variable, else marker', () => {
  const rules = { color: [{ template: 'blue', weight: 1 }] };
  c.seedSequence([0]);
  assert.equal(c.rollPickSource('color', rules, {}), 'blue');
  assert.equal(c.rollPickSource('width', {}, { width: 42 }), '42');
  assert.equal(c.rollPickSource('nosuch', {}, {}), '{nosuch?}'); // visible-failure marker
  c.resetRandom();
});

test('rollPickSource: a quoted bare word is a literal string, not a rule lookup', () => {
  const rules = { hello: [{ template: 'ROLLED', weight: 1 }] };
  c.seedSequence([0]);
  // unquoted bare word still does a rule lookup (predictable, unchanged)
  assert.equal(c.rollPickSource('hello', rules, {}), 'ROLLED');
  // quotes force the literal — the escape hatch for {label := "hello"}
  assert.equal(c.rollPickSource('"hello"', rules, {}), 'hello');
  assert.equal(c.rollPickSource("'hello'", rules, {}), 'hello');
  // a word with no matching rule: bare → marker, quoted → the literal text
  assert.equal(c.rollPickSource('nosuch', {}, {}), '{nosuch?}');
  assert.equal(c.rollPickSource('"nosuch"', {}, {}), 'nosuch');
  // nested {…} still expands inside a quoted literal (a text frame, not a dead end)
  assert.equal(c.rollPickSource('"say {hello}"', rules, {}), 'say ROLLED');
  c.resetRandom();
});

test('rollPickSource: empty source → null (callers branch on null)', () => {
  assert.equal(c.rollPickSource('', {}, {}), null);
  assert.equal(c.rollPickSource('   ', {}, {}), null);
});

// Build a tree with one pick declaration + (optionally) other var declarations.
const mkPickRoot = (recs) => {
  const root = c.mkRoot();
  for (const rec of recs) {
    const n = c.mkNode(`[[var:${rec.key}]]`);
    n.vars = [rec];
    root.children.push(n);
  }
  return root;
};

test('collectVars: a pick contributes its FROZEN rolled string (no evaluation)', () => {
  const root = mkPickRoot([{ key: 'p1', name: 'beast', kind: 'pick', expr: 'dragon|wyrm', rolled: 'wyrm' }]);
  const vars = c.collectVars(root);
  assert.equal(vars.beast, 'wyrm');
});

test('collectVars: repeated resolution never re-rolls (frozen across passes)', () => {
  const rec = { key: 'p1', name: 'beast', kind: 'pick', expr: 'dragon|wyrm|drake', rolled: 'drake' };
  const root = mkPickRoot([rec]);
  // a moving RNG would change the value IF the engine ran — it must not
  c.seedSequence([0.1, 0.5, 0.9, 0.3]);
  const a = c.collectVars(root).beast;
  const b = c.collectVars(root).beast;
  const d = c.collectVars(root).beast;
  c.resetRandom();
  assert.equal(a, 'drake');
  assert.equal(b, 'drake');
  assert.equal(d, 'drake');
  assert.equal(rec.rolled, 'drake'); // the stored record is untouched
});

test('collectVars: re-roll = update rolled, every reference resolves the new value', () => {
  const rec = { key: 'p1', name: 'beast', kind: 'pick', expr: 'dragon|wyrm', rolled: 'dragon' };
  const root = mkPickRoot([rec]);
  assert.equal(c.collectVars(root).beast, 'dragon');
  rec.rolled = 'wyrm'; // what rerollPickVar does
  assert.equal(c.collectVars(root).beast, 'wyrm');
});

test('collectVars: mixed map — numbers for formula vars, strings for picks', () => {
  const root = mkPickRoot([
    { key: 'm1', name: 'hp', expr: '10' },
    { key: 'p1', name: 'beast', kind: 'pick', expr: 'dragon|wyrm', rolled: 'dragon' },
  ]);
  const vars = c.collectVars(root);
  assert.equal(vars.hp, 10);
  assert.equal(vars.beast, 'dragon');
});

test('collectVars: a formula var referencing a pick fails VISIBLY (absent), not silently', () => {
  const root = mkPickRoot([
    { key: 'p1', name: 'beast', kind: 'pick', expr: 'dragon|wyrm', rolled: 'dragon' },
    { key: 'm1', name: 'dmg', expr: 'beast*2' }, // text in math — must not compute
  ]);
  const vars = c.collectVars(root);
  assert.equal(vars.beast, 'dragon'); // pick is fine
  assert.equal('dmg' in vars, false); // the math var fails to resolve (renders ?)
});

test('collectVars: last declaration wins across kinds (pick over formula, formula over pick)', () => {
  const pickLast = mkPickRoot([
    { key: 'a1', name: 'x', expr: '5' },
    { key: 'a2', name: 'x', kind: 'pick', expr: 'a|b', rolled: 'b' },
  ]);
  assert.equal(c.collectVars(pickLast).x, 'b');
  const mathLast = mkPickRoot([
    { key: 'b1', name: 'x', kind: 'pick', expr: 'a|b', rolled: 'a' },
    { key: 'b2', name: 'x', expr: '7' },
  ]);
  assert.equal(c.collectVars(mathLast).x, 7);
});

test('evalMath: a string-valued variable fails to null (type-safe, fail-visible)', () => {
  assert.equal(c.evalMath('beast*2', { beast: 'dragon' }), null);
  assert.equal(c.evalMath('beast', { beast: 'dragon' }), null);
});

test('parseDice: a string-valued variable modifier fails to null', () => {
  assert.equal(c.parseDice('1d6+beast', { beast: 'wolf' }), null);
});

test('formatVarValue: strings pass through, numbers format as math results', () => {
  assert.equal(c.formatVarValue('dragon'), 'dragon');
  assert.equal(c.formatVarValue(42), '42');
  // pin the literal output (a rounding regression in formatMathResult would otherwise change
  // both sides of a self-comparison together and pass); the delegation is still verified below
  assert.equal(c.formatVarValue(2 / 3), '0.66666667');
  assert.equal(c.formatVarValue(2 / 3), c.formatMathResult(2 / 3)); // numbers route through formatMathResult
});

test('flattenArtifacts: a pick declaration exports its frozen value', () => {
  const node = c.mkNode('A [[var:p1]] appears');
  node.vars = [{ key: 'p1', name: 'beast', kind: 'pick', expr: 'dragon|wyrm', rolled: 'dragon' }];
  const out = c.flattenArtifacts(node.text, node, { beast: 'dragon' });
  assert.equal(out, 'A beast = dragon appears');
});

test('flattenArtifacts: a display-only reference to a pick exports the frozen text', () => {
  const node = c.mkNode('It was [[var:r1]]!');
  node.vars = [{ key: 'r1', name: 'beast', expr: '' }]; // display-only ref record
  const out = c.flattenArtifacts(node.text, node, { beast: 'wyrm' });
  assert.equal(out, 'It was wyrm!');
});

// #925f: on a prose EXPORT (proseExport=true) of a PARAGRAPH point, a pill flattens to just its
// RESULT — the recipe (2d6 =, name =, expr ≈) is dropped so the exported paragraph is clean prose.
// A bullet, or any non-para type, keeps the informative recipe. Scoped to the export flag, so
// display labels are untouched.
test('#925f: a paragraph exports pills as result-only; a bullet keeps the recipe', () => {
  const dice = { key: 'd1', expr: '2d6', total: 9, parts: [{ kind: 'dice', sides: 6 }] };
  const defVar = { key: 'v1', name: 'beast', kind: 'pick', expr: 'dragon|wyrm', rolled: 'dragon' };
  // a PARAGRAPH: result-only
  const para = c.mkNode('You take [[dice:d1]] from the [[var:v1]]'); para.type = 'para';
  para.dice = [dice]; para.vars = [defVar];
  assert.equal(c.flattenArtifacts(para.text, para, { beast: 'dragon' }, true), 'You take 9 from the dragon');
  // a BULLET (default type): the recipe stays
  const bullet = c.mkNode('Damage [[dice:d1]] from [[var:v1]]');
  bullet.dice = [dice]; bullet.vars = [defVar];
  assert.equal(c.flattenArtifacts(bullet.text, bullet, { beast: 'dragon' }, true), 'Damage 2d6 = 9 from beast = dragon',
    'a non-para node ignores proseExport — the recipe is informative there');
  // the SAME paragraph WITHOUT the export flag (a display label) keeps the recipe
  assert.equal(c.flattenArtifacts(para.text, para, { beast: 'dragon' }, false), 'You take 2d6 = 9 from the beast = dragon',
    'display sinks (proseExport=false) keep the recipe even for a paragraph');
  // frozenTokenText directly: the para+prose combo drops the recipe, everything else keeps it
  assert.equal(c.frozenTokenText('dice', 'd1', para, {}, undefined, true), '9');
  assert.equal(c.frozenTokenText('dice', 'd1', bullet, {}, undefined, true), '2d6 = 9');
});

test('#925f: the prose-mode pill CSS drops the stadium in a paragraph', () => {
  assert.ok(_src.includes('.nt-para .dice-roll, .nt-para .gr-roll, .nt-para .mk-roll,'),
    'a .nt-para-scoped rule must lighten the inline pills');
  assert.ok(/\.nt-para \.dice-roll[^{]*\{[^}]*background:transparent/.test(_src),
    'para pills drop the capsule background');
  // PER FAMILY, not just dice. The original pin asserted only the dice recipe, and that is exactly
  // how the est family drifted: `.est-expr`/`.est-eq` were never hidden and `.est-summary` was never
  // flattened, so a paragraph showed "Also 5 to 10 ≈ 7.13 (4.96 – 9.91)▃▅▇█ nights" while the EXPORT
  // already dropped the recipe. Screen and file out of step, on the one invariant this exception is
  // stated to hold. A per-family list is the only shape that cannot silently miss a family again.
  const chromeDrop = between(_src, '.nt-para .dice-ico', '.nt-para .var-ref .var-name');
  for (const sel of ['.nt-para .dice-formula', '.nt-para .dice-eq', '.nt-para .est-expr', '.nt-para .est-eq']) {
    assert.ok(chromeDrop.includes(sel), `${sel} must be hidden in a paragraph (recipe off, result-only)`);
  }
  assert.ok(/\{display:none\}/.test(chromeDrop), 'and the block actually hides them');
  for (const sel of ['.nt-para .dice-total', '.nt-para .var-val', '.nt-para .est-summary']) {
    assert.ok(new RegExp(sel.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '[^{]*\\{font-weight:inherit;font-family:inherit\\}|' +
                         sel.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + ',').test(_src),
      `${sel} must read as prose, not a bold-mono island`);
  }
  // both export paths (markdown + plain text) pass proseExport=true to flattenArtifacts
  assert.ok((_src.match(/flattenArtifacts\([\s\S]*?, node, varMap, true\)/g) || []).length >= 2,
    'both the markdown and plain-text export bodies must pass proseExport=true');
});

// UXP-137: the freeze-to-text core produces exactly what flattenArtifacts inlines (lockstep).
test('both collectPillActions callers read UNRENDERED text — the reason one broke and one did not', () => {
  // The bullet menu broke because focusing a point unfolds its pills, so the tokens were gone from
  // node.text by the time rows were collected. The base cell menu (the other caller) is immune for a
  // structural reason worth pinning: it reads the cell out of the parsed MODEL, which comes from
  // node.text, never from the rendered cell. Driven and confirmed — both "Re-sample value" and the
  // long-shipped "Re-roll dice" appear in a focused cell's Shift+F10 menu and both mutate the record.
  // If either caller ever starts reading rendered DOM text, that is the regression this catches.
  const cp = fnBody(_src, 'showColPanel');
  assert.ok(/const cellRaw = rowOps \? String\(model\.rows\[rowIdx\]\?\.\[colIdx\] \?\? ''\) : '';/.test(cp),
    'the cell menu takes its raw cell text from the parsed model, not from the DOM');
  assert.ok(/collectPillActions\(node, cellRaw\)/.test(cp), 'and scopes the pill rows to that cell');
  // exactly two callers; a third would need the same argument made for it
  assert.equal((_src.match(/collectPillActions\(/g) || []).length, 3,
    'two call sites plus the declaration — a new caller must show it reads unrendered text');
});

// ── #1116: the pill's own door ───────────────────────────────────────────────────────────────
test('#1116 pillTokenFor — a rendered pill element can name the token it draws', () => {
  // The pure half of the door: the DOM handler reads className + dataset.key, this decides which
  // artifact that is. Every type in the token grammar is covered, so a new pill family that forgets
  // to register here opens an empty menu rather than the wrong one.
  assert.equal(c.pillTokenFor('gr-roll', 'k3f'), '[[grammar:k3f]]');
  assert.equal(c.pillTokenFor('dice-roll', 'x1'), '[[dice:x1]]');
  assert.equal(c.pillTokenFor('est-pill', 'e9'), '[[est:e9]]');
  assert.equal(c.pillTokenFor('mk-roll', 'm2'), '[[markov:m2]]');
  assert.equal(c.pillTokenFor('math-roll', 'q7'), '[[math:q7]]');
  assert.equal(c.pillTokenFor('var-pill var-dist', 'v4'), '[[var:v4]]', 'extra classes do not confuse it');
  assert.equal(c.pillTokenFor('seq-pill', 's1'), '[[seq:s1]]');
  assert.equal(c.pillTokenFor('query-pill', 'y3'), '[[query:y3]]');
  // not a pill, or a pill with no key: no token, so the handler falls through and the browser
  // keeps its own context menu on ordinary prose.
  assert.equal(c.pillTokenFor('node-content', 'k3f'), null);
  assert.equal(c.pillTokenFor('gr-roll', ''), null);
  assert.equal(c.pillTokenFor('gr-roll', undefined), null);
  assert.equal(c.pillTokenFor(null, 'k3f'), null);
  assert.equal(c.pillTokenFor(['gr-roll', 'gr-stale'], 'k3f'), '[[grammar:k3f]]', 'an array of classes works too');
});

test('#1116 collectPillActions scopes to ONE pill when the menu is opened from it', () => {
  // A point with three pills used to open a nine-row wall. The scope parameter already existed for
  // the base cell; the pill door reuses it rather than growing a second filter.
  const node = { text: 'a [[grammar:g1]] b [[dice:d1]] c [[dice:d2]]',
    grammar: [{ key: 'g1', origin: 'a|b', result: 'a' }],
    dice: [{ key: 'd1', expr: '2d6', total: 7 }, { key: 'd2', expr: '1d4', total: 3 }] };
  const all = c.collectPillActions(node);
  assert.ok(all.length >= 8, `the unscoped menu lists every pill (got ${all.length})`);
  const scoped = c.collectPillActions(node, '[[dice:d1]]');
  assert.equal(scoped.length, 4, 'one dice pill contributes re-roll + show distribution + edit + freeze');
  assert.ok(scoped.every(r => /2d6/.test(r.label) || r.label === 'Freeze to text'),
    'and they are THAT pill\'s rows: ' + JSON.stringify(scoped.map(r => r.label)));
});

test('#1403 every pill flavour with an edit dialog lists it — a census, not a list', () => {
  // The PILLS section IS the keyboard door (UXP-13/14): every pill carries tabindex="-1", so its
  // pencil is unreachable by keyboard and this menu is the only way in. Driven on origin/main:
  //   dice / grammar / math / est  -> Edit row present
  //   named PICK var               -> "Re-roll pick", "Freeze to text"      <- no Edit
  //   named UNCERTAIN var          -> "Re-sample value", "Freeze to text"   <- no Edit
  //   named FORMULA var            -> NO ROWS AT ALL
  // The two that had rows had them because they have a CLICK gesture, and the rows stopped there.
  const flavours = [
    ['dice',      { text: '[[dice:k]]',    dice:    [{ key: 'k', expr: '2d6', total: 7 }] }],
    ['grammar',   { text: '[[grammar:k]]', grammar: [{ key: 'k', origin: 'a|b', result: 'a' }] }],
    ['math',      { text: '[[math:k]]',    math:    [{ key: 'k', expr: '2+2' }] }],
    ['est',       { text: '[[est:k]]',     est:     [{ key: 'k', expr: '4 to 9', seed: 1 }] }],
    ['markov',    { text: '[[markov:k]]',  markov:  [{ key: 'k', name: 'm', pairs: [] }] }],
    ['var pick',  { text: '[[var:k]]',     vars:    [{ key: 'k', name: 'who', expr: 'a|b', kind: 'pick' }] }],
    ['var dist',  { text: '[[var:k]]',     vars:    [{ key: 'k', name: 'cost', expr: '100 to 200', kind: 'dist' }] }],
    ['var formula', { text: '[[var:k]]',   vars:    [{ key: 'k', name: 'total', expr: '40 * 2' }] }],
  ];
  for (const [name, node] of flavours) {
    const rows = nonEmpty(c.collectPillActions(node), name + ' pill rows');
    assert.ok(rows.some(r => /^Edit /.test(r.label)),
      name + ' must offer its edit dialog here: ' + JSON.stringify(rows.map(r => r.label)));
    assert.ok(rows.some(r => r.label === 'Freeze to text'), name + ' keeps its freeze row');
  }
  // the three variable flavours share ONE dialog, and the row must name the dialog it opens (P1) --
  // there were three different strings for it before ("Edit uncertain variable" on the pencil,
  // "Edit variable" on the dialog it opened, and no row at all).
  assert.equal(c.varEditLabel('pick'), 'Edit random variable');
  assert.equal(c.varEditLabel('dist'), 'Edit uncertain variable');
  assert.equal(c.varEditLabel(undefined), 'Edit variable');
  assert.ok(fnBody(_src, 'editVar').includes('title: varEditLabel(v.kind)'),
    'the dialog title comes from the same core the menu row uses');
  assert.ok(fnBody(_src, 'collectPillActions').includes('label:varEditLabel(v.kind)')
         || /varEditLabel\(v\.kind\)/.test(fnBody(_src, 'collectPillActions')),
    'and so does the row');
  // ONE loop over node.vars, gated on the token rather than on a kind: gating on kind is exactly
  // how the formula flavour ended up with no section at all.
  const cpa = fnBody(_src, 'collectPillActions');
  assert.ok(/for \(const v of node\.vars \|\| \[\]\) if \(has\('var', v\.key\)\) \{/.test(cpa),
    'the vars loop admits every flavour, then branches for the gesture');
  assert.ok(!/for \(const v of node\.vars \|\| \[\]\) if \(v\.kind === /.test(cpa),
    'and no kind-gated loop remains');
});

test('#1116 the freeze writes what the pill SHOWS, not a value from a different scope', () => {
  // MEASURED before the fix, by driving: with `{n := 10}` above the reader and `{n := 99}` below,
  // the pill read `n * 2=20` while Freeze to text wrote `198` — a number never on screen. The pills
  // render from the POSITIONAL var map (#767 renderPosVarMaps); the freeze read the document-wide
  // collectVars(). That is the one-value-two-displays bug #1115 removed from the estimate export.
  const fz = fnBody(_src, 'freezePillToText');
  assert.match(fz, /frozenTokenText\(type, key, node, varMapAt\(node\), root, node\.type === 'para'\)/,
    'the freeze must read the positional map, and the prose flag, exactly as the render does');
  assert.doesNotMatch(fz, /frozenTokenText\([^)]*collectVars\(\)/, 'never the document-wide map');
  // The prose half: on a paragraph the export writes `3` and the freeze wrote `2d6 = 3`. A novelist
  // committing a pick in a sentence is asking for words, not a recipe.
  assert.ok(/node\.type === 'para'/.test(fz), 'the prose flag is passed, so freeze and export agree');
});

// ── #1146: freezing a DECLARATION orphans every reference to it, and said nothing about it ──
// Reproduced on main before any fix: `{who := Maren Osk | Halvard | Sister Ivy}` with two `{who}`
// references, freeze the declaration, and both references fall to the `var-undef` dash. The issue
// said they render `?`; they do not. Measured, an orphaned reference renders "—" with a dashed
// --del border, title "Variable not found. Click to edit", and aria "Variable who not found" — so
// the REFERENCES were never silent. What was silent is the destructive action itself: it announced
// "Frozen to text: who = Sister Ivy" / "Pill frozen to text" and never mentioned the two points it
// had just changed, which can be anywhere in the document including off screen. Undo restores all
// three, verified. So this reports the consequence rather than refusing the action: the app's own
// habit is an affordance, never a gate, and gating damage that is already visible and already
// undoable would cost a user something they may legitimately want.
test('orphanedVarRefCount: counts POSITIONALLY, because that is how a reference resolves', () => {
  const decl = { id: 'd', text: 'Tonight [[var:k1]]', vars: [{ key: 'k1', name: 'who', kind: 'pick', expr: 'a | b', rolled: 'a' }], children: [] };
  const ref1 = { id: 'r1', text: 'At the door [[var:k2]]', vars: [{ key: 'k2', name: 'who', expr: '' }], children: [] };
  const ref2 = { id: 'r2', text: 'Later [[var:k3]]', vars: [{ key: 'k3', name: 'who', expr: '' }], children: [] };
  const other = { id: 'o', text: 'Weather [[var:k4]]', vars: [{ key: 'k4', name: 'sky', expr: '' }], children: [] };

  // the declaration is gone (this is the post-prune document): both references are stranded
  assert.equal(c.orphanedVarRefCount({ children: [ref1, ref2, other] }, 'who'), 2);
  // a declaration ABOVE covers every reference after it
  assert.equal(c.orphanedVarRefCount({ children: [decl, ref1, ref2] }, 'who'), 0,
    'references below a surviving declaration still resolve, so nothing is reported');
  // THE CASE A NON-POSITIONAL COUNT GOT WRONG, found by driving rather than by reasoning: the
  // surviving declaration sits BELOW the reference, so the reference reads the dash. "Is the name
  // declared anywhere" answered 0 here while the screen showed a broken pill.
  assert.equal(c.orphanedVarRefCount({ children: [ref1, decl, ref2] }, 'who'), 1,
    'a reference ABOVE the only surviving declaration is orphaned and must be counted');
  // case-insensitive on the name, like every other var lookup
  assert.equal(c.orphanedVarRefCount({ children: [ref1] }, 'WHO'), 1);
  // never counts a different name, and never counts a reference whose token was already removed
  assert.equal(c.orphanedVarRefCount({ children: [ref1, ref2, other] }, 'sky'), 1);
  assert.equal(c.orphanedVarRefCount({ children: [{ id: 'x', text: 'no token here', vars: [{ key: 'k9', name: 'who', expr: '' }], children: [] }] }, 'who'), 0,
    'a dangling record with no [[var:]] token in the text is not a live reference');

  // #1418: a reference is a reference whichever ENGINE holds it. This counted the bare `{total}`
  // reference pill and not `{= total * 2}`, so freezing a declaration reported "nothing broken"
  // while a math pill dropped to `#ERR (bad ref)`. Driven, before: the bare form warned about 1
  // point, the expression form said nothing at all.
  const mathRef = { id: 'm', text: 'twice [[math:x1]]', math: [{ key: 'x1', expr: 'who * 2' }], children: [] };
  const estRef  = { id: 'e', text: 'range [[est:u1]]', est: [{ key: 'u1', expr: 'who to 90' }], children: [] };
  const depDecl = { id: 'p', text: 'dep [[var:k5]]', vars: [{ key: 'k5', name: 'doubled', expr: 'who * 2' }], children: [] };
  assert.equal(c.orphanedVarRefCount({ children: [mathRef] }, 'who'), 1, 'a math pill naming it counts');
  assert.equal(c.orphanedVarRefCount({ children: [estRef] }, 'who'), 1, 'an estimate pill naming it counts');
  assert.equal(c.orphanedVarRefCount({ children: [depDecl] }, 'who'), 1, 'a variable whose expression names it counts');
  assert.equal(c.orphanedVarRefCount({ children: [ref1, mathRef] }, 'who'), 2, 'both engines add up');
  // the same positional rule: a declaration above covers an expression below it
  assert.equal(c.orphanedVarRefCount({ children: [decl, mathRef] }, 'who'), 0,
    'an expression below a surviving declaration still resolves');
  // NEGATIVES. A rollup names a PROPERTY, not this variable; a function call is not a reference;
  // and a record whose token is gone is not live.
  assert.equal(c.orphanedVarRefCount({ children: [{ id: 'g', text: 'roll [[math:x2]]', math: [{ key: 'x2', expr: 'sum(cost)' }], children: [] }] }, 'who'), 0);
  assert.equal(c.orphanedVarRefCount({ children: [{ id: 'f', text: 'call [[math:x3]]', math: [{ key: 'x3', expr: 'who(3)' }], children: [] }] }, 'who'), 0,
    'a name followed by ( is a function call, not a variable reference');
  assert.equal(c.orphanedVarRefCount({ children: [{ id: 'n', text: 'no token', math: [{ key: 'x4', expr: 'who * 2' }], children: [] }] }, 'who'), 0,
    'a math record with no token in the text is not a live reference');
});

test('#1418 exprNamesVar — the same identifier rule mathErrorReason uses', () => {
  assert.equal(c.exprNamesVar('total * 2', 'total'), true);
  assert.equal(c.exprNamesVar('TOTAL * 2', 'total'), true, 'case-insensitive, like every var lookup');
  assert.equal(c.exprNamesVar('subtotal * 2', 'total'), false, 'a substring is not a reference');
  assert.equal(c.exprNamesVar('total(3)', 'total'), false, 'a call is not a reference');
  assert.equal(c.exprNamesVar('total.count', 'total'), false,
    'a dotted name is ONE identifier (the variable-base projection rule), so it is not a bare `total`');
  assert.equal(c.exprNamesVar('a + total', 'total'), true);
  assert.equal(c.exprNamesVar('', 'total'), false);
  assert.equal(c.exprNamesVar('total', ''), false);
  // it must MATCH mathErrorReason's scan, or the count and the error message would disagree about
  // what a reference is -- which is the whole reason it was lifted rather than re-written.
  const mer = fnBody(_src, 'mathErrorReason'), env = fnBody(_src, 'exprNamesVar');
  const RE = '/[A-Za-z_]\\w*(?:\\.[A-Za-z_]\\w*)*/g';
  assert.ok(mer.includes(RE) && env.includes(RE), 'both use the same identifier regex');
  assert.ok(mer.includes("/^\\s*\\(/.test(s.slice(re.lastIndex))") && env.includes("/^\\s*\\(/.test(s.slice(re.lastIndex))"),
    'and both skip a name followed by (');
});

test('orphanedVarRefCount: walks the whole tree, ancestors included', () => {
  const decl = { id: 'd', text: 'Tonight [[var:k1]]', vars: [{ key: 'k1', name: 'who', kind: 'pick', expr: 'a | b', rolled: 'a' }], children: [] };
  const ref1 = { id: 'r1', text: 'At the door [[var:k2]]', vars: [{ key: 'k2', name: 'who', expr: '' }], children: [] };
  const ref2 = { id: 'r2', text: 'Later [[var:k3]]', vars: [{ key: 'k3', name: 'who', expr: '' }], children: [] };
  // it recurses in PRE-ORDER, because a reference is usually not a sibling of the declaration and
  // "above" means earlier in document order, ancestors included
  assert.equal(c.orphanedVarRefCount({ children: [{ id: 'p', text: 'parent', vars: [], children: [ref1, { id: 'q', text: 'mid', vars: [], children: [ref2] }] }] }, 'who'), 2,
    'nested references count, which is the whole reason this walks the tree');
  assert.equal(c.orphanedVarRefCount({ children: [{ id: 'p', text: 'parent [[var:k1]]', vars: decl.vars, children: [ref1] }] }, 'who'), 0,
    'a declaration on an ANCESTOR is above its descendants, so they resolve');
  // empty / missing name is not a match-everything
  assert.equal(c.orphanedVarRefCount({ children: [ref1] }, ''), 0);
  assert.equal(c.orphanedVarRefCount({ children: [ref1] }, null), 0);
});

test('freezeOrphanNote: says what the freeze cost, and says nothing when it cost nothing', () => {
  assert.equal(c.freezeOrphanNote('who', 0), '', 'the common case must read exactly as it did before');
  assert.equal(c.freezeOrphanNote('who', null), '');
  const one = c.freezeOrphanNote('who', 1), many = c.freezeOrphanNote('who', 3);
  assert.match(one, /1 point using who now shows no value/, 'singular agrees');
  assert.match(many, /3 points using who now show no value/, 'plural agrees');
  assert.match(many, /Undo to put it back/, 'names the remedy, not just the miss (the house rule)');
  for (const s of [one, many]) {
    assert.doesNotMatch(s, /—/, 'no em dash in a user-facing string');
    assert.ok(s.startsWith(' '), 'it appends to an existing sentence, so it carries its own leading space');
  }
});

test('#1146 the freeze CALLS the counter and reports it (a tested core proves nothing about the call site)', () => {
  const fz = fnBody(_src, 'freezePillToText');
  // the name must be read BEFORE the prune drops the record, or the count is always 0
  assert.match(fz, /const declName = type === 'var' \?/, 'only a var pill can orphan anything');
  assert.ok(fz.indexOf('const declName') < fz.indexOf('pruneArtifacts('),
    'the name must be captured BEFORE pruneArtifacts drops the record it lives on');
  assert.match(fz, /v\.key === key && v\.expr/, 'and only a DECLARATION (non-empty expr) has dependents');
  // the counter runs after the prune, so the number describes the document the user now has
  assert.ok(fz.indexOf('orphanedVarRefCount(root, declName)') > fz.indexOf('pruneArtifacts('),
    'the count must be taken AFTER the prune, or it counts a declaration that is already gone');
  assert.match(fz, /freezeOrphanNote\(declName, orphaned\)/, 'and the note is built from it');
  // both feedback channels carry it: the toast a sighted user sees and the live region a screen
  // reader hears. Reporting to only one is the half-fix this repo keeps finding.
  assert.match(fz, /announce\(`Frozen to text: \$\{frozen\}\.\$\{note\}`\)/, 'the live region carries the note');
  assert.match(fz, /flashHint\('Pill frozen to text\.' \+ note\)/, 'and so does the toast');
  // the orphans are elsewhere in the tree, so a single-row rerender would leave them stale on screen
  assert.match(fz, /if \(orphaned\) render\(\);/, 'a freeze that stranded references must repaint the tree, not just this row');
  assert.match(fz, /else rerenderNode\(node\.id\);/, 'and the common case must stay a cheap single-row repaint');
});

test('#1116 the pill door is wired, scoped, and does not hijack ordinary prose', () => {
  const ace = fnBody(_src, 'attachContentEvents');
  assert.match(ace, /content\.addEventListener\('contextmenu'/, 'the pill door exists');
  assert.match(ace, /pillTokenFor\(el\.className, el\.dataset\.key\)/, 'it resolves the token from the element');
  assert.match(ace, /if \(!token \|\| !node\.text\.includes\(token\)\) return;/,
    'a right-click on ordinary text must fall through to the browser menu, not be swallowed');
  assert.match(ace, /showBulletPopup\(node\.id, bullet, \{ pillScope: token \}\)/, 'and it opens the menu scoped');
  // THE REGRESSION THAT WOULD MAKE THIS WORSE THAN THE BUG: the click still re-rolls. "A generative
  // pill changes on click" is a recorded P1 sign-off made separately for dice, clocks and estimates.
  const md = between(_src, 'for (const p of REROLL_PILLS) {', 'math pill: click anywhere opens the editor');
  assert.match(md, /if \(onEdit\) p\.edit\(node, key\); else p\.reroll\(node, key\);/,
    'the mousedown branch is untouched: plain click re-rolls, the pencil edits');
  assert.doesNotMatch(md, /contextmenu|button === 2|pillScope/, 'the door is a SEPARATE listener, not a new click mode');
  // A pill-scoped menu drops point-level chrome, or the three rows are buried.
  const sbp = fnBody(_src, 'showBulletPopup');
  assert.match(sbp, /opts\.pillScope \? actions\.filter\(a => a\.sec === 'Pills'\)/,
    'a pill menu shows its rows even in Lean, where the Pills section is otherwise filtered out');
  assert.match(sbp, /!isBase && !leanCollapsed && !opts\.pillScope/, 'no type switcher on a pill menu');
});

test('edit-on-click is scoped to the content box — the row-level gutter/margin edit fallback is removed', () => {
  // Owner report: clicking away from a point (bullet gutter / left margin / inter-row padding) entered edit on
  // that row's point. .node-content is flex:1 and its OWN mousedown handles clicks on the whole text box, so
  // the row-level "click anywhere in the row → edit" fallback is removed: you enter edit only inside the accent box.
  assert.ok(!_src.includes('.md-task-check,.node-link,.dice-roll,.mk-roll,.gr-roll,.math-roll,.est-pill,'),
    'the row-level INTERACTIVE allow-list (the click-anywhere-in-row edit fallback) is gone');
  // but the content box still enters edit AND places the caret where you clicked
  assert.ok(_src.includes('const r = caretFromPoint(rAfter.left + dx, rAfter.top + dy)'),
    'clicking the content box still enters edit and places the caret at the click point');
});

test('the hover point-menu gates on LIVE dom editing state, blocking ONLY the point being edited', () => {
  // Regression ("the hover menu became unreliable"): activeContentId went stale when a render() ended an edit
  // without exitEdit, blocking hover-open for the whole session. It now reads the DOM (can't drift), AND blocks
  // only THIS point when it is the one being edited — hovering another point's bullet mid-edit still opens.
  assert.ok(_src.includes("const editingEl = document.querySelector('.node-content[data-editing]')") &&
    _src.includes('if (!dragId && editingEl?.dataset.id !== node.id) showBulletPopup(node.id, bullet)'),
    'the 200ms hover-open opens unless THIS point is the one being edited (#455 covers its own text only)');
  assert.ok(!_src.includes('if (!dragId && activeContentId == null) showBulletPopup'),
    'the stale-prone activeContentId guard is gone from the hover path');
});

test('a click on an interactive pill/link never falls through to entering edit (the edit-sink backstop)', () => {
  // Owner: "a link, or a roll, should be interactable always when clicking over them." The content mousedown
  // enters edit only after an explicit bail for any interactive token, so no pill/link click can drop into
  // raw-text edit even if its own branch misses an edge target.
  const guard = ".dice-roll,.mk-roll,.gr-roll,.math-roll,.var-pill,.est-pill,.seq-pill,.query-pill,.act-pill,.node-link,.hashtag,.fn-ref,.web-img-blocked,.md-task-check,.todo-state,.note-ind,.md-spoiler,a";
  assert.ok(_src.includes("if (e.target.closest?.('" + guard + "')) return;"),
    'the edit-entering mousedown bails when the click is inside an interactive pill/link/token');
  // it sits right before the enterEdit call, after the editing-guard
  const idxGuard = _src.indexOf("if (e.target.closest?.('" + guard + "')) return;");
  const idxEnter = _src.indexOf('enterEdit(content, node);\n    content.focus();\n    const rAfter');
  assert.ok(idxGuard > -1 && idxEnter > idxGuard, 'the backstop precedes the enterEdit sink');
});

test('the Shift+F10 pill rows are collected from FOLDED text, or the keyboard door is empty', () => {
  // Found by driving, after a source pin said the "Re-sample value" row existed. Reaching a point
  // with the keyboard means FOCUSING it, and focus unfolds its pills — node.text goes from
  // `Dice [[dice:key]] here` to `Dice {2d6} here`. collectPillActions matches on the token, so it
  // returned [] and the entire Pills section vanished from the menu. The mouse path (hover a bullet
  // from display mode) worked, which is why it went unnoticed: the advertised keyboard door to the
  // pill wall was empty for EVERY pill family. Reproduced identically on origin/main, so it is
  // long-standing rather than new — but #952 added a row to that menu and claimed P3 through it.
  const sbp = fnBody(_src, 'showBulletPopup');
  assert.ok(/if \(activeContentId === nodeId\) \{[\s\S]{0,400}commitActiveEdit\(\)/.test(sbp),
    'the point being edited must be committed (and refolded) before its rows are collected');
  // #1116 re-anchored: this matched the call's exact spelling (`collectPillActions(node)`), and the
  // call grew a scope argument, so indexOf returned -1 and the ordering assertion inverted. The
  // INTENT is unchanged and still load-bearing - commit before collect - so it is pinned on the
  // call rather than on how it is spelled.
  const collectAt = sbp.search(/collectPillActions\(node[,)]/);
  assert.ok(collectAt > -1, 'showBulletPopup must still collect the pill rows');
  assert.ok(sbp.indexOf('commitActiveEdit()') < collectAt,
    'and the commit must precede the collection, or the rows are read from unfolded text');
  // Scoped to THIS point: a hover over another point's bullet must not commit an edit elsewhere.
  assert.ok(/activeContentId === nodeId/.test(sbp),
    'the commit is scoped to the menu\'s own point, so hovering never closes an unrelated edit');
  // commitActiveEdit is the shared helper render() already uses; this must not grow a second one.
  assert.ok(/function commitActiveEdit\(\)/.test(_src));
  // and the row this all exists to reach is still emitted
  assert.ok(/label:'Re-sample value' \+ tag\(v\.name\)/.test(_src));
});

test('#952 the distribution pill does not fight the shipped prose-mode rules (#925f/#944)', () => {
  // Found by measuring computed styles in a paragraph, not by reading the CSS. Two artifacts this
  // change introduced, both invisible to a source-only reading:
  //  (1) a `.var-pill.var-dist .var-val` weight rule (0,3,0) OUT-SPECIFIES the prose-mode
  //      `.nt-para .var-val{font-weight:inherit}` (0,2,0), so a distribution stayed bold inside a
  //      paragraph while every neighbouring pill flattened. Measured: weight 600 vs 400.
  //  (2) the '≈' separator added to the reference pill had no .nt-para rule, so once #944 hides
  //      the name you got a dangling "≈ 143.2" mid-sentence.
  assert.ok(!/\.var-pill\.var-dist \.var-val\{[^}]*font-weight/.test(_src),
    'no font-weight override on .var-dist .var-val — it would out-specify the prose-mode flattening');
  assert.ok(/\.nt-para \.var-ref \.var-name, \.nt-para \.var-ref \.var-eq\{display:none\}/.test(_src),
    'the separator is hidden wherever the name is: it only ever separated the name from the value');
  // the prose-mode rule still flattens .var-val (the rule being relied on). Asserted as MEMBERSHIP,
  // not as the exact selector list — pinning the whole list broke the moment .est-summary joined it,
  // which is the brittleness the widened #925f pin above exists to avoid.
  assert.ok(/\.nt-para \.var-val[,{][^{]*\{font-weight:inherit;font-family:inherit\}/.test(_src),
    'the prose-mode weight/family flattening covers .var-val');
  // and the DECLARATION keeps its separator in prose — only a reference drops name+separator (#944)
  assert.ok(!/\.nt-para \.var-pill \.var-eq\{display:none\}/.test(_src),
    'the chrome-drop is reference-only; a declaration still reads name ≈ value');
});

test('#952 a distribution FREEZES and EXPORTS to its summary, never to "?"', () => {
  // The hole: frozenTokenText's var arm resolves through varMap[name], and #952 deliberately keeps
  // distributions OUT of that map (the sibling lane protects resolveVarDefs' number|string
  // contract). So every freeze/export sink printed "?" — the .md and .txt exports, the bullet
  // menu's freeze action, and every displayText sink (backlinks, unlinked-reference matching,
  // search snippets). Measured on the pre-fix build: flattenArtifacts(...) === 'Budget ? total'.
  const rec = { key: 'v1', name: 'cost', kind: 'dist', expr: '100 to 200', seed: 12345, typed: true };
  const ref = { key: 'v2', name: 'cost', expr: '' };
  const vars = c.attachVarDists(Object.create(null), { cost: rec });
  const para   = c.mkNode('Budget [[var:v1]] and [[var:v2]] total'); para.type = 'para'; para.vars = [rec, ref];
  const bullet = c.mkNode('Budget [[var:v1]] and [[var:v2]] total'); bullet.vars = [rec, ref];
  const SUM = /^[\d.]+ \([\d.]+ – [\d.]+\) \S+$/;   // "mean (p5 – p95) ▂▄█…", the est arm's shape
  for (const [label, node, pe] of [['para export', para, true], ['para display', para, false],
                                   ['bullet export', bullet, true], ['bullet display', bullet, false]]) {
    const out = c.flattenArtifacts(node.text, node, vars, pe);
    assert.ok(!out.includes('?'), `${label} must not export a distribution as "?" (${out})`);
    assert.ok(/\d/.test(out), `${label} carries real numbers`);
  }
  // the DECLARATION keeps its name outside a prose export, like every other var; the reference
  // never does. '≈' not '=': the frozen text must not claim a certainty the value lacks.
  assert.match(c.frozenTokenText('var', 'v1', bullet, vars, undefined, false), /^cost ≈ /);
  assert.match(c.frozenTokenText('var', 'v1', para, vars, undefined, true), SUM, 'a prose export is result-only (#925f)');
  assert.match(c.frozenTokenText('var', 'v2', bullet, vars, undefined, false), SUM, 'a reference is result-only everywhere');
  // THE property, surviving the freeze: a reference and its declaration freeze to the SAME text.
  assert.equal(c.frozenTokenText('var', 'v2', para, vars, undefined, true),
               c.frozenTokenText('var', 'v1', para, vars, undefined, true),
               'the frozen reference is the frozen declaration — correlation survives export');
  // deterministic, because the seed is (still) the only source of the draw
  assert.equal(c.frozenTokenText('var', 'v1', para, vars, undefined, true),
               c.frozenTokenText('var', 'v1', para, vars, undefined, true));
  // an unsamplable dist says #ERR rather than lying or blanking
  const bad = { key: 'v9', name: 'oops', kind: 'dist', expr: 'garbage', seed: 1 };
  const bn = c.mkNode('[[var:v9]]'); bn.vars = [bad];
  assert.equal(c.frozenTokenText('var', 'v9', bn, c.attachVarDists(Object.create(null), { oops: bad })), 'oops ≈ #ERR');
  // regression: the other two kinds are untouched
  const f  = { key: 'v3', name: 'rate', expr: '85' };
  const pk = { key: 'v4', name: 'tone', kind: 'pick', expr: 'warm|cool', rolled: 'warm' };
  const n2 = c.mkNode('[[var:v3]] [[var:v4]]'); n2.vars = [f, pk];
  assert.equal(c.flattenArtifacts(n2.text, n2, { rate: 85, tone: 'warm' }, false), 'rate = 85 tone = warm');
  // and a name with NO value at all still reads '?' — the honest answer stays for the honest case
  const n3 = c.mkNode('[[var:v5]]'); n3.vars = [{ key: 'v5', name: 'nope', expr: '1/0' }];
  assert.equal(c.frozenTokenText('var', 'v5', n3, {}), 'nope = ?');
});

test('frozenTokenText — per type, and matches flattenArtifacts', () => {
  const node = c.mkNode('x');
  node.dice = [{ key: 'd1', expr: '2d6', total: 7, parts: [{ kind: 'dice', sides: 6 }] }];
  node.grammar = [{ key: 'g1', result: 'a goblin', anon: true }];
  node.markov = [{ key: 'm1', path: ['a', 'b', 'c'] }];
  assert.equal(c.frozenTokenText('dice', 'd1', node, {}), '2d6 = 7');
  assert.equal(c.frozenTokenText('grammar', 'g1', node, {}), 'a goblin');
  assert.equal(c.frozenTokenText('markov', 'm1', node, {}), 'a → b → c');
  assert.equal(c.frozenTokenText('dice', 'missing', node, {}), '');   // no record → ''
  // lockstep: flattening the token yields the same string frozenTokenText returns
  node.text = 'You find [[grammar:g1]]';
  assert.equal(c.flattenArtifacts(node.text, node, {}), 'You find a goblin');
});

test('OPML: a pick record serializes kind + rolled into the _vars attribute', () => {
  const root = mkPickRoot([{ key: 'p1', name: 'beast', kind: 'pick', expr: 'dragon|wyrm', rolled: 'dragon' }]);
  const xml = c.toOpml(root);
  assert.ok(xml.includes('_vars='), 'vars sidecar should serialize');
  assert.ok(xml.includes('pick'), 'kind:pick should ride the JSON blob');
  assert.ok(xml.includes('rolled'), 'rolled should ride the JSON blob');
});

test('regression: formula-only variables are untouched by the pick branch', () => {
  const root = mkPickRoot([
    { key: 'r', name: 'r', expr: '5' },
    { key: 'a', name: 'area', expr: 'pi*r^2' },
  ]);
  const vars = c.collectVars(root);
  assert.equal(vars.r, 5);
  assert.ok(Math.abs(vars.area - Math.PI * 25) < 1e-9);
});

// ── mathErrorReason — reason-coded #ERR (UXP-8 table cells, UXP-34 math pills) ──
// Classifies why evalMath(expr, vars) returned null, so the failure carries a cause
// instead of a bare #ERR or (worse) a stale last-good value.
{
  const { mathErrorReason } = c;

  test('mathErrorReason — an undeclared identifier is a bad ref', () => {
    assert.equal(mathErrorReason('x * 2', {}), 'bad ref');
    assert.equal(mathErrorReason('$1 * tax', {}), 'bad ref'); // table-style: tax undeclared
  });

  test('mathErrorReason — a string-valued (pick) variable is non-numeric', () => {
    assert.equal(mathErrorReason('beast * 2', { beast: 'dragon' }), 'non-numeric');
  });

  test('mathErrorReason — a cyclic identifier reports cycle (most specific)', () => {
    assert.equal(mathErrorReason('a + 1', {}, new Set(['a'])), 'cycle');
  });

  test('mathErrorReason — constants and function calls are not flagged', () => {
    assert.equal(mathErrorReason('2*pi', {}), '');            // pi is a constant, not a var
    assert.equal(mathErrorReason('sqrt(16) + e', {}), '');    // sqrt( → fn, e → constant
    assert.equal(mathErrorReason('c2f(20)', {}), '');         // unit-conversion fn, no enumeration needed
    assert.equal(mathErrorReason('asdate(today + 90)', {}), '');
  });

  test('mathErrorReason — a resolvable numeric variable is not flagged', () => {
    assert.equal(mathErrorReason('r * 2', { r: 5 }), '');
  });

  test('mathErrorReason — a malformed expression with no bad identifier is generic', () => {
    assert.equal(mathErrorReason('2 + * 3', {}), '');  // syntactic garbage → bare #ERR, no parenthetical
  });

  test('mathErrorReason — bad ref wins over non-numeric when both are present', () => {
    assert.equal(mathErrorReason('missing + beast', { beast: 'dragon' }), 'bad ref');
  });

  test('mathErrorReason — estimate-constructor syntax reads as estimate, not bad ref', () => {
    // crossing the estimate↔math boundary: the `to` operator / normal( / uniform(
    assert.equal(mathErrorReason('5 to 10', {}), 'estimate');
    assert.equal(mathErrorReason('(5 to 10) + 1', {}), 'estimate');   // was 'bad ref' (the `to` looked like an unknown name)
    assert.equal(mathErrorReason('normal(8, 2)', {}), 'estimate');
    assert.equal(mathErrorReason('2 * uniform(0, 10)', {}), 'estimate');
    // it is the MOST specific reason — wins even when a bad ref is also present
    assert.equal(mathErrorReason('missing + 5 to 10', {}), 'estimate');
    // and it does NOT false-positive on innocent math: `today` (contains "to"),
    // a var named `total`, or a function with no estimate keyword
    assert.equal(mathErrorReason('asdate(today + 90)', {}), '');
    assert.equal(mathErrorReason('total * 2', { total: 5 }), '');
    assert.equal(mathErrorReason('c2f(20)', {}), '');
  });

  test('mathReasonPhrase — one human phrase per code, shared by the dialogs (P1)', () => {
    // Each code maps to a non-empty, plain-language phrase. The phrases name the
    // problem in user terms (no engine jargon) and, where there is one, the fix.
    assert.match(c.mathReasonPhrase('estimate'), /estimate/);
    assert.match(c.mathReasonPhrase('estimate'), /5 to 10/);          // shows the user form, not "separate engine"
    // #1127: and it names the form that WORKS, not only the one that does not. The refusal was
    // correct but stopped one step short, so a user with the right model and the right tool still
    // stalled. Mirrors the not-uncertain arm, which already ends by naming a working shape.
    // Driven: dropping the "=" promotes {total * 1.2} to a real estimate pill, so the advice is
    // followable. {cost * 2} is the shape guide/computing-numbers.md already teaches verbatim.
    assert.match(c.mathReasonPhrase('estimate'), /without the =/, 'names the fix, not just the miss');
    assert.match(c.mathReasonPhrase('estimate'), /\{cost \* 2\}/, 'and shows the shape that would work');
    // #1159: this used to be /declare it|add it as a property/ — an OR that "declare it as a
    // variable" satisfies, so it stayed GREEN through the fix and could not detect it. The old
    // text's second remedy ("add it as a property") is the one the reporter had ALREADY done, and
    // nothing said a property is read only from this point and the points above it. Lock the
    // teaching, not a fragment that survives either wording.
    const badRef = c.mathReasonPhrase('bad ref');
    assert.match(badRef, /no value here/, 'still names the miss');
    assert.match(badRef, /sibling/, 'states the scope rule that was invisible before');
    assert.match(badRef, /points above it|to a parent/, 'names the inheritance remedy');
    assert.match(badRef, /\{cost := 40\}/, 'and shows the document-wide form that always works');
    assert.doesNotMatch(badRef, /or add it as a property/,
      'must not still offer the remedy the user has usually already tried');
    assert.match(c.mathReasonPhrase('non-numeric'), /not a number/);
    assert.match(c.mathReasonPhrase('cycle'), /depends on itself/);
    // jargon must NOT reappear (the de-jargon pass, this commit)
    assert.doesNotMatch(c.mathReasonPhrase('estimate'), /separate engine/);
    assert.doesNotMatch(c.mathReasonPhrase('non-numeric'), /text pick/);
    assert.equal(c.mathReasonPhrase(''), '');         // generic → caller's own fallback
    assert.equal(c.mathReasonPhrase('whatever'), ''); // unknown code → no phrase
  });

  // ── #1169: a KNOWN function at the wrong arity ───────────────────────────────
  // Before this, moonphase(today) reported byte-identically to notafunction(1): the reason chain
  // skipped every `name(` call, so a real function given the wrong number of values fell to the
  // generic "could not be evaluated". evalMath's parser already knew (#827's arity dispatch falls
  // through to `throw 0`); the sentinel just carried no information.
  test('#1169: fnArities — the arg counts a name accepts, as a SET (overloads) not a number', () => {
    assert.deepEqual([...c.fnArities('moonphase')], [3]);
    assert.deepEqual([...c.fnArities('log')], [1, 2], 'log is 1-arg base-10 AND 2-arg log(x, base)');
    assert.deepEqual([...c.fnArities('floor')], [1]);
    // Variadics: min/max/avg/and/or take two or more, so an arity "mismatch" is meaningless for
    // them. Two assertions, because the first alone CANNOT FAIL (#1133): they are in none of the
    // FN tables today, so fnArities returns null via want.length regardless of the exclusion.
    for (const v of ['min', 'max', 'avg', 'and', 'or']) assert.equal(c.fnArities(v), null, v);
    // (a) the redundancy claim itself - if a fixed-arity `min` is ever added to a table, the
    //     exclusion stops being belt-and-braces and starts being the only thing preventing a
    //     false positive on a legal variadic call. Fail loudly at that moment.
    const fnTables = nonEmpty(['FN1', 'FN2', 'FN3'].map(t => between(_src, `const ${t} = `, '\n});')),
      'the FN arity tables');
    for (const v of ['min', 'max', 'avg', 'and', 'or'])
      for (const [i, body] of fnTables.entries())
        assert.doesNotMatch(body, new RegExp(`(?<![\\w.])${v}\\s*:`),
          `'${v}' is now in FN${i + 1}: the MATH_VARIADIC_NAMES exclusion is load-bearing, not redundant`);
    // (b) and source-pin the exclusion, so deleting it is red even while it is redundant
    assert.match(_src, /MATH_VARIADIC_NAMES\.has\(n\)\s*\)\s*return null/,
      'the variadic exclusion was removed from fnArities');
    assert.equal(c.fnArities('notafunction'), null, 'an unknown name is a DIFFERENT mistake');
    assert.equal(c.fnArities(''), null);
  });

  test('#1169: fnArityProblem — finds the mismatch, and stays quiet when there is none', () => {
    const norm = p => p && { name: p.name, got: p.got, want: [...p.want] };
    assert.deepEqual(norm(c.fnArityProblem('moonphase(today)')), { name: 'moonphase', got: 1, want: [3] });
    assert.deepEqual(norm(c.fnArityProblem('moonphase(today, 28)')), { name: 'moonphase', got: 2, want: [3] });
    assert.deepEqual(norm(c.fnArityProblem('floor()')), { name: 'floor', got: 0, want: [1] });
    assert.deepEqual(norm(c.fnArityProblem('log(1, 2, 3)')), { name: 'log', got: 3, want: [1, 2] });
    // the documented form, and both valid log overloads
    assert.equal(c.fnArityProblem('moonphase(due, 28, 0)'), null);
    assert.equal(c.fnArityProblem('log(100)'), null);
    assert.equal(c.fnArityProblem('log(1024, 2)'), null);
    // a NESTED call's commas must not inflate the outer count (top-level commas only)
    assert.equal(c.fnArityProblem('floor(moonphase(today, 28, 0) * 8)'), null);
    assert.deepEqual(norm(c.fnArityProblem('floor(moonphase(today), 2)')),
      { name: 'floor', got: 2, want: [1] }, 'outer checked first, and its own count is 2');
    // variadics and unknown names are never flagged
    assert.equal(c.fnArityProblem('min(1, 2, 3, 4)'), null);
    assert.equal(c.fnArityProblem('notafunction(1)'), null);
    // unbalanced parens is a SYNTAX error, not an arity one - do not claim otherwise
    assert.equal(c.fnArityProblem('moonphase(today'), null);
    assert.equal(c.fnArityProblem(''), null);
  });

  test('#1169: the phrase names the function, the counts, and a shape that works', () => {
    const ph = c.arityPhrase('moonphase(today)');
    assert.match(ph, /moonphase/, 'names the function, not just "a function"');
    assert.match(ph, /1 value where it takes 3/, 'names BOTH counts');
    assert.match(ph, /moonphase\(a, b, c\)/, 'and shows the shape that would work (#1159 house style)');
    assert.match(ph, /moon phase 0 to 1 for a date/, 'reuses MATH_FN_DESC rather than a second copy');
    // an overloaded name offers both shapes
    const lg = c.arityPhrase('log(1, 2, 3)');
    assert.match(lg, /takes 1 or 2/);
    assert.match(lg, /log\(a\) or log\(a, b\)/);
    assert.match(c.arityPhrase('floor()'), /0 values where it takes 1/, 'plural agreement at zero');
    // no expr (an older caller) still yields a true sentence rather than throwing or lying
    assert.match(c.arityPhrase(), /wrong number of values/);
    assert.doesNotMatch(c.arityPhrase(), /undefined|NaN/);
    // it must read as a NOUN phrase: every caller prefixes it
    for (const p of ['This uses ', 'This calculation uses ', 'Invalid expression: ']) {
      assert.doesNotMatch(p + ph, /uses [A-Z]/, 'no sentence-start capital mid-prefix');
    }
    assert.doesNotMatch(ph, /—/, 'no em dashes in user copy');
  });

  test('#1169: the reason chain returns arity LAST, so every specific arm still wins', () => {
    assert.equal(c.mathErrorReason('moonphase(today)'), 'arity');
    assert.equal(c.mathErrorReason('log(1, 2, 3)'), 'arity');
    // the documented form is not an error at all
    assert.equal(c.mathErrorReason('moonphase(today, 28, 0)'), '');
    // an unknown NAME keeps falling through to the caller's own syntax-error fallback: that is a
    // different mistake and 'bad ref'/syntax already covers it. This is the pair that used to be
    // indistinguishable, so it is the assertion that proves the fix.
    assert.equal(c.mathErrorReason('notafunction(1)'), '');
    assert.notEqual(c.mathErrorReason('moonphase(today)'), c.mathErrorReason('notafunction(1)'));
    // precedence: a bad ref INSIDE a wrong-arity call stays 'bad ref' (more actionable)
    assert.equal(c.mathErrorReason('qqq + 1'), 'bad ref');
    assert.equal(c.mathErrorReason('moonphase(qqq)'), 'bad ref', 'the typo outranks the count');
    // and the phrase map routes the code
    assert.match(c.mathReasonPhrase('arity', 'moonphase(today)'), /moonphase given 1 value/);
  });

  // #1133: a tested core proves NOTHING about whether the callers pass the expression. Without
  // the second argument every one of these sites would silently render the generic fallback.
  test('#1169: every mathReasonPhrase call site passes the expression', () => {
    const calls = nonEmpty([..._src.matchAll(/mathReasonPhrase\(([^;]*?)\)\s*(?:\|\||;|\s*\?)/g)]
      .map(m => m[1]), 'mathReasonPhrase call sites');
    assert.ok(calls.length >= 4, `expected the 4 known call sites, found ${calls.length}`);
    for (const args of calls) {
      assert.ok(/,/.test(args), `a mathReasonPhrase call passes no expression: mathReasonPhrase(${args})`);
    }
  });
}

// ── #1175: significant figures, the scale-independent sibling of decimal places ──────────────
// From the 2026-07-29 persona fleet: a postdoc would THINK in Pointliner but not RECORD in it,
// because `decimals` cannot state precision across scales. Measured on main before the change:
// decimals:3 turns 0.0124 into 0.012 (loses a real digit) and 1240 into 1,240.000 (invents three).
{
  test('#1175 parseNumFmt: sigfigs is additive, and decimals still wins if both arrive', () => {
    // the three-arg shape every existing caller used must be byte-identical
    assert.deepEqual({ ...c.parseNumFmt('2', '£', '') }, { decimals: 2, prefix: '£' });
    assert.equal(c.parseNumFmt('', '', ''), null, 'all blank is still no record at all');
    assert.deepEqual({ ...c.parseNumFmt('', '', '', 3) }, { sigfigs: 3 });
    assert.deepEqual({ ...c.parseNumFmt('', '$', '%', 4) }, { sigfigs: 4, prefix: '$', suffix: '%' });
    // Unreachable through the UI (the fields blank each other), so this is the imported-OPML guard.
    assert.deepEqual({ ...c.parseNumFmt('2', '', '', 3) }, { decimals: 2 },
      'decimals wins and sigfigs is DROPPED, so no existing record changes meaning');
    // 1..15; toPrecision allows more but past ~15 a double only reports float noise
    for (const bad of [0, -1, 16, 100, 2.5, 'x'])
      assert.equal(c.parseNumFmt('', '', '', bad), null, `sigfigs ${bad} is rejected`);
    assert.deepEqual({ ...c.parseNumFmt('', '', '', 1) }, { sigfigs: 1 });
    assert.deepEqual({ ...c.parseNumFmt('', '', '', 15) }, { sigfigs: 15 });
  });

  test('#1175 formatNumDisplay: significant figures hold across scales, and keep trailing zeros', () => {
    // the postdoc's two numbers, which are the acceptance test
    assert.equal(c.formatNumDisplay(1 / 3, { sigfigs: 3 }), '0.333');
    assert.equal(c.formatNumDisplay(0.0124, { sigfigs: 3 }), '0.0124');
    // THE reason the field exists: one setting, same meaning at every magnitude
    assert.equal(c.formatNumDisplay(0.0124, { sigfigs: 3 }), '0.0124');
    assert.equal(c.formatNumDisplay(1.24, { sigfigs: 3 }), '1.24');
    assert.equal(c.formatNumDisplay(1240, { sigfigs: 3 }), '1,240', 'and still groups thousands');
    // trailing zeros are KEPT: in significant figures that IS the precision claim, and it matches
    // the recorded rule for the sibling field ("exactly that many, trailing zeros included")
    assert.equal(c.formatNumDisplay(2.5, { sigfigs: 3 }), '2.50');
    assert.equal(c.formatNumDisplay(1, { sigfigs: 3 }), '1.00');
    // affixes still apply
    assert.equal(c.formatNumDisplay(0.0124, { sigfigs: 2, prefix: '~', suffix: ' g' }), '~0.012 g');
    // an exponent is never shown to a user: fall back to the full-precision formatter
    assert.ok(!/e/i.test(c.formatNumDisplay(124000, { sigfigs: 3 })), 'no exponent leaks out');
    // 1e-9 falls back to formatMathResult, which itself prints an exponent at that magnitude --
    // pre-existing behaviour the sigfigs branch must not worsen, and cannot fix here.
    assert.equal(c.formatNumDisplay(1e-9, { sigfigs: 3 }), c.formatMathResult(1e-9),
      'a magnitude the default cannot express plainly falls back to it, unchanged');
    // non-finite still routes to the shared formatter
    assert.equal(c.formatNumDisplay(Infinity, { sigfigs: 3 }), c.formatMathResult(Infinity));
  });

  test('#1175 the default is untouched — no existing pill changes appearance', () => {
    // Every one of these is what main printed before the change. A regression here is a silent
    // reformat of every document in existence, so it is the pin that matters most.
    for (const [v, want] of [[1 / 3, '0.33333333'], [0.0124, '0.0124'], [289.68192, '289.68192'],
                             [1000, '1,000'], [700000, '700,000'], [0, '0']])
      assert.equal(c.formatNumDisplay(v, null), want, `default for ${v}`);
    assert.equal(c.formatConvertResult(0.0254), '0.02540', 'the #983 deciding case is untouched');
    assert.equal(c.formatConvertResult(289.68192), '289.7');
    assert.equal(c.estNumFmt(5, null), '5', 'the estimate trim survives');
    assert.equal(c.estNumFmt(4.1, null), '4.1');
  });

  test('#1175 estNumFmt honours sigfigs below 1, where the default now also carries 3 (#1177)', () => {
    assert.equal(c.estNumFmt(0.0124, { sigfigs: 3 }), '0.0124');
    // An explicit sigfigs keeps its trailing zeros: the author asked for exactly that many.
    // A lab notebook lives below 0.001 routinely, so ignoring the author there would defeat the field.
    assert.equal(c.estNumFmt(0.00004, { sigfigs: 2 }), '0.000040');
    // REWRITTEN by #1177, not loosened. This read `(0.00004).toPrecision(3)` -- i.e. '0.0000400',
    // untrimmed -- because the sub-0.001 escape returned toPrecision's raw output. #1177 unified the
    // sub-1 default onto ONE rule with the trim the default path uses everywhere else, so the padding
    // goes. The PRECISION is unchanged (still 3 s.f.), which is what this line was written to lock.
    assert.equal(c.estNumFmt(0.00004, null), '0.00004', 'default: 3 s.f. with the trailing zeros trimmed');
    assert.equal(+c.estNumFmt(0.00004, null), +(0.00004).toPrecision(3), 'the VALUE is still 3 s.f.');
    // decimals keeps precedence, matching parseNumFmt
    assert.equal(c.estNumFmt(1.239, { decimals: 2 }), c.formatNumDisplay(1.239, { decimals: 2 }));
    // REWRITTEN by #1177. This asserted `'0'` on purpose, to record that #1175 deliberately left the
    // collapse alone ("a default change is not this PR's business") while proving the new field could
    // recover the number. #1177 IS that default change: the postdoc should not have needed a format
    // setting to stop her measurement reading as zero.
    assert.equal(c.estNumFmt(0.00253, null), '0.00253', 'the default no longer collapses (#1177)');
    assert.equal(c.estNumFmt(0.00253, { sigfigs: 3 }), '0.00253', 'and sigfigs agrees with it');
  });

  test('#1177 the sub-1 band keeps its digits, and the ladder has no cliff', () => {
    // MEASURED on main: the escape fired only below 0.001, so the ladder broke at exactly that edge --
    // 0.000999 rendered with 3 significant figures and 0.001 rendered as a bare `0`. It protected the
    // SMALLER side and abandoned the band immediately above, which is backwards.
    assert.equal(c.estNumFmt(0.000999, null), '0.000999', 'just below the old edge, unchanged');
    assert.equal(c.estNumFmt(0.001, null), '0.001', 'AT the old edge -- this was "0"');
    assert.equal(c.estNumFmt(0.0010001, null), '0.001', 'and just above it');
    // The band that printed a bare zero for a non-zero number: [0.001, 0.005).
    for (const x of [0.001, 0.00212, 0.00253, 0.00294, 0.00499])
      assert.notEqual(c.estNumFmt(x, null), '0', `${x} must not render as a bare zero`);
    // The damage ran all the way to 1, because toFixed(2) only carries 3 s.f. once |x| >= 1.
    assert.equal(c.estNumFmt(0.0124, null), '0.0124', 'was "0.01" -- the postdoc\'s own number');
    assert.equal(c.estNumFmt(0.0253, null), '0.0253', 'was "0.03"');
    assert.equal(c.estNumFmt(0.253, null), '0.253', 'was "0.25"');
    assert.equal(c.estNumFmt(0.999, null), '0.999', 'was "1", which rounded away a real digit');
    // The trim is what keeps the common cases clean -- no 0.100 / 0.500 noise.
    assert.equal(c.estNumFmt(0.1, null), '0.1', 'not 0.100');
    assert.equal(c.estNumFmt(0.5, null), '0.5', 'not 0.500');
    // The acceptance case, through the shared headline the pill and the export both use.
    assert.equal(c.distHeadline({ mean: 0.00253, p5: 0.00212, p95: 0.00294 }, null),
      '0.00253 (0.00212 – 0.00294)', 'the lab-notebook pill read "0 (0 – 0)" before');
    // NOTHING at or above 1 moves. These are the #1115 outputs, byte-identical.
    for (const [x, want] of [[1.005, '1'], [2.48, '2.48'], [5, '5'], [4.1, '4.1'], [9.99, '9.99'],
                             [12.4, '12.4'], [700, '700'], [1240, '1,240'], [86500, '86,500'], [700000, '700,000']])
      assert.equal(c.estNumFmt(x, null), want, `${x} is above the band and must not move`);
    // The explicit-format branch now runs FIRST. Before #1177 the magnitude escape ran ahead of it and
    // read only `sigfigs`, so raising the threshold to 1 without reordering would have started
    // silently dropping an author's `decimals` on every value below 1. This is that guard.
    assert.equal(c.estNumFmt(0.253, { decimals: 2 }), '0.25', 'an explicit decimals still wins below 1');
    assert.equal(c.estNumFmt(0.253, { decimals: 4 }), '0.2530', 'including its trailing zeros');
    assert.equal(c.estNumFmt(0.253, { sigfigs: 2 }), '0.25', 'and an explicit sigfigs');
    assert.equal(c.estNumFmt(0.253, { prefix: '£' }), '£0.253', 'prefix-only is not an explicit format, so the default applies');
    // #1115's recorded decision, CHECKED not assumed: a genuinely tiny number stays scientific. An
    // earlier draft of #1177 proposed removing exponentials outright before this pin was found.
    assert.match(c.estNumFmt(0.00000012, null), /e-/, 'the scientific tail is deliberate and survives');
  });

  test('#1177 a display string is never parsed back into a number', () => {
    // The variables dialog teaches percentile()/chanceover() with a threshold taken from the
    // distribution's own middle, because #1101 wanted the line "copy-pasteable rather than an abstract
    // example the reader has to translate". It read `Number(estNumFmt(mid))` -- and estNumFmt GROUPS
    // THOUSANDS, so Number("700,000") is NaN. Measured: every median at or above 1000 produced
    // `{= chanceover(cost, NaN)} is NaN%`, which for anything money-scale is the normal case. There was
    // no test on this line at all, which is why it shipped.
    assert.ok(/const t = Number\.isFinite\(mid\) \? \+\(\+mid\.toPrecision\(3\)\) : 0;/.test(_src),
      'the threshold must be derived from the NUMBER, not from the formatted string');
    // The class, not just the instance: a grouped/affixed display string is never numeric input.
    // Read the COMMENT-STRIPPED view. This change's own comment quotes the call it removed, and that
    // is the THIRD time in three PRs that writing a fix's rationale turned its own negative assertion
    // red (#1178's runner pin and the #1175 parseNumFmt call-site pin were the other two). Prose about
    // the old form must not be able to disarm the guard against it.
    assert.ok(!/Number\(estNumFmt\(/.test(NC),
      'no caller may parse estNumFmt output back into a number — grouping makes that NaN');
    assert.ok(!/parseFloat\(estNumFmt\(|Number\(formatNumDisplay\(|parseFloat\(formatNumDisplay\(/.test(NC),
      'the same holds for formatNumDisplay, which groups for the same reason');
    // ...and prove the stripped view still contains the code, so the two negatives above cannot pass
    // by reading an empty string (the #1132 shrinking-input failure mode).
    assert.ok(NC.includes('function estNumFmt(') && NC.length > 1e6,
      'the comment-stripped view must still hold the source for those negatives to mean anything');
    // And the arithmetic it replaced it with: never NaN, and rounded to something a reader would type.
    const t = mid => Number.isFinite(mid) ? +(+mid.toPrecision(3)) : 0;
    assert.equal(t(149823.4), 150000, 'a median of 149823.4 teaches 150000, not 149823');
    assert.equal(t(1500), 1500);
    assert.equal(t(700000), 700000, 'the case that was NaN');
    assert.equal(t(0.253), 0.253, 'and a sub-1 median keeps its digits');
    assert.equal(t(0.00253), 0.00253);
    assert.equal(t(NaN), 0, 'a non-finite median falls back to 0 rather than propagating');
    for (const m of [0.253, 0.00253, 2.48, 1500, 149823.4, 700000])
      assert.ok(Number.isFinite(t(m)), `${m} must not produce NaN`);
  });

  test('#1181 a dialog preview never announces an action it cannot perform', () => {
    // openMathDialog previews by rendering a REAL pill. Driven before the fix, that dragged TWO inert
    // affordances into the dialog: the .math-edit pencil (role=button, "Edit formula and number
    // format") and the pill's own title/aria ("Click to edit the formula or number format."), inside
    // the very dialog a click would have opened. Both did nothing -- a preview is innerHTML from a
    // string and no handler is ever attached to it -- so this is "claims an action it hasn't got",
    // which is the P4 case, not a broken action. On hover:none the pencil is a visible 26px chip with
    // a 44px tap overlay, so the dead target was prominent.
    const rmp = fnBody(_src, 'renderMathPill');
    assert.ok(/function renderMathPill\(key, m, opts = \{\}\)/.test(_src),
      'renderMathPill takes an opts bag; the other three call sites rely on it being optional');
    assert.ok(/const pencil = opts\.preview \? ''/.test(rmp), 'the pencil is gated on preview mode');
    // Hoisting settled a drift the five copies had accumulated: three wrote the glyph bare, two wrote
    // it aria-hidden. The span carries the accessible name, so the glyph is decorative and aria-hidden
    // is correct -- and this line is why that is a DECISION rather than a comment. Added because a
    // mutation removing it passed green: the consolidation was claimed and not guarded.
    assert.ok(/const pencil = [\s\S]{0,220}<i class="fa-solid fa-pen" aria-hidden="true"><\/i>/.test(rmp),
      'the pen glyph is decorative and must stay aria-hidden — the span already names the control');
    assert.ok(/const editTip = opts\.preview \? ''/.test(rmp), 'and so is the click invitation');
    // THE CALL SITE, not only the renderer: a renderer that CAN suppress chrome proves nothing about
    // whether its one preview caller asks it to (#1133).
    const omd = fnBody(_src, 'openMathDialog');
    assert.ok(/renderMathPill\('preview', \{[^}]*\}, \{ preview: true \}\)/.test(omd),
      "openMathDialog's preview must pass { preview: true }");
    // THE CLASS, reusing the #1178 walker: which pill renderers do previews call at all? Exactly one
    // today, and it opts in. A frozen list, so a new preview rendering a pill has to make this choice
    // deliberately instead of inheriting the chrome by accident.
    const PILL_RENDERERS = /\b(renderMathPill|renderEstPill|renderDicePill|renderVarPill|renderQueryPill|renderSeqPill|renderGrammarPill)\s*\(/;
    const withPills = nonEmpty(previewCallbacks(_src), 'preview callbacks')
      .filter(cb => PILL_RENDERERS.test(cb.body));
    assert.equal(withPills.length, 1,
      `exactly one preview renders a pill today; found ${withPills.length}. A new one must pass ` +
      'a preview flag and be added here, or it ships the same inert chrome.');
    assert.ok(/\{ preview: true \}/.test(withPills[0].body), 'and that one opts out of the chrome');
    // No preview may emit interactive chrome DIRECTLY either -- surveyed, none does.
    for (const cb of previewCallbacks(_src))
      assert.ok(!/role="button"|<button/.test(cb.body),
        `a preview callback (via ${cb.via}) emits a button; nothing in a preview is ever wired`);
  });

  test('#1184 every dialog preview is NAMED, and none of them announces', () => {
    // A preview answers "what will this do", and that answer was visual only: the div had no role and
    // no name, so a screen-reader user met it as loose text after the field. Owner's call was to LABEL
    // it and stop there (UXP-281); announce-on-settle stays a separate decision.
    const NCsrc = NC;   // comment-stripped: this change's own comment quotes the attributes below
    const sites = [...NCsrc.matchAll(/className = 'io-preview';/g)];
    assert.equal(sites.length, 2,
      `two places create a preview div -- openInsertDialog's shared runner and openVarDialog's ` +
      `hand-built form. Found ${sites.length}: a new one must be named here too, or it ships silent.`);
    // Both set the role AND the name. `role="group"` is not decoration: a bare <div> maps to role
    // `generic`, and ARIA-in-HTML PROHIBITS naming on generic, so aria-label there is spec-invalid and
    // inconsistently exposed. Measured in Chromium's a11y tree: a bare div DID surface the name, which
    // is precisely why this was checked rather than assumed -- one engine is not support.
    assert.equal((NCsrc.match(/prev\.setAttribute\('role', 'group'\)/g) || []).length, 2,
      'both previews take a role that permits a name');
    assert.equal((NCsrc.match(/prev\.setAttribute\('aria-label', 'Preview: '/g) || []).length, 2,
      'and both are named "Preview: <field>" -- the field disambiguates the calendar dialog\'s four');
    // THE DECISION, pinned as a negative. These previews re-render on EVERY keystroke (#1178), so a
    // polite live region would be a stream of interruptions rather than help. If a future change wants
    // announcement it must be debounced-on-settle and must revisit UXP-281, not bolt aria-live on.
    const runner = fnBody(NCsrc, 'openInsertDialog');
    assert.ok(!/prev\.setAttribute\('aria-live'|role', 'status'|role', 'alert'/.test(runner),
      'no live region on a per-keystroke preview -- that is the decision UXP-281 records');
    assert.ok(!/io-preview[^\n]*aria-live/.test(NCsrc), 'and none is declared in markup either');
    // The class must not be nested inside itself: openColFmtDialog's callback used to return a
    // <span class="io-preview"> INSIDE the div that already carries it, which would make the named
    // group ambiguous to read and a selector-based guard unable to tell the two apart.
    assert.ok(!/<span class="io-preview">/.test(NCsrc),
      'a preview callback must not re-declare the class inside the div that already has it');

    // #1506 widened this guard's REACH, not its claim. It said "every dialog preview is NAMED" while
    // seeing only the two that carry the io-preview class; the Schedule dialog builds its three by
    // hand with inline styles and the Properties dialog builds an error div, and all four were
    // invisible here and shipped unnamed. They now go through nameFieldPreview, which applies the
    // same role + "Preview: " name UXP-281 chose, so there is one way to name a field message.
    const namer = fnBody(NCsrc, 'nameFieldPreview');
    assert.match(namer, /setAttribute\('role', 'group'\)/, 'the hand-built messages take a role that permits a name');
    assert.match(namer, /setAttribute\('aria-label', 'Preview: '/, 'and the same name shape as the io-preview divs');
    assert.ok(!/aria-live/.test(namer), 'and no live region, which is the half UXP-281 decided against');
    // Identity, not a count: name the sites, so a new hand-built message shows up as a missing site
    // rather than as a number that happens to still add up.
    const SITES = { dateField: 'the Schedule start/due field messages',
                    openDueDateDialog: "the Schedule dialog's repeat message",
                    openPropsDialog: 'the Properties error message' };
    for (const [fn, what] of Object.entries(SITES)) {
      assert.match(fnBody(NCsrc, fn), /nameFieldPreview\(/,
        `${what} (${fn}) is a field message built by hand, and must be named the same way`);
    }
    const named = nonEmpty([...NCsrc.matchAll(/^\s*nameFieldPreview\(/gm)], 'nameFieldPreview call sites');
    assert.equal(named.length, Object.keys(SITES).length,
      `${named.length} hand-built messages are named and ${Object.keys(SITES).length} are accounted for ` +
      `above. A new one must be listed here, or it ships unnamed exactly as these four did.`);
  });

    test('#1506 a dialog Save that refuses says so, through one helper', () => {
    // Measured, driving the real app: the Save button ENABLED, pressed, and nothing happened at all.
    // No props written, no toast, nothing in the live region, and in the Schedule dialog not a pixel
    // changed. The app already owned the sentence (the typed /due door flashes it) and the channel
    // (builderFormApply announces its own refusal, "P4: no silent refocus"); only the dialogs omitted it.
    const fn = fnBody(_src, 'refuseDialogSave');
    assert.match(fn, /announce\(why\)/, 'the refusal reaches the live region: a failed action is an event');
    assert.match(fn, /setAttribute\('aria-invalid', 'true'\)/,
      'and the field focus is about to land on says so on arrival, which is what makes that move mean something');
    assert.match(fn, /input\.focus\(\)/, 'the focus move that already worked is kept');
    // UXP-281 (#1184) is a standing decision, and this must not reopen it by the back door.
    assert.doesNotMatch(fn, /aria-live/, 'a refusal announces through announce(), never by bolting a live region on');

    // THE CENSUS. Both enabled-Save dialogs route every refusal through the one helper. A bare
    // `inp.focus(); return;` is exactly what this issue was.
    const DOORS = { openDueDateDialog: 3, openPropsDialog: 1 };
    for (const [door, n] of Object.entries(DOORS)) {
      const body = fnBody(_src, door);
      const calls = nonEmpty(body.match(/refuseDialogSave\(/g) || [], `${door} refusals`);
      assert.equal(calls.length, n, `${door} has ${n} ways to refuse and each must say so; found ${calls.length}`);
      assert.doesNotMatch(body, /\{\s*\w+F?\.inp\.focus\(\);\s*return;\s*\}/,
        `${door} still bails silently somewhere: a refocus with no word is the whole defect`);
    }
    // The two dialogs that DISABLE their commit instead are a different, visible pattern and are
    // deliberately untouched. Measured: their commit button reports disabled true on an invalid form.
    for (const door of nonEmpty(['openInsertDialog', 'openVarDialog'], 'disabled-commit dialogs')) {
      assert.match(fnBody(_src, door), /okBtn\.disabled = !valid\(\)/,
        `${door} refuses by disabling its commit, which is visible; it must keep doing that`);
    }
  });

  test('#1506 aria-invalid tracks the field, and never outlives the mistake', () => {
    // A field that keeps claiming to be invalid after it has been fixed is the same defect one level
    // down: the next focus landing announces a lie. markFieldInvalid is called on every keystroke.
    const fn = fnBody(_src, 'markFieldInvalid');
    assert.match(fn, /removeAttribute\('aria-invalid'\)/, 'it clears, not just sets');
    const dlg = fnBody(_src, 'openDueDateDialog');
    const clears = nonEmpty(dlg.match(/markFieldInvalid\(inp, /g) || [], 'Schedule live-validity updates');
    assert.ok(clears.length >= 4,
      `each of the three fields re-states its validity as you type; found ${clears.length} updates`);
    assert.match(fnBody(_src, 'openPropsDialog'), /markFieldInvalid\(el, false\)/,
      'and a Properties save that succeeds clears what the last refusal marked');
  });
test('#1175 every fmt door offers the field, and the two are exclusive (#1133 call sites)', () => {
    // A record with a field one dialog can set and another cannot is a P1 break, so all THREE must
    // offer it. A tested core proves nothing about whether the dialogs pass it.
    const fields = nonEmpty([..._src.matchAll(/key: 'sigfigs',/g)], "the sigfigs dialog fields");
    assert.equal(fields.length, 3,
      'the math pill, base column and estimate dialogs each offer Significant figures');
    const decls = nonEmpty([..._src.matchAll(/exclusiveWith: '(decimals|sigfigs)'/g)].map(m => m[1]),
      'exclusiveWith declarations');
    assert.equal(decls.filter(d => d === 'decimals').length, 3, 'each sigfigs field clears decimals');
    assert.equal(decls.filter(d => d === 'sigfigs').length, 3, 'and each decimals field clears sigfigs');
    // the runner must actually honour the declaration, or the fields are decoration
    assert.match(fnBody(_src, 'openInsertDialog'), /f\.exclusiveWith && inp\.value\.trim\(\) !== ''/,
      'openInsertDialog blanks the partner field on input');
    // and every parseNumFmt call site must pass the 4th argument
    const calls = nonEmpty([..._src.matchAll(/parseNumFmt\(([^)]*)\)/g)].map(m => m[1])
      .filter(a => /decimals/.test(a)), 'parseNumFmt call sites');
    for (const a of calls)
      assert.match(a, /sigfigs/, `a parseNumFmt call site drops sigfigs: parseNumFmt(${a})`);
  });
}

// ── unfold/refold + offset translation (UXP-30 / UXP-31) ───────────────────────
// In edit mode, inline-able [[type:key]] tokens unfold to their {…} source; the
// token form is LONGER, so any offset captured against the edit buffer must be
// translated before it touches the folded text. foldedOffsetFor is that inverse
// (of unfoldedPrefixLen); foldedTextForSave is what undo entries must record.
{
  const diceNode = (text) => {
    const n = c.mkNode(text);
    n.dice = [{ key: 'k1', expr: '2d6', result: 7 }];
    return n;
  };

  test('artifactToShorthand — inline-able forms and atomic nulls', () => {
    assert.equal(c.artifactToShorthand('dice', { expr: '2d6' }), '{2d6}');
    assert.equal(c.artifactToShorthand('math', { expr: '2*r' }), '{= 2*r}');
    assert.equal(c.artifactToShorthand('var', { name: 'str', expr: '' }), '{str}');   // display-only unfolds
    assert.equal(c.artifactToShorthand('var', { name: 'str', expr: '5' }), null);     // declaring stays atomic
    // only ANONYMOUS grammar shorthand unfolds — a named grammar (incl. a
    // collapsed roll table) is a declaration: unfolding would lose the doc-wide
    // name on edit (re-promotion is anonymous), so it stays atomic
    assert.equal(c.artifactToShorthand('grammar', { def: 'origin: red | blue', origin: 'origin', anon: true }), '{red | blue}');
    assert.equal(c.artifactToShorthand('grammar', { def: 'color: red | blue', origin: 'color' }), null);       // named stays atomic
    assert.equal(c.artifactToShorthand('grammar', { def: 'a: x\nb: y', origin: 'a', anon: true }), null);      // multi-rule stays atomic
  });

  test('unfoldArtifacts ⇄ foldedTextForSave — untouched shorthand folds back verbatim', () => {
    const n = diceNode('a [[dice:k1]] b');
    c.unfoldArtifacts(n);
    assert.equal(n.text, 'a {2d6} b');
    assert.equal(c.foldedTextForSave(n), 'a [[dice:k1]] b'); // the token, frozen roll intact
    assert.equal(n.text, 'a {2d6} b');                       // non-mutating
    n.text = 'a {2d6} b plus prose';                         // typing elsewhere
    assert.equal(c.foldedTextForSave(n), 'a [[dice:k1]] b plus prose');
    c.refoldArtifacts(n);
    assert.equal(n.text, 'a [[dice:k1]] b plus prose');
  });

  test('foldedTextForSave — an EDITED shorthand is left literal (promote owns it)', () => {
    const n = diceNode('a [[dice:k1]] b');
    c.unfoldArtifacts(n);
    n.text = 'a {3d8} b'; // user rewrote the dice source
    assert.equal(c.foldedTextForSave(n), 'a {3d8} b');
    c.refoldArtifacts(n);
  });

  test('foldedOffsetFor — identity on token-free text', () => {
    const n = c.mkNode('plain prose only');
    assert.equal(c.foldedOffsetFor(n, 0), 0);
    assert.equal(c.foldedOffsetFor(n, 7), 7);
  });

  test('foldedOffsetFor — before / after / inside an unfolded span', () => {
    // folded 'a [[dice:k1]] b' (token at 2..13) ⇄ unfolded 'a {2d6} b' (span at 2..7)
    const n = diceNode('a [[dice:k1]] b');
    assert.equal(c.foldedOffsetFor(n, 0), 0);
    assert.equal(c.foldedOffsetFor(n, 2), 2);   // just before the span
    assert.equal(c.foldedOffsetFor(n, 7), 13);  // just after the span → just after the token
    assert.equal(c.foldedOffsetFor(n, 4), 13);  // INSIDE the span → snaps after the token
    assert.equal(c.foldedOffsetFor(n, 9), 15);  // end of buffer → end of folded text
  });

  test('foldedOffsetFor — the UXP-30 repro: stale offset would land inside the token', () => {
    // unfolded buffer 'a {2d6} b ' caret at end (10); folded 'a [[dice:k1]] b ' —
    // raw 10 falls inside [[dice:k1]] (2..13): the corruption. Translated → 16 (end).
    const n = diceNode('a [[dice:k1]] b ');
    assert.equal(c.foldedOffsetFor(n, 10), 16);
  });

  test('foldedOffsetFor — a just-promoted token uses its LITERAL width, not the canonical rebuild (#766)', () => {
    // The user typed the literal `{=1+1}` (6 chars), but the math record's canonical shorthand is
    // `{= 1+1}` (7). A caret offset captured at the end of the unfolded LITERAL buffer
    // (`{=1+1}rest!` = 11) must map to the true end of the folded text, not one char short of it.
    const node = { text: '[[math:k1]]rest!', math: [{ key: 'k1', expr: '1+1' }] };
    const T = '[[math:k1]]'.length;              // folded token width (11); text.length = T + 5 (16)
    assert.equal(c.artifactToShorthand('math', node.math[0]), '{= 1+1}');   // canonical is 7 chars
    // WITHOUT the promoted-literal hint → canonical width (7): offset 11 lands one char short (the bug)
    vm.runInContext('_promotedLit = new Map();', c._context);
    assert.equal(c.foldedOffsetFor(node, 11), T + 4);            // 11 - 7 = 4 past token → short of end
    // WITH the literal width recorded (6) → offset 11 maps to the real end (after "rest!")
    vm.runInContext('_promotedLit = new Map([["k1", 6]]);', c._context);
    assert.equal(c.foldedOffsetFor(node, 11), T + 5);           // 11 - 6 = 5 → end of "rest!"
    assert.equal(node.text.length, T + 5);                      // confirm T+5 IS the end
    // a key NOT in the map falls back to canonical (no false match on unique keys)
    assert.equal(c.foldedOffsetFor({ text: '[[math:k2]]x', math: [{ key: 'k2', expr: '1+1' }] }, 8),
      '[[math:k2]]'.length + 1);                                // 8 - 7 = 1 → after 'x'
    vm.runInContext('_promotedLit = new Map();', c._context);   // reset for later tests
  });

  test('foldedOffsetFor — accumulates across multiple inline-able tokens', () => {
    const n = c.mkNode('[[dice:a1]]+[[math:m1]] end');
    n.dice = [{ key: 'a1', expr: '2d6' }];
    n.math = [{ key: 'm1', expr: '2*r' }];
    // unfolded: '{2d6}+{= 2*r} end' (17) ⇄ folded (27)
    assert.equal(c.foldedOffsetFor(n, 6), 12);   // between the two tokens
    assert.equal(c.foldedOffsetFor(n, 17), 27);  // end ↔ end
  });

  test('foldedOffsetFor — atomic tokens (declaring var / named grammar) are identity', () => {
    const n = c.mkNode('x [[var:v1]] y');
    n.vars = [{ key: 'v1', name: 'str', expr: '5' }]; // declaring → no unfold
    assert.equal(c.foldedOffsetFor(n, 14), 14);
    const n2 = c.mkNode('x [[grammar:r1]] y');        // named grammar → atomic, no unfold
    n2.grammar = [{ key: 'r1', def: 'loot: a | b', origin: 'loot', result: 'a' }];
    assert.equal(c.foldedOffsetFor(n2, 18), 18);
  });

  test('foldedOffsetFor ∘ unfoldedPrefixLen — round-trips folded boundary offsets', () => {
    const n = diceNode('a [[dice:k1]] b');
    for (const p of [0, 1, 2, 13, 14, 15]) { // every plain-text/boundary offset
      assert.equal(c.foldedOffsetFor(n, c.unfoldedPrefixLen(n, n.text.slice(0, p))), p);
    }
  });
}

// ── classifyBraceBody (UXP-6: the typo signal) ───────────────────────────────
// Classifies a {body} the way promoteBraceBody will treat it on exit, with
// explicit rules/vars (pure). 'invalid' is the set that used to fail SILENTLY:
// styled as valid grammar (or as nothing) but left as literal text on exit.

test('classifyBraceBody: valid artifact bodies classify artifact', () => {
  assert.equal(c.classifyBraceBody('2d6', {}, {}), 'artifact');           // dice
  assert.equal(c.classifyBraceBody('= 2*3', {}, {}), 'artifact');         // expression
  assert.equal(c.classifyBraceBody('= x', {}, { x: 5 }), 'artifact');     // expr over a var
  assert.equal(c.classifyBraceBody('a|b 2|c', {}, {}), 'artifact');       // alternation
  assert.equal(c.classifyBraceBody('color', { color: ['red'] }, {}), 'artifact'); // known rule
  assert.equal(c.classifyBraceBody('str', {}, { str: 3 }), 'artifact');   // known var
  // a typed decl whose formula references a not-yet-defined var is a valid artifact
  // (a live formula, not a frozen pick) — the {y := x} regression, edit-mode side
  assert.equal(c.classifyBraceBody('y := x', {}, {}), 'artifact');
  assert.equal(c.classifyBraceBody('total := x + z', {}, {}), 'artifact');
});

test('classifyBraceBody: attempted-but-broken bodies classify invalid (no more silent failure)', () => {
  assert.equal(c.classifyBraceBody('2d6kh', {}, {}), 'invalid');  // dice sniff passes, parse fails
  assert.equal(c.classifyBraceBody('= 2*', {}, {}), 'invalid');   // malformed expression
  assert.equal(c.classifyBraceBody('=', {}, {}), 'invalid');      // empty expression attempt
  assert.equal(c.classifyBraceBody('= x', {}, {}), 'invalid');    // expr over an unknown var
  assert.equal(c.classifyBraceBody('colr', { color: ['red'] }, {}), 'invalid'); // unknown name (typo)
});

test('classifyBraceBody: prose braces stay literal (the escape hatch)', () => {
  assert.equal(c.classifyBraceBody('hello world', {}, {}), 'literal');
  assert.equal(c.classifyBraceBody('', {}, {}), 'literal');
  assert.equal(c.classifyBraceBody('  ', {}, {}), 'literal');
});

test('classifyBraceBody: a dice-looking body that fails parseDice still falls through like promoteBraceBody', () => {
  // promoteBraceBody does NOT stop at the failed dice branch — '2d6|1d4' then
  // promotes as alternation. The classifier must mirror that fall-through.
  assert.equal(c.classifyBraceBody('2d6|1d4', {}, {}), 'artifact');
});

// ── braceTypeLabel (UXP-7: shorthand live preview) ────────────────────────────
test('braceTypeLabel: identifies the pill type for every valid artifact body', () => {
  const [dt] = c.braceTypeLabel('2d6', {}, {});          assert.equal(dt, 'dice');
  const [mt] = c.braceTypeLabel('= 2*3', {}, {});        assert.equal(mt, 'math');
  const [at] = c.braceTypeLabel('a|b', {}, {});          assert.equal(at, 'grammar');
  const [rt, rd] = c.braceTypeLabel('color', { color: ['red'] }, {});
  assert.equal(rt, 'grammar'); assert.equal(rd, 'color');
  const [vt, vd] = c.braceTypeLabel('str', {}, { str: 5 });
  assert.equal(vt, 'var'); assert.equal(vd, 'str = 5');
});

