  assert.ok(/id:'clock'[^\n]*section:'Trackers'/.test(arr) && /id:'meter'[^\n]*section:'Trackers'/.test(arr) && /id:'progress'[^\n]*section:'Trackers'/.test(arr),
    'progress/clock/meter sit in a Trackers section');
