test('document tabs: strip is gated on workspaceDir, keyboard-cycle wired + documented', () => {
  // The strip hides without a connected workspace (the cheap-version gate).
  assert.ok(/if \(!workspaceDir \|\| !openTabs\.length\)/.test(_src),
    'renderDocTabs is not gated on workspaceDir + a non-empty tab list');
  // Next/prev-tab chords call cycleDocTab, alongside the existing global chords.
  assert.ok(/ctrl && e\.shiftKey && e\.key===']'/.test(_src) && /ctrl && e\.shiftKey && e\.key==='\['/.test(_src),
    'Ctrl/Cmd+Shift+] / [ tab-cycle handlers not found');
  assert.ok(_src.includes('function cycleDocTab'), 'cycleDocTab not found');
  // ARIA tablist semantics (P3) and keyboard activation alongside pointer (caret invariant).
  assert.ok(_src.includes('role="tablist"') && _src.includes("setAttribute('role', 'tab')"),
    'doc-tabs is not an ARIA tablist with role=tab tabs');
  // #1514: this used to be the WHOLE keyboard claim, and it is exactly the vacuous shape CLAUDE.md
  // warns about -- "a handler exists" passed while Home/End were unbound, the tab stop never moved,
  // and every close button was a Tab stop. The presence claim stays (it is still true and still
  // worth pinning); what it asserts about is now pinned by name below.
  assert.ok(/tab\.addEventListener\('keydown'/.test(_src),
    'tabs lack a keyboard handler (added alongside the mousedown path)');
  // Discoverable: an essential ?-panel row advertises the shortcut.
  assert.ok(_src.includes("id:'file-tabs'"),
    'the tab-cycle shortcut is not listed in the essential shortcuts registry');
  // The current folder-backed doc is registered as a tab from the single chokepoint
  // (renderWorkspaceAffordance), so every connect/switch/reconnect path surfaces the strip.
  assert.ok(_src.includes('openTabs = tabAdd(openTabs, fileName)') && _src.includes('persistOpenTabs'),
    'the current doc is not registered as a tab from renderWorkspaceAffordance');
  // Shows the strip with an EXPLICIT display (the CSS default is display:none, so '' re-hides
  // it — the build-but-stay-hidden bug). Must set 'flex', not ''.
  assert.ok(/strip\.style\.display = 'flex'/.test(_src),
    'renderDocTabs must set display:flex explicitly (not "", which the CSS default re-hides)');
});

// #1514: `renderDocTabs` hand-rolled the tablist. Its own comment said "roving tabindex (tablist
// pattern)" and the pattern was implemented nowhere: `tabs[(i + dir + n) % n]?.focus()` -- no
// Home/End, no tab-stop swap, and wrapping where §3 says the roving groups clamp. Measured on four
// documents: Home and End moved NOTHING across 16 primitives (re-measured with 30 tabs and a
// genuinely overflowing strip, still nothing); after roving to tab 1 the tabindexes were STILL
// [-1, 0, -1, -1], so Tab away and Tab back dropped you on the active tab again; and all four
// `.doc-tab-close` buttons reported `tabIndex 0` with no explicit attribute -- six Tab stops for
// four documents, growing one per open document, the first of them a Close button belonging to a
// tab that was itself -1.
//
// §3 already listed the tablist among the seven roving groups, with `roveIndex` named as the shared
// core. Unlike #1512, the doc was right and the code was wrong.
test('#1514 the document tab strip is one roving group, not one Tab stop per document', () => {
  const { tabFocusAfterClose, tabCloseSay } = c;
  // ---- 1. where focus goes after a close. `tabClose`'s `nextActive` cannot answer this: it is
  // null for a background tab, and focus still has to land somewhere.
  assert.equal(tabFocusAfterClose(['a', 'b', 'c'], 'a'), 'b', 'the tab that slid into the slot');
  assert.equal(tabFocusAfterClose(['a', 'b', 'c'], 'b'), 'c');
  assert.equal(tabFocusAfterClose(['a', 'b', 'c'], 'c'), 'b', 'closing the last tab falls back one');
  assert.equal(tabFocusAfterClose(['a'], 'a'), null, 'nothing left to focus');
  assert.equal(tabFocusAfterClose(['a', 'b'], 'zz'), null, 'a name that is not open moves nothing');
  assert.equal(tabFocusAfterClose([], 'a'), null);
  // it agrees with tabClose wherever tabClose has an opinion (the ACTIVE-tab case), so the strip's
  // focus and the document that opens cannot drift apart.
  for (const name of ['a', 'b', 'c']) {
    assert.equal(tabFocusAfterClose(['a', 'b', 'c'], name), c.tabClose(['a', 'b', 'c'], name, name).nextActive,
      `closing the active tab ${name}: focus and the newly-active document must be the same tab`);
  }

  // ---- 2. P4: the strip just loses a chip. Say what went and what is left.
  assert.equal(tabCloseSay('one', 3), 'Closed one. 3 documents open.');
  assert.equal(tabCloseSay('one', 1), 'Closed one. 1 document open.', 'singular at one');
  assert.equal(tabCloseSay('one', 0), 'Closed one. No documents open.', 'and never "0 documents"');

  // ---- 3. THE CALL SITES. The shared roving core, and the hand-rolled modulo gone.
  const rd = fnBody(_src, 'renderDocTabs');
  assert.ok(rd, 'renderDocTabs must exist');
  assert.ok(rd.includes('const to = roveIndex(e.key, i, tabs.length)') && rd.includes('roveTo(tab, tabs[to])'),
    'the tablist must navigate through the shared roveIndex/roveTo, like the other six groups');
  assert.ok(!/%\s*n\)\]\?\.focus\(\)/.test(rd) && !rd.includes("+ (e.key === 'ArrowRight' ? 1 : -1) + n"),
    'the hand-rolled wrapping modulo must be gone -- it is what skipped Home/End and the tab-stop swap');
  assert.ok(/e\.key === 'ArrowRight' \|\| e\.key === 'ArrowLeft' \|\| e\.key === 'Home' \|\| e\.key === 'End'/.test(rd),
    'Home and End must be claimed keys, not unbound');
  // one Tab stop for the strip: the close button is not a native default any more.
  assert.ok(rd.includes("close.setAttribute('tabindex', '-1')"),
    'a close button must not be a Tab stop -- that is the stop-per-document growth');
  // the keyboard door for closing asks for focus back; the pointer door deliberately does not.
  assert.ok(rd.includes("closeDocTab(name, { refocus: true })"),
    'Delete/Backspace on a tab must ask for focus to be restored');
  const clickLine = rd.split('\n').find(l => l.includes("close.addEventListener('click'"));
  assert.ok(clickLine && clickLine.includes('closeDocTab(name);') && !clickLine.includes('refocus'),
    'the ✕ must NOT pull focus into the strip -- its mousedown preventDefault exists to keep the caret');
  // a tab must be findable by name for focus to return to it
  assert.ok(rd.includes('tab.dataset.name = name'), 'a tab must carry its filename for focus to find it');

  const cd = fnBody(_src, 'closeDocTab');
  assert.ok(cd.includes('announce(tabCloseSay(displayName(name), tabs.length))'),
    'closing a tab must announce on BOTH doors');
  assert.ok(cd.includes('if (opts.refocus) focusDocTab(tabFocusAfterClose(before, name))'),
    'the keyboard door must place focus through the pure core, not by hand');
  assert.ok(/const before = openTabs\.slice\(\);/.test(cd),
    'the pre-close list must be captured BEFORE the mutation, or the neighbour cannot be computed');

  const fd = fnBody(_src, 'focusDocTab');
  assert.ok(fd, 'focusDocTab must exist');
  assert.ok(fd.includes("tabs.forEach(t => t.setAttribute('tabindex', t === el ? '0' : '-1'))"),
    'restoring focus must also move the single tab stop, or the group has two stops or none');
  assert.ok(/const add = strip\?\.querySelector\('\.doc-tab-add'\)/.test(fd) && fd.includes('restoreChromeReturn()'),
    'with no tab left, focus must fall to the + or back into the document -- never to <body>');

  // ---- 4. the WRAPPING sibling is untouched. §3 calls Ctrl/Cmd+Shift+] / [ a cycle, and clamping
  // the arrows would be a regression if it had quietly clamped that too.
  assert.ok(_src.includes('function tabCycle'), 'tabCycle must survive');
  assert.ok(/return tabs\[\(i \+ dir \+ tabs\.length\) % tabs\.length\];/.test(_src),
    'Ctrl/Cmd+Shift+] / [ must still WRAP -- it is the cycle, the arrows are the roving group');

  // ---- 5. P2: the keys are documented where the guide teaches the strip. Removing the close
  // buttons from the Tab order makes Delete the keyboard door, so it has to be written down.
  const entry = _src.slice(_src.indexOf("id:'workspace-documents'"));
  assert.ok(entry.slice(0, 6000).includes('Delete to close it'),
    'the concept guide must teach the strip keys it now depends on');
});

// #1515: Escape out of the Capture strip stranded focus on the toolbar button, from TWO
// independent causes -- fixing either one alone leaves the bug:
//   1. capInputKeydown's Escape ran closeCapture() and then let the event BUBBLE to the
//      #capture-strip listener, which ran it again with the return target already consumed, so the
//      second pass took the button fallback and overrode the focus the first pass had restored.
//      Measured: closes = 2, with a committed capture and without one.
//   2. the return target was a stored ELEMENT (`document.activeElement`), and a committed capture
//      calls render(), so it was detached -- measured `isConnected === false` -- and even a single
//      close fell through to the button. This one breaks the ✕/click door too.
//
// THE FAMILY IS THREE. `#capture-strip`, `#journal-strip` and `#chronicle-strip` each held their own
// element slot and each fell through to their own toolbar button after a committed entry (driven:
// all three stranded). They now share one exit, so they cannot drift apart again.
test('#1515 a toolbar strip hands the caret back to the interrupted edit, not to its own button', () => {
  // spread into a host object: the core runs in the vm realm, so a bare deepEqual would compare
  // prototypes across realms and fail on a correct answer.
  const plan = (...a) => ({ ...c.stripExitPlan(...a) });
  // ---- 1. the exit policy, by value.
  assert.deepEqual(plan(true, 'a', 'b'), { to: 'edit', id: null },
    'a restored chrome-return wins: the interrupted edit, caret and all');
  assert.deepEqual(plan(false, 'a', 'b'), { to: 'cursor', id: 'a' },
    'else the remembered point');
  assert.deepEqual(plan(false, null, 'b'), { to: 'cursor', id: 'b' },
    'else the first row -- the Escape blur rung, never the toolbar button');
  assert.deepEqual(plan(false, null, null), { to: 'button', id: null },
    'the button is the LAST resort, for a document with no points to go back to');
  assert.deepEqual(plan(true, null, null), { to: 'edit', id: null },
    'and a restored edit does not need a row at all');

  // ---- 2. CAUSE 1: the handled Escape must stop travelling.
  const cik = fnBody(_src, 'capInputKeydown');
  assert.ok(/e\.key === 'Escape'\) \{ e\.preventDefault\(\); e\.stopPropagation\(\);/.test(cik),
    "the strip input's Escape must stopPropagation -- without it the #capture-strip listener closes a second time");
  // and the belt: a second close cannot undo the first one's restore.
  for (const [fn, flag] of [['closeCapture', 'captureOpen'], ['closeJournalStrip', 'journalOpen'], ['closeChronicleStrip', 'chronicleOpen']]) {
    assert.ok(fnBody(_src, fn).includes(`if (!${flag}) return;`),
      `${fn} must be idempotent -- a second door must not re-run the exit`);
  }

  // ---- 3. CAUSE 2: an id survives a re-render; an element does not.
  // (deliberately narrow: `ioReturnFocus` is the DIALOG mechanism, which resolves through
  // `dialogReturnTarget()` and already handles a detached target by design. The three strips were
  // the outlier, and they are the subject.)
  for (const slot of ['captureReturnFocus', 'journalReturnFocus', 'chronicleReturnFocus']) {
    assert.ok(!_src.includes(slot),
      `${slot} must be gone -- a strip may not hold document.activeElement, because a commit re-renders and detaches it`);
  }
  for (const [open, slot] of [['openCaptureDialog', 'captureReturnId'], ['openJournalStrip', 'journalReturnId'],
                              ['openChronicleStrip', 'chronicleReturnId']]) {
    const body = fnBody(_src, open);
    assert.ok(body.includes('armChromeReturn()') && body.includes(`${slot} = captureCurrentPointId()`),
      `${open} must remember the interrupted edit by id (armChromeReturn), not by element`);
  }

  // ---- 4. CENSUS RATCHET, read off the app's OWN enumeration of the family. The CSS rule that
  // gives the strips their shared look is the list of what a strip is; a fourth one joining it has
  // to come past this test.
  const rule = nonEmpty([..._src.matchAll(/^(#[a-z-]+-strip(?:,#[a-z-]+-strip)+)\{display:none/gm)],
    'the shared toolbar-strip CSS rule (the file’s own list of strips)');
  const strips = nonEmpty(rule[0][1].split(',').map(x => x.replace('#', '')), 'strip ids in that rule');
  assert.ok(strips.length >= 3, `the family is at least capture/journal/chronicle (${strips.join(', ')})`);
  for (const id of strips) {
    // the function that closes this strip is the one that takes its .on class off
    const marker = `getElementById('${id}').classList.remove('on')`;
    assert.ok(_src.includes(marker), `${id} must have a close path`);
    const fn = nonEmpty([...(_src.match(/function (\w+)\([^)]*\) \{[\s\S]*?\n\}/g) || [])]
      .filter(b => b.includes(marker)), `a function that closes ${id}`)[0];
    assert.ok(fn.includes('stripReturnFocus('),
      `${id} closes without the shared exit -- that is how the three drifted apart in the first place`);
  }

  // ---- 5. the shared exit itself.
  const sr = fnBody(_src, 'stripReturnFocus');
  assert.ok(sr, 'stripReturnFocus must exist');
  assert.ok(sr.includes('stripExitPlan(restoreChromeReturn()'),
    'the exit must be decided by the pure plan, not re-derived per strip');
  assert.ok(/flatIndex\.get\(returnId\) != null \? returnId : null/.test(sr),
    'a remembered point that is not ON SCREEN must not become the row cursor (driven: a collapsed-away point painted nothing and announced a positionless string)');
  assert.ok(/document\.activeElement\?\.blur\?\.\(\); moveRowCursor\(plan\.id\)/.test(sr),
    'the blur is load-bearing: focus left on a toolbar button means the outline arrows never reach the row cursor (#1512)');
});

// #1517: the capture strip's destination chip said "top level (no inbox set)" while `doCapture`
// dropped the point into a DIFFERENT slot's inbox, and its toast said so -- the strip and the toast
// contradicted each other on screen at the same moment. Measured: inbox 1 = Beta, target slot 4
// (never set), capture "groceries" -> `Beta[groceries]`, toast "· Beta", chip still "top level" for
// every later capture that session. It reproduces on the FIRST capture of a session too, so no
// in-strip switch is needed to reach it.
//
// The two surfaces were two independent expressions: the chip read `inboxAt(captureSlot)`, the
// commit read `inboxAt(captureSlot) || resolveInbox() || root`. The middle term already CONTAINED
// the first (`resolveInbox` opens with `inboxAt(captureSlot)`), so all it ever added was "…or the
// first non-empty slot" -- a cross-slot redirect named nowhere: not on the chip, not in the manager
// (no chip carries `.cur`), and not in §3, which documents only "an empty slot adopts the selected
// point".
test('#1517 the chip that names the capture destination and the commit that uses it are one reader', () => {
  const { captureDestSlotId, captureDestSay } = c;
  // ---- 1. the destination, by value. A slot's OWN inbox or nothing.
  assert.equal(captureDestSlotId(['b'], 1), 'b', 'a set slot');
  assert.equal(captureDestSlotId(['b'], 4), null, 'an UNSET slot is not a redirect into slot 1');
  assert.equal(captureDestSlotId(['b', null, 'g'], 2), null, 'nor into a later set slot');
  assert.equal(captureDestSlotId(['b', null, 'g'], 3), 'g');
  assert.equal(captureDestSlotId([], 1), null, 'no inboxes at all -> the top level (#559)');
  assert.equal(captureDestSlotId(['b'], 0), null, 'slots are 1-based');
  assert.equal(captureDestSlotId(['b'], -1), null);
  assert.equal(captureDestSlotId(['b'], 1.5), null);
  assert.equal(captureDestSlotId(null, 1), null, 'a document with no inbox list');
  assert.equal(captureDestSlotId(undefined, 1), null);

  // ---- 2. P4: changing the target changes where your next capture goes, and the chord was silent.
  assert.equal(captureDestSay(1, 'Beta'), 'Capturing to inbox 1: Beta');
  assert.equal(captureDestSay(10, 'Beta'), 'Capturing to inbox 0: Beta', 'slot 10 reads as 0, like its chord');
  assert.equal(captureDestSay(4, null), 'Inbox 4 is not set. Captures land at the top level.',
    'and an unset slot says where the capture WILL go, not just that the slot is empty');
  assert.match(captureDestSay(4, null), /top level/,
    'the words on the chip and the words in the live region must be the same words');

  // ---- 3. THE AGREEMENT. Both surfaces read the one function; neither re-derives.
  const dc = fnBody(_src, 'doCapture');
  const rc = fnBody(_src, 'renderCaptureStrip');
  assert.ok(dc.includes('const inbox = captureDest();'), 'the commit reads the shared destination');
  // and the shared reader is TOTAL: it never hands back null, so #559's "no inbox is a working
  // state" survives being the only fallback left.
  assert.match(_src, /function captureDest\(\) \{ return nodeById\(captureDestSlotId\(root\.inboxes, captureSlot\)\) \|\| root; \}/,
    'captureDest must fall back to the top level, never to null or to another slot');
  assert.ok(rc.includes('const landing = captureDest();') && rc.includes('const inbox = landing === root ? null : landing;'),
    'and so does the chip that names it -- null there means "the top level", which is what its copy says');
  const code = (b) => b.split('\n').map(l => l.replace(/\s*\/\/.*$/, '')).join('\n');
  assert.ok(!code(dc).includes('resolveInbox'),
    'the cross-slot redirect must be gone from the capture commit: it is what the chip never named');
  // and neither surface may re-derive the destination for itself -- re-deriving is how they came
  // to disagree. (Scoped to the two bodies: the three-term expression still appears verbatim in the
  // comment that explains why it went, and a global string search would match that.)
  assert.ok(!code(dc).includes('inboxAt(captureSlot)') && !code(rc).includes('inboxAt(captureSlot)'),
    'neither the commit nor the chip may read the slot directly any more -- both go through captureDest()');

  // ---- 4. CENSUS. `resolveInbox` is still right for the doors that have NO destination chip to
  // contradict -- they name where the point went in their own toast. A new caller has to be
  // classified here, because "which door may silently pick another slot" is the whole question.
  const srcCode = _src.split('\n').map(l => l.replace(/^\s*\/\/.*$/, '')).join('\n');
  const calls = nonEmpty([...srcCode.matchAll(/(?<!function )resolveInbox\(\)/g)], 'resolveInbox call sites');
  assert.equal(calls.length, 3,
    'exactly three doors may still fall back across slots — the URL/share append, its toast, and ' +
    'the link-and-create default. None of them shows a destination chip to contradict: each names ' +
    'where the point actually went. A fourth caller has to be classified here.');
  // the #559 zero-setup promise those doors carry is untouched
  assert.match(_src, /function appendTextToInbox[\s\S]{0,400}resolveInbox\(\) \|\| root/,
    'URL/share append keeps the top-level fallback');

  // ---- 5. the slot chord speaks.
  const ts = fnBody(_src, 'captureTargetSlot');
  assert.ok(ts.includes('announce(captureDestSay(slot, dest === root ? null : crumbLabel(dest)))'),
    'targeting a slot must say where captures now land -- it was silent even on a correctly labelled slot');
  // the order that matters is the READ, not the announce: `captureDest()` is what resolves the
  // slot, so hoisting it above the assignment names the slot you just left.
  assert.ok(ts.indexOf('captureSlot = slot') < ts.indexOf('const dest = captureDest()'),
    'the destination must be read AFTER the switch, or it names the old one');
});

// #1518: `#fn-panel` docked at `bottom:0` UNDER the opaque touch quick bar, so the whole footnote
// editor was invisible. `syncFnPanelBottom` wrote an inline `bottom = kbH + 'px'`, and with no
// software keyboard kbH is 0 — an inline 0 that beats the `@media(hover:none)` rule
// `#fn-panel,#var-panel{bottom:var(--qbar-h,0px)}` written for exactly this case.
//
// Measured at 390x844 AND 768x1024: 53px overlap, the panel's only interactive row entirely inside
// the bar, `elementFromPoint` returning `qb-capture`. The editor was FOCUSED the whole time and
// typing reached the model — invisible, not unreachable, which is why nothing errored.
test('#1518 a bottom-docked panel clears the touch quick bar', () => {
  const { panelFloorPx } = c;
  // ---- 1. the floor, by value. MAX, not sum: `position:fixed` resolves against the LAYOUT
  // viewport, so while the keyboard is up the bar is behind it (measured: bar 791..844, visual
  // viewport ending at 544) and adding both would leave a 53px gap.
  assert.equal(panelFloorPx(0, 53), 53, 'no keyboard: clear the quick bar');
  assert.equal(panelFloorPx(300, 53), 300, 'keyboard up: clear the keyboard, and NOT keyboard+bar');
  assert.notEqual(panelFloorPx(300, 53), 353, 'summing them would float the panel above the keyboard');
  assert.equal(panelFloorPx(300, 0), 300, 'desktop-style: no bar');
  assert.equal(panelFloorPx(0, 0), 0, 'nothing at the bottom: dock flush');
  assert.equal(panelFloorPx(53, 300), 300, 'whichever is taller, in either order');
  // junk floors read as absent rather than throwing or going negative
  assert.equal(panelFloorPx(-5, 53), 53);
  assert.equal(panelFloorPx(null, 53), 53);
  assert.equal(panelFloorPx('x', 53), 53);
  assert.equal(panelFloorPx(undefined, undefined), 0);

  // ---- 2. THE CALL SITE. The bare kbH is what pinned the panel to the bar.
  const fb = fnBody(_src, 'syncFnPanelBottom');
  assert.ok(fb.includes("panel.style.bottom = (open ? panelFloorPx(kbH, quickBarHeight()) : 0) + 'px'"),
    'the panel must lift by the FLOOR, not by the keyboard inset alone');
  assert.ok(!/panel\.style\.bottom = kbH \+ 'px'/.test(fb),
    'the bare keyboard-only lift must be gone — it is an inline 0 that beats the CSS lift');
  // the CSS rule the inline style was overriding is still there and still names both panels.
  // NEWLINE-ANCHORED on purpose: the explanatory comment in syncFnPanelBottom quotes this rule
  // verbatim, so a bare `includes` matched the comment and the guard passed with the real rule
  // deleted — measured, by its own mutant surviving.
  const CSS_LIFT = '\n  #fn-panel,#var-panel{bottom:var(--qbar-h,0px)}';
  assert.ok(_src.includes(CSS_LIFT),
    'the hover:none lift must survive: it is what #var-panel relies on entirely');

  // ---- 3. CENSUS RATCHET, over the app's OWN list of bottom-docked panels. `bottomStackHeight`
  // is where the file enumerates them; a fourth one added there must declare how it clears the bar.
  const stack = fnBody(_src, 'bottomStackHeight');
  const panels = nonEmpty([...stack.matchAll(/on\('([a-z-]+-panel)'\)/g)].map(m => m[1]),
    'the docked panels bottomStackHeight counts');
  assert.deepEqual(panels.slice().sort(), ['bl-panel', 'fn-panel', 'var-panel'],
    'the bottom-docked panel family');
  const LIFT = {
    // each panel, and the ONE mechanism that lifts it over the quick bar
    'var-panel': () => _src.includes(CSS_LIFT),
    'fn-panel':  () => fnBody(_src, 'syncFnPanelBottom').includes('quickBarHeight()'),
    'bl-panel':  () => fnBody(_src, 'syncBlPanelBottom').includes('quickBarHeight()'),
  };
  for (const id of panels) {
    assert.ok(LIFT[id], `${id} is docked at the bottom and nothing here says how it clears the quick bar`);
    assert.ok(LIFT[id](), `${id} no longer clears the quick bar`);
  }
});

// #1519: the same blanket line lived verbatim in all THREE transient strips —
// `else if (e.key !== 'Tab') e.stopPropagation()`. Right for typing (a plain key in the box is an
// edit, not a command) and wrong for chords: it swallowed Ctrl+Z, Ctrl+Y, Ctrl+Shift+Z and each
// strip's OWN toggle. Measured on all three: after a commit the undo chords were total no-ops while
// the commit sat on `undoStack` the whole time, and Ctrl+Shift+I could not close the strip it had
// opened — which §3 documents as "the same chord closes it".
//
// The fix is an ALLOW-LIST because a blanket forward regresses the textarea: the global handler
// claims Ctrl+V whenever `activeContentId == null` (always true inside a strip) and Ctrl+C / Ctrl+X
// whenever points are selected. Driven: all four text chords stay local, and no point is pasted,
// copied or cut by them.
test('#1519 a transient strip keeps the edits and passes the listed global chords', () => {
  const P = (o) => c.stripChordPasses(o);
  // ---- 1. the policy, by value.
  assert.equal(P({ key: 'Tab' }), true, 'Tab still reaches the focus trap');
  assert.equal(P({ key: 'z' }), false, 'an unmodified key is an EDIT and stays in the box');
  assert.equal(P({ key: 'i', shift: true }), false, 'so is a shifted letter');
  // undo/redo, gated on whether the BOX has anything of its own to undo
  assert.equal(P({ key: 'z', ctrl: true }), true, 'a fresh box: Ctrl+Z reaches the document stack');
  assert.equal(P({ key: 'z', ctrl: true, typed: true }), false,
    'mid-draft: Ctrl+Z is native text undo, and forwarding it would undo a POINT instead');
  assert.equal(P({ key: 'y', ctrl: true }), true, 'Ctrl+Y redo');
  assert.equal(P({ key: 'Z', ctrl: true, shift: true }), true, 'Ctrl+Shift+Z redo');
  assert.equal(P({ key: 'Z', ctrl: true, shift: true, typed: true }), false, 'and it is gated the same way');
  // the strips' own toggles
  assert.equal(P({ key: 'I', ctrl: true, shift: true }), true, 'Ctrl+Shift+I closes the capture strip');
  assert.equal(P({ key: 'j', ctrl: true, shift: true }), true, 'Ctrl+Shift+J the journal');
  assert.equal(P({ key: 'i', ctrl: true }), false, 'without Shift it is not the toggle');
  // meta-modified variants are the same chord on macOS; alt is not
  assert.equal(P({ key: 'z', ctrl: true, alt: true }), false, 'Alt makes it a different chord');
  assert.equal(P({ key: '' }), false);
  assert.equal(P({}), false);

  // ---- 2. THE REGRESSION GUARD, checked against the global handler rather than restated. Every
  // chord the global handler would MISFIRE on from inside a strip must be refused by the policy.
  // (the global handler is an anonymous document listener, so it is matched in _src by its chords
  // rather than sliced out by name)
  const claimed = nonEmpty([...(_src.match(/ctrl && e\.key==='[a-z]'/g) || [])], 'single-letter ctrl chords in the global handler');
  for (const [chord, why] of [
    ['v', 'pastes POINTS into the outline when activeContentId is null — always true inside a strip'],
    ['c', 'copies the SELECTED POINTS instead of the selected text'],
    ['x', 'cuts the selected points out of the document'],
    ['f', 'steals focus to the search box mid-capture'],
  ]) {
    assert.ok(claimed.some(s => s.includes(`'${chord}'`)),
      `precondition: the global handler still claims Ctrl+${chord.toUpperCase()} (${why})`);
    assert.equal(P({ key: chord, ctrl: true }), false,
      `Ctrl+${chord.toUpperCase()} must stay in the textarea: forwarded, it ${why}`);
  }
  assert.equal(P({ key: 'a', ctrl: true }), false, 'and Ctrl+A selects the box text, not the points');

  // ---- 3. CENSUS. All three strips route through the ONE policy, and none keeps the blanket line.
  // The family is read off the shared CSS rule, the same ratchet #1515 established.
  const rule = nonEmpty([..._src.matchAll(/^(#[a-z-]+-strip(?:,#[a-z-]+-strip)+)\{display:none/gm)],
    'the shared toolbar-strip CSS rule');
  const strips = nonEmpty(rule[0][1].split(',').map(x => x.replace('#', '')), 'strip ids');
  assert.deepEqual(strips.slice().sort(), ['capture-strip', 'chronicle-strip', 'journal-strip']);
  // the keydown handler for each strip's textarea, by the function that builds it
  const HANDLER = { 'capture-strip': 'capInputKeydown', 'journal-strip': 'renderJournalStrip', 'chronicle-strip': 'renderChronicleStrip' };
  for (const id of strips) {
    const body = fnBody(_src, HANDLER[id]);
    assert.ok(body, `${id}: no handler found (${HANDLER[id]})`);
    assert.ok(body.includes('if (!stripKeyEscapes(e)) e.stopPropagation()'),
      `${id} must route its key policy through the shared reader`);
    assert.ok(!/e\.key !== 'Tab'\) e\.stopPropagation\(\)/.test(body),
      `${id} must not keep the blanket line — it is the whole defect, in three places`);
  }
  // and every strip stamps `typed`, or its undo gate reads a flag nobody sets
  const stamps = nonEmpty([..._src.matchAll(/input\.addEventListener\('input', \(\) => \{ input\.dataset\.typed = '1';/g)],
    "the strips' typed stamps");
  assert.equal(stamps.length, 3, 'all three strips must stamp `typed`, or Ctrl+Z forwards mid-draft');
});

// #1520: in the Guided command builder — the phone's MAIN `@` and `/` menu — 48 of 89 command
// NAMES rendered at `clientWidth 0`, with their descriptions at 0 too, leaving a column of bare
// syntax fragments. `.builder-typed` is `white-space:nowrap; flex-shrink:0`, so it claimed its full
// content width (up to 336px) and `.cmd-info` (flex:1, min-width:0) collapsed into what was left.
//
// Measured at 1280x900 as well: 14 names still at zero width, so this was never only a narrow
// defect — a fix aimed at the `@media(max-width:560px)` rule would have left them.
//
// This is CSS, so the pins here are the shape and the DRIVEN check is the guard. That split is the
// point: UXP-250 shipped this row and verified PRESENCE only ("0 without a label, 0 without a
// description"), at one width, which cannot see a zero-width render.
test('#1520 the builder row gives the name the width and stacks the syntax', () => {
  // the row wraps, and the syntax takes its own line rather than the row's width
  assert.ok(_src.includes('\n.builder-item{flex-wrap:wrap}'),
    'the builder row must be allowed to wrap');
  assert.ok(_src.includes('.builder-item>.builder-typed{flex-basis:100%;margin-left:26px;max-width:calc(100% - 26px);overflow:hidden;text-overflow:ellipsis}'),
    'the syntax example takes its own line, indented past the icon and ellipsised if still too wide');
  // and the name column keeps min-width:0 — a floor there pushes the row PAST the nav, which reads
  // as "visible" to clientWidth and is clipped on screen (measured; that is how this was first
  // mis-fixed).
  assert.ok(_src.includes('.builder-item>.cmd-info{display:flex;flex-direction:column;min-width:0;flex:1;gap:1px}'),
    'the name column must not carry a min-width floor: it overflows the nav instead of wrapping');

  // UXP-171's remedy is UNTOUCHED. Its `.builder-nav{width:150px}` inside the narrow media query is
  // the proximate cause of the squeeze, and widening or removing it trades this bug for that one
  // ("Builder has no responsive layout"). The fix is at the ROW, not the column.
  assert.ok(_src.includes('\n  .builder-nav{width:150px}'),
    "UXP-171's narrow builder nav must survive — reverting it is not the fix");
  assert.ok(_src.includes('\n.builder-nav{width:260px;'),
    'and the wide default is unchanged too');
});

// #1521: the verbosity dial called a bare `render()`, which tears down the active contenteditable.
// Measured: `activeElement` went to BODY, `activeContentId` to null, and the next four characters
// typed vanished. The filed repro named the two chords; driving the family found ALL FOUR doors
// broken — the File-menu tier indicator and the tier card too, because `setVerbosity` has the same
// bare render as `toggleVerbosity`.
//
// The verifier's narrowing decides the fix. Escape produces the same swallowing and is CORRECT:
// what Escape leaves behind is a painted, announced row cursor, because Escape is a request to
// leave the point. The dial is not, and of eight chords driven mid-edit only these two landed on
// <body> — Ctrl+Shift+V and Ctrl+Shift+X keep the caret. So the caret comes back; a row cursor here
// would make the dial mean "stop editing", which is exactly the P1 break.
test('#1521 the verbosity dial carries the caret across its re-render', () => {
  const plan = (...a) => { const r = c.caretKeepPlan(...a); return r && { ...r }; };
  // ---- 1. the plan, by value.
  assert.deepEqual(plan('n1', 8, true), { id: 'n1', offset: 8 }, 'the point and the offset come back');
  assert.equal(plan(null, 8, true), null, 'nothing was being edited: a plain render');
  assert.equal(plan('n1', 8, false), null, 'the point did not survive the render');
  assert.deepEqual(plan('n1', null, true), { id: 'n1', offset: null },
    'no readable offset still re-enters the point rather than dropping to <body>');
  assert.deepEqual(plan('n1', 0, true), { id: 'n1', offset: 0 }, 'offset 0 is a real offset, not absent');
  assert.deepEqual(plan('n1', -3, true), { id: 'n1', offset: null }, 'a nonsense offset degrades to the point');
  assert.deepEqual(plan('n1', 4.7, true), { id: 'n1', offset: 4 }, 'and a fractional one is floored');

  // ---- 2. BOTH dial writers go through it. The issue named the chords; the census is the doors.
  for (const fn of ['toggleVerbosity', 'setVerbosity']) {
    const body = fnBody(_src, fn);
    assert.ok(body.includes('renderKeepingCaret()'),
      `${fn} must carry the caret across its re-render`);
    assert.ok(!/\n  render\(\);/.test(body),
      `${fn} must not keep a bare render() — that is what tore down the edit`);
  }
  // all four doors reach one of those two writers, so none can drift
  assert.ok(_src.includes("getElementById('fm-tier-ind')?.addEventListener('click', () => toggleVerbosity(1))"),
    'the File-menu tier indicator is a dial door');
  assert.ok(_src.includes("el.addEventListener('click', () => setVerbosity(el.dataset.tier))"),
    'and so is the tier card');

  // ---- 3. the reader itself: save BEFORE the render, restore after, and never invent a caret.
  const rk = fnBody(_src, 'renderKeepingCaret');
  assert.ok(rk, 'renderKeepingCaret must exist');
  assert.ok(rk.indexOf('const off =') < rk.indexOf('render();'),
    'the offset must be read BEFORE the render — afterwards the element is gone');
  assert.ok(rk.includes('caretKeepPlan(id, off, !!nodeById(id))'),
    'and the decision goes through the pure plan, including "did the point survive"');
  assert.ok(rk.includes('if (plan) focusNodeAtOffset(plan.id, plan.offset)'),
    'the restore is the Esc-from-zoom idiom, not a row cursor');
  // and NOT the row-cursor rung: that would make a display setting mean "stop editing"
  assert.ok(!rk.includes('moveRowCursor'),
    'the dial must not paint a row cursor — Escape does that because Escape means LEAVE the point');
});

// #1522: `adoptDoc` cleared `focusedId` and left `selFocusId`/`selAnchorId` pointing into the
// DISCARDED document. `selFocusId ?? selAnchorId ?? flatRows[0]` never reached its fallback — a
// stale id is not a nullish one — so `flatRowStep` returned null on an id `flatIndex` had never
// heard of, and the handler returned BEFORE `preventDefault()`. Measured: the arrows moved nothing,
// painted nothing, announced nothing, and the page scrolled 0 → 40 → 80 → 120 → 80. The scroll is
// the worst part: it reads as "the key did something".
//
// Two halves, and the second is not redundant. `adoptDoc` is the cause, but `restoreSnapshot` (undo)
// also replaces `root` at runtime and does not clear the selection either; the arrow guard covers it
// and any future path, without either one having to remember.
test('#1522 a document swap leaves no cursor pointing at a discarded point', () => {
  const { rowCursorAnchorId, rowCursorEntryIndex } = c;
  // ---- 1. which id the arrows act from. `live` is the membership test flatIndex provides.
  const live = (...ids) => { const s = new Set(ids); return (id) => s.has(id); };
  assert.equal(rowCursorAnchorId('a', 'b', live('a', 'b')), 'a', 'the focus id wins when it is on screen');
  assert.equal(rowCursorAnchorId('a', 'b', live('b')), 'b', 'else the anchor');
  assert.equal(rowCursorAnchorId('a', 'b', live()), null, 'neither on screen: no cursor in THIS document');
  assert.equal(rowCursorAnchorId('stale', null, live('x')), null,
    'a STALE id reads as no cursor — the bug is that `??` cannot see the difference');
  assert.equal(rowCursorAnchorId(null, null, live('x')), null);
  assert.equal(rowCursorAnchorId(null, 'b', live('b')), 'b', 'the anchor alone is enough');
  assert.equal(rowCursorAnchorId('a', 'b', () => false), null, 'a predicate that knows nothing yields nothing');

  // ---- 2. where it lands with no live cursor: the NEAR end, not a step from a row it was never on.
  assert.equal(rowCursorEntryIndex(1, 5), 0, 'ArrowDown enters at the first row');
  assert.equal(rowCursorEntryIndex(-1, 5), 4, 'ArrowUp at the last');
  assert.equal(rowCursorEntryIndex(1, 1), 0, 'a one-row document');
  assert.equal(rowCursorEntryIndex(-1, 1), 0);
  assert.equal(rowCursorEntryIndex(1, 0), null, 'an empty outline has nowhere to land');
  assert.equal(rowCursorEntryIndex(1, null), null);
  assert.equal(rowCursorEntryIndex(1, 2.5), null, 'a non-integer count is not a row count');

  // ---- 3. THE CAUSE. The outgoing document's cursor and selection are dropped on the swap, beside
  // the `focusedId` reset that was already there.
  const ad = fnBody(_src, 'adoptDoc');
  assert.ok(ad, 'adoptDoc must exist');
  assert.ok(/focusedId = null;[\s\S]{0,600}selectedIds\.clear\(\); selAnchorId = null; selFocusId = null;/.test(ad),
    'a swap must drop the row cursor and the selection, not just the zoom');

  // ---- 4. THE DEFENCE. The arrow handler asks flatIndex rather than trusting the variable.
  const arrows = between(_src, "if ((e.key==='ArrowDown' || e.key==='ArrowUp') && activeContentId == null", 'if (!nextId) return;');
  assert.ok(arrows.includes('rowCursorAnchorId(selFocusId, selAnchorId, id => flatIndex.has(id))'),
    'the arrows must resolve their starting row through the membership test');
  assert.ok(!/selFocusId \?\? selAnchorId \?\? flatRows\[0\]/.test(arrows),
    'the `??` chain must be gone — it is what could not see a stale id');
  assert.ok(/if \(fromId == null\) \{\s*e\.preventDefault\(\);/.test(arrows),
    'and with no live cursor the key must be CLAIMED, or the page scrolls and pretends it worked');
  assert.ok(arrows.includes('moveRowCursor(flatRows[rowCursorEntryIndex(dir, flatRows.length)].node.id)'),
    'landing goes through the one writer, so it is painted and announced like every other move');
});

test('UXP-36: pill-pencil keyboard activation (Enter/Space) is present', () => {
  assert.ok(_src.includes('.dice-edit,.mk-edit,.math-edit,.gr-edit,.var-edit'),
    'pill-pencil keyboard activation selector not found in index.html');
});

// ── UXP-19: outline tree + base grid ARIA (the dedicated pass) ────────────────

test('UXP-19: the outline is a flat ARIA tree (role + level/position attributes)', () => {
  assert.ok(_src.includes(`vlist.setAttribute('role', 'tree')`), 'role=tree on #vlist');
  assert.ok(_src.includes(`'aria-multiselectable'`), 'tree is multiselectable');
  assert.ok(_src.includes(`div.setAttribute('role', 'treeitem')`), 'rows are treeitems');
  assert.ok(_src.includes(`'aria-level'`), 'aria-level set');
  assert.ok(_src.includes(`'aria-posinset'`), 'aria-posinset set');
  assert.ok(_src.includes(`'aria-setsize'`), 'aria-setsize set');
});

test('UXP-19: the interactive base table is role="grid"; computed cells aria-readonly', () => {
  assert.ok(_src.includes(`role="grid" aria-label="Base"`), 'role=grid on the base table');
  assert.ok(_src.includes(`tabindex="0" aria-readonly="true"`), 'computed cells aria-readonly');
});

// #488: a full render() must not throw scroll to the top. It captures scrollY at entry and
// restores it after the vlist rebuild, clamped to the new document height, and SKIPS the restore
// when the render intends to move scroll (a zoom changed focusedId, or an empty-doc focusNode runs).
test('#488: render() captures and restores scroll (clamped), skipping intentional scroll moves', () => {
  // whole-source checks (render() is a large function with nested closures; the tokens below
  // are unique to the #488 scroll-restore block, so a src-level match is precise enough)
  assert.ok(/const _preScrollY = window\.scrollY/.test(_src), 'captures scrollY at entry');
  assert.ok(/_focusChanged = focusedId !== _lastRenderFocusedId/.test(_src), 'detects a zoom (focusedId change) to skip restore');
  assert.ok(/if \(!_focusChanged && !firstChildId\)/.test(_src), 'skips restore on a zoom or an empty-doc focusNode');
  assert.ok(/Math\.min\(_preScrollY, maxScroll\)/.test(_src), 'clamps the restored offset to the new (possibly shorter) document height');
  assert.ok(/window\.scrollTo\(0, target\)/.test(_src) && /renderWindow\(false\); \/\/ re-window/.test(_src), 'restores scroll and re-windows for the restored offset (no flash)');
});

test('UXP-19: pills carry tabindex=-1 (programmatic/AT focus reach)', () => {
  const dice = c.renderDicePill('k', { key: 'k', expr: '2d6', total: 7, parts: [] });
  assert.ok(dice.includes('tabindex="-1"'), dice);
  const mk = c.renderMarkovPill('m', { key: 'm', def: 'a -> b', start: 'a', steps: 1, path: ['a', 'b'] });
  assert.ok(mk.includes('tabindex="-1"'), mk);
  const gr = c.renderGrammarPill('g', { key: 'g', def: 'origin: x', origin: 'origin', result: 'x!' });
  assert.ok(gr.includes('tabindex="-1"'), gr);
  const sq = c.renderSeqPill('q', { key: 'q', name: 'Flow', states: ['A', 'B', 'C'], doneFrom: 2 });
  assert.ok(sq.includes('tabindex="-1"'), sq);
});

