// ── UXP-25: ol ordinals from text not type (markdown-lazy numbering) ──────────

test('UXP-25: deriveTypeFromText detects ol from N. prefix', () => {
  assert.equal(c.deriveTypeFromText('1. foo'),   'ol');
  assert.equal(c.deriveTypeFromText('2. bar'),   'ol');
  assert.equal(c.deriveTypeFromText('10. baz'),  'ol');
  assert.equal(c.deriveTypeFromText('1. '),       'ol');   // empty body (Enter-continuation stub)
  assert.equal(c.deriveTypeFromText('- item'),    null);   // ul is NOT ol
  assert.equal(c.deriveTypeFromText('1 nospace'), null);   // missing dot — not ol
  assert.equal(c.deriveTypeFromText('1.nospace'), null);   // missing space after dot — not ol
  assert.equal(c.deriveTypeFromText('# heading'), 'h1');   // existing derivations intact
});

test('UXP-25: continuationPrefix returns 1. for any ol item', () => {
  assert.equal(c.continuationPrefix('1. first'),  '1. ');
  assert.equal(c.continuationPrefix('5. fifth'),  '1. ');  // literal value ignored
  assert.equal(c.continuationPrefix('10. tenth'), '1. ');
  assert.equal(c.continuationPrefix('- bullet'),  '');     // ul stays empty (no continuation)
  assert.equal(c.continuationPrefix('> quote'),   '> ');   // quote path unaffected
});

test('UXP-25: textForDisplay strips ol N. prefix', () => {
  const n1 = c.mkNode('1. buy milk');   n1.type = 'ol';
  const n5 = c.mkNode('5. fifth item'); n5.type = 'ol';
  assert.equal(c.textForDisplay(n1), 'buy milk');
  assert.equal(c.textForDisplay(n5), 'fifth item');
  // h1 prefix stripping intact
  const h = c.mkNode('# Title'); h.type = 'h1';
  assert.equal(c.textForDisplay(h), 'Title');
});

test('UXP-25: the computed ol gutter ordinal is hidden while editing (no double number)', () => {
  // Edit reveals the raw "N. " marker in the text (markdown-first); the position-
  // computed .ol-num gutter must hide then, or the point shows two numbers at once.
  assert.match(_src, /\.node-row:has\(>?\.node-content\[data-editing\]\)>\.ol-num\{visibility:hidden\}/,
    'ol-num hide-while-editing rule missing');
});

test('UXP-25: migrateNodePrefixes adds 1. to legacy type-only ol nodes', () => {
  const root = c.mkRoot();
  const legacy = c.mkNode('buy milk'); legacy.type = 'ol';
  const already = c.mkNode('1. already has prefix'); already.type = 'ol';
  const two = c.mkNode('2. different number'); two.type = 'ol';
  root.children.push(legacy, already, two);
  c.migrateNodePrefixes(root);
  assert.equal(legacy.text, '1. buy milk');   // prefix added
  assert.equal(already.text, '1. already has prefix'); // unchanged
  assert.equal(two.text, '2. different number');       // unchanged (already has N.)
});

// ─── search query language (operators over the existing vocabulary) ──────────

test('search query: parseSearchQuery — words, phrases, tags, is:, negation', () => {
  assert.deepEqual(host(c.parseSearchQuery('alpha Beta')), [
    { neg: false, kind: 'text', value: 'alpha' },
    { neg: false, kind: 'text', value: 'beta' }]);
  assert.deepEqual(host(c.parseSearchQuery('"two words"')),
    [{ neg: false, kind: 'text', value: 'two words' }]);
  assert.deepEqual(host(c.parseSearchQuery('#Work')),
    [{ neg: false, kind: 'tag', value: 'work' }]);
  assert.deepEqual(host(c.parseSearchQuery('is:DONE')),
    [{ neg: false, kind: 'is', value: 'done' }]);
  assert.deepEqual(host(c.parseSearchQuery('-#work -is:done -"a b" -word')), [
    { neg: true, kind: 'tag',  value: 'work' },
    { neg: true, kind: 'is',   value: 'done' },
    { neg: true, kind: 'text', value: 'a b' },
    { neg: true, kind: 'text', value: 'word' }]);
  assert.deepEqual(host(c.parseSearchQuery('')), []);
  assert.deepEqual(host(c.parseSearchQuery('""')), []);   // empty phrase contributes nothing
});

test('search query: malformed tokens stay literal text (the escape hatch)', () => {
  // The escape hatch is INTACT for everything that has a second reading as prose. `is:` is the
  // one exception, and it is not an exception to the hatch's PURPOSE ("never silently match
  // everything") but to its mechanism: `is:` is a reserved closed namespace, so a rejected value
  // has no prose reading, and laundering it into text ran a literal search for "is:tomorrow"
  // rather than matching nothing. It parses invalid now; the three below are unchanged.
  assert.deepEqual(host(c.parseSearchQuery('is:tomorrow')),
    [{ neg: false, kind: 'invalid', field: 'is', value: 'tomorrow', raw: 'is:tomorrow' }]);
  assert.deepEqual(host(c.parseSearchQuery('-')),
    [{ neg: false, kind: 'text', value: '-' }]);            // lone dash is literal
  assert.deepEqual(host(c.parseSearchQuery('#')),
    [{ neg: false, kind: 'text', value: '#' }]);
  assert.deepEqual(host(c.parseSearchQuery('#foo-bar')),
    [{ neg: false, kind: 'tag', value: 'foo-bar' }]);       // hyphens are valid tag chars (nested-tag support)
});

test('search query: tag terms are word-anchored and token-blind', () => {
  const q = s => c.parseSearchQuery(s);
  const n = c.mkNode('ship the #work item');
  assert.equal(c.queryMatchesNode(q('#work'), n), true);
  assert.equal(c.queryMatchesNode(q('#wor'), n), false);     // no prefix match
  assert.equal(c.queryMatchesNode(q('#WORK'), n), true);     // case-insensitive
  const n2 = c.mkNode('about #workshops');
  assert.equal(c.queryMatchesNode(q('#work'), n2), false);   // #work ≠ #workshops
  const n3 = c.mkNode('see [[#abc123|label]]');
  assert.equal(c.queryMatchesNode(q('#abc123'), n3), false); // link targets aren't tags
  const n4 = c.mkNode('#TODO ship it');
  assert.equal(c.queryMatchesNode(q('#todo'), n4), true);    // state keywords are hashtag-shaped
});

test('search: a #tag / has:tag query never matches the [#A] priority marker (#757, lockstep with collectTags)', () => {
  const q = s => c.parseSearchQuery(s);
  // `#DONE [#A] Finish report`: a status keyword + org priority marker, no real `#a` hashtag.
  const n = c.mkNode('#DONE [#A] Finish report');
  assert.equal(c.queryMatchesNode(q('#a'), n), false, '#a must not match the #A inside [#A]');
  assert.equal(c.queryMatchesNode(q('has:tag'), n), false, 'has:tag must not fire on a bare [#A] marker');
  // collectTags blanks the whole `#DONE [#A]` prefix, so search agrees: a status point is
  // found via is:/state: (the render side shows it as a status badge, not a hashtag pill).
  assert.equal(c.queryMatchesNode(q('is:done'), n), true, 'the proper door for a status point');
  // a status keyword with NO priority marker is still a hashtag-shaped match (unchanged behavior)
  assert.equal(c.queryMatchesNode(q('#done'), c.mkNode('#DONE Finish report')), true);
  // a genuine single-letter tag still matches, even alongside a leading [#A]
  assert.equal(c.queryMatchesNode(q('#a'), c.mkNode('[#A] then a real #a tag')), true);
});

test('search query: is:todo / is:done / is:note', () => {
  const q = s => c.parseSearchQuery(s);
  const open     = c.mkNode('#TODO write tests');
  const done     = c.mkNode('#DONE shipped');
  const task     = c.mkNode('- [ ] buy milk');
  const taskDone = c.mkNode('- [x] bought');
  const plain    = c.mkNode('plain prose');
  const noted    = c.mkNode('point'); noted.note = 'context';
  assert.equal(c.queryMatchesNode(q('is:todo'), open), true);
  assert.equal(c.queryMatchesNode(q('is:todo'), task), true);
  assert.equal(c.queryMatchesNode(q('is:todo'), done), false);
  assert.equal(c.queryMatchesNode(q('is:todo'), plain), false);
  assert.equal(c.queryMatchesNode(q('is:done'), done), true);
  assert.equal(c.queryMatchesNode(q('is:done'), taskDone), true);
  assert.equal(c.queryMatchesNode(q('is:done'), open), false);
  assert.equal(c.queryMatchesNode(q('is:done'), plain), false);
  assert.equal(c.queryMatchesNode(q('is:note'), noted), true);
  assert.equal(c.queryMatchesNode(q('is:note'), plain), false);
});

test('search query: AND of all terms; negation; notes searched by text terms', () => {
  const q = s => c.parseSearchQuery(s);
  const n = c.mkNode('#TODO ship the #work report');
  assert.equal(c.queryMatchesNode(q('report #work'), n), true);
  assert.equal(c.queryMatchesNode(q('report #home'), n), false);
  assert.equal(c.queryMatchesNode(q('report -#work'), n), false);
  assert.equal(c.queryMatchesNode(q('report -#home'), n), true);
  assert.equal(c.queryMatchesNode(q('report -is:done'), n), true);
  assert.equal(c.queryMatchesNode(q('report is:todo'), n), true);
  const noted = c.mkNode('title'); noted.note = 'hidden detail';
  assert.equal(c.queryMatchesNode(q('hidden'), noted), true);
  assert.equal(c.queryMatchesNode(q('"hidden detail"'), noted), true);
  assert.equal(c.queryMatchesNode(q('"detail hidden"'), noted), false);
  assert.equal(c.queryMatchesNode([], n), false);  // empty query matches nothing
});

test('search query: searchHighlightNeedles — positive text + tags only', () => {
  const terms = c.parseSearchQuery('alpha #work -beta is:done "a b"');
  assert.deepEqual(host(c.searchHighlightNeedles(terms)), ['alpha', '#work', 'a b']);
  assert.deepEqual(host(c.searchHighlightNeedles([])), []);
});

test('search query: front doors + wiring are present (src pins)', () => {
  // P2: the focus-shown legend under the search box, described to AT
  assert.ok(_src.includes('id="search-hint"'), 'search hint legend missing');
  assert.ok(_src.includes('aria-describedby="search-hint"'), 'input not described by the hint');
  assert.ok(_src.includes('#search-wrap:focus-within #search-hint'), 'hint not shown on focus');
  // the GUIDE (? concept guide) documents the operators — id:'search-ops' in cat:'getting-around'
  assert.ok(_src.includes("id:'search-ops'"), 'GUIDE search-ops entry missing');
  // wiring: applySearch parses once per query
  assert.ok(_src.includes('searchTerms = parseSearchQuery(q)'), 'applySearch does not parse the query');
});

// ─── per-node properties ─────────────────────────────────────────────────────

test('properties: mkNode initialises props as an empty array', () => {
  const n = c.mkNode('hello');
  assert.deepEqual(host(n.props), []);
});

test('properties: parseSearchQuery parses has: and key:value operators', () => {
  assert.deepEqual(host(c.parseSearchQuery('has:status')),
    [{ neg: false, kind: 'has', value: 'status' }]);
  assert.deepEqual(host(c.parseSearchQuery('status:done')),
    [{ neg: false, kind: 'prop', key: 'status', value: 'done' }]);
  assert.deepEqual(host(c.parseSearchQuery('-has:priority')),
    [{ neg: true, kind: 'has', value: 'priority' }]);
  assert.deepEqual(host(c.parseSearchQuery('author:alice')),
    [{ neg: false, kind: 'prop', key: 'author', value: 'alice' }]);
  // is: with an unrecognised value is an INVALID term, not literal text. It used to be a text
  // term, i.e. a literal search for the string "is:tomorrow" — this test asserted that.
  assert.deepEqual(host(c.parseSearchQuery('is:tomorrow')),
    [{ neg: false, kind: 'invalid', field: 'is', value: 'tomorrow', raw: 'is:tomorrow' }]);
});

// ── an unreadable is: filter matches nothing and says why ────────────────────
// The parse half and the message half are deliberately separate: matching is honest the instant
// the token is rejected, while the message waits until the value can no longer become valid.

test('parseSearchQuery — a rejected is: value is invalid, a bare is: is not', () => {
  const p = s => host(c.parseSearchQuery(s))[0];
  assert.equal(p('is:held').kind, 'is', 'a canonical value is untouched');
  assert.equal(p('is:blocked').kind, 'invalid');
  assert.equal(p('is:blocked').field, 'is');
  assert.equal(p('is:blocked').value, 'blocked');
  assert.equal(p('IS:Blocked').value, 'blocked', 'case-insensitive, lowercased like every term');
  assert.equal(p('-is:blocked').neg, true, 'negation still parses onto the invalid term');
  // a bare `is:` is a half-typed query: incomplete, not wrong, and it must not accuse anyone
  assert.equal(p('is:').kind, 'text');
  // the quoted arm is the same rule: no is: value holds a space, so a quoted one cannot be valid
  assert.equal(p('is:"a b"').kind, 'invalid');
  assert.equal(p('is:"a b"').value, 'a b');
  assert.equal(p('is:""').kind, 'text', 'an empty quoted value is incomplete too');
});

test('queryMatchesNode — an invalid term kills its clause, and NEGATING it does not widen', () => {
  const q = s => c.parseSearchQuery(s);
  const n = c.mkNode('#urgent ship the thing');
  // The whole point. queryMatchesNode compares `termMatchesNode(...) === !t.neg`, so a guard
  // placed inside termMatchesNode would make this match EVERY point in the document — a typo
  // turned into a wider query than the user asked for. It must be a hard false above that.
  assert.equal(c.queryMatchesNode(q('-is:blocked'), n), false, 'a negated invalid filter matches NOTHING');
  assert.equal(c.queryMatchesNode(q('is:blocked'), n), false);
  // AND: the clause is dead, so the query is dead. Answering with the #urgent subset would be
  // answering a different question than the one asked, which is the defect, not the fix.
  assert.equal(c.queryMatchesNode(q('is:blocked #urgent'), n), false);
  assert.equal(c.queryMatchesNode(q('#urgent is:blocked'), n), false, 'order does not matter');
  // OR: a clause is explicitly independent, so a dead one takes only its own conjunction down.
  assert.equal(c.queryMatchesNode(q('is:blocked | #urgent'), n), true);
  assert.equal(c.queryMatchesNode(q('is:blocked | #nope'), n), false);
  // and the literal-text behaviour it replaced is gone: a point whose PROSE contains the typo
  // used to match it, because the term was a text search for that string.
  const literal = c.mkNode('the is:blocked filter never worked');
  assert.equal(c.queryMatchesNode(q('is:blocked'), literal), false, 'no longer a literal string search');
});

test('searchHighlightNeedles — a rejected filter is not <mark>ed as if it were a search word', () => {
  // It used to be: an invalid is: token became kind:'text', and every text term is a needle, so
  // the app highlighted the user's own typo in the body.
  assert.deepEqual(host(c.searchHighlightNeedles(c.parseSearchQuery('is:blocked'))), []);
  assert.deepEqual(host(c.searchHighlightNeedles(c.parseSearchQuery('is:blocked ship'))), ['ship']);
});

test('searchTermProblems — the four suggestion ranks, best answer first', () => {
  const msg = (query, opts) => c.searchTermProblems(c.parseSearchQuery(query), opts)[0]?.message || '';
  // rank 1 — a live sequence state is the EXACT answer: state:blocked returns the user's actual
  // rows, where is:held returns a superset. So it outranks the alias map, and names both.
  const withState = { states: ['TODO', 'BLOCKED', 'DONE'] };
  assert.match(msg('is:blocked', withState), /state:blocked/);
  assert.match(msg('is:blocked', withState), /is:held/, 'the held band is still offered as the wider read');
  // rank 2 — no such state, so the curated alias map. `blocked` and `held` share no characters,
  // which is exactly why this map is hand-written rather than an edit-distance metric.
  assert.match(msg('is:blocked', { states: ['TODO'] }), /Try is:held\./);
  assert.ok(!/state:/.test(msg('is:blocked', { states: ['TODO'] })), 'no state is offered when none exists');
  assert.match(msg('is:finished', {}), /Try is:done\./);
  assert.match(msg('is:late', {}), /Try is:overdue\./);
  // rank 3 — a prefix of a real value, on COMMITTED text (no typing flag)
  assert.match(msg('is:duplicate', {}), /Did you mean is:duplicate-title\?/);
  // rank 4 — nothing to suggest, so name the door instead of shrugging
  assert.match(msg('is:bogusfilter', {}), /is:todo, is:done or is:overdue/);
  // every message leads with what went wrong, and house style bans em dashes in user copy
  assert.match(msg('is:bogusfilter', {}), /^is:bogusfilter is not a filter this app knows, so it matches nothing\./);
  for (const qy of ['is:blocked', 'is:finished', 'is:duplicate', 'is:bogusfilter'])
    assert.ok(!msg(qy, withState).includes('—'), `no em dash in user copy: ${qy}`);
});

test('UXP-233: an unreadable due:/start: date is invalid, not a literal text search', () => {
  const p = s => host(c.parseSearchQuery(s))[0];
  // valid forms are untouched
  assert.equal(p('due:today').kind, 'due');
  assert.equal(p('due:2026-07-25').kind, 'due');
  assert.equal(p('start:today+7').kind, 'start');
  assert.equal(p('due:overdue').op, 'overdue');
  // and an unreadable one no longer launders into a literal search for its own string
  assert.equal(p('due:nonsense').kind, 'invalid');
  assert.equal(p('due:nonsense').field, 'due');
  assert.equal(p('start:garbage').field, 'start');
  // the negation trap, same as is:. queryMatchesNode kills the clause regardless of neg, so a
  // typo can never WIDEN a date query into matching everything.
  const n = c.mkNode('#urgent ship it');
  assert.equal(c.queryMatchesNode(c.parseSearchQuery('-due:nonsense'), n), false, 'a negated bad date matches NOTHING');
  assert.equal(c.queryMatchesNode(c.parseSearchQuery('due:nonsense #urgent'), n), false, 'and kills its clause');
  assert.equal(c.queryMatchesNode(c.parseSearchQuery('due:nonsense | #urgent'), n), true, 'the OR side still answers');
});

test('dateStillTyping — a partial date is a prefix, so typing toward one stays quiet', () => {
  // UXP-233 claimed the date grammar was too open to decide this. It is not: the whole vocabulary
  // is five words, today±N, and Y-M-D, so "still on the way there" is a prefix test like is:.
  for (const v of ['', 't', 'to', 'toda', 'tom', 'over', 'w', 'mont',
                   'today+', 'today-', 'today+1', '2', '2026', '2026-', '2026-0', '2026-07', '2026-07-2',
                   '<', '<t', '<2026-07', '>today+'])
    assert.equal(c.dateStillTyping(v), true, `"${v}" is still on its way to a real date`);
  // ...and these can never become one, so they report immediately
  for (const v of ['nonsense', 'yesterday', '2026-13-99x', 'today+x', 'todayy', '2026-07-25-'])
    assert.equal(c.dateStillTyping(v), false, `"${v}" can never become a date`);
  // a bound narrows what is reachable: week and month are WINDOWS, taken only at op '=', so
  // `<week` is final and wrong even though `week` alone would still be in flight.
  assert.equal(c.dateStillTyping('week'), true);
  assert.equal(c.dateStillTyping('<week'), false, 'a bound rules windows out, so <week can never resolve');
  assert.equal(c.dateStillTyping('<month'), false);
});

test('searchTermProblems — a bad date says so, in its own vocabulary', () => {
  const msg = (q, o) => c.searchTermProblems(c.parseSearchQuery(q), o)[0]?.message || '';
  assert.match(msg('due:nonsense', {}), /^due:nonsense is not a date this app can read/);
  assert.match(msg('due:nonsense', {}), /due:today/);
  assert.match(msg('due:nonsense', {}), /due:2026-07-25/);
  assert.match(msg('due:nonsense', {}), /due:today\+7/);
  assert.match(msg('due:nonsense', {}), /before or after/);
  assert.match(msg('start:garbage', {}), /^start:garbage/, 'the message names the field the user typed');
  // the typing rule is shared with is:, so a half-typed date never accuses anyone
  assert.equal(c.searchTermProblems(c.parseSearchQuery('due:2026-0'), { typing: true }).length, 0);
  assert.equal(c.searchTermProblems(c.parseSearchQuery('due:nonsense'), { typing: true }).length, 1);
  // a date message and an is: message are distinct, so neither is a template of the other
  assert.ok(!msg('due:nonsense', {}).includes('is not a filter this app knows'));
  assert.ok(!msg('is:blocked', {}).includes('is not a date this app can read'));
  // no em dashes in user copy, same house rule as everywhere else
  for (const q of ['due:nonsense', 'start:garbage']) assert.ok(!msg(q, {}).includes('—'));
});

test('UXP-232: the roll pill and the math pill carry the reason too', () => {
  // The two surfaces that inherited honest matching from S3-PR4 but showed no reason.
  // {roll:} rides an anonymous grammar, so its cue is the PILL's tooltip, not the inline marker
  // (the marker is text inside the point, where a sentence does not belong).
  const gp = fnBody(_src, 'renderGrammarPill');
  assert.ok(gp.includes('searchTermProblems('), 'the roll pill must ask why it found nothing');
  // #899: the extraction regex must accept the OPTIONAL `folder` modifier, or a folder roll with an
  // unreadable filter loses its reason. The old form of this line fell back to gp.includes('roll'),
  // which is true of every grammar pill — vacuous. Pin the widened regex itself.
  assert.ok(/roll\(\?:\\s\+folder\)\?\\s\*:/.test(gp),
    'it reads the query back out of g.def, modifier or not');
  // Assert the ternary's SHAPE, not string positions: the comment above it quotes the old copy,
  // so indexOf would measure the comment rather than the code (the same trap the announce() count
  // hit in S3-PR4 — comments in this file are read by the tests).
  assert.match(gp, /const cta = \(badFilter \?/,
    'the reason must win over the "nothing matched" copy, which is itself the wrong answer here');

  // The math pill is the subtle one: count() returns 0, not null, so math-err never fires and the
  // pill renders as a confident success. The slot is the success tooltip, beside folderTip.
  const mp = fnBody(_src, 'renderMathPill');
  assert.ok(mp.includes('const queryTip'), 'the math pill must compute a query tip');
  assert.ok(/matchAll\(\/"\(\[\^"\]\*\)"\/g\)/.test(mp), 'every quoted argument is a search, so each is asked about');
  assert.equal((mp.match(/\$\{escQ\(queryTip\)\}/g) || []).length, 4,
    'both the bare and the ordinary success renders carry it, in title AND aria-label');
  // ...and the empty-SCOPE branch returns before those, so it needs the reason too, LEADING:
  // "no points below this one" is the wrong explanation when the query could not be read, and
  // that branch is the one a bare count("…") actually lands on. Found by driving, not by reading.
  assert.match(mp, /const tip = \(queryTip \? queryTip\.trim\(\) \+ ' ' : ''\)/,
    'the unreadable-filter reason must LEAD the empty-scope tip, not be unreachable behind it');
  // #1331 restructured the tail into a hasDoc ternary, but the no-scope fallback copy is still present
  assert.ok(mp.includes("'No points below this one to search"), 'the empty-scope fallback tip is still there for the truly-empty case');
});

test('searchTermProblems — opts.typing separates "still typing" from "wrong"', () => {
  const probs = (query, opts) => c.searchTermProblems(c.parseSearchQuery(query), opts);
  // A live input suppresses a value that is still GROWING toward a real one, so typing i-s-:-t-o-d
  // on the way to is:todo never accuses anyone. The MATCH is already honest either way.
  assert.equal(probs('is:tod', { typing: true }).length, 0);
  assert.equal(probs('is:d', { typing: true }).length, 0);
  // ...but a value that can never become valid is reported immediately, mid-typing or not.
  assert.equal(probs('is:blocked', { typing: true }).length, 1);
  assert.equal(probs('is:doen', { typing: true }).length, 1, 'a transposition is not a prefix');
  // committed text (a pill in a document) has no half-typed state, so it always reports
  assert.equal(probs('is:tod', {}).length, 1);
  // one entry per DISTINCT token, however many times it appears
  assert.equal(probs('is:blocked is:blocked', {}).length, 1);
  assert.equal(probs('is:blocked is:bogus', {}).length, 2);
  // a valid query has nothing to say
  assert.equal(probs('is:todo #urgent', {}).length, 0);
  assert.equal(probs('', {}).length, 0);
  assert.equal(c.searchTermProblems(null).length, 0, 'null-safe, like every pure core here');
});

test('the search legend teaches exactly the is: values the parser accepts', () => {
  // Nothing pinned this. The legend is where a Guided user LEARNS the vocabulary, so a value the
  // parser gained without a chip is unteachable, and a chip the parser lost teaches a filter that
  // now explains itself instead of working. The completion drift guard covers the OTHER direction
  // (SEARCH_IS_VALUES vs searchCompletions); this covers the human-readable surface.
  const canonical = searchIsValuesFromSrc(_src);
  const legend = between(_src, '<div id="search-hint"', '</div>\n      </div>');
  const chips = [...legend.matchAll(/<kbd>is:([\w-]+)<\/kbd>/g)].map(m => m[1]);
  const missing = canonical.filter(v => !chips.includes(v));
  const extra = chips.filter(v => !canonical.includes(v));
  assert.equal(missing.length, 0, `is: values with no legend chip: ${missing.join(', ')}`);
  assert.equal(extra.length, 0, `legend chips the parser rejects: ${extra.join(', ')}`);
});

test('the invalid-filter reason is WIRED, in the search box and in the pills', () => {
  // A source pin proves the call is present, not that it works; the behaviour is driven in a
  // browser. What these own is the wiring that cannot run headless, and the two easy mistakes.
  const app = fnBody(_src, 'applySearch');
  assert.ok(app.includes('renderSearchProblems(searchTerms)'), 'applySearch must compute the problems');
  // ONE announce() call. announce() clears the live region then rAF-sets it, so a second call
  // swallows the first and the reason would be the half that got lost.
  assert.equal((app.match(/announce\(/g) || []).length, 1, 'exactly one announce() call, with the reason folded in');
  assert.ok(/announce\(problems\.length \?/.test(app), 'the reason must lead the announcement, not the count');

  const rsp = fnBody(_src, 'renderSearchProblems');
  assert.ok(rsp.includes('typing: true'), 'the search box is a LIVE input, so a still-growing value stays quiet');
  assert.ok(rsp.includes('el.hidden = !problems.length'), 'the island hides itself when there is nothing to say');
  // The gate's INTENT is that knownStates() is not paid for on every keystroke. #1367 widened it to
  // admit a grouping attempt as well, whose terms are kind:'text' rather than 'invalid' — without
  // that, the search box would be the one surface that never explains a bracket while the roll and
  // the query pill both do. Rewritten to assert the intent (a gate, still cheap, still not
  // unconditional) rather than the old literal, per the record-the-reversal rule.
  assert.ok(/some\(t => t\.kind === 'invalid'/.test(rsp), 'the gate still leads with the invalid-term test');
  assert.ok(/t\.kind === 'text' && \/\[\(\)\]\/\.test/.test(rsp), 'and admits a bracket, the grouping attempt');
  assert.ok(!/^\s*searchTermProblems\(terms/m.test(rsp), 'but never calls it unconditionally');
  // the typing courtesy lives in searchTermProblems, which is where the terms are inspected
  assert.ok(fnBody(_src, 'searchTermProblems').includes('opts.typing && groupStillOpen'),
    'and an unclosed group stays quiet while it is still being typed');

  const pill = fnBody(_src, 'renderQueryPill');
  assert.ok(pill.includes('searchTermProblems(parseSearchQuery(expr)'), 'the query/count pill must explain itself too');
  assert.ok(!/searchTermProblems\(parseSearchQuery\(expr\)[^)]*typing/.test(pill),
    'a pill is COMMITTED text: no typing flag, so a prefix miss like {count: is:tod} still reports');
  // the reason REPLACES the zero-result line: an unreadable filter did not find zero, it never ran
  assert.ok(pill.indexOf('probs.length') < pill.indexOf('No matching points.'),
    'the problem branch must precede the no-match branch, or the misleading copy wins');
});

test('properties: queryMatchesNode — has: and key:value matching', () => {
  const q = s => c.parseSearchQuery(s);
  const n = c.mkNode('a task');
  n.props = [{ key: 'status', val: 'done' }, { key: 'author', val: 'alice' }];

  assert.equal(c.queryMatchesNode(q('has:status'), n), true);
  assert.equal(c.queryMatchesNode(q('has:priority'), n), false);
  assert.equal(c.queryMatchesNode(q('status:done'), n), true);
  assert.equal(c.queryMatchesNode(q('status:open'), n), false);
  assert.equal(c.queryMatchesNode(q('author:alice'), n), true);
  assert.equal(c.queryMatchesNode(q('author:bob'), n), false);
  // negation
  assert.equal(c.queryMatchesNode(q('-has:status'), n), false);
  assert.equal(c.queryMatchesNode(q('-has:priority'), n), true);
  assert.equal(c.queryMatchesNode(q('-status:open'), n), true);
  // AND with other terms
  assert.equal(c.queryMatchesNode(q('task status:done'), n), true);
  assert.equal(c.queryMatchesNode(q('task status:open'), n), false);
  // no props at all
  const bare = c.mkNode('no props');
  assert.equal(c.queryMatchesNode(q('has:status'), bare), false);
});

test('#589 is:pill and has:query see a query pill (the newest artifact family)', () => {
  const q = s => c.parseSearchQuery(s);
  // a point whose ONLY artifact is a query pill
  const qn = c.mkNode('[[query:abc]]');
  qn.query = [{ key: 'abc', expr: 'is:todo' }];
  assert.equal(c.queryMatchesNode(q('is:pill'), qn), true, 'is:pill must match a query-only point');
  assert.equal(c.queryMatchesNode(q('has:query'), qn), true, 'has:query must match a query pill');
  // and negation flips
  assert.equal(c.queryMatchesNode(q('-has:query'), qn), false);
  // a point with no query pill does not match has:query...
  const other = c.mkNode('plain');
  assert.equal(c.queryMatchesNode(q('has:query'), other), false);
  // ...unless it literally has a property named "query" (the has:<propkey> fall-through is preserved)
  other.props = [{ key: 'query', val: 'x' }];
  assert.equal(c.queryMatchesNode(q('has:query'), other), true, 'a literal query property still matches via fall-through');
});

test('#589 drift guard: features.md lists every has: sidecar word from the code', () => {
  // The has: sidecar family (HAS_SIDECAR_FIELD) had no doc pin, which is exactly how `query` went
  // silently missing when the query artifact shipped. Derive the words from source and require each
  // to appear as has:<word> in the user-facing features.md, so the next artifact can't hide.
  const m = _src.match(/const HAS_SIDECAR_FIELD = \{([^}]+)\}/);
  assert.ok(m, 'HAS_SIDECAR_FIELD not found (renamed?)');
  const words = [...m[1].matchAll(/(\w+)\s*:/g)].map(x => x[1]);
  assert.ok(words.length >= 7, `parsed too few has: words: ${words.join(',')}`);
  const doc = readFileSync(_guidePath('features.md'), 'utf8');
  const missing = words.filter(w => !doc.includes(`has:${w}`));
  assert.deepEqual(missing, [],
    `features.md is missing these shipped has: operators: ${missing.map(w => 'has:' + w).join(', ')}`);
});

