// UXP-241 pure core: a toggle re-renders the panel, then asks what to say. The count line is the
// answer whenever it has one; an emptied panel falls back to its empty-state title rather than
// going silent. null means "nothing to announce" (the repo's pure-core convention).
test('UXP-241 overlayCountMessage: count wins, empty-state title is the fallback', () => {
  assert.equal(c.overlayCountMessage('8 dated points', 'No dated points here yet'), '8 dated points');
  assert.equal(c.overlayCountMessage('15 points, 1 links, 20 unlinked references', ''), '15 points, 1 links, 20 unlinked references');
  // the panel emptied: .graph-count renders '' and the empty state carries the honest sentence
  assert.equal(c.overlayCountMessage('', 'No dated points here yet'), 'No dated points here yet');
  assert.equal(c.overlayCountMessage('   ', 'No links yet'), 'No links yet');
  // nothing to say → null, never an empty announce() that clears the region for no reason
  assert.equal(c.overlayCountMessage('', ''), null);
  assert.equal(c.overlayCountMessage(undefined, undefined), null);
  assert.equal(c.overlayCountMessage('  ', '  '), null);
});

// UXP-240 pure core: the index math behind every roving-tabindex group. Ends CLAMP (the calendar
// grid's rule) and null means "no move", so a caller never focuses the element it started on.
test('UXP-240 roveIndex: step, clamp, ends', () => {
  assert.equal(c.roveIndex('ArrowDown', 0, 5), 1);
  assert.equal(c.roveIndex('ArrowRight', 0, 5), 1);
  assert.equal(c.roveIndex('ArrowUp', 3, 5), 2);
  assert.equal(c.roveIndex('ArrowLeft', 3, 5), 2);
  assert.equal(c.roveIndex('Home', 3, 5), 0);
  assert.equal(c.roveIndex('End', 1, 5), 4);
  // clamping, NOT wrapping — an ArrowUp at the top must not jump to the bottom
  assert.equal(c.roveIndex('ArrowUp', 0, 5), null);
  assert.equal(c.roveIndex('ArrowDown', 4, 5), null);
  assert.equal(c.roveIndex('Home', 0, 5), null);
  assert.equal(c.roveIndex('End', 4, 5), null);
  // an unhandled key declines, so the caller leaves the event alone
  assert.equal(c.roveIndex('Enter', 1, 5), null);
  assert.equal(c.roveIndex('Tab', 1, 5), null);
  // degenerate inputs
  assert.equal(c.roveIndex('ArrowDown', 0, 0), null);
  assert.equal(c.roveIndex('ArrowDown', 5, 5), null);
  assert.equal(c.roveIndex('ArrowDown', -1, 5), null);
  assert.equal(c.roveIndex('ArrowDown', 0, 1), null);   // a single item has nowhere to go
});

test('UXP-240 roveIndex: PageUp/PageDown page a group, and decline without groups', () => {
  // three months: rows 0-2, 3-4, 5-8
  const starts = [0, 3, 5];
  assert.equal(c.roveIndex('PageDown', 0, 9, starts), 3);
  assert.equal(c.roveIndex('PageDown', 1, 9, starts), 3);   // from INSIDE a group, not just its start
  assert.equal(c.roveIndex('PageDown', 3, 9, starts), 5);
  assert.equal(c.roveIndex('PageUp', 6, 9, starts), 3);
  assert.equal(c.roveIndex('PageUp', 4, 9, starts), 0);
  // clamps at the first/last group rather than wrapping
  assert.equal(c.roveIndex('PageUp', 1, 9, starts), null);
  assert.equal(c.roveIndex('PageDown', 7, 9, starts), null);
  // the graph passes no groups, so paging declines and the panel scrolls natively instead
  assert.equal(c.roveIndex('PageDown', 1, 9), null);
  assert.equal(c.roveIndex('PageUp', 1, 9, []), null);
});

// UXP-239 + UXP-241 wiring. Source pins only — they prove the lines are PRESENT; that focus actually
// survives the re-render and that Escape still closes was verified by driving the running app.
test('UXP-239/241 overlay toggles: refocus after re-render + announce the new count (src pins)', () => {
  const aoc = fnBody(_src, 'announceOverlayCount');
  assert.ok(aoc.includes('overlayCountMessage('), 'the wrapper must go through the pure core');
  assert.ok(aoc.includes('.graph-count') && aoc.includes('.graph-empty-title'), 'must read BOTH rendered strings (shared by graph + timeline)');
  assert.ok(aoc.includes('announce('), 'must reach #a11y-live through the existing announce() helper');

  // UXP-239: the timeline source chip is destroyed by `panel.innerHTML = ''`, so it must be
  // refocused — otherwise focus lands on <body>, outside #timeline-back, and Escape goes dead.
  const rt = fnBody(_src, 'renderTimeline');
  assert.ok(rt.includes(".tl-toggle.tl-src-' + key)?.focus()"),
    'the source chip must refocus itself after the re-render, and via .tl-toggle.tl-src-KEY — rows reuse the bare tl-src-KEY class');
  assert.ok(rt.includes('announceOverlayCount(panel)'), 'the source chip must announce the new count (P3-5)');

  // all three count-changing toggles announce: one header must not have one toggle that speaks and
  // one that does not (P1).
  const rg = fnBody(_src, 'renderGraph');
  const scopeLine = rg.split('\n').find(l => l.includes(".graph-scope .on')?.focus()"));
  assert.ok(scopeLine && scopeLine.includes('announceOverlayCount(panel)'), 'the graph scope toggle must announce its new count');
  const unlinkedLine = rg.split('\n').find(l => l.includes(".graph-unlinked-toggle')?.focus()"));
  assert.ok(unlinkedLine && unlinkedLine.includes('announceOverlayCount(panel)'), 'the graph unlinked toggle must announce its new count');
});

// UXP-237: an unwritten footnote's marker must not survive into an exported file. Both text exports
// already skipped the DEFINITION line for a note with no text, which is exactly what left the
// marker dangling; a real CommonMark renderer then prints `[^ghost]` as raw brackets mid-sentence.
test('UXP-237 fnIsWritten: blank text and a missing record both mean unwritten', () => {
  // Phase A: fnIsWritten(store, id) — the store is [{id, text}] and written means non-blank text.
  assert.equal(c.fnIsWritten([{ id: 'a', text: 'the note' }], 'a'), true);
  assert.equal(c.fnIsWritten([{ id: 'a', text: '' }], 'a'), false);      // the editor-opened case
  assert.equal(c.fnIsWritten([{ id: 'a', text: '  \n ' }], 'a'), false);
  assert.equal(c.fnIsWritten([], 'a'), false);                          // no record at all
  assert.equal(c.fnIsWritten(null, 'a'), false);
  assert.equal(c.fnIsWritten([{ id: 'b', text: 'other' }], 'a'), false);
});

test('UXP-237 stripUnwrittenFnRefs: drops the marker, keeps the written one, leaves no double space', () => {
  const written = [{ id: 'ok', text: 'the actual note' }];   // Phase A: store = [{id, text}]
  // a written marker is untouched
  assert.equal(c.stripUnwrittenFnRefs('A real one[^ok].', written), 'A real one[^ok].');
  // an unwritten one goes, and the sentence still reads
  assert.equal(c.stripUnwrittenFnRefs('A dangling one[^ghost] and a real one[^ok].', written),
    'A dangling one and a real one[^ok].');
  // THE SPACING CASE: a marker preceded by a space must not leave two behind
  assert.equal(c.stripUnwrittenFnRefs('one [^ghost] and', []), 'one and');
  assert.equal(c.stripUnwrittenFnRefs('one[^ghost] and', []), 'one and');
  // end of sentence keeps its full stop
  assert.equal(c.stripUnwrittenFnRefs('the end[^ghost].', []), 'the end.');
  // two in a row
  assert.equal(c.stripUnwrittenFnRefs('both[^a][^b] gone', []), 'both gone');
  // the editor-opened empty record drops too (the subtle one the render cue also pins)
  assert.equal(c.stripUnwrittenFnRefs('See[^a]', [{ id: 'a', text: '' }]), 'See');
  // untouched when there is nothing to do
  assert.equal(c.stripUnwrittenFnRefs('no markers here', []), 'no markers here');
  assert.equal(c.stripUnwrittenFnRefs('', []), '');
  assert.equal(c.stripUnwrittenFnRefs(null, []), '');
});

test('UXP-237 countUnwrittenFnRefs: counts markers, and skips excluded subtrees', () => {
  // Phase A: written-ness lives in the doc store (root.footnotes), not per node; markers reference by id.
  const mk = (text, extra = {}) => Object.assign(c.mkNode(text), extra);
  const root = c.mkRoot();
  root.footnotes = [{ id: 'a', text: 'written' }];   // only 'a' is written; b/c/d/e/f have no store entry
  root.children.push(mk('One[^a] two[^b]'));   // b unwritten -> 1
  root.children.push(mk('Three[^c]'));         // -> 2
  assert.equal(c.countUnwrittenFnRefs(root), 2);
  // a marker inside an excluded subtree was never going to be exported, so it is not "dropped"
  const scaffold = mk('Scaffolding[^d]', { noexport: true });
  scaffold.children.push(mk('Nested[^e]'));
  root.children.push(scaffold);
  assert.equal(c.countUnwrittenFnRefs(root), 2, 'a noexport subtree must not inflate the count');
  // nested markers under a KEPT point do count
  root.children[0].children.push(mk('Child[^f]'));
  assert.equal(c.countUnwrittenFnRefs(root), 3);
  // a clean tree reports nothing, so the toast keeps its original wording
  const clean = c.mkRoot();
  clean.footnotes = [{ id: 'a', text: 'here' }];
  clean.children.push(mk('All good[^a]'));
  assert.equal(c.countUnwrittenFnRefs(clean), 0);
  assert.equal(c.countUnwrittenFnRefs(null), 0);
});

// ── Phase A: the doc-level footnote store (numbering, migration, export renumber) ─────────────
test('Phase A footnoteOrder: document order, shared ids counted once, reuse does not renumber', () => {
  const r = c.mkRoot();
  const a = c.mkNode('first[^x] then[^y]');
  a.children.push(c.mkNode('nested[^y] again'));   // y already seen -> no renumber
  const b = c.mkNode('reuse[^x] and new[^z]');      // x reused, z new
  r.children.push(a, b);
  const ord = c.footnoteOrder(r);
  assert.equal(ord.get('x'), 1, 'x is the first marker in document order');
  assert.equal(ord.get('y'), 2, 'y second; its reuse in the child does not renumber it');
  assert.equal(ord.get('z'), 3, 'z third, in document order across points');
  assert.equal(ord.size, 3, 'each id is numbered exactly once');
});

test('Phase A migrateNodeFootnotes: lifts to store, remaps markers, persists orphans, diverges collisions', () => {
  let n = 0; const mint = () => 'F' + (++n);   // deterministic id minter
  const store = [];
  const nodeA = { text: 'a claim[^1] here', footnotes: [{ key: '1', text: 'Ives 2019' }] };
  c.migrateNodeFootnotes(nodeA, store, mint);
  assert.equal(nodeA.text, 'a claim[^F1] here', 'the [^key] marker remaps to the store id');
  // cross-realm: objects pushed by the VM-realm function fail deepEqual on prototype, so compare fields.
  assert.equal(JSON.stringify(store), JSON.stringify([{ id: 'F1', text: 'Ives 2019' }]), 'the footnote lifts into the store');
  assert.equal(nodeA.footnotes.length, 0, 'the legacy per-node array is cleared');
  // THE COLLISION FIX: a second point that also used [^1] must diverge to its own id.
  const nodeB = { text: 'other[^1]', footnotes: [{ key: '1', text: 'Smith 2020' }] };
  c.migrateNodeFootnotes(nodeB, store, mint);
  assert.equal(nodeB.text, 'other[^F2]', 'a second [^1] on another point becomes a DISTINCT id');
  assert.equal(store.length, 2, 'two once-colliding footnotes are now two store entries');
  // NO auto-prune: an unreferenced legacy footnote (no marker in the text) still lifts and persists.
  const nodeC = { text: 'no marker here', footnotes: [{ key: '9', text: 'orphan ref' }] };
  c.migrateNodeFootnotes(nodeC, store, mint);
  assert.ok(store.some(f => f.text === 'orphan ref'), 'an unreferenced legacy footnote persists as an orphan');
  // idempotent: a second pass over an already-migrated node lifts nothing.
  c.migrateNodeFootnotes(nodeA, store, mint);
  assert.equal(store.length, 3, 'a second pass is a no-op');
});

test('Phase A migrateFootnotesToStore: lifts across every depth using the real id minter', () => {
  const store = [];
  const root = { text: 'x[^1]', footnotes: [{ key: '1', text: 'top' }],
    children: [{ text: 'y[^2]', footnotes: [{ key: '2', text: 'child' }], children: [] }] };
  c.migrateFootnotesToStore(root, store);
  assert.equal(store.length, 2, 'both the root and the nested footnote lifted');
  assert.ok(store.every(f => /^f/.test(f.id)), 'store ids use the fnId (f…) shape');
  assert.ok(/\[\^f/.test(root.text) && /\[\^f/.test(root.children[0].text), 'markers remapped at every depth');
  assert.deepEqual(store.map(f => f.text).sort(), ['child', 'top']);
});

test('Phase A renumberFnMarkers: [^id] -> [^number] via the order map; unknown ids untouched', () => {
  const order = new Map([['abc', 1], ['xyz', 2]]);
  assert.equal(c.renumberFnMarkers('see[^abc] and[^xyz]', order), 'see[^1] and[^2]');
  assert.equal(c.renumberFnMarkers('unknown[^zzz] stays', order), 'unknown[^zzz] stays');
  assert.equal(c.renumberFnMarkers('', order), '');
  assert.equal(c.renumberFnMarkers(null, null), '');
});

test('Phase A: footnotes are NOT auto-pruned — pruneFootnotes and its call site are gone', () => {
  assert.ok(!/pruneFootnotes\(/.test(_src),
    'pruneFootnotes must be fully removed (the function AND the exitEdit call), so orphans persist');
});

// ── Phase B: the Footnotes manager (list, copy-link, delete-orphans) ─────────────────────────
test('Phase B footnoteReport: numbered rows first, orphans last, ref counts + first reference', () => {
  const r = c.mkRoot();
  r.footnotes = [
    { id: 'A', text: 'Ives 2019' },
    { id: 'B', text: 'Smith 2020' },
    { id: 'ORPH', text: 'never cited' },   // no marker references it -> an orphan
  ];
  const p1 = c.mkNode('claim one[^A]'); p1.id = 'p1';
  const p2 = c.mkNode('claim two[^B] and again[^A]'); p2.id = 'p2';
  r.children.push(p1, p2);
  const rep = c.footnoteReport(r);
  assert.equal(rep.length, 3);
  // A appears first (number 1), cited twice, first in p1
  assert.equal(rep[0].id, 'A'); assert.equal(rep[0].number, 1);
  assert.equal(rep[0].refCount, 2); assert.equal(rep[0].firstRefId, 'p1');
  // B is number 2, cited once, first in p2
  assert.equal(rep[1].id, 'B'); assert.equal(rep[1].number, 2);
  assert.equal(rep[1].refCount, 1); assert.equal(rep[1].firstRefId, 'p2');
  // the orphan sorts LAST, has no number, no references, nowhere to jump
  assert.equal(rep[2].id, 'ORPH'); assert.equal(rep[2].number, null);
  assert.equal(rep[2].refCount, 0); assert.equal(rep[2].firstRefId, null);
});

