// UXP-240 wiring. Source pins; that the arrows actually move focus was verified by driving.
test('UXP-240 overlay roving tabindex: seeds, key claims, and the trap selector (src pins)', () => {
  // exactly one tab stop seeded per group, over document order
  const rt = fnBody(_src, 'renderTimeline');
  assert.ok(rt.includes("row.setAttribute('tabindex', rowIdx === 0 ? '0' : '-1')"), 'timeline rows must seed a single roving tab stop');
  const rg = fnBody(_src, 'renderGraph');
  assert.ok(rg.includes("g.setAttribute('tabindex', nodeIdx === 0 ? '0' : '-1')"), 'graph nodes must seed a single roving tab stop');
  // and NOT the old unconditional form, at either site
  assert.ok(!rt.includes("row.setAttribute('tabindex', '0')") && !rg.includes("g.setAttribute('tabindex', '0')"),
    'no item may take an unconditional tabindex 0 — that is the defect UXP-240 filed');

  // the claimed key sets. The timeline is a vertical list and pages by month; the graph walks one
  // document order with all four arrows and leaves paging to the panel's own scroll.
  assert.ok(_src.includes("['ArrowUp','ArrowDown','Home','End','PageUp','PageDown']"), 'the timeline must claim Up/Down + Home/End + PageUp/PageDown');
  assert.ok(_src.includes("['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Home','End']"), 'the graph must claim all four arrows + Home/End');
  assert.ok(_src.includes("panel.querySelectorAll('.tl-item')") && _src.includes("panel.querySelectorAll('.graph-node')"),
    'both handlers must read their group live, so a re-render cannot leave a stale list');
  assert.ok(_src.includes('roveIndex(e.key, i, rows.length, starts)'), 'the timeline must pass month starts so paging works');
  assert.ok(_src.includes('roveIndex(e.key, i, nodes.length)'), 'the graph must pass no groups, so paging declines');

  // roveTo swaps BOTH attributes — leaving the old stop at 0 would grow the tab order again
  const rto = fnBody(_src, 'roveTo');
  assert.ok(rto.includes("setAttribute('tabindex', '-1')") && rto.includes("setAttribute('tabindex', '0')") && rto.includes('.focus()'),
    'roveTo must clear the old stop, set the new one, and move focus');

  // THE REGRESSION GUARD. A roved-out item is skipped by native Tab, so a trap that still counts it
  // computes a `last` that Tab can never reach — the wrap never fires and Tab escapes the modal.
  // Timeline rows are <button>s, so this bites without the :not() clause.
  const traps = _src.split('\n').filter(l => l.includes("[tabindex=\"0\"],button:not(:disabled)"));
  assert.equal(traps.length, 2, 'expected exactly the two overlay Tab traps');
  for (const t of traps) assert.ok(t.includes(':not([tabindex="-1"])'), 'an overlay Tab trap must exclude roved-out items or Tab walks out of the modal');
});

test('#519 depth nudges: Guided-only, once-ever, toast channel, wired at trigger points (src pins)', () => {
  // the firing door enforces ALL three constraints in one place
  const fn = fnBody(_src, 'fireNudge');
  assert.ok(fn.includes('if (!isGuided()) return'), 'a nudge must be Guided-only (the verbosity dial)');
  assert.ok(fn.includes('nudgeSeen(') && fn.includes('markNudgeSeen('), 'a nudge must fire once ever (persisted)');
  assert.ok(fn.includes('flashHint('), 'a nudge must use the standard toast channel (one-feedback-pattern)');
  // persistence is localStorage-backed (survives sessions, never nags again)
  assert.ok(_src.includes("localStorage.getItem(NUDGE_STORE_KEY)") && _src.includes("localStorage.setItem(NUDGE_STORE_KEY"), 'nudge state persists in localStorage');
  // the two trigger helpers gate before doing any work (cheap on the hot paths)
  const ms = fnBody(_src, 'maybeNudgeSum');
  assert.ok(ms.includes('if (!isGuided() || nudgeSeen(') && ms.includes('nudgeSumKey('), 'maybeNudgeSum must guard then use the pure predicate');
  const mr = fnBody(_src, 'maybeNudgeRoll');
  assert.ok(mr.includes('if (!isGuided() || nudgeSeen(') && mr.includes('nudgeRollTag('), 'maybeNudgeRoll must guard then use the pure predicate');
  // wired at the point-of-relevance commit sites: the props dialog save, the /prop slash, and a tag edit
  assert.ok(_src.includes('maybeNudgeSum(node, p.key)'), 'props-dialog save must offer the sum nudge');
  assert.ok(_src.includes('maybeNudgeSum(cur, ps.key)'), 'the /prop slash must offer the sum nudge');
  assert.ok(_src.includes('maybeNudgeRoll()'), 'a tag edit must offer the roll nudge');
  // Trigger 3 (#H): the first self-authored pill is greeted once. Guarded on a real pill token
  // produced this exit (_promotedLit), and wired into exitEdit right after the promote pass.
  const mfp = fnBody(_src, 'maybeNudgeFirstPill');
  assert.ok(mfp.includes('_promotedLit.size === 0') && mfp.includes("fireNudge('firstpill', 'Nice, that is a live pill."),
    'maybeNudgeFirstPill must guard on a produced pill token, then fire the firstpill nudge');
  assert.match(_src, /promoteInlineShorthand\(node\);[\s\S]{0,120}?maybeNudgeFirstPill\(\);/,
    'the first-pill nudge must run in exitEdit right after the promote pass (so _promotedLit is fresh)');
  // Trigger 4 (γ): a bare "cost: 120" tail teaches the /prop door once, Guided-only, never rewriting text.
  const mnf = fnBody(_src, 'maybeNudgeField');
  assert.ok(mnf.includes("!isGuided() || nudgeSeen('field')") && mnf.includes('fieldNudgeKey(node.text)') && mnf.includes("fireNudge('field'"),
    'maybeNudgeField must guard (Guided/once-ever), read the pure predicate, and fire the field nudge');
  assert.ok(/\/prop:\$\{f\.key\}=\$\{f\.val\}/.test(_src), 'the field nudge names the /prop door with the typed key and value');
  assert.match(_src, /maybeNudgeFirstPill\(\);[\s\S]{0,120}?maybeNudgeField\(node\);/, 'the field nudge runs in exitEdit beside the other post-commit nudges');
  // #1334: the PERSISTENT one-click twin of the toast — a "+ property" door on a bare `key: number` point.
  const faf = fnBody(_src, 'maybeAddFieldAffordance');
  assert.ok(faf.includes('if (!isGuided()) return') && faf.includes('fieldNudgeKey(node.text)'), 'Guided-only, gated on the same bare-field predicate as the toast');
  assert.ok(faf.includes("b.textContent = '+ property'"), 'it is a visible + property door');
  assert.ok(faf.includes("'$1{prop $2: $3}'"), 'a click promotes the trailing key: number to a {prop …} in place');
  assert.ok(faf.includes('promoteLoadedShorthand(node)'), 'and promotes it to a real property chip');
  assert.ok(faf.includes("e.preventDefault(); e.stopPropagation();"), 'caret invariant: mousedown never drops the caret');
  assert.ok(_src.includes('maybeAddRowAffordance(node, row); maybeAddFieldAffordance(node, row);'), 'wired into the render affordance pass');
  // Trigger 5 (δ): a hand-typed [[Name]] resolves to a [[#id]] token on an unambiguous match; on
  // zero/many it stays literal and points once at the [[ picker (Guided, once-ever).
  const mtl = fnBody(_src, 'maybeNudgeTypedLink');
  assert.ok(mtl.includes("!isGuided() || nudgeSeen('typedlink')") && mtl.includes("fireNudge('typedlink'"),
    'maybeNudgeTypedLink must guard (Guided/once-ever) and fire the typedlink nudge');
  assert.ok(/type \[\[ and pick the point from the menu/.test(_src), 'the typedlink nudge points at the [[ picker');
  // wired in exitEdit right after the field nudge: rewrite only on an actual change, nudge on unresolved
  assert.match(_src, /maybeNudgeField\(node\);[\s\S]{0,600}?resolveTypedLinks\(node\.text, root, node\.id\)/,
    'the typed-link resolve runs in exitEdit right after the field nudge');
  assert.ok(/if \(lr\.text !== node\.text\) node\.text = lr\.text;/.test(_src), 'text is rewritten only when the resolve actually changed it');
  assert.ok(/if \(lr\.unresolved\.length\) maybeNudgeTypedLink\(lr\.unresolved\[0\]\)/.test(_src), 'an unresolved typed link fires the nudge');
});

