// The roll-forward wiring is DOM/module-global coupled (reads node.props, mutates text,
// flashes), so pin it at the source: rollForwardRepeat must anchor off the old date, preserve
// the span, re-open the task, and announce — never a silent flip.
test('rollForwardRepeat — wiring (#462)', () => {
  const fn = fnBody(_src, 'rollForwardRepeat');
  assert.ok(fn, 'rollForwardRepeat must exist');
  assert.ok(/if \(wasDone \|\| !node \|\| !node\.checked\) return false/.test(fn), 'only fires on a fresh not-done→done flip');
  assert.ok(/nextOccurrence\(desc, base\)/.test(fn), 'advances via nextOccurrence off the old date (fixed cadence)');
  assert.ok(/const delta = nextDue - base/.test(fn) && /startEp \+ delta/.test(fn), 'preserves the start→due span (both shift by the same delta)');
  assert.ok(/reopenTaskText\(node\)/.test(fn), 're-opens the task text so it recurs, not a done copy');
  // #1504 scoped this: `flashHint(` anywhere in the body stopped distinguishing the branches once
  // the dateless bail gained one of its own, so a mutant that deleted the RESCHEDULE announcement
  // would still have found a flashHint here.
  assert.ok(/flashHint\('⟳ Rescheduled to/.test(fn), 'visible + announced (flashHint reaches #a11y-live), never a silent flip');
  // it is actually called at the two done-transition chokepoints
  assert.ok(/rollForwardRepeat\(node, wasDone\)/.test(fnBody(_src, 'toggleTaskInNode')), 'wired into the checkbox path');
  // #1502: this comment said "the two chokepoints" while asserting ONE, and that gap was the bug.
  // The roll lived in exitEdit and toggleTaskInNode only, so every completion made outside an edit
  // session ended the recurrence for good. There is now one writer, and the census names its doors.
  assert.match(fnBody(_src, 'commitTodoDone'), /rollForwardRepeat\(node, wasDone\)/,
    'the shared writer is where the roll now lives');
  const DOORS = { exitEdit: 'typing #DONE / the state-cycle chord',
                  applyTodoCycleToNodes: 'the bulk cycle chord over a selection',
                  showTodoPicker: 'the state-badge picker',
                  applyBlockCmd: 'the row-cursor state command' };
  for (const [fn, what] of Object.entries(DOORS)) {
    assert.match(fnBody(_src, fn), /commitTodoDone\(/,
      `${what} (${fn}) must route its done-flip through the one writer, or it ends the recurrence silently`);
  }
  // and none of them may re-derive `checked` themselves afterwards, which is how a door drifts back out
  const stray = nonEmpty(Object.keys(DOORS), 'done-flip doors')
    .filter(fn => /\.checked = todoDoneFromText\(/.test(fnBody(_src, fn)));
  assert.deepEqual(host(stray), [],
    'a door that sets .checked itself has stepped around the writer and lost the roll-forward');
  // repeat is a reserved key everywhere the other reserved keys are guarded
  assert.ok(/k === REPEAT_KEY/.test(_src), 'repeat is hidden from the generic Properties editor + prop-vars');
});

test('#1502 the one writer rolls a repeating point forward, and leaves everything else alone', () => {
  const today = c.dueDateToday();
  const mk = (text, props) => {
    const n = c.mkNode(text); n.type = 'todo'; n.props = props.map(([key, val]) => ({ key, val }));
    n.checked = c.todoDoneFromText(n.text); return n;
  };
  const dueOf = n => (n.props || []).find(p => p.key.toLowerCase() === 'due')?.val ?? null;
  const flip = n => { const w = n.checked; n.text = c.setTodoState(n.text, 'DONE'); return c.commitTodoDone(n, w); };

  // the reported case: a repeating point rolls forward and RE-OPENS
  const rep = mk('#TODO Water plants', [['due', c.formatEpochDays(today)], ['repeat', 'every 3 days']]);
  assert.equal(flip(rep), true, 'the writer reports that it rescheduled');
  assert.equal(dueOf(rep), c.formatEpochDays(today + 3), 'the schedule advanced by the cadence');
  assert.equal(rep.checked, false, 'and the point is open again, not done');

  // every case that must simply complete, with no roll
  const plain = mk('#TODO Buy milk', [['due', c.formatEpochDays(today)]]);
  assert.equal(flip(plain), false, 'a to-do with no repeat just completes');
  assert.equal(plain.checked, true);
  assert.equal(dueOf(plain), c.formatEpochDays(today), 'and its date is untouched');

  const noDate = mk('#TODO Stretch', [['repeat', 'every 3 days']]);
  assert.equal(flip(noDate), false, 'a repeat with no date has nothing to advance');
  assert.equal(noDate.checked, true);

  const badPhrase = mk('#TODO Odd', [['due', c.formatEpochDays(today)], ['repeat', 'every blue moon']]);
  assert.equal(flip(badPhrase), false, 'an unrecognised phrase completes normally rather than erroring');
  assert.equal(badPhrase.checked, true);

  const already = mk('#DONE Water plants', [['due', c.formatEpochDays(today)], ['repeat', 'every 3 days']]);
  assert.equal(flip(already), false, 'a point already done does not roll a second time');
  assert.equal(dueOf(already), c.formatEpochDays(today));

  // a flip to a non-done state is not a completion
  const toNext = mk('#TODO Water plants', [['due', c.formatEpochDays(today)], ['repeat', 'every 3 days']]);
  const w = toNext.checked; toNext.text = c.setTodoState(toNext.text, 'NEXT');
  assert.equal(c.commitTodoDone(toNext, w), false, 'NEXT is not done, so nothing rolls');
  assert.equal(dueOf(toNext), c.formatEpochDays(today));
  assert.equal(toNext.checked, false);

  assert.equal(c.commitTodoDone(null, false), false, 'no node, no crash');
});

// #1536: `fallbackCopy` has to borrow focus (a textarea must be focused to be selected) and used to
// hand it to <body>, because removing the focused element leaves it there. In a contenteditable
// outliner that is the caret gone. It runs on exactly the paths where the clipboard API said no, so
// the person least likely to have a working clipboard also lost their place. Driven in
// tests/browser.mjs (check 60) with the rejection forced -- locally the write resolves and the
// fallback never runs, which is how this reached CI as a one-row failure and nothing else.
test('#1536 the clipboard fallback returns the focus and the caret it borrowed', () => {
  const fn = fnBody(_src, 'fallbackCopy');
  assert.match(fn, /const prev = document\.activeElement/, 'it remembers who had focus before it takes it');
  assert.match(fn, /getCaretOffset\(prev\)/,
    'and WHERE their caret was, as the app’s logical offset -- a DOM Range does not survive the ' +
    'refold that blurring the point triggers');
  assert.match(fn, /setCaretByOffset\(prev, caret\)/, 'and puts it back, not just the focus');
  // both exits restore, and the throw is the one that matters: this function IS the failure path
  assert.match(fn, /\} catch \(_\) \{ giveItBack\(\); \}/,
    'a copy that threw still borrowed the focus, so it still owes it back');
  // and it restores BEFORE it announces, with the toast still on the success path only: a throw
  // must not claim "Link copied", which is the one thing the original catch got right
  const success = between(fn, 'document.body.removeChild(ta);', '} catch');
  assert.match(success, /giveItBack\(\);[\s\S]*if \(after\) after\(\)/,
    'the focus comes back, then the copy reports success');

  // the census: every door that copies goes through this one fallback, so fixing it fixes them all
  const DOORS = { copyNodeLink: 'Copy link / the keyboard shortcut',
                  copyTextToClipboard: 'copy this text (footnotes, share text)' };
  for (const [door, what] of Object.entries(DOORS)) {
    assert.match(fnBody(_src, door), /fallbackCopy\(/,
      `${what} (${door}) must fall back through the shared helper, or it keeps the old defect`);
  }
});

// ─── #1504: a repeat with nothing to advance from ────────────────────────────
// rollForwardRepeat has ALWAYS known this case ("a repeat with no date can't advance") and always
// returned false in silence. Three surfaces could have said so and none did: the Schedule dialog
// promised "Advances when you complete it", the chip read "Recurring. Click to edit the schedule",
// and ticking the box completed the point and ended the recurrence with no word anywhere.
test('#1504 repeatIsDateless — either date anchors a repeat, neither leaves it inert', () => {
  assert.equal(c.repeatIsDateless('', ''), true, 'no dates at all: nothing to advance from');
  assert.equal(c.repeatIsDateless(null, undefined), true, 'a missing prop reads the same as blank');
  assert.equal(c.repeatIsDateless('   ', '\t'), true, 'whitespace is not a date');
  assert.equal(c.repeatIsDateless('someday', 'whenever'), true, 'unparseable text is not an anchor');
  // the NEGATIVES are the half that keeps this honest: measured, a start-only repeat advances
  // normally (rollForwardRepeat anchors on due, ELSE start), so flagging it would be a false alarm.
  assert.equal(c.repeatIsDateless('', '2026-09-01'), false, 'a due date anchors it');
  assert.equal(c.repeatIsDateless('2026-09-01', ''), false, 'so does a start date, on its own');
  assert.equal(c.repeatIsDateless('2026-09-01', '2026-09-08'), false, 'and so does a range');
  assert.equal(c.repeatIsDateless(' 2026-09-01 ', ''), false, 'padding does not hide a real date');
  assert.equal(c.repeatIsDateless('today', ''), false, 'a relative form is still a date');
});

test('#1504 repeatNeedsDate — only a parseable, unanchored repeat asks for a date', () => {
  const mk = (props) => ({ props: props.map(([key, val]) => ({ key, val })) });
  assert.equal(c.repeatNeedsDate(mk([['repeat', 'every week']])), true, 'the reported case');
  assert.equal(c.repeatNeedsDate(mk([['Repeat', ' every week ']])), true, 'the key match is case-insensitive');
  assert.equal(c.repeatNeedsDate(mk([['repeat', 'every week'], ['due', 'not a date']])), true,
    'a due prop that does not parse is not an anchor');
  assert.equal(c.repeatNeedsDate(mk([['repeat', 'every week'], ['due', '2026-09-01']])), false,
    'a due date anchors it, so there is nothing to warn about');
  assert.equal(c.repeatNeedsDate(mk([['repeat', 'every week'], ['start', '2026-09-01']])), false,
    'a start-only repeat advances (measured), so it must not be flagged');
  assert.equal(c.repeatNeedsDate(mk([['repeat', 'every blue moon']])), false,
    'an unparseable phrase has its own flag and its own words -- two cues would say two different things');
  assert.equal(c.repeatNeedsDate(mk([['due', '2026-09-01']])), false, 'no repeat, nothing to warn about');
  assert.equal(c.repeatNeedsDate(mk([])), false, 'a bare point is not a broken repeat');
  assert.equal(c.repeatNeedsDate(null), false, 'no node, no crash');
});

test('#1504 all three surfaces route through the ONE dateless predicate, and each has its own words', () => {
  // ONE predicate, or the chip and the dialog drift into disagreeing about what "no date" means.
  assert.match(fnBody(_src, 'repeatNeedsDate'), /repeatIsDateless\(/,
    'the node-level question is the value-level question, asked of two props');

  // surface 1 — the property chip
  const props = fnBody(_src, 'buildPropsArea');
  assert.match(props, /const inert = ok && repeatNeedsDate\(node\)/,
    'the chip asks the shared predicate, and only about a phrase that PARSES');
  assert.match(props, /if \(!ok \|\| inert\) chip\.classList\.add\('prop-repeat-bad'\)/,
    'an inert repeat wears the existing bad-flag chrome (#1389) rather than minting a second one');
  const chipTitles = nonEmpty(
    (between(props, "const inert = ok && repeatNeedsDate(node)", "// #1317").match(/'[^']*Click to [^']*'/g) || []),
    'repeat chip titles');
  assert.equal(new Set(chipTitles).size, chipTitles.length,
    'the unrecognised phrase and the unanchored phrase are different failures and must not share a sentence');
  assert.match(props, /no date to advance from\)/,
    'and assistive tech hears the difference too, not just the tooltip');

  // surface 2 — the Schedule dialog, warning while both date fields are still on screen
  const dlg = fnBody(_src, 'openDueDateDialog');
  assert.match(dlg, /repeatIsDateless\(startF\.inp\.value, dueF\.inp\.value\)/,
    'the dialog asks about the LIVE field values, not the saved props -- nothing is saved yet');
  assert.match(between(dlg, 'repeatIsDateless(startF.inp.value', 'preview.style.color = \'var(--muted)\''),
    /No date to advance from/,
    'and it replaces the promise instead of printing both');
  // the warning depends on the other two fields, so it must re-run when they change
  for (const f of nonEmpty(['startF', 'dueF'], 'date fields')) {
    assert.ok(new RegExp(`${f}\\.inp\\.addEventListener\\('input', \\(\\) => repeatF\\.update\\(\\)\\)`).test(dlg),
      `typing in ${f} must refresh the repeat warning, or it goes stale mid-dialog`);
  }

  // surface 3 — completion, where the recurrence actually ends
  const roll = fnBody(_src, 'rollForwardRepeat');
  assert.match(between(roll, 'if (base == null)', 'nextOccurrence('), /flashHint\(/,
    'the bail branch says the recurrence is over, instead of returning false in silence');
  assert.match(between(roll, 'if (base == null)', 'nextOccurrence('), /no date to advance from/,
    'and it names the same failure the chip and the dialog name (P1)');

  // CENSUS RATCHET. The family is "code that reads a point's repeat phrase", and it is exactly the
  // three sites above. A fourth is a NEW surface that has not been asked whether the repeat it is
  // about can actually advance -- which is the entire shape of this bug -- so it fails here until
  // someone decides. Code lines only: #1502's own comment quotes a call it is describing.
  const code = _src.split('\n').filter(l => !/^\s*\/\//.test(l));
  const readers = nonEmpty(code.filter(l => /\brepeatOf\(/.test(l) && !/^function repeatOf\(/.test(l.trim())),
    'repeatOf call sites');
  assert.equal(readers.length, 2,
    `repeatOf is read at 2 sites (repeatNeedsDate, rollForwardRepeat); found ${readers.length}. ` +
    'A new reader is a new surface: does it know an unanchored repeat can never advance?');
  const describers = nonEmpty(code.filter(l => /\bdescribeRepeat\(/.test(l) && !/^function describeRepeat\(/.test(l.trim())),
    'describeRepeat call sites');
  assert.equal(describers.length, 2,
    `a repeat is described to a person at 2 places, both in the Schedule dialog preview; found ${describers.length}. ` +
    'A third is somewhere new making the promise this issue was about.');
});

test('formatDueDate — state classification', () => {
  const today = c.dueDateToday();
  assert.equal(c.formatDueDate(today).state,     'today');
  assert.equal(c.formatDueDate(today).label,     'Today');
  assert.equal(c.formatDueDate(today + 1).state, 'soon');
  assert.equal(c.formatDueDate(today + 1).label, 'Tomorrow');
  assert.equal(c.formatDueDate(today - 1).state, 'overdue');
  assert.equal(c.formatDueDate(today - 1).label, 'Yesterday');
  assert.equal(c.formatDueDate(today - 5).state, 'overdue');
  assert.ok(c.formatDueDate(today - 5).label.includes('overdue'));
  assert.equal(c.formatDueDate(today + 3).state, 'soon');
  assert.equal(c.formatDueDate(today + 10).state,'future');
});

test('formatDueDate — iso is always YYYY-MM-DD', () => {
  const ep = c.parseDueDate('2026-06-15');
  const { iso } = c.formatDueDate(ep);
  assert.match(iso, /^\d{4}-\d{2}-\d{2}$/);
  assert.equal(iso, '2026-06-15');
});

test('collectDueDates — returns sorted dated nodes', () => {
  const r = c.mkRoot();
  const a = c.mkNode('alpha'); a.props = [{ key: 'due', val: '2026-08-01' }];
  const b = c.mkNode('beta');  b.props = [{ key: 'due', val: '2026-06-15' }];
  const x = c.mkNode('no date'); // no due prop
  r.children.push(a, b, x);
  const items = host(c.collectDueDates(r));
  assert.equal(items.length, 2);
  assert.equal(items[0].title, 'beta');   // earlier date first
  assert.equal(items[0].iso,   '2026-06-15');
  assert.equal(items[1].title, 'alpha');
  assert.equal(items[1].iso,   '2026-08-01');
});

test('collectDueDates — unparseable due prop ignored', () => {
  const r = c.mkRoot();
  const n = c.mkNode('bad date'); n.props = [{ key: 'due', val: 'not-a-date' }];
  r.children.push(n);
  assert.equal(c.collectDueDates(r).length, 0);
});

test('collectDueDates — start date: started vs not-yet-started + range', () => {
  const r = c.mkRoot();
  // started yesterday, due in a week → started=true, runningDays=1
  const running = c.mkNode('running task');
  running.props = [{ key: 'start', val: 'today-1' }, { key: 'due', val: 'today+7' }];
  // starts next week (future start), due later → not started, has a due
  const upcoming = c.mkNode('upcoming task');
  upcoming.props = [{ key: 'start', val: 'today+7' }, { key: 'due', val: 'today+14' }];
  // start-only, started today → started=true, no due
  const startedOnly = c.mkNode('started only');
  startedOnly.props = [{ key: 'start', val: 'today' }];
  r.children.push(running, upcoming, startedOnly);

  const items = host(c.collectDueDates(r));
  const by = title => items.find(i => i.title === title);

  assert.equal(by('running task').started, true);
  assert.equal(by('running task').runningDays, 1);
  assert.ok(by('running task').due !== null && by('running task').start !== null);

  assert.equal(by('upcoming task').started, false);   // future start
  assert.ok(by('upcoming task').due !== null);

  assert.equal(by('started only').started, true);
  assert.equal(by('started only').runningDays, 0);    // started today
  assert.equal(by('started only').due, null);
});

test('collectDueDates — done flag is derived from the node text', () => {
  const r = c.mkRoot();
  const open = c.mkNode('- [ ] open');   open.props = [{ key: 'due', val: 'today' }];
  const done = c.mkNode('- [x] finished'); done.props = [{ key: 'due', val: 'today' }];
  r.children.push(open, done);
  const items = host(c.collectDueDates(r));
  assert.equal(items.find(i => i.title === 'open').done,     false);
  assert.equal(items.find(i => i.title === 'finished').done, true);
});

test('collectDueDates — carries structural held-ness for a dated point (UXP-162)', () => {
  const SEQ = [
    { key: 'default', name: 'To-do', states: ['TODO', 'NEXT', 'WAITING', 'DONE'], heldFrom: 2, doneFrom: 3 },
    { key: 'flow', name: 'Flow', states: ['DOING', 'BLOCKED', 'SHIPPED'], heldFrom: 1, doneFrom: 2 },
  ];
  const r = c.mkRoot();
  const blocked = c.mkNode('#BLOCKED waiting on API'); blocked.props = [{ key: 'due', val: 'today' }];
  const doing   = c.mkNode('#DOING build it');         doing.props   = [{ key: 'due', val: 'today' }];
  const waiting = c.mkNode('#WAITING built-in held');  waiting.props = [{ key: 'due', val: 'today' }];
  r.children.push(blocked, doing, waiting);
  const items = host(c.collectDueDates(r, SEQ));
  assert.equal(items.find(i => i.title.includes('waiting on API')).waiting, true);   // custom held
  assert.equal(items.find(i => i.title.includes('build it')).waiting, false);        // active
  assert.equal(items.find(i => i.title.includes('built-in')).waiting, true);         // built-in WAITING
});

test('parseSearchQuery / termMatchesNode — start: operator mirrors due:', () => {
  const q = host(c.parseSearchQuery('start:today'));
  assert.equal(q[0].kind, 'start');
  assert.equal(q[0].op, '=');
  assert.equal(q[0].epochDay, c.dueDateToday());

  const n = c.mkNode('task');
  n.props = [{ key: 'start', val: '2026-06-15' }];
  const ep = c.parseDueDate('2026-06-15');
  assert.ok( c.termMatchesNode({ kind: 'start', op: '=', epochDay: ep }, n, []));
  assert.ok(!c.termMatchesNode({ kind: 'start', op: '=', epochDay: ep + 1 }, n, []));
  // a due: term must NOT match a node that only carries a start prop
  assert.ok(!c.termMatchesNode({ kind: 'due', op: '=', epochDay: ep }, n, []));
});

test('calendarMonthGrid — 42 contiguous days, Sunday-aligned, month present', () => {
  const mid = c.parseDueDate('2026-06-15');         // June 2026
  const grid = c.calendarMonthGrid(mid);
  assert.equal(grid.length, 42);
  // contiguous: each cell is the previous + 1
  for (let i = 1; i < grid.length; i++) assert.equal(grid[i], grid[i - 1] + 1);
  // starts on a Sunday (getUTCDay 0)
  assert.equal(new Date(grid[0] * 86400000).getUTCDay(), 0);
  // the 1st of June sits at index === its day-of-week
  const first = c.parseDueDate('2026-06-01');
  assert.equal(grid.indexOf(first), new Date(first * 86400000).getUTCDay());
  // every day of June is in the grid
  for (let d = 1; d <= 30; d++) {
    assert.ok(grid.includes(c.parseDueDate('2026-06-' + String(d).padStart(2, '0'))));
  }
});

test('addMonths — clamps the day to the target month length', () => {
  const jan31 = c.parseDueDate('2026-01-31');
  // +1 month → Feb (2026 not leap) clamps to the 28th, never overflows to March
  assert.equal(c.addMonths(jan31, 1), c.parseDueDate('2026-02-28'));
  // -2 months → Nov 30 (Nov has 30 days, 31 clamps to 30)
  assert.equal(c.addMonths(jan31, -2), c.parseDueDate('2025-11-30'));
  // a safe day round-trips exactly
  assert.equal(c.addMonths(c.parseDueDate('2026-06-15'), 1), c.parseDueDate('2026-07-15'));
});

test('agendaGantt — bar/ongoing layout, axis range includes today, day offsets', () => {
  const today = c.parseDueDate('2026-06-14');
  const items = [
    // a full range start→due
    { id: 'a', start: c.parseDueDate('2026-06-12'), due: c.parseDueDate('2026-06-18'), title: 'A' },
    // due only → a 1-day bar at the deadline
    { id: 'b', start: null, due: c.parseDueDate('2026-06-20'), title: 'B' },
    // start only → ongoing bar from start to today
    { id: 'd', start: c.parseDueDate('2026-06-10'), due: null, title: 'D' },
    // undated → skipped
    { id: 'x', start: null, due: null, title: 'X' },
  ];
  const g = host(c.agendaGantt(items, today));
  // range spans earliest (Jun 10) to latest (Jun 20), padded one day each side
  assert.equal(g.rangeStart, c.parseDueDate('2026-06-09'));
  assert.equal(g.rangeEnd,   c.parseDueDate('2026-06-21'));
  assert.equal(g.rangeDays,  g.rangeEnd - g.rangeStart + 1);
  // undated dropped; rows sorted by start day (D@10, A@12, B@20)
  assert.deepEqual(g.rows.map(r => r.id), ['d', 'a', 'b']);
  const byId = Object.fromEntries(g.rows.map(r => [r.id, r]));
  // A: range bar, start Jun 12 → due Jun 18 = 7 days, offset from Jun 9 = 3
  assert.equal(byId.a.kind, 'bar');
  assert.equal(byId.a.offsetDays, 3);
  assert.equal(byId.a.spanDays, 7);
  // B: due-only → 1-day bar at Jun 20 (offset 11)
  assert.equal(byId.b.kind, 'bar');
  assert.equal(byId.b.spanDays, 1);
  assert.equal(byId.b.offsetDays, 11);
  // D: ongoing → Jun 10 to today (Jun 14) = 5 days, offset 1
  assert.equal(byId.d.kind, 'ongoing');
  assert.equal(byId.d.offsetDays, 1);
  assert.equal(byId.d.spanDays, 5);
  // empty / null input is safe (still a valid 1-day frame)
  assert.equal(host(c.agendaGantt([], today)).rows.length, 0);
  assert.equal(host(c.agendaGantt(null, today)).rows.length, 0);
});

test('agendaGantt — today is always inside the range even with only future items', () => {
  const today = c.parseDueDate('2026-06-14');
  const g = host(c.agendaGantt([{ id: 'f', start: null, due: c.parseDueDate('2026-08-01'), title: 'F' }], today));
  assert.ok(g.rangeStart <= today && today <= g.rangeEnd, 'today must be within the axis range');
  // a far-future deadline still anchors back to today (range starts a day before today)
  assert.equal(g.rangeStart, today - 1);
});

test('agendaGantt — a row carries the item done flag through to the renderer (B3)', () => {
  const today = c.parseDueDate('2026-06-14');
  const g = host(c.agendaGantt([
    { id: 'o', start: null, due: c.parseDueDate('2026-06-18'), title: 'Open', done: false },
    { id: 'd', start: null, due: c.parseDueDate('2026-06-20'), title: 'Done', done: true },
  ], today));
  const byId = Object.fromEntries(g.rows.map(r => [r.id, r]));
  // done must survive the layout so renderAgendaGantt can dim/strike it (.done class)
  assert.equal(byId.o.done, false);
  assert.equal(byId.d.done, true);
});

test('agendaGantt — a future-dated start with no due is a pending marker, not an ongoing bar (#768)', () => {
  const today = c.parseDueDate('2026-06-14');
  const g = host(c.agendaGantt([
    { id: 'run',  start: c.parseDueDate('2026-06-10'), due: null, title: 'Running' },     // started (start <= today)
    { id: 'soon', start: c.parseDueDate('2026-06-20'), due: null, title: 'Not started' }, // future start (start > today)
  ], today));
  const byId = Object.fromEntries(g.rows.map(r => [r.id, r]));
  // a STARTED start-only point is an open-ended 'ongoing' bar spanning start → today
  assert.equal(byId.run.kind, 'ongoing');
  assert.equal(byId.run.spanDays, 5);          // 2026-06-10 → 2026-06-14 inclusive
  // a FUTURE start is a 1-day 'pending' marker at its start, NOT an in-progress bar (#768)
  assert.equal(byId.soon.kind, 'pending');
  assert.equal(byId.soon.spanDays, 1);         // a single-day marker, not a bar reaching back to today
});

test('#1198 agendaGantt — a millennium-spanning set clamps the drawn window, never a freeze, never a drop', () => {
  const today = c.parseDueDate('2026-06-14');
  const items = [
    { id: 'now',  start: null, due: today, title: 'Today' },
    { id: 'past', start: null, due: c.parseDueDate('1347-06-15'), title: 'Siege' },   // ~680 years back
    { id: 'far',  start: null, due: c.parseDueDate('3200-01-01'), title: 'Campaign' }, // ~1200 years fwd
  ];
  const g = host(c.agendaGantt(items, today));
  // every dated item is still a row (nothing silently dropped — they live in the List/Month too)
  assert.equal(g.rows.length, 3, 'all three dated items are kept');
  // but the DRAWN window is clamped so a day-per-column axis can't freeze the tab
  assert.equal(g.clamped, true, 'a centuries-wide span clamps the drawn window');
  assert.ok(g.rangeDays <= 11001, `rangeDays stays bounded (was ${g.rangeDays}, true span ${g.trueDays})`);
  assert.ok(g.trueDays > 500000, 'the true span is recorded so the render can say how wide it really is');
  assert.equal(g.offWindow, 2, 'the two far events are counted as outside the drawn window');
  // a set that fits is NOT clamped (the common case is untouched)
  const near = host(c.agendaGantt([{ id: 'a', start: null, due: c.parseDueDate('2026-08-01'), title: 'A' }], today));
  assert.equal(near.clamped, false, 'a normal-range plan draws its full window, unclamped');
});

test('agendaMonthCells — 42 cells, items placed on their day, inMonth/today flags', () => {
  const today  = c.parseDueDate('2026-06-14');
  const anchor = c.parseDueDate('2026-06-01');     // June 2026
  const d10    = c.parseDueDate('2026-06-10');
  const july5  = c.parseDueDate('2026-07-05');
  const items = [
    { id: 'a', epochDay: d10 },
    { id: 'b', epochDay: d10 },                     // same day as a
    { id: 'c', epochDay: today },
    { id: 'z', epochDay: july5 },                   // next month → out-of-month trailing cell
  ];
  const cells = host(c.agendaMonthCells(items, anchor, today));
  assert.equal(cells.length, 42);
  // backbone is exactly calendarMonthGrid (Sunday-aligned 6 weeks)
  assert.deepEqual(cells.map(x => x.epochDay), host(c.calendarMonthGrid(anchor)));
  // two items share June 10's cell; it's in-month with the right day number
  const cell10 = cells.find(x => x.epochDay === d10);
  assert.deepEqual(cell10.items.map(i => i.id).sort(), ['a', 'b']);
  assert.equal(cell10.inMonth, true);
  assert.equal(cell10.dom, 10);
  // today flag
  const cellToday = cells.find(x => x.epochDay === today);
  assert.equal(cellToday.isToday, true);
  assert.deepEqual(cellToday.items.map(i => i.id), ['c']);
  // a July item lands in a trailing out-of-month cell (June 2026's grid reaches July 11)
  assert.ok(c.calendarMonthGrid(anchor).includes(july5), 'July 5 should be in June 2026 grid');
  const julyCell = cells.find(x => x.epochDay === july5);
  assert.equal(julyCell.inMonth, false);
  assert.equal(julyCell.items.length, 1);
  // empty days carry an empty array, never undefined
  assert.ok(cells.every(x => Array.isArray(x.items)));
});

test('agendaWeekCells — 7 Sunday-aligned days + an Earlier bucket for overdue/running', () => {
  const today  = c.parseDueDate('2026-06-17');     // a Wednesday
  const inWeek = c.parseDueDate('2026-06-18');     // Thu, same week
  const before = c.parseDueDate('2026-06-05');     // overdue, before the week
  const beforeDone = c.parseDueDate('2026-06-06'); // before the week but DONE → not carried
  const nextWeek = c.parseDueDate('2026-06-25');   // beyond the week → excluded
  const items = [
    { id: 'now', epochDay: today },
    { id: 'thu', epochDay: inWeek },
    { id: 'old', epochDay: before, done: false },
    { id: 'olddone', epochDay: beforeDone, done: true },
    { id: 'nxt', epochDay: nextWeek },
  ];
  const wk = host(c.agendaWeekCells(items, today, today));
  assert.equal(wk.days.length, 7, 'seven day cells');
  assert.equal(new Date(wk.start * 86400000).getUTCDay(), 0, 'week starts on Sunday');
  // today's cell carries the item and the isToday flag
  const td = wk.days.find(d => d.epochDay === today);
  assert.deepEqual(td.items.map(i => i.id), ['now']);
  assert.equal(td.isToday, true);
  // Thursday holds its item
  assert.deepEqual(wk.days.find(d => d.epochDay === inWeek).items.map(i => i.id), ['thu']);
  // the overdue-before-the-week item spills to Earlier; the DONE one does NOT; next week excluded
  assert.deepEqual(wk.earlier.map(i => i.id), ['old']);
  assert.ok(!wk.days.some(d => d.items.some(i => i.id === 'nxt')), 'next-week item excluded');
  // empty days carry an empty array
  assert.ok(wk.days.every(d => Array.isArray(d.items)));
});

test('addWeeks — steps by 7-day weeks', () => {
  const w = c.parseDueDate('2026-06-17');
  assert.equal(c.addWeeks(w, 1), w + 7);
  assert.equal(c.addWeeks(w, -2), w - 14);
});

test('agendaDayStats — counts to-do vs done and orders active-first (done sinks)', () => {
  const items = [
    { id: 'a', done: false },
    { id: 'b', done: true },
    { id: 'c', done: false },
    { id: 'd', done: true },
  ];
  const { ordered, todo, done } = c.agendaDayStats(items);
  assert.equal(todo, 2);
  assert.equal(done, 2);
  // active items keep their incoming order and come first; done items sink, order preserved
  assert.deepEqual(ordered.map(x => x.id), ['a', 'c', 'b', 'd']);
  // empty day
  const e = c.agendaDayStats([]);
  assert.deepEqual([e.todo, e.done, e.ordered.length], [0, 0, 0]);
});

