  assert.ok(rvs.includes("host.querySelector('.mt-base-views')") && rvs.includes('strip.replaceWith(fresh)') && rvs.includes('wireViewButtons(host, node)'),
    'it replaces the switcher strip in place and re-wires the buttons');
