// ── sync-safety: tmpWriteName (atomic-write temp filename) ────────────────────
test('tmpWriteName — produces a hidden per-write .pltmp sibling, not a .opml (HARD-10)', () => {
  // WAVE-2 HARD-10: the temp name is now per-write-unique (a monotonic suffix) so two racing writers
  // on one file can't collide on a fixed temp. Shape: starts '.', ends '.pltmp', carries the base.
  const t1 = c.tmpWriteName('notes.opml');
  assert.match(t1, /^\.notes\.\d+\.pltmp$/, `hidden .pltmp sibling of the base, got "${t1}"`);
  assert.ok(!/\.opml$/i.test(t1), 'never ends in .opml (would be doc-listed)');
  assert.notEqual(c.tmpWriteName('notes.opml'), t1, 'each call is unique (no fixed-temp collision)');
  assert.match(c.tmpWriteName('Daily Log.opml'), /^\.Daily Log\.\d+\.pltmp$/);
});
// ── file-name display / normalize ────────────────────────────────────────────
test('displayName — strips .opml and maps the unsaved sentinel', () => {
  assert.equal(c.displayName('notes.opml'), 'notes');
  assert.equal(c.displayName('Notes.OPML'), 'Notes');
  assert.equal(c.displayName('unsaved'), 'Untitled');
  assert.equal(c.displayName(''), 'Untitled');
  assert.equal(c.displayName('no-extension'), 'no-extension');
});
test('toFileName — sanitizes and ensures a single .opml', () => {
  assert.equal(c.toFileName('Project notes'), 'Project notes.opml');
  assert.equal(c.toFileName('already.opml'), 'already.opml');
  assert.equal(c.toFileName('  spaced  '), 'spaced.opml');
  assert.equal(c.toFileName(''), 'outline.opml');
  assert.equal(c.toFileName('a/b:c*?'), 'a-b-c--.opml');   // illegal path chars -> dashes
});
test('tmpWriteName — the temp name is NOT listed as a document', () => {
  // critical: a stray/interrupted temp must never appear in the workspace doc list
  const listed = host(c.workspaceDocList(['notes.opml', c.tmpWriteName('notes.opml')]));
  assert.deepEqual(listed, ['notes.opml']);
});

// ── the Markdown export survives a renderer ──────────────────────────────────
// toMarkdown pushed one array entry per line and joined with '\n', so it never emitted a `\n\n`
// at all. Under CommonMark that merges blocks that were separate on screen. Verified against a
// real CommonMark implementation (markdown-it) outside the repo; these pin the shape it produces.
const _mdN = (text, type = 'ul', extra = {}) => Object.assign(c.mkNode(text, type), extra);
const _mdOf = (...kids) => { const r = c.mkRoot(); r.children.push(...kids); return c.toMarkdown(r); };

test('toMarkdown — a blank line separates blocks, and NEVER two list items', () => {
  // para -> para was one <p>. This is the transition the whole policy exists for.
  assert.match(_mdOf(_mdN('One.', 'para'), _mdN('Two.', 'para')), /One\.\n\nTwo\./);
  // ...but bullets must stay TIGHT. A blank line between list items makes the list loose, which
  // wraps every <li> in <p> and changes the render of an ordinary outline. The likeliest
  // regression in this change, so it is asserted directly.
  assert.match(_mdOf(_mdN('a'), _mdN('b'), _mdN('c')), /- a\n- b\n- c/);
  assert.ok(!/- a\n\n- b/.test(_mdOf(_mdN('a'), _mdN('b'))), 'no blank line between two bullets');
  // a block on either side of a list run is separated from it in both directions
  assert.match(_mdOf(_mdN('a'), _mdN('After.', 'para')), /- a\n\nAfter\./);
  assert.match(_mdOf(_mdN('Before.', 'para'), _mdN('a')), /Before\.\n\n- a/);
  // headings, quotes and tables are blocks too
  assert.match(_mdOf(_mdN('# H', 'h1'), _mdN('Body.', 'para')), /# H\n\nBody\./);
  assert.match(_mdOf(_mdN('> Q', 'quote'), _mdN('After.', 'para')), /> Q\n\nAfter\./);
  assert.match(_mdOf(_mdN('| a |\n|---|', 'base'), _mdN('After.', 'para')), /\|---\|\n\nAfter\./);
  // no leading blank line, and the file still ends in exactly one newline
  const md = _mdOf(_mdN('One.', 'para'), _mdN('Two.', 'para'));
  assert.ok(!md.startsWith('\n'), 'no leading blank line');
  assert.ok(md.endsWith('\n') && !md.endsWith('\n\n'), 'exactly one trailing newline');
});

test('toMarkdown — the footnote definition run is its own block', () => {
  // Phase A: footnotes come from the doc store (root.footnotes) and export as document-order numbers.
  const r = c.mkRoot();
  r.footnotes = [{ id: 'a', text: 'the body' }];
  r.children.push(_mdN('Prose with a ref[^a]', 'para'), _mdN('after'));
  const md = c.toMarkdown(r);
  assert.match(md, /Prose with a ref\[\^1\]\n\n {2}\[\^1\]: the body/, 'a blank line before the definition');
  assert.match(md, /\[\^1\]: the body\n\n- after/, 'and the next point is separated from it');
});

test('toMarkdown — a blockquote keeps its > even when the point is not typed as a quote', () => {
  // textForDisplay strips a `> ` prefix via its deriveTypeFromText fallback REGARDLESS of declared
  // type (#420), but toMarkdown re-added it only for node.type === 'quote'. So every blockquote
  // written on a para lost its `>` and shipped as a plain sentence, while mdToHtml drew a real
  // <blockquote> on screen. What you saw was not what shipped.
  assert.match(_mdOf(_mdN('> A quotation', 'para')), /^> A quotation/m, 'a quote on a PARA keeps its >');
  assert.match(_mdOf(_mdN('> A quotation', 'quote')), /^> A quotation/m, 'a declared quote still does');
  // every line, not just the first: a multi-line quote must not depend on lazy continuation to
  // stay one blockquote, which the blank-line policy is specifically breaking
  const multi = _mdOf(_mdN('> line one\nline two', 'quote'));
  assert.match(multi, /> line one\n> line two/, 'the > is on every line');
});

// ── #1296 spreadsheet paste → points with tagged number properties ──────────
test('#1296 importCellValue: currency/thousands/percent reduce to a bare number; other cells stay text', () => {
  assert.equal(c.importCellValue('$3,200.00'), '3200.00', 'a currency-and-thousands cell becomes a number a sum can read');
  assert.equal(c.importCellValue('1,234'), '1234', 'thousands separators dropped');
  assert.equal(c.importCellValue('45%'), '45', 'a percent becomes its number');
  assert.equal(c.importCellValue('-5'), '-5', 'a negative keeps its sign');
  assert.equal(c.importCellValue('  "quoted"  '), 'quoted', 'surrounding quotes stripped');
  assert.equal(c.importCellValue('3 apples'), '3 apples', 'a number with text stays text (not 3)');
  assert.equal(c.importCellValue('v2'), 'v2', 'a label with a digit stays text');
  assert.equal(c.importCellValue(''), '', 'an empty cell is empty');
});

test('#1296 importKeyName: a header becomes an engine-safe property key', () => {
  assert.equal(c.importKeyName('Unit Cost'), 'unit_cost', 'spaces become underscores, lowercased');
  assert.equal(c.importKeyName('Cost ($)'), 'cost', 'punctuation trimmed to a clean key');
  assert.equal(c.importKeyName('  Qty  '), 'qty');
  assert.equal(c.importKeyName('($)'), '', 'a key with no word characters is empty');
});

test('#1296 importSplitRow: tab is a plain split; comma is quote-aware', () => {
  assert.deepEqual(host(c.importSplitRow('a\tb\tc', '\t')), ['a', 'b', 'c'], 'tab split');
  assert.deepEqual(host(c.importSplitRow('a,b,c', ',')), ['a', 'b', 'c'], 'comma split');
  assert.deepEqual(host(c.importSplitRow('a,"b, c",d', ',')), ['a', 'b, c', 'd'], 'a quoted comma stays inside its cell');
  assert.deepEqual(host(c.importSplitRow('a,"he said ""hi""",b', ',')), ['a', 'he said "hi"', 'b'], 'a doubled quote is one literal quote');
});

test('#1296 sniffDelimited: rectangular tab/comma tables detected; prose and Markdown are not', () => {
  assert.equal(c.sniffDelimited('Item\tCost\nCabinets\t3200\nSink\t540'), '\t', 'a TSV paste is a table');
  assert.equal(c.sniffDelimited('Item,Cost\nCabinets,3200\nSink,540'), ',', 'a CSV paste is a table');
  assert.equal(c.sniffDelimited('Hello, world. This is prose, with commas.'), null, 'one line of prose is not a table');
  assert.equal(c.sniffDelimited('# A heading\n- a list item\n- another'), null, 'Markdown is not a delimited table');
  assert.equal(c.sniffDelimited('just one column\nsecond row\nthird row'), null, 'a single column is not a table');
});

test('#1296 tableToPoints: rows become points under one heading; number columns emit numeric {prop} tokens', () => {
  const src = 'Item\tCost\tQty\tRoom\nCabinets\t$3,200\t2\tKitchen\nCountertop\t1800\t1\tKitchen\nSink\t540\t1\tBath';
  const { points } = c.tableToPoints(src, '\t');
  assert.equal(points.length, 1, 'the whole table lands under ONE heading');
  const head = points[0];
  assert.match(head.text, /^##\s/, 'the parent is a heading, so the + Total door can appear on it (deriveTypeFromText → h2)');
  assert.equal(nonEmpty(head.children, 'table rows').length, 3, 'one point per data row (header row excluded)');
  // First column is the point text; each later column is a {prop key: value} promoteLoadedShorthand
  // turns into a real prop. A numeric cell is normalized to a bare number (so a sum reads it); a text
  // cell stays text (so it gets no + Total door). Header cells become engine-safe keys.
  assert.equal(head.children[0].text, 'Cabinets {prop cost: 3200} {prop qty: 2} {prop room: Kitchen}',
    'currency normalized to a number, qty numeric, Room kept as text; keys lowercased');
  // The header row is never a data point, and an empty cell contributes no token.
  const { points: p2 } = c.tableToPoints('Item,Cost\nOnly,\n', ',');
  assert.equal(p2[0].children[0].text, 'Only', 'an empty cost cell adds no {prop} token');
});

test('#1324 pasting a spreadsheet into the OUTLINE runs the same conversion (not just the Import dialog)', () => {
  // handlePaste sniffs a delimited paste and converts it to the table-of-points, promotes the {prop} tokens,
  // and tells the user with an undoable toast. Before, this ran ONLY inside the Import dialog, so a paste
  // into the outline split each row into a plain point and the CSV->properties feature stayed hidden.
  const hp = fnBody(_src, 'handlePaste');
  assert.ok(hp.includes('const delim = sniffDelimited(text)'), 'the paste handler sniffs for a delimited table');
  assert.ok(hp.includes('tableToPoints(text, delim).points'), 'a delimited paste is converted to the table-of-points');
  assert.ok(/\.forEach\(promoteLoadedShorthand\)/.test(hp) && hp.includes('promoteLoadedShorthand)'), 'the {prop} tokens are promoted to real props');
  assert.ok(/as a table with columns\. Undo to remove\./.test(hp), 'a loud, undoable toast reports the conversion (P4)');
  // the sniff placement matters: it runs AFTER the single-line and para early-returns, so it never
  // hijacks a one-line paste or a prose block.
  assert.ok(hp.indexOf("node.type === 'para'") < hp.indexOf('sniffDelimited(text)'), 'the table sniff runs after the prose/para branch, not before');
});

test('#1310 CSV export: csvCell escaping and rowsToCsv are the inverse of the paste importer', () => {
  assert.equal(c.csvCell('plain'), 'plain', 'a clean cell is bare');
  assert.equal(c.csvCell('a,b'), '"a,b"', 'a comma forces quotes');
  assert.equal(c.csvCell('he said "hi"'), '"he said ""hi"""', 'internal quotes double');
  assert.equal(c.csvCell('two\nlines'), '"two\nlines"', 'a newline forces quotes');
  assert.equal(c.rowsToCsv([['a', 'b'], ['c', 'd']]), 'a,b\r\nc,d', 'rows join with CRLF, cells with commas');
  // Round-trip: a value with a comma survives export → re-parse by the #1296 importer.
  const csv = c.rowsToCsv([['name', 'note'], ['Sink', 'a, tricky value']]);
  assert.deepEqual(host(c.importSplitRow(csv.split('\r\n')[1], ',')), ['Sink', 'a, tricky value'], 'the exported quoting round-trips through importSplitRow');
});

test('#1310 sectionToCsvRows: rows become a grid (union of property columns, values frozen, empties filled)', () => {
  const head = c.mkNode('## Budget');
  const mk = (t, props) => { const n = c.mkNode(t); for (const [k, v] of props) n.props.push({ key: k, val: String(v) }); return n; };
  head.children.push(
    mk('Hall {prop cost: 3200}', [['cost', 3200], ['qty', 2]]),   // text carries a pill token; title must clean it
    mk('Catering', [['cost', 4800]]),                              // no qty → empty cell
  );
  const rows = c.sectionToCsvRows(head, {});
  assert.deepEqual(host(rows[0]), ['name', 'cost', 'qty'], 'header is a name column + the UNION of property keys');
  assert.deepEqual(host(rows[1]), ['Hall', '3200', '2'], 'the title is cleaned of its pill token; values follow the columns');
  assert.deepEqual(host(rows[2]), ['Catering', '4800', ''], 'a row missing a column gets an empty cell');
  // Nothing to export: fewer than two rows, or no properties at all.
  assert.equal(c.sectionToCsvRows(c.mkNode('lonely'), {}), null, 'no children → null');
  const plain = c.mkNode('p'); plain.children.push(c.mkNode('a'), c.mkNode('b'));
  assert.equal(c.sectionToCsvRows(plain, {}), null, 'rows with no properties → nothing to tabulate');
});

test('#1310 the CSV export is wired (a section with property rows gets a bullet-menu door)', () => {
  assert.ok(_src.includes("label:'Export table to CSV'"), 'the bullet menu offers a CSV export');
  assert.ok(_src.includes('sectionToCsvRows(node, knownStates(root)) ?'), 'the door only appears when there is a table to export');
  const fn = fnBody(_src, 'exportSectionCsv');
  assert.ok(fn.includes('rowsToCsv(rows)') && fn.includes("'.csv'"), 'it downloads the rows as a .csv');
});

// ── #1297 date-series generator (batch dated points at a fixed interval) ─────
test('#1297 dateSeries: evenly-spaced dates from start to end, inclusive, capped, invalid → empty', () => {
  // 2026-04-01 is epoch day 20544; every 14 days through 2026-05-01 (20574) → Apr 1, 15, 29.
  const start = c.parseDueDate('2026-04-01'), end = c.parseDueDate('2026-05-01');
  const s = c.dateSeries(start, 14, end);
  assert.deepEqual(host(s), [start, start + 14, start + 28], 'three dates, 14 apart, the last on or before the end');
  assert.equal(c.dateSeries(start, 14, start)[0], start, 'a single-day range yields just the start');
  assert.deepEqual(host(c.dateSeries(end, 14, start)), [], 'end before start → no dates');
  assert.deepEqual(host(c.dateSeries(start, 0, end)), [], 'a zero/blank step makes no series (no infinite loop)');
  assert.deepEqual(host(c.dateSeries(start, -5, end)), [], 'a negative step is rejected');
  assert.equal(c.dateSeries(start, 1, start + 10000, 366).length, 366, 'the count is capped so a huge range never runs away');
});

test('#1297 the date-series generator is wired (bullet-menu door, dated to-do children, parseDueDate inputs)', () => {
  assert.ok(_src.includes("label:'Repeating dates…'") && _src.includes('openDateSeriesDialog(nodeId)'), 'a bullet-menu door opens the generator');
  const ins = fnBody(_src, 'insertDateSeriesPoints');
  assert.ok(ins.includes("mkNode('- [ ] ' + label)") && ins.includes("setDateProp(cn, 'due'"), 'each generated point is a to-do with a real due date, so it lands in the Agenda');
  const dlg = fnBody(_src, 'openDateSeriesDialog');
  assert.ok(dlg.includes('parseDueDate') && dlg.includes('dateSeries('), 'the dialog parses the dates and calls the pure series core');
  assert.ok(dlg.includes('flashError'), 'bad input is rejected visibly, never a silent empty insert');
});

// ── #1265 Markdown import (markdownToPoints, the inverse of toMarkdown) ──────
const _mdStruct = (nodes) => nodes.map(n => ({ text: n.text, type: n.type, kids: _mdStruct(n.children || []) }));

test('#1265 markdownToPoints — headings nest by level, lists by relative indent', () => {
  const { points } = c.markdownToPoints('# Book\n\nSome intro prose.\n\n- first\n  - nested\n- second\n\n## Chapter One\n\nChapter prose.');
  const s = _mdStruct(points);
  assert.equal(s.length, 1, 'one top-level heading holds everything');
  assert.equal(s[0].text, '# Book'); assert.equal(s[0].type, 'h1');
  const k = s[0].kids;
  assert.equal(k[0].text, 'Some intro prose.'); assert.equal(k[0].type, 'para');
  assert.equal(k[1].text, 'first'); assert.equal(k[1].type, 'ul');
  assert.equal(k[1].kids[0].text, 'nested', 'a two-space indent nests');
  assert.equal(k[2].text, 'second', 'a dedent is a sibling');
  const ch = k.find(x => x.text === '## Chapter One');
  assert.ok(ch && ch.type === 'h2', 'the ## heading nests under the # heading');
  assert.equal(ch.kids[0].text, 'Chapter prose.');
});

test('#1265 markdownToPoints — todos, quotes, dividers, ordered lists', () => {
  const s = _mdStruct(c.markdownToPoints('- [ ] open task\n- [x] done task\n> a quotation\n1. first\n2. second\n---').points);
  assert.equal(s[0].type, 'todo'); assert.equal(s[0].text, '- [ ] open task');
  assert.equal(s[1].type, 'todo');
  assert.equal(s[2].type, 'quote'); assert.equal(s[2].text, '> a quotation');
  assert.equal(s[3].type, 'ol'); assert.equal(s[3].text, 'first');
  assert.equal(s[5].type, 'divider');
});

test('#1265 markdownToPoints — a FLAT foreign file (no indentation) still nests by heading level', () => {
  const s = _mdStruct(c.markdownToPoints('# A\n## B\n- x\n## C\n- y').points);
  assert.equal(s.length, 1, 'one top-level, # A');
  assert.equal(s[0].kids.length, 2, '## B and ## C both under # A');
  assert.equal(s[0].kids[0].text, '## B');
  assert.equal(s[0].kids[0].kids[0].text, 'x', '- x under B');
  assert.equal(s[0].kids[1].text, '## C');
  assert.equal(s[0].kids[1].kids[0].text, 'y', '- y under C, not left under B');
});

test('#1265 markdownToPoints — footnote def attaches to its referencing point; frontmatter dropped', () => {
  const { points, skipped } = c.markdownToPoints('---\ntitle: X\n---\n# H\n\nA claim.[^1]\n\n[^1]: The source.');
  assert.ok(skipped.includes('frontmatter'), 'a YAML frontmatter block is dropped and reported');
  let host = null; (function w(ns){ for (const n of ns){ if (/\[\^1\]/.test(n.text)) host = n; w(n.children || []); } })(points);
  assert.ok(host, 'the referencing point exists');
  assert.equal(JSON.stringify(host.footnotes), JSON.stringify([{ key: '1', text: 'The source.' }]),
    'the def attaches as a per-node footnote (the doc store lifts it on insert)');
});

test('#1265 markdownToPoints — export then re-import is stable (round-trip fixed point)', () => {
  const md = '# Book\n\nIntro.\n\n- a\n  - a1\n- b\n\n## Ch\n\nProse.';
  const p1 = c.markdownToPoints(md).points;
  const root = Object.assign(c.mkRoot(), { children: p1, footnotes: [] });
  const p2 = c.markdownToPoints(c.toMarkdown(root)).points;
  assert.equal(JSON.stringify(_mdStruct(p2)), JSON.stringify(_mdStruct(p1)),
    'import(export(import(md))) equals import(md): export and import are inverses on our own shape');
});

test('#1265 Markdown import — wired into the Import door (format-sniffed, reuses appendOpmlSubtrees)', () => {
  assert.ok(_src.includes('markdownToPoints(text)'), 'the Import door parses non-OPML text as Markdown');
  assert.ok(/appendOpmlSubtrees\(null, label, \{ all: true, announce: true, trees: points \}\)/.test(_src),
    'Markdown points append as trees (skips the OPML round-trip so footnotes survive), reusing promote/undo/footnote-lift');
  assert.ok(/if \(opts\.trees\)/.test(_src), 'appendOpmlSubtrees accepts pre-parsed trees');
  assert.ok(_src.includes('.md,.markdown'), 'the file picker accepts .md/.markdown');
});

test('#1296 spreadsheet import — wired into the Import door (sniffed before Markdown, same append path, .csv accepted)', () => {
  assert.ok(_src.includes('(tblDelim = sniffDelimited(text))'), 'the Import door sniffs a delimited table before falling back to Markdown');
  assert.ok(_src.includes('tableToPoints(text, tblDelim)'), 'a detected table parses into heading+row trees');
  assert.ok(/tableNote = ok/.test(_src) && _src.includes('click + Total to sum'), 'a successful table import nudges the user toward the + Total door');
  assert.ok(/inp\.accept = '[^']*\.csv/.test(_src), 'the file picker accepts .csv');
  // Order guard: the OPML sniff and the table sniff both precede the Markdown fallback, so a CSV never
  // reaches markdownToPoints (a comma-heavy sentence would otherwise import as one prose point).
  const di = between(_src, 'const doImport = (text, label) =>', 'const doVaultImport');
  assert.ok(di.indexOf('sniffDelimited') < di.indexOf('markdownToPoints'), 'table is tried before Markdown');
});

// ── #1265 PR 2: multi-file "vault" import (each file a section, [[wikilinks]] resolved) ──────
test('#1265 PR2 markdownVaultToPoints — [[Page]] between files resolves to an internal link; unknown stays text', () => {
  const { points } = c.markdownVaultToPoints([
    { name: 'Alpha.md', text: '# Alpha\n\nSee [[Beta]] and [[Ghost]].' },
    { name: 'Beta.md', text: '# Beta\n\nThe other note.' },
  ]);
  assert.equal(points.length, 2, 'each file becomes one top-level section');
  const alpha = points.find(p => /Alpha/.test(p.text));
  const beta = points.find(p => /Beta/.test(p.text));
  // the leading H1 IS the section, so its id is what [[Beta]] should point at
  const body = alpha.children.find(k => /See /.test(k.text));
  assert.ok(body.text.includes(`[[#${beta.id}|Beta]]`), 'a known [[Page]] becomes an internal link to that section');
  assert.ok(body.text.includes('[[Ghost]]'), 'an unresolved wikilink stays as literal text');
});

test('#1265 PR2 markdownVaultToPoints — ![[embed]] becomes a live mirror; [[Page|alias]] keeps the alias', () => {
  const { points } = c.markdownVaultToPoints([
    { name: 'Index.md', text: '# Index\n\n![[Detail]] plus [[Detail|the details]].' },
    { name: 'Detail.md', text: '# Detail\n\nStuff.' },
  ]);
  const detail = points.find(p => /Detail/.test(p.text));
  const body = points.find(p => /Index/.test(p.text)).children.find(k => /plus/.test(k.text));
  assert.ok(body.text.includes(`[[#${detail.id}|]]`), '![[Page]] becomes an empty-label mirror embed');
  assert.ok(body.text.includes(`[[#${detail.id}|the details]]`), '[[Page|alias]] links with the alias as the label');
});

test('#1265 PR2 markdownVaultToPoints — a file with no leading H1 is wrapped in a #filename section', () => {
  const { points } = c.markdownVaultToPoints([{ name: 'notes/loose.md', text: 'just a paragraph.\n\n- a point' }]);
  assert.equal(points.length, 1);
  assert.equal(points[0].type, 'h1', 'wrapper section is a heading');
  assert.equal(points[0].text, '# loose', 'wrapper is titled by the basename (path + extension stripped)');
  assert.ok(points[0].children.some(k => /just a paragraph/.test(k.text)), 'the file content nests under the wrapper');
});

test('#1265 PR2 markdownVaultToPoints — filename resolves even when the leading heading text differs', () => {
  // Obsidian resolves [[Page]] by FILENAME; the file "kestrel.md" titled "# The Kestrel" resolves both.
  const { points } = c.markdownVaultToPoints([
    { name: 'home.md', text: '# Home\n\nlink [[kestrel]] and [[The Kestrel]].' },
    { name: 'kestrel.md', text: '# The Kestrel\n\nA bird.' },
  ]);
  const bird = points.find(p => /Kestrel/.test(p.text));
  const body = points.find(p => /Home/.test(p.text)).children.find(k => /link/.test(k.text));
  assert.ok(body.text.includes(`[[#${bird.id}|kestrel]]`), 'resolves by filename');
  assert.ok(body.text.includes(`[[#${bird.id}|The Kestrel]]`), 'also resolves by the leading-heading text');
});

test('#1265 PR2 vault import — wired into the Import door (multi-file -> one linked doc, no re-clone)', () => {
  assert.ok(_src.includes('markdownVaultToPoints(md)'), 'multiple files route through the vault parser');
  assert.ok(/trees: points, noClone: true/.test(_src),
    'the vault appends its trees with noClone so cross-section [[#id]] links are not orphaned by a per-clone re-id');
  assert.ok(/const clones = opts\.noClone \? pick : pick\.map\(deepCloneNodeNewIds\)/.test(_src),
    'appendOpmlSubtrees honours noClone (append fresh trees as-is)');
  assert.ok(/inp\.multiple = true/.test(_src), 'the file picker accepts multiple files');
});

// ── #1265: BibTeX (.bib) → citations in the document footnote store ──────
// The panel's last import bridge. Same rule as its Markdown and spreadsheet siblings: a FORMAT, never
// a product, so these fixtures are plain BibTeX/BibLaTeX rather than any one manager's dialect.
const _BIB = [
  '% exported by a reference manager',
  '@string{jt = {Journal of Things}}',
  '@article{smith2020,',
  '  author  = {Smith, Jane and Doe, John},',
  '  title   = {A Study of {DNA} Things},',
  '  journal = {Journal of Things},',
  '  year    = {2020},',
  '  doi     = {https://doi.org/10.1000/xyz}',
  '}',
  '@book{muller-2019,',
  '  author    = {M{\\"u}ller, Anna},',
  '  title     = {Origins of \\emph{Everything}},',
  '  publisher = "Big Press",',
  '  date      = {2019-05-01}',
  '}',
].join('\n');

test('#1265 sniffBibtex — tells a .bib from Markdown, OPML and a spreadsheet, past leading comments', () => {
  assert.ok(c.sniffBibtex(_BIB), 'a real .bib is recognised even behind a % comment line');
  assert.ok(c.sniffBibtex('@misc(parens,\n title = {T})'), 'the paren entry form counts too');
  assert.equal(c.sniffBibtex('# A heading\n\n- a bullet'), false, 'Markdown is not BibTeX');
  assert.equal(c.sniffBibtex('<?xml version="1.0"?><opml/>'), false, 'OPML is not BibTeX');
  assert.equal(c.sniffBibtex('Item\tCost\nRope\t5'), false, 'a spreadsheet is not BibTeX');
  assert.equal(c.sniffBibtex('an email to a@b.com, then @home later'), false,
    'a stray @ mid-prose does not open an entry');
});

test('#1265 the BibTeX sniff MUST precede the table sniff: a .bib really is rectangular under a comma split', () => {
  const bib = '@article{k,\n  title = {T},\n  year = {2020},\n}';
  // Not a hypothetical: this is the live hazard the branch order exists to dodge. Without it every
  // citation in a .bib lands as a spreadsheet row.
  assert.ok(c.sniffDelimited(bib), 'sniffDelimited CLAIMS a plain .bib (one field per line reads as 2 columns)');
  assert.ok(c.sniffBibtex(bib), 'so the BibTeX sniff has to get there first');
});

test('#1265 parseBibtex — entries, nested braces, quoted values, macros named as skipped', () => {
  const { entries, skipped } = c.parseBibtex(_BIB);
  assert.equal(entries.length, 2, 'two real entries; @string is not one of them');
  assert.ok(skipped.includes('BibTeX macros'), 'the @string macro is passed over and SAID so');
  assert.equal(entries[0].type, 'article');
  assert.equal(entries[0].key, 'smith2020');
  assert.equal(entries[0].fields.title, 'A Study of {DNA} Things', 'a nested brace run survives the scan intact');
  assert.equal(entries[1].fields.publisher, 'Big Press', 'a "quoted" value parses');
  assert.equal(c.parseBibtex('@comment{jabref-meta: databaseType:bibtex;}').skipped[0], 'comment blocks');
  assert.equal(c.parseBibtex('@article{a, title = {X} # { Y}}').entries[0].fields.title, 'X Y',
    'a # concatenation joins its parts');
  assert.equal(JSON.stringify(c.parseBibtex('').entries), '[]', 'empty input is empty, not a throw');
  assert.equal(c.parseBibtex('@article{unterminated, title = {X}').entries.length, 1,
    'an unterminated entry takes the rest of the file rather than throwing');
});

test('#1265 bibFieldText — LaTeX that SPELLS a character becomes that character', () => {
  assert.equal(c.bibFieldText('M{\\"u}ller, Anna'), 'Müller, Anna', 'umlaut');
  assert.equal(c.bibFieldText('Fran\\c{c}ois'), 'François', 'cedilla in its braced form');
  assert.equal(c.bibFieldText("Beyonc\\'{e}"), 'Beyoncé', 'acute accent');
  assert.equal(c.bibFieldText('Wei\\ss'), 'Weiß', 'eszett');
  assert.equal(c.bibFieldText('A Study of {DNA} Things'), 'A Study of DNA Things',
    'capitalization braces are removed, their content kept');
  assert.equal(c.bibFieldText('Origins of \\emph{Everything}'), 'Origins of Everything',
    'an unknown command is dropped and its argument kept');
  assert.equal(c.bibFieldText('Smith \\& Sons'), 'Smith & Sons', 'escaped punctuation is unescaped');
  assert.equal(c.bibFieldText('Vol.~3'), 'Vol. 3', 'a tilde is a non-breaking space, not a tilde accent');
  // The command-name hazard: a backslash-c is a cedilla, so a naive rule turns \citep{Smith} into a
  // cedilla on the i and eats the command name.
  assert.equal(c.bibFieldText('\\citep{Smith}'), 'Smith', 'a command STARTING with an accent letter is not eaten');
});

test('#1265 bibDropsLatex — reports a command it had to drop, stays quiet about one it translated', () => {
  assert.equal(c.bibDropsLatex('M{\\"u}ller'), false,
    'an accent is translated exactly, so nothing was simplified (P4: no crying wolf)');
  assert.equal(c.bibDropsLatex('Wei\\ss'), false, 'so is an eszett');
  assert.equal(c.bibDropsLatex('Origins of \\emph{Everything}'), true, 'a dropped command IS a simplification');
});

test('#1265 bibAuthorNames / bibYear — names split at depth 0, BibLaTeX date falls back to its year', () => {
  assert.equal(JSON.stringify(c.bibAuthorNames('Smith, Jane and Doe, John')), '["Smith, Jane","Doe, John"]');
  assert.equal(JSON.stringify(c.bibAuthorNames('{Smith and Sons}')), '["Smith and Sons"]',
    'a braced corporate name is one author, not two');
  assert.equal(JSON.stringify(c.bibAuthorNames('')), '[]', 'no author is no names');
  assert.equal(c.bibYear({ year: '2020' }), '2020');
  assert.equal(c.bibYear({ date: '2019-05-01' }), '2019', 'a BibLaTeX date yields its year');
  assert.equal(c.bibYear({ year: 'in press' }), '', 'a non-year year yields nothing rather than junk');
});

test('#1265 bibCitation — one neutral line: nothing invented, nothing duplicated', () => {
  const { entries } = c.parseBibtex(_BIB);
  assert.equal(c.bibCitation(entries[0]),
    'Smith, Jane; Doe, John. A Study of DNA Things. Journal of Things, 2020. doi:10.1000/xyz.',
    'authors, title, container plus year, doi -- and the doi URL prefix normalised off');
  assert.equal(c.bibCitation(entries[1]), 'Müller, Anna. Origins of Everything. Big Press, 2019.');
  assert.equal(c.bibCitation({ fields: { title: 'Alone' } }), 'Alone.', 'a sparse entry prints only what it has');
  assert.equal(c.bibCitation({ fields: {} }), '', 'an entry with nothing to say says nothing');
  assert.equal(c.bibCitation({ fields: { booktitle: 'Same', title: 'Same', year: '2001' } }), 'Same. 2001.',
    'a container equal to the title is not printed twice');
});

test('#1265 bibToPoints — each entry a point whose [^key] footnote carries its citation', () => {
  const { points, skipped } = c.bibToPoints(_BIB);
  assert.equal(points.length, 1, 'one section holds the import');
  assert.equal(points[0].text, '## Imported references');
  assert.equal(points[0].type, 'h2');
  assert.ok(skipped.includes('BibTeX macros') && skipped.includes('LaTeX commands'),
    'the toast is told what was passed over and what was simplified');
  const kids = nonEmpty(points[0].children, 'imported reference points');
  assert.equal(kids.length, 2, 'one point per entry');
  assert.ok(kids[0].text.startsWith('A Study of DNA Things '), 'the title is the point you read');
  assert.ok(kids[0].text.includes('[^smith2020]'), 'the point carries a footnote marker');
  assert.ok(kids[0].text.includes('{prop cite: smith2020}'),
    'the cite key rides along as a property: it is what her reference manager calls this source');
  assert.ok(kids[0].text.includes('{prop year: 2020}'), 'and the year, so a reading list sorts');
  assert.equal(JSON.stringify(kids[0].footnotes),
    JSON.stringify([{ key: 'smith2020', text: c.bibCitation(c.parseBibtex(_BIB).entries[0]), stable: true }]),
    'the citation is the FOOTNOTE, and #1244 marks it `stable` so the lift KEEPS the cite key as the ' +
    'store id — that is what makes an imported bibliography citable by the key you already know');
  assert.equal(JSON.stringify(c.bibToPoints('not a bib at all').points), '[]',
    'junk imports nothing rather than an empty section');
});

test('#1265 bibToPoints — a marker-hostile cite key is remapped, and two entries never share a footnote', () => {
  const { points } = c.bibToPoints('@misc{smith]2020, title = {T}}\n@misc{dup, title = {A}}\n@misc{dup, title = {B}}');
  const kids = nonEmpty(points[0].children, 'imported reference points');
  // getFnRefs stops at the first ], so a key holding one would silently truncate every marker.
  assert.equal(kids[0].footnotes[0].key, 'smith_2020', 'a key a marker cannot hold is remapped');
  assert.ok(kids[0].text.includes('[^smith_2020]'), 'and the marker in the text agrees with it');
  assert.ok(kids[0].text.includes('{prop cite: smith]2020}'),
    'while the ORIGINAL key is kept, untouched, as the property');
  assert.notEqual(kids[1].footnotes[0].key, kids[2].footnotes[0].key,
    'two entries sharing a cite key get distinct markers, or they would share one citation');
});

test('#1265 BibTeX import — wired into the Import door (sniffed before the table, same append path)', () => {
  const dlg = fnBody(_src, 'openImportDialog');
  const di = between(dlg, 'const doImport = (text, label) =>', 'const doVaultImport');
  // Match the whole BRANCH HEAD, not just the call: an `indexOf('sniffBibtex')` order check still
  // passed with the branch disabled (`false && sniffBibtex(text)`), because the substring stays put.
  const bibHead = '} else if (sniffBibtex(text)) {';
  const tblHead = '} else if ((tblDelim = sniffDelimited(text))) {';
  assert.ok(di.includes(bibHead), 'BibTeX is a LIVE branch of the format sniff, not a disabled one');
  assert.ok(di.includes(tblHead), 'and so is the delimited table');
  assert.ok(di.includes('bibToPoints(text)'), 'the branch parses the file into points');
  assert.ok(di.indexOf(bibHead) < di.indexOf(tblHead),
    'BibTeX is tried BEFORE the table sniff, which would otherwise claim a .bib (proved above)');
  assert.ok(di.indexOf(tblHead) < di.indexOf('markdownToPoints'),
    'and the table before Markdown, as before');
  assert.ok(/trees: points/.test(di),
    'references append as trees, so the footnote lift runs and one undo reverts the whole import');
  assert.ok(di.includes('no references found in that BibTeX file'),
    'an empty or unparseable .bib is refused OUT LOUD (P4)');
  assert.ok(/open File then Footnotes/.test(di),
    'the success toast names the door that lists the citations (P2)');
  const said = nonEmpty([...di.matchAll(/flash(?:Hint|Error)\(`?'?([^`'\n]+)/g)].map(m => m[1]),
    'user-facing strings in the BibTeX branch');
  for (const s of said) assert.ok(!/—/.test(s), `no em dashes in user copy: ${s}`);
});

test('#1265 the Import door format family — every format it accepts is in the picker AND named in the copy', () => {
  const dlg = fnBody(_src, 'openImportDialog');
  const di = between(dlg, 'const doImport = (text, label) =>', 'const doVaultImport');
  const accept = dlg.match(/inp\.accept = '([^']+)'/)[1];
  const intro = dlg.match(/intro\.textContent = '([^']+)'/)[1];
  const paste = dlg.match(/pasteLbl\.textContent = '([^']+)'/)[1];
  // The census: one appendOpmlSubtrees call per format the door can take. A fifth format adds a fifth
  // call and fails here until it joins the table below -- the ratchet that catches the NEXT omission.
  const appends = nonEmpty([...di.matchAll(/appendOpmlSubtrees\(/g)], 'format branches in doImport');
  const family = [
    { ext: '.opml', word: 'opml' },
    { ext: '.bib', word: 'BibTeX' },
    { ext: '.csv', word: 'spreadsheet' },
    { ext: '.md', word: 'Markdown' },
  ];
  assert.equal(appends.length, family.length,
    'one append per format; add a format, add it to this census (P2: a door nobody is told about is syntax-only)');
  for (const f of family) {
    assert.ok(accept.includes(f.ext), `the file picker accepts ${f.ext}`);
    assert.ok(intro.includes(f.word), `the dialog intro names ${f.word}`);
    assert.ok(paste.includes(f.word) || paste.includes(f.ext), `the paste label names ${f.word}`);
  }
});

// ── The proposal-status drift guard: a doc marked Proposed whose work already shipped ──────
// Two sessions running picked their "next" task off a status column that lied. #1265 (Markdown +
// vault + spreadsheet import) and #1243 (contested rolls + the session seed) were both marked
// Proposed while fully shipped AND pinned, so an agent read the backlog and set out to rebuild
// finished work. The status column IS the backlog, and nothing checked it against the tree.
//
// The signal is the cheapest one that separates the two cases: a doc marked Proposed whose SOURCE
// ISSUE already has passing tests. Measured before this was written rather than assumed -- it fires
// on 4 of the 5 currently-Proposed docs, and every one checked was a TRUE positive (#1267's pattern
// palette is live in the Builder; #1353's phases 1-3, #1240's builder machinery and #1268's save
// chip all have shipped tests). So this is drift, not noise.
//
// It deliberately does NOT decide shipped-vs-proposed: that is a judgement call and the owner's.
// It forces the ambiguity to be WRITTEN DOWN in the doc, where the next agent picking work will
// actually read it. The census runs BOTH ways -- a new drifting doc fails until someone looks, and
// an entry that stopped drifting (re-statused, or its tests went away) fails until it is removed --
// so the registry cannot rot into a permanent waiver list.
const _claudeMd  = readFileSync(new URL('../CLAUDE.md', import.meta.url), 'utf8');
const _suiteSelf = readFileSync(new URL('./test.mjs', import.meta.url), 'utf8');

// Every issue number named in a test TITLE, with how many tests name it.
const _testedIssues = (() => {
  const out = new Map();
  for (const m of _suiteSelf.matchAll(/test\(\s*(['"`])([\s\S]*?)\1/g)) {
    for (const n of new Set([...m[2].matchAll(/#(\d+)/g)].map(x => x[1]))) {
      out.set(n, (out.get(n) || 0) + 1);
    }
  }
  return out;
})();

// Docs the always-loaded CLAUDE.md table marks Proposed, paired with the issues their header names
// that ALREADY have tests. The header window is where a proposal states the issue it tracks.
// Every doc row in the CLAUDE.md "Where to find things" table, whatever its status. This is the
// parser's own liveness check: bind non-vacuity HERE rather than to the drift set, because an empty
// drift set is the GOAL, and a guard that fails when the drift is finally cleaned would just teach
// the next person to delete it.
const _tableRows = [..._claudeMd.matchAll(/^\|\s*.+?\s*\|\s*`(guidance\/[^`]+)`\s*\|\s*(\w[\w ]*?)\s*\|/gm)]
  .map(m => ({ doc: m[1], status: m[2].trim() }));

const _driftingProposals = (() => {
  const out = new Map();
  for (const m of _claudeMd.matchAll(/^\|\s*.+?\s*\|\s*`(guidance\/[^`]+)`\s*\|\s*Proposed\s*\|/gm)) {
    const rel = m[1];
    let doc;
    try { doc = readFileSync(new URL('../' + rel, import.meta.url), 'utf8'); } catch { continue; }
    const issues = [...new Set([...doc.slice(0, 1200).matchAll(/#(\d+)/g)].map(x => x[1]))];
    const shipped = issues.filter(i => _testedIssues.has(i)).map(i => `#${i} (${_testedIssues.get(i)} tests)`);
    if (shipped.length) out.set(rel, shipped);
  }
  return out;
})();

// The census. Every entry is a doc whose status says "not built yet" while the suite already tests
// the issue it tracks. Each MUST carry a "Shipped so far:" line naming what landed.
// Empty, and that is the point: every doc it held was audited against its own acceptance criteria
// and re-statused Shipped (#1353 says so in its own body; #1267's Patterns section, #1240's phases
// 0-4 and all four of #1268's items are live in index.html). An entry here is a KNOWN, WRITTEN-DOWN
// exception, never a parking space -- and the census below fails if one is added without cause.
const PROPOSED_WITH_SHIPPED_TESTS = new Set([]);

test('#1265/#1243 status drift — a Proposed doc whose issue already has tests is declared, not silent', () => {
  // Non-vacuity binds to the SCANNERS, never to the drift set. An empty drift set is the goal, so
  // asserting on it would fail the day the backlog is finally honest. What must never be empty is
  // the machinery: if the table stops parsing (a renamed column, a reshaped table) or no test title
  // names an issue, this guard has quietly stopped looking and would pass forever on nothing.
  nonEmpty(_testedIssues, 'issue numbers named in test titles');
  nonEmpty(_tableRows, 'doc rows parsed from the CLAUDE.md table');
  assert.ok(_tableRows.some(r => /^(Proposed|Shipped)$/.test(r.status)),
    'the table parses no Proposed/Shipped row, so the status column this guard reads has changed shape');

  const live = [..._driftingProposals.keys()].sort();
  const declared = [...PROPOSED_WITH_SHIPPED_TESTS].sort();

  const undeclared = live.filter(d => !PROPOSED_WITH_SHIPPED_TESTS.has(d));
  assert.deepEqual(undeclared, [],
    'a doc is marked Proposed but the suite already tests the issue it tracks — either it shipped ' +
    'and the status is stale (this is what sent two sessions to rebuild #1265 and #1243), or the ' +
    'tests belong to a different phase. Decide which, then add it to PROPOSED_WITH_SHIPPED_TESTS ' +
    'with a "Shipped so far:" line in the doc. Evidence: ' +
    JSON.stringify(Object.fromEntries(_driftingProposals)));

  const stale = declared.filter(d => !_driftingProposals.has(d));
  assert.deepEqual(stale, [],
    'a declared entry no longer drifts (it was re-statused, or its tests went away) — remove it, ' +
    'so this census stays a live list rather than a permanent waiver');
});

test('#1265/#1243 status drift — each declared doc SAYS what already shipped, where the next agent reads it', () => {
  // No nonEmpty() here, deliberately. An empty census is the goal state, and the test above already
  // proves the census EQUALS the live drift set -- so "nothing to check" is a PROVEN nothing, not an
  // unnoticed one. Re-adding a non-vacuity assert here would fail the day the backlog goes honest.
  for (const rel of [...PROPOSED_WITH_SHIPPED_TESTS]) {
    const doc = readFileSync(new URL('../' + rel, import.meta.url), 'utf8');
    const m = doc.match(/\*\*Shipped so far:\*\*\s*(.+)/);
    assert.ok(m, `${rel} is Proposed while its issue already has tests, so it must carry a ` +
      '"**Shipped so far:**" line naming what landed. A status column that lies is the whole defect.');
    assert.ok(/#\d+/.test(m[1]), `${rel}: the "Shipped so far" line must name the issue it is talking about`);
    // it belongs at the TOP, not buried: someone skimming to pick work must hit it
    assert.ok(doc.indexOf(m[0]) < 900,
      `${rel}: the "Shipped so far" line is too far down to be seen by someone skimming for work`);
  }
});

// ── #1267: snippet / pattern palette (ready-to-use {…} recipes in the Builder) ──────
// PATTERN_RECIPES is pure data (not a function), so it is parsed straight out of the source rather
// than loaded as a core. The array runs from its declaration to the next const.
const _PATTERN_RECIPES = (() => {
  const m = _src.match(/const PATTERN_RECIPES = (\[[\s\S]*?\n\]);\nconst INSERT_CMDS/);
  return m ? (new Function('return ' + m[1]))() : null;
})();
test('#1267 PATTERN_RECIPES — every recipe is well-formed, unique, and em-dash-free', () => {
  const R = _PATTERN_RECIPES;
  assert.ok(Array.isArray(R) && R.length >= 8, 'a real set of recipes ships');
  const ids = new Set();
  for (const r of R) {
    assert.ok(r.id && r.label && r.desc, `${r.id}: has id/label/desc`);
    assert.ok(Array.isArray(r.keys) && r.keys.length, `${r.id}: carries search synonyms`);
    assert.ok(!ids.has(r.id), `${r.id}: unique id`); ids.add(r.id);
    assert.ok(!!r.line !== !!r.block, `${r.id}: is exactly one of line/block`);
    if (r.block) {
      assert.ok(r.block.parent && Array.isArray(r.block.rows) && r.block.rows.length >= 2,
        `${r.id}: a block has a parent pill over >=2 worked rows`);
    }
    const blob = JSON.stringify(r);
    assert.ok(!blob.includes('—'), `${r.id}: no em dash`);
  }
});

test('#1267 PATTERN_RECIPES — a {roll: #tag} recipe carries its own tag (never lands reading "no match")', () => {
  // the #1107 drift-guard shape, applied to the recipe set: a roll must have its table with it.
  for (const r of nonEmpty(_PATTERN_RECIPES, 'PATTERN_RECIPES')) {
    const text = r.line || (r.block && r.block.parent) || '';
    const m = text.match(/\{roll:\s*(#[\w-]+)/);
    if (!m) continue;
    const tag = m[1];
    const rows = (r.block && r.block.rows) || [];
    assert.ok(rows.some(row => (row.text || '').includes(tag)),
      `${r.id}: the ${tag} table ships in the recipe's own rows`);
  }
});

test('#1267 block recipes are HONEST — the rollup/scoped/check rows compute a real, non-zero result', () => {
  // Prove the "nothing lands reading 0 / no match yet" promise from the numbers in the rows, without
  // the render engine: each computational block references a prop its rows actually carry, and the sum
  // is > 0 (and satisfies the check where present).
  const sumProp = (rows, prop) => rows.reduce((a, row) => {
    const p = (row.props || []).find(x => x.key === prop); return a + (p ? Number(p.val) : 0);
  }, 0);
  const byId = Object.fromEntries(nonEmpty(_PATTERN_RECIPES, 'PATTERN_RECIPES').map(r => [r.id, r]));
  assert.equal(sumProp(byId['pat-sum'].block.rows, 'gold'), 16, 'Party gold sums to 16, not 0');
  assert.equal(sumProp(byId['pat-scoped'].block.rows, 'cost'), 65, 'the scoped total sums the tagged rows');
  assert.ok(byId['pat-scoped'].block.rows.every(r => r.text.includes('#thismonth')), 'every scoped row carries the query tag');
  const spent = sumProp(byId['pat-check'].block.rows, 'cost');
  assert.ok(spent > 0 && spent <= 100, `the check passes on arrival (spent ${spent} <= 100)`);
  assert.ok(byId['pat-check'].block.check.includes('<= 100'), 'the check is a real constraint prop');
});

test('#1267 recipeToNodes — a line drops one point; a block drops a parent over prop-carrying rows', () => {
  const line = c.recipeToNodes({ id:'x', line:'Damage {2d6}' });
  assert.equal(line.length, 1); assert.equal(line[0].text, 'Damage {2d6}');
  assert.equal((line[0].children || []).length, 0, 'a line recipe has no children');
  const block = c.recipeToNodes({ id:'y', block:{ parent:'T {= sum(cost)}', check:'sum(cost) <= 100', rows:[ { text:'A', props:[{ key:'cost', val:'60' }] }, { text:'B', props:[{ key:'cost', val:'25' }] } ] } });
  assert.equal(block.length, 1);
  assert.equal(block[0].children.length, 2, 'the two worked rows nest under the parent');
  assert.equal(block[0].children[0].props[0].key, 'cost', 'row props are carried onto the node');
  const chk = (block[0].props || []).find(p => p.key === 'check');
  assert.ok(chk && chk.val === 'sum(cost) <= 100', 'the check becomes a real check prop on the parent');
});

