test('searchWorkspace — flags .capped when the result set hits the cap (UXP-146)', () => {
  // a doc of N matching points under one other doc; current doc is excluded
  const mkDoc = (n) => ({ id: 'r', children: Array.from({ length: n }, (_, i) => ({ id: 'n' + i, text: 'apple ' + i, children: [] })) });
  const index = { roots: new Map([['other', mkDoc(60)]]), nameByDocId: new Map([['other', 'Other']]) };
  // read the raw return (not host()/JSON-normalized — that would drop the array's .capped property)
  const capped = c.searchWorkspace('apple', index, 'current', 50);
  assert.equal(capped.length, 50, 'stops at the cap');
  assert.equal(capped.capped, true, 'signals truncation');
  // under the cap → no flag
  const small = { roots: new Map([['other', mkDoc(5)]]), nameByDocId: new Map([['other', 'Other']]) };
  const few = c.searchWorkspace('apple', small, 'current', 50);
  assert.equal(few.length, 5);
  assert.ok(!few.capped, 'no truncation flag under the cap');
});

test('termMatchesNode — a quoted prop matches by contains; bare matches exact', () => {
  const node = { props: [{ key: 'area', val: 'Home Renovation' }] };
  // quoted: contains a substring
  assert.equal(c.termMatchesNode({ kind: 'prop', key: 'area', value: 'renovation', contains: true }, node, SEQS), true);
  // bare exact: a substring does NOT match
  assert.equal(c.termMatchesNode({ kind: 'prop', key: 'area', value: 'renovation' }, node, SEQS), false);
  // bare exact: the full (lowercased) value DOES match
  assert.equal(c.termMatchesNode({ kind: 'prop', key: 'area', value: 'home renovation' }, node, SEQS), true);
});

// ── QX-1: is:/has: structural + artifact + symmetry filters ───────────────
const isM = (val, node) => c.termMatchesNode({ kind: 'is', value: val }, node, SEQS);
const hasM = (val, node) => c.termMatchesNode({ kind: 'has', value: val }, node, SEQS);

test('QX-1 parseSearchQuery — the new is: verbs tokenize as is: terms, not text', () => {
  for (const v of ['passing', 'pill', 'random', 'leaf', 'parent', 'collapsed', 'expanded']) {
    const t = host(c.parseSearchQuery('is:' + v))[0];
    assert.equal(t.kind, 'is', v);
    assert.equal(t.value, v, v);
  }
  // an unknown is: verb is an invalid term: `is:` is reserved, so there is nothing else it could
  // have meant. A BARE `is:` is still text — half-typed is incomplete, not wrong.
  assert.equal(host(c.parseSearchQuery('is:banana'))[0].kind, 'invalid');
  assert.equal(host(c.parseSearchQuery('is:'))[0].kind, 'text');
});

test('QX-1 is:passing / is:leaf / is:parent / is:collapsed / is:expanded', () => {
  // is:passing requires an actual passing check; distinct from -is:failing
  const passing = { text: '', props: [{ key: 'check', val: '1 < 2' }] };
  const failing = { text: '', props: [{ key: 'check', val: '2 < 1' }] };
  const noCheck = { text: 'plain' };
  assert.equal(isM('passing', passing), true);
  assert.equal(isM('passing', failing), false);
  assert.equal(isM('passing', noCheck), false);            // check-less is NOT passing
  assert.equal(isM('failing', noCheck), false);            // ...nor failing: so -is:failing != is:passing
  // structure
  const leaf = { text: 'x', children: [] };
  const parent = { text: 'x', children: [{ id: '1' }] };
  assert.equal(isM('leaf', leaf), true);
  assert.equal(isM('parent', leaf), false);
  assert.equal(isM('leaf', parent), false);
  assert.equal(isM('parent', parent), true);
  // fold state
  assert.equal(isM('collapsed', { text: 'x', collapsed: true }), true);
  assert.equal(isM('expanded', { text: 'x', collapsed: true }), false);
  assert.equal(isM('expanded', { text: 'x', collapsed: false }), true);
  assert.equal(isM('expanded', { text: 'x' }), true);      // undefined collapsed reads as expanded
});

test('QX-1 is:pill and is:random over the sidecar arrays', () => {
  const bare = { text: 'x' };
  assert.equal(isM('pill', bare), false);
  assert.equal(isM('random', bare), false);
  for (const k of ['dice', 'markov', 'math', 'grammar', 'est', 'vars', 'seq']) {
    const n = { text: 'x', [k]: [{ key: 'a' }] };
    assert.equal(isM('pill', n), true, 'pill sees ' + k);
  }
  // random is the generative subset: dice/markov/grammar/est, plus a pick var
  assert.equal(isM('random', { text: 'x', dice: [{ key: 'a' }] }), true);
  assert.equal(isM('random', { text: 'x', grammar: [{ key: 'a' }] }), true);
  assert.equal(isM('random', { text: 'x', math: [{ key: 'a' }] }), false);   // static math excluded
  assert.equal(isM('random', { text: 'x', vars: [{ key: 'a', kind: 'formula' }] }), false); // display-only var excluded
  assert.equal(isM('random', { text: 'x', vars: [{ key: 'a', kind: 'pick' }] }), true);     // a pick var IS random
});

test('QX-1 has:<sidecar> and has:children / has:footnote, with props fall-through', () => {
  assert.equal(hasM('dice', { dice: [{ key: 'a' }] }), true);
  assert.equal(hasM('var', { vars: [{ key: 'a' }] }), true);   // token 'var' -> field 'vars'
  assert.equal(hasM('seq', { seq: [{ key: 'a' }] }), true);
  assert.equal(hasM('dice', { dice: [] }), false);             // empty sidecar
  assert.equal(hasM('children', { children: [{ id: '1' }] }), true);
  assert.equal(hasM('children', { children: [] }), false);
  // "has a footnote" now means a marker whose source is WRITTEN, not merely present. The harness root
  // has no store, so a bare marker no longer qualifies; the written-source path is covered just below.
  assert.equal(hasM('footnote', { text: 'a claim with a ref[^a]' }), false);   // marker present but source unwritten (empty store) → not a footnote
  assert.equal(hasM('footnote', { text: 'no footnote here' }), false);
  // the has:<propkey> contract survives: a user property keyed 'dice' still matches
  // (empty sidecar, so the fall-through property scan runs)
  assert.equal(hasM('dice', { dice: [], props: [{ key: 'dice', val: 'yes' }] }), true);
  // and a plain property still matches as before
  assert.equal(hasM('owner', { props: [{ key: 'owner', val: 'zeo' }] }), true);
  assert.equal(hasM('owner', { props: [] }), false);
});

test('has:footnote requires a WRITTEN source, so a sourcing check catches an unwritten [^x]', () => {
  // the fix: has:footnote = getFnRefs(node.text).some(id => fnIsWritten(root.footnotes, id)). Test that
  // composition against an explicit store (a written one, a blank one, and a dangling ref), then pin the
  // wiring in termMatchesNode. So `count("#claim -has:footnote") == 0` (research-notes) stays red until a
  // claim's marker actually has a written source, not just a bracket.
  const store = [{ id: 'a', text: 'Ives 2020, p.4' }, { id: 'b', text: '   ' }];
  assert.ok(c.getFnRefs('a claim[^a] and[^b]').length === 2, 'getFnRefs pulls each distinct marker');
  const written = text => c.getFnRefs(text).some(id => c.fnIsWritten(store, id));
  assert.equal(written('a claim[^a]'), true,  'a marker with a written source qualifies');
  assert.equal(written('a claim[^b]'), false, 'a marker whose source is blank does NOT');
  assert.equal(written('a claim[^ghost]'), false, 'a dangling marker (no store entry) does NOT');
  assert.match(_src, /getFnRefs\(node\.text\)\.some\(id => fnIsWritten\(root\.footnotes, id\)\)/,
    'has:footnote wires the written-source requirement, not mere marker presence');
});

// ── QX-2/147: relative date windows + var: declaration lookup ─────────────
test('QX-2 parseSearchQuery — due:week/month become op:window; < / > and bad values unaffected', () => {
  const today = c.dueDateToday();
  const wk = host(c.parseSearchQuery('due:week'))[0];
  assert.equal(wk.kind, 'due'); assert.equal(wk.op, 'window'); assert.equal(wk.epochDay, today + 7);
  const mo = host(c.parseSearchQuery('start:month'))[0];
  assert.equal(mo.kind, 'start'); assert.equal(mo.op, 'window'); assert.equal(mo.epochDay, today + 30);
  // an explicit bound is NOT a window (< / > keep their compare meaning). `<week` therefore names
  // nothing the parser can read, and UXP-233 stopped that laundering into a literal text search:
  // it is an invalid term now, so it matches nothing honestly and explains itself.
  assert.equal(host(c.parseSearchQuery('due:<week'))[0].kind, 'invalid');
  assert.equal(host(c.parseSearchQuery('due:<week'))[0].field, 'due');
  // the value KEEPS the bound: dateStillTyping needs it to know `<week` is final, and the message
  // should echo what was typed rather than a version with the bound quietly removed
  assert.equal(host(c.parseSearchQuery('due:<week'))[0].value, '<week');
  // overdue still wins
  assert.equal(host(c.parseSearchQuery('due:overdue'))[0].op, 'overdue');
});

test('QX-2 termMatchesNode — due:week matches today..today+7 inclusive, not before/after', () => {
  const today = c.dueDateToday();
  const iso = ep => c.formatEpochDays(ep);
  const dueTerm = host(c.parseSearchQuery('due:week'))[0];
  const node = d => ({ props: [{ key: 'due', val: iso(d) }] });
  assert.equal(c.termMatchesNode(dueTerm, node(today), SEQS), true);       // today: in
  assert.equal(c.termMatchesNode(dueTerm, node(today + 7), SEQS), true);    // +7: inclusive end
  assert.equal(c.termMatchesNode(dueTerm, node(today + 8), SEQS), false);   // +8: past the window
  assert.equal(c.termMatchesNode(dueTerm, node(today - 1), SEQS), false);   // yesterday: before today
  assert.equal(c.termMatchesNode(dueTerm, { props: [] }, SEQS), false);     // undated
  // start:month over the start key
  const startTerm = host(c.parseSearchQuery('start:month'))[0];
  assert.equal(c.termMatchesNode(startTerm, { props: [{ key: 'start', val: iso(today + 30) }] }, SEQS), true);
  assert.equal(c.termMatchesNode(startTerm, { props: [{ key: 'start', val: iso(today + 31) }] }, SEQS), false);
});

test('QX-3 var:NAME parses and matches the DECLARING point, not a reference pill', () => {
  const t = host(c.parseSearchQuery('var:strength'))[0];
  assert.equal(t.kind, 'var'); assert.equal(t.value, 'strength');
  const varM = (name, node) => c.termMatchesNode({ kind: 'var', value: name }, node, SEQS);
  // a declaration has a truthy expr
  assert.equal(varM('strength', { vars: [{ name: 'strength', expr: '10' }] }), true);
  assert.equal(varM('strength', { vars: [{ name: 'Strength', expr: 'pi*r' }] }), true);   // case-insensitive
  // a display-only reference pill has an empty expr, so it does NOT match
  assert.equal(varM('strength', { vars: [{ name: 'strength', expr: '' }] }), false);
  assert.equal(varM('strength', { vars: [] }), false);
  assert.equal(varM('other', { vars: [{ name: 'strength', expr: '10' }] }), false);
});

// ── QX-4: numeric comparison on properties (the real parser extension) ────
test('QX-4 parseSearchQuery — key:>N parses to propnum; longest-match >= over >; signs and decimals', () => {
  const p = q => host(c.parseSearchQuery(q))[0];
  let t = p('cost:>100');
  assert.equal(t.kind, 'propnum'); assert.equal(t.key, 'cost'); assert.equal(t.op, '>'); assert.equal(t.num, 100);
  t = p('cost:>=100'); assert.equal(t.op, '>=');    // >= wins longest-match, NOT '>' + text '=100'
  t = p('score:<=3.5'); assert.equal(t.op, '<='); assert.equal(t.num, 3.5);
  t = p('temp:<-4');    assert.equal(t.op, '<'); assert.equal(t.num, -4);   // signed
  // is: is never a numeric prop key. It is not text either: `is:` is reserved, so `is:>1` is a
  // rejected is: value that says so, rather than a literal search for the string "is:>1".
  assert.equal(p('is:>1').kind, 'invalid');
  // a non-numeric value is NOT propnum: it stays the exact key:value (bare) or text
  assert.equal(p('cost:high').kind, 'prop');
  assert.equal(p('cost:>high').kind, 'text');   // op but no number → falls through to literal text
});

test('QX-4 termMatchesNode — numeric compare, with non-numeric and date values rejected', () => {
  const m = (q, props) => c.termMatchesNode(host(c.parseSearchQuery(q))[0], { props }, SEQS);
  assert.equal(m('cost:>100', [{ key: 'cost', val: '150' }]), true);
  assert.equal(m('cost:>100', [{ key: 'cost', val: '100' }]), false);   // strict >
  assert.equal(m('cost:>=100', [{ key: 'cost', val: '100' }]), true);   // inclusive
  assert.equal(m('cost:<=100', [{ key: 'cost', val: '100' }]), true);
  assert.equal(m('cost:<100', [{ key: 'cost', val: '99.5' }]), true);   // decimal value
  // a non-numeric property value never matches (no throw, no NaN compare)
  assert.equal(m('cost:>100', [{ key: 'cost', val: 'soon' }]), false);
  assert.equal(m('cost:>100', [{ key: 'cost', val: '' }]), false);
  // a date-shaped value on an arbitrary key is NOT numeric here (dates belong to due:/start:);
  // use a non-date key so the propnum arm handles it (due:/start: have their own date arm).
  assert.equal(m('deadline:>100', [{ key: 'deadline', val: '2026-06-13' }]), false);
  // a missing property never matches
  assert.equal(m('cost:>100', [{ key: 'weight', val: '200' }]), false);
  assert.equal(m('cost:>100', []), false);
  // negation composes (a point whose cost is NOT > 100)
  const neg = c.parseSearchQuery('-cost:>100');
  assert.equal(c.queryMatchesNode(host(neg), { props: [{ key: 'cost', val: '50' }] }, SEQS), true);
  assert.equal(c.queryMatchesNode(host(neg), { props: [{ key: 'cost', val: '150' }] }, SEQS), false);
});

// ── QX-5: OR disjunction (standalone `|` splits AND-clauses) ─────────────────
test('QX-5 parseSearchQuery — a standalone | is an or marker; glued/negated/quoted stay literal', () => {
  const kinds = q => host(c.parseSearchQuery(q)).map(t => t.kind);
  assert.deepEqual(kinds('a | b'), ['text', 'or', 'text']);
  assert.deepEqual(kinds('a |b'), ['text', 'text']);       // glued: '|b' is literal text
  assert.deepEqual(kinds('a| b'), ['text', 'text']);       // glued the other way
  assert.deepEqual(kinds('-| a'), ['text', 'text']);       // negated pipe is literal
  assert.deepEqual(kinds('"|"'), ['text']);                 // quoted pipe is the literal escape
});

test('QX-5 queryMatchesNode — OR of clauses, AND binds tighter, negation inside a clause', () => {
  const seqs = SEQS;
  const q = s => host(c.parseSearchQuery(s));
  const todo = { text: '#TODO write intro' };
  const done = { text: '#DONE ship draft' };
  const plain = { text: 'grocery list' };
  // simple OR
  assert.equal(c.queryMatchesNode(q('is:todo | is:done'), todo, seqs), true);
  assert.equal(c.queryMatchesNode(q('is:todo | is:done'), done, seqs), true);
  assert.equal(c.queryMatchesNode(q('is:todo | is:done'), plain, seqs), false);
  // AND binds tighter: (write AND is:todo) OR ship
  assert.equal(c.queryMatchesNode(q('write is:todo | ship'), todo, seqs), true);   // left clause
  assert.equal(c.queryMatchesNode(q('write is:todo | ship'), done, seqs), true);   // right clause
  assert.equal(c.queryMatchesNode(q('write is:todo | ship'), plain, seqs), false);
  // the left clause requires BOTH its terms
  assert.equal(c.queryMatchesNode(q('write is:done | ship'), todo, seqs), false);
  // negation stays clause-local: (-is:done AND intro) OR grocery
  assert.equal(c.queryMatchesNode(q('-is:done intro | grocery'), todo, seqs), true);
  assert.equal(c.queryMatchesNode(q('-is:done intro | grocery'), plain, seqs), true);
  assert.equal(c.queryMatchesNode(q('-is:done intro | grocery'), done, seqs), false);
});

test('QX-5 empty clauses are dropped, never auto-true (a stray pipe cannot match everything)', () => {
  const seqs = SEQS;
  const q = s => host(c.parseSearchQuery(s));
  const node = { text: 'anything at all' };
  assert.equal(c.queryMatchesNode(q('|'), node, seqs), false);          // only a pipe: no live clause
  assert.equal(c.queryMatchesNode(q('| |'), node, seqs), false);
  assert.equal(c.queryMatchesNode(q('zzz |'), node, seqs), false);      // trailing pipe: empty clause dropped
  assert.equal(c.queryMatchesNode(q('| zzz'), node, seqs), false);      // leading pipe likewise
  assert.equal(c.queryMatchesNode(q('anything |'), node, seqs), true);  // the live clause still matches
  assert.equal(c.queryMatchesNode(q('zzz | | anything'), node, seqs), true); // doubled pipe: middle empty dropped
});

test('QX-5 searchHighlightNeedles ignores or markers and collects across clauses', () => {
  const needles = host(c.searchHighlightNeedles(host(c.parseSearchQuery('alpha | #beta -gamma'))));
  assert.deepEqual(needles, ['alpha', '#beta']);
});

// ── query pill: the pure queryRows core (shared with the future base view) ──
test('queryRows — matches across the tree, excludes the host, caps with a total', () => {
  const root = { children: [
    { id: 'h1', text: '#TODO alpha', children: [
      { id: 'c1', text: '#TODO nested one', children: [] },
      { id: 'c2', text: '#DONE nested two', children: [] },
    ] },
    { id: 'h2', text: '#TODO beta', children: [] },
  ] };
  const r = host(c.queryRows('is:todo', root, 'host-not-present'));
  assert.deepEqual(r.rows.map(x => x.id).sort(), ['c1', 'h1', 'h2']);   // three open to-dos, done excluded
  assert.equal(r.total, 3);
  assert.equal(r.truncated, false);
  // titles are stripped display text
  assert.equal(r.rows.find(x => x.id === 'h1').title, 'alpha');
  // the host point is excluded even when it matches
  const r2 = host(c.queryRows('is:todo', root, 'h1'));
  assert.equal(r2.rows.find(x => x.id === 'h1'), undefined);
  assert.equal(r2.total, 2);
});

test('resolveSearchExpr / queryRows — a dynamic {var} argument resolves before the search (compose edge)', () => {
  const root = { children: [
    { id: 'v', text: '[[var:k1]]', vars: [{ key: 'k1', name: 'state', kind: 'pick', rolled: 'todo', expr: '"todo"' }], children: [] },
    { id: 'h1', text: '#TODO alpha', children: [] },
    { id: 'h2', text: '#DONE beta', children: [] },
  ] };
  // the search arg is a {var}: it resolves to "todo" and then filters exactly like the literal is:todo
  assert.equal(c.resolveSearchExpr('is:{state}', root), 'is:todo');
  const r = host(c.queryRows('is:{state}', root, 'host'));
  assert.deepEqual(r.rows.map(x => x.id), ['h1'], 'the dynamic query matches the same points as is:todo');
  // a literal expr (no braces) is returned untouched — the search box path is never expanded
  assert.equal(c.resolveSearchExpr('is:todo', root), 'is:todo');
  assert.equal(c.resolveSearchExpr('', root), '');
  // an undefined var leaves a visible marker (never silently matches everything)
  assert.match(c.resolveSearchExpr('is:{missing}', root), /\{missing\?\}/);
});

test('queryRows — an empty or whitespace query returns nothing (never matches everything)', () => {
  const root = { children: [{ id: 'a', text: 'x', children: [] }] };
  assert.deepEqual(host(c.queryRows('', root, null)), { rows: [], total: 0, truncated: false });
  assert.deepEqual(host(c.queryRows('   ', root, null)), { rows: [], total: 0, truncated: false });
});

test('queryRows — caps the row slice but reports the true total (truncated flag)', () => {
  const kids = [];
  for (let i = 0; i < 15; i++) kids.push({ id: 'k' + i, text: '#TODO item ' + i, children: [] });
  const root = { children: kids };
  const r = host(c.queryRows('is:todo', root, null, 10));
  assert.equal(r.rows.length, 10);
  assert.equal(r.total, 15);
  assert.equal(r.truncated, true);
});

test('queryRows — the full operator grammar composes (OR, negation, dates)', () => {
  const root = { children: [
    { id: 'a', text: '#TODO write', props: [{ key: 'due', val: '2000-01-01' }], children: [] },   // overdue
    { id: 'b', text: '#TODO plan', children: [] },
    { id: 'd', text: '#DONE ship', children: [] },
  ] };
  // is:overdue | is:todo -is:done → a (overdue) and b (open todo), not d
  const r = host(c.queryRows('is:overdue | is:todo -is:done', root, null));
  assert.deepEqual(r.rows.map(x => x.id).sort(), ['a', 'b']);
});

test('queryParts — sniffs {query: expr}, rejects the empty and keywordless forms', () => {
  assert.deepEqual(host(c.queryParts('query: is:todo | due:week')), { expr: 'is:todo | due:week' });
  assert.deepEqual(host(c.queryParts('query:#idea -is:done')), { expr: '#idea -is:done' });
  assert.equal(c.queryParts('query:'), null);        // no search string
  assert.equal(c.queryParts('query:   '), null);     // whitespace only
  assert.equal(c.queryParts('is:todo'), null);       // no keyword
  assert.equal(c.queryParts('querylike: x'), null);  // the keyword must be exactly 'query'
  // classifyBraceBody routes it to an artifact so exit-promotion fires
  assert.equal(c.classifyBraceBody('query: is:todo', [], {}), 'artifact');
});

// ── {count: query} — the query family's third verb (#541) ───────────────────
test('countParts — sniffs {count: expr}, rejects the empty and keywordless forms', () => {
  assert.deepEqual(host(c.countParts('count: is:todo | due:week')), { expr: 'is:todo | due:week' });
  assert.deepEqual(host(c.countParts('count:#thread is:todo')), { expr: '#thread is:todo' });
  assert.equal(c.countParts('count:'), null);         // no search string
  assert.equal(c.countParts('count:   '), null);      // whitespace only
  assert.equal(c.countParts('is:todo'), null);        // no keyword
  assert.equal(c.countParts('counter: x'), null);     // the keyword must be exactly 'count'
  // classify + typeLabel agree: valid artifact, labeled as the query family's count form
  assert.equal(c.classifyBraceBody('count: is:todo', [], {}), 'artifact');
  assert.deepEqual(host(c.braceTypeLabel('count: is:todo', [], {})), ['query', 'count']);
});

test('promoteBraceBody — {count:} builds a query record with show:count; unfolds to its own verb (#541)', () => {
  const node = { text: '', query: [] };
  const tok = c.promoteBraceBody(node, 'count: is:todo');
  assert.match(tok, /^\[\[query:/, 'a {count:} promotes to a QUERY pill (same sidecar)');
  assert.equal(node.query[0].expr, 'is:todo');
  assert.equal(node.query[0].show, 'count');
  // the unfold source round-trips the verb, so an edit re-promotes to the same form
  assert.equal(c.artifactToShorthand('query', node.query[0]), '{count: is:todo}');
  // a plain query record still unfolds to {query: …}, untouched
  assert.equal(c.artifactToShorthand('query', { key: 'q1', expr: 'is:todo' }), '{query: is:todo}');
});

test('queryRows — total counts every match even when the row cap clips the list (#541 reads .total)', () => {
  const tree = { id: 'r', text: '', children: [
    { id: 'a', text: '- [ ] one', children: [] },
    { id: 'b', text: '- [ ] two', children: [] },
    { id: 'c', text: '- [ ] three', children: [] },
    { id: 'd', text: 'done already', children: [] },
  ] };
  const { total, rows } = c.queryRows('is:todo', tree, null, 1);
  assert.equal(total, 3, 'total is the real count');
  assert.equal(rows.length, 1, 'the cap only clips the rows');
  assert.equal(c.queryRows('is:todo', tree, 'a', 99).total, 2, 'the host point is excluded');
  assert.equal(c.queryRows('nomatchword', tree, null, 1).total, 0, 'zero is a valid count');
});

// ── QX-6: link/tag presence filters (has:link/tag pure; has:backlink/is:broken threaded) ──
test('QX-6 has:link and has:tag are pure node reads with the props fall-through intact', () => {
  const hasM = (val, node) => c.termMatchesNode({ kind: 'has', value: val }, node, SEQS);
  // links: same-doc plain, labeled, mirror, and cross-doc forms all count
  assert.equal(hasM('link', { text: 'see [[#abc12]]' }), true);
  assert.equal(hasM('link', { text: 'see [[#abc12|the intro]]' }), true);
  assert.equal(hasM('link', { text: 'mirror [[#abc12|]]' }), true);
  assert.equal(hasM('link', { text: 'cross [[docaa#abc12|x]]' }), true);
  assert.equal(hasM('link', { text: 'a footnote [^k] is not a link' }), false);
  assert.equal(hasM('link', { text: 'plain text' }), false);
  // tags: any sigil counts, including hashtag-shaped state keywords; link targets never read as tags
  assert.equal(hasM('tag', { text: 'an #idea here' }), true);
  assert.equal(hasM('tag', { text: '#TODO write it' }), true);
  assert.equal(hasM('tag', { text: 'only a link [[#abc12]]' }), false);
  assert.equal(hasM('tag', { text: 'code#notatag' }), false);   // word-anchored, mirrors the #tag matcher
  assert.equal(hasM('tag', { text: 'plain' }), false);
  // the has:<propkey> contract: a real property keyed link/tag still matches
  assert.equal(hasM('link', { text: 'plain', props: [{ key: 'link', val: 'y' }] }), true);
  assert.equal(hasM('tag', { text: 'plain', props: [{ key: 'tag', val: 'y' }] }), true);
});

test('QX-6 has:backlink and is:broken read the threaded collectLinks index', () => {
  // A links to B (live) and to a dead id; B is linked-to; C stands alone.
  const root = { children: [
    { id: 'aaa11', text: 'see [[#bbb22]] and [[#dead9]]', children: [] },
    { id: 'bbb22', text: 'the target', children: [] },
    { id: 'ccc33', text: 'unrelated', children: [] },
  ] };
  const links = host(c.collectLinks(root));
  const A = root.children[0], B = root.children[1], C = root.children[2];
  const m = (term, node) => c.termMatchesNode(term, node, SEQS, undefined, links);
  assert.equal(m({ kind: 'has', value: 'backlink' }, B), true);    // B is linked to
  assert.equal(m({ kind: 'has', value: 'backlink' }, A), false);
  assert.equal(m({ kind: 'has', value: 'backlink' }, C), false);
  assert.equal(m({ kind: 'is', value: 'broken' }, A), true);       // A contains the dead link
  assert.equal(m({ kind: 'is', value: 'broken' }, B), false);
  assert.equal(m({ kind: 'is', value: 'broken' }, C), false);
  // parses as an is: term, and composes with OR across the QX family
  assert.equal(host(c.parseSearchQuery('is:broken'))[0].kind, 'is');
  const q = host(c.parseSearchQuery('is:broken | has:backlink'));
  assert.equal(c.queryMatchesNode(q, A, SEQS, undefined, links), true);
  assert.equal(c.queryMatchesNode(q, B, SEQS, undefined, links), true);
  assert.equal(c.queryMatchesNode(q, C, SEQS, undefined, links), false);
});

// ── QP-2 Phase A: queryTableRows, the query-base row engine ──────────────────
test('queryTableRows — projects title/property/formula per matched point', () => {
  const root = { children: [
    { id: 'aa111', text: '#TODO buy lumber', props: [{ key: 'cost', val: '40' }], children: [] },
    { id: 'bb222', text: '#TODO hire crew', props: [{ key: 'cost', val: '100' }], children: [] },
    { id: 'cc333', text: '#DONE paid deposit', props: [{ key: 'cost', val: '10' }], children: [] },
  ] };
  const cols = [{ name: 'Task', field: 'title' }, { name: 'Cost', field: 'cost' }, { name: 'Doubled', field: '= cost * 2' }];
  const r = host(c.queryTableRows('is:todo', cols, root, null));
  assert.deepEqual(r.header, ['Task', 'Cost', 'Doubled']);
  assert.equal(r.total, 2);
  assert.equal(r.truncated, false);
  // title -> a plain [[#id]] link token (live title, no sidecar; the §0.1 rule)
  assert.deepEqual(r.rows[0], { id: 'aa111', cells: ['[[#aa111]]', '40', '80'] });
  assert.deepEqual(r.rows[1].cells, ['[[#bb222]]', '100', '200']);
});

test('queryTableRows — formula columns see the row point (rollups + own props), errors are #ERR', () => {
  const root = { children: [
    { id: 'pp111', text: '#TODO project', props: [{ key: 'rate', val: '2' }], children: [
      { id: 'k1', text: 'part', props: [{ key: 'cost', val: '30' }], children: [] },
      { id: 'k2', text: 'part', props: [{ key: 'cost', val: '12' }], children: [] },
    ] },
  ] };
  const cols = [{ name: 'Total', field: '= sum(cost) * rate' }, { name: 'Bad', field: '= nosuchvar + 1' }];
  const r = host(c.queryTableRows('is:todo', cols, root, null));
  assert.deepEqual(r.rows[0].cells, ['84', '#ERR']);   // (30+12)*2; unknown ident fails visibly (P4)
});

test('queryTableRows — cap with true total, host exclusion, empty/invalid inputs', () => {
  const kids = [];
  for (let i = 0; i < 7; i++) kids.push({ id: 'n' + i, text: '#TODO item ' + i, children: [] });
  const root = { children: kids };
  const cols = [{ name: 'T', field: 'title' }];
  const capped = host(c.queryTableRows('is:todo', cols, root, null, 5));
  assert.equal(capped.rows.length, 5);
  assert.equal(capped.total, 7);
  assert.equal(capped.truncated, true);
  const excl = host(c.queryTableRows('is:todo', cols, root, 'n0'));
  assert.equal(excl.total, 6);
  assert.equal(excl.rows.find(r => r.id === 'n0'), undefined);
  // empty query or no columns -> empty result, never a crash
  assert.deepEqual(host(c.queryTableRows('', cols, root, null)).rows, []);
  assert.deepEqual(host(c.queryTableRows('is:todo', [], root, null)).rows, []);
  // a missing property projects as an empty cell
  const miss = host(c.queryTableRows('is:todo', [{ name: 'X', field: 'nope' }], root, null, 1));
  assert.deepEqual(miss.rows[0].cells, ['']);
});

test('queryTableRows — the projected model serializes as a valid pipe table', () => {
  const root = { children: [{ id: 'z9', text: '#TODO alpha | beta', props: [{ key: 'note', val: 'a|b' }], children: [] }] };
  const cols = [{ name: 'Task', field: 'title' }, { name: 'Note', field: 'note' }];
  const q = host(c.queryTableRows('is:todo', cols, root, null));
  const model = { aligns: q.header.map(() => null), rows: [q.header, ...q.rows.map(r => r.cells)] };
  const md = c.serializeTable(model);
  const back = host(c.parseTable(md));       // round-trips: pipes in values are escaped
  assert.deepEqual(back.rows[1], ['[[#z9]]', 'a|b']);
});

test('parseQBaseCols — Name: field lines, bare fields, formula colons survive', () => {
  assert.deepEqual(host(c.parseQBaseCols('Title: title\ndue\nCost: = sum(cost)')), [
    { name: 'Title', field: 'title' },
    { name: 'due', field: 'due' },
    { name: 'Cost', field: '= sum(cost)' },
  ]);
  // a bare formula line containing a ternary colon stays ONE field
  assert.deepEqual(host(c.parseQBaseCols('= cost > 2 ? 1 : 0')), [
    { name: '= cost > 2 ? 1 : 0', field: '= cost > 2 ? 1 : 0' },
  ]);
  assert.equal(c.parseQBaseCols(''), null);
  assert.equal(c.parseQBaseCols('  \n  '), null);
});

test('queryTableRows — date props compute as epoch-days in formula columns', () => {
  const root = { children: [
    { id: 'd1', text: '#TODO ship it', props: [{ key: 'due', val: '2026-07-10' }], children: [] },
  ] };
  const r = host(c.queryTableRows('is:todo', [{ name: 'D', field: '= daysuntil(due)' }], root, null));
  // daysuntil is relative to the real today, so pin the identity via date() instead
  const r2 = host(c.queryTableRows('is:todo', [{ name: 'D', field: '= due - date(2026,7,1)' }], root, null));
  assert.equal(r2.rows[0].cells[0], '9');           // 2026-07-10 minus 2026-07-01
  assert.notEqual(r.rows[0].cells[0], '#ERR');      // daysuntil(due) resolves, whatever today is
});

// ── FR-1: field roles, the role-aware cell paint ─────────────────────────────
test('mtCellHtml — status/date/number roles shape the paint; non-conforming values fall through', () => {
  const node = { colRole: ['status', 'date', 'number', null], dice: [], math: [], vars: [], grammar: [], est: [], seq: [], props: [] };
  // status: a built-in state keyword renders as its chip; DONE gets the muted done styling
  assert.match(c.mtCellHtml(node, 'TODO', 0), /todo-state todo-state-todo/);
  assert.match(c.mtCellHtml(node, 'DONE', 0), /todo-state-isdone/);
  // a non-state word in a status column falls through to the plain render (P4: never an error)
  assert.doesNotMatch(c.mtCellHtml(node, 'banana', 0), /todo-state/);
  // date: an ISO value renders as an urgency chip with the ISO in the title
  assert.match(c.mtCellHtml(node, '2199-01-01', 1), /ag-chip/);
  assert.match(c.mtCellHtml(node, '2199-01-01', 1), /2199-01-01/);
  assert.doesNotMatch(c.mtCellHtml(node, 'not a date', 1), /ag-chip/);
  // number: formatted; a word falls through
  assert.equal(c.mtCellHtml(node, '42.0', 2), '42');
  assert.doesNotMatch(c.mtCellHtml(node, 'n/a', 2), /42/);
  // no role, and a node with no colRole at all: plain render
  assert.doesNotMatch(c.mtCellHtml(node, 'TODO', 3), /todo-state/);
  const bare = { dice: [], math: [], vars: [], grammar: [], est: [], seq: [], props: [] };
  assert.doesNotMatch(c.mtCellHtml(bare, 'TODO', 0), /todo-state/);
});

// ε: a per-column number format (node.colFmt) makes a Number column read as money/measure/percent —
// the same {decimals,prefix,suffix} record the {= } math pill carries, applied per column by index.
test('mtCellHtml — a Number column honors its per-column colFmt (money/percent); other columns unaffected', () => {
  const node = { colRole: ['number', 'number', null],
    colFmt: [{ prefix: '$', decimals: 2 }, { suffix: '%' }, null],
    dice: [], math: [], vars: [], grammar: [], est: [], seq: [], props: [] };
  // column 0: $ + 2 decimals + thousands grouping
  assert.equal(c.mtCellHtml(node, '1200', 0), '$1,200.00', 'prefix + decimals + grouping compose');
  // column 1: a percent suffix, no forced decimals
  assert.equal(c.mtCellHtml(node, '8', 1), '8%', 'suffix formats without decimals');
  // a non-numeric value in a formatted column still falls through to the plain render (never #ERR)
  assert.doesNotMatch(c.mtCellHtml(node, 'n/a', 0), /\$/, 'a non-number cell is not formatted');
  // a Number column with no colFmt slot groups but adds no prefix/suffix (baseline #946 behavior)
  const plain = { colRole: ['number'], dice: [], math: [], vars: [], grammar: [], est: [], seq: [], props: [] };
  assert.equal(c.mtCellHtml(plain, '1200', 0), '1,200', 'no colFmt → group only, no affix');
});

// ε: the per-column format setter creates lazily, aligns by index, and drops the whole array when
// every column is back to default — so an untouched base serializes clean (mirrors mtSetColWidth).
test('mtSetColFmt — lazy create, per-index set, drop-to-undefined when all null', () => {
  const node = { text: '| A | B |\n| --- | --- |\n| 1 | 2 |' };
  c.mtSetColFmt(node, 1, { suffix: '%' });
  assert.deepEqual(host(node.colFmt), [null, { suffix: '%' }], 'lazily created and set at the column index');
  c.mtSetColFmt(node, 1, null);
  assert.equal(node.colFmt, undefined, 'clearing the only format drops the array back to undefined');
  // clearing a never-set format is a no-op (no array springs into existence)
  c.mtSetColFmt(node, 0, null);
  assert.equal(node.colFmt, undefined, 'clearing when there is nothing to clear stays undefined');
});

// ε: the DOM wiring that can't run headless — the column menu item, its dialog, the footer format,
// and colFmt parity at every column-array splice site (a missed splice drops data on a column op).
test('per-column number format — menu/dialog/footer/parity wiring (src pins)', () => {
  // the Column menu offers Number format… on a Number column, opened a frame late like Column formula…
  assert.ok(/curRole === 'number'\)?\s*\n\s*addItem\('Number format…'/.test(_src), 'the Show as section adds Number format… for a Number column');
  assert.ok(/requestAnimationFrame\(\(\) => openColFmtDialog\(node, colIdx\)\)/.test(_src), 'the item opens the dialog a frame late (focus-restore first)');
  // the dialog reuses parseNumFmt → mtSetColFmt and deep-links the number-format guide
  const d = fnBody(_src, 'openColFmtDialog');
  assert.ok(d.includes("guideId: 'number-format'") && d.includes('mtSetColFmt(node, colIdx, parseNumFmt('),
    'openColFmtDialog reuses parseNumFmt → mtSetColFmt and deep-links the guide');
  // the footer total of a formatted column formats too (display-only)
  assert.ok(/const totFmt = node\.colFmt\?\.\[c\];/.test(_src) && /formatNumDisplay\(Number\(totRaw\), totFmt\)/.test(_src),
    'the aggregate footer cell honors the column format');
  // colFmt is spliced/moved beside colW/colRole at every column op, and torn down / persisted with them
  assert.ok(/if \(node\.colFmt\) node\.colFmt\.splice\(at, 0, null\)/.test(_src), 'insert keeps colFmt aligned');
  assert.ok(/if \(node\.colFmt\) mtMoveItem\(node\.colFmt, colIdx, to\)/.test(_src), 'move keeps colFmt aligned');
  assert.ok(/if \(node\.colFmt\) mtMoveItem\(node\.colFmt, from, to\)/.test(_src), 'the header-drag drop handler keeps colFmt aligned too (the inline mtMoveCol twin)');
  assert.ok(/if \(node\.colFmt\) \{ node\.colFmt\.splice\(colIdx, 1\);/.test(_src), 'delete keeps colFmt aligned + drops when empty');
  assert.ok(/delete node\.colFmt;/.test(_src), 'base→text teardown drops colFmt');
  assert.ok(/n\.colFmt\?\.some\(x => x != null\)\)\s+attrs \+= ` _colfmt=/.test(_src), 'toOpml serializes _colfmt when set');
});

// ── Bases round 1 (B1–B4): correctness fixes ─────────────────────────────────
test('qbaseColRoles — roles inferred from the projection, aligned to the rendered columns (B4)', () => {
  const roles = host(c.qbaseColRoles([
    { name: 'Point', field: 'title' },
    { name: 'Due', field: 'due' },
    { name: 'Begin', field: ' Start ' },          // case/space-insensitive
    { name: 'Left', field: '= daysuntil(due)' },  // formula projection -> number
    { name: 'Owner', field: 'owner' },            // plain prop -> no role
  ]));
  assert.deepEqual(roles, [null, 'date', 'date', 'number', null]);
  // filtered exactly like queryTableRows' colList, so indexes line up with rendered columns
  assert.deepEqual(host(c.qbaseColRoles([{ field: '  ' }, null, { field: 'due' }, { name: 'x' }])), ['date']);
  assert.deepEqual(host(c.qbaseColRoles([])), []);
  assert.deepEqual(host(c.qbaseColRoles(undefined)), []);
});

test('mtColRoles — query bases infer, authored bases keep hand-set roles and fall back to data inference (B4 + #922)', () => {
  // an explicit hand-set role is returned verbatim (explicit mode)
  assert.deepEqual(c.mtColRoles({ colRole: ['status', null] }), ['status', null]);
  const q = { qbase: { expr: 'is:todo', cols: [{ name: 'P', field: 'title' }, { name: 'D', field: 'due' }] } };
  assert.deepEqual(host(c.mtColRoles(q)), [null, 'date']);
  // an authored base with no id (or no rows) infers nothing → []
  assert.deepEqual(host(c.mtColRoles({})), []);
  // and mtCellHtml consults it: a query base's due column paints date chips with no colRole set
  const qn = Object.assign({ dice: [], math: [], vars: [], grammar: [], est: [], seq: [], props: [] }, q);
  assert.match(c.mtCellHtml(qn, '2199-01-01', 1), /ag-chip/);
  assert.doesNotMatch(c.mtCellHtml(qn, '2199-01-01', 0), /ag-chip/);
  // #922: an authored base with NO colRole infers Status/Date from the data — Board/Calendar light up
  const base = c.mkNode('| Task | State | Due |\n| --- | --- | --- |\n| A | TODO | 2026-01-02 |\n| B | DONE | 2026-03-04 |');
  base.id = 'b922'; base.type = 'base';
  assert.deepEqual(host(c.mtColRoles(base)), [null, 'status', 'date'], 'a state column → status, a date column → date, the label column → null');
  // an explicit role puts the base in explicit mode (inference no longer fills the gaps)
  base.colRole = [null, null, null];
  assert.deepEqual(host(c.mtColRoles(base)), [null, null, null], 'once colRole is set, it is returned verbatim');
});

test('#922 inferColRolesFromModel — status/date columns from data; mixed/empty/footer excluded', () => {
  const STATES = ['TODO', 'NEXT', 'WAITING', 'DONE'];
  const model = { aligns: [null, null, null, null], rows: [
    ['Task', 'State', 'Due', 'Note'],
    ['A', 'TODO', '2026-01-02', 'hi'],
    ['B', 'DONE', '2026-03-04', 'yo'],
  ] };
  assert.deepEqual(host(c.inferColRolesFromModel(model, false, STATES)), [null, 'status', 'date', null],
    'a keyword column → status, a date column → date, free text and labels → null');
  // a column mixing a keyword and a date is ambiguous → null
  const mixed = { aligns: [null], rows: [['X'], ['TODO'], ['2026-01-02']] };
  assert.deepEqual(host(c.inferColRolesFromModel(mixed, false, STATES)), [null]);
  // an all-empty column → null (nothing to infer)
  const empty = { aligns: [null, null], rows: [['A', 'B'], ['x', ''], ['y', '']] };
  assert.deepEqual(host(c.inferColRolesFromModel(empty, false, STATES)), [null, null]);
  // a footer row is excluded from the scan: the data rows are all dates, only the footer is a keyword
  const footer = { aligns: [null], rows: [['When'], ['2026-01-02'], ['2026-03-04'], ['TODO']] };
  assert.deepEqual(host(c.inferColRolesFromModel(footer, true, STATES)), ['date'], 'the footer keyword does not break the date inference');
  // one non-empty keyword cell is enough (a status column need not be full)
  const sparse = { aligns: [null], rows: [['S'], ['DONE'], ['']] };
  assert.deepEqual(host(c.inferColRolesFromModel(sparse, false, STATES)), ['status']);
  // a header-only table infers nothing
  assert.deepEqual(host(c.inferColRolesFromModel({ aligns: [null], rows: [['H']] }, false, STATES)), []);
});

// ── #1114: the Board's dead end ──────────────────────────────────────────────────────────────
test('#1114 normStateKey — a state answers to the spelling a person types in a cell', () => {
  // A sequence must declare IN_PROGRESS: a state keyword cannot hold a space (LEAD_WORD_RE stops
  // at the first one, and seqDefString's own advice is "join the words"). But a base cell is free
  // text and the natural thing to type is `in progress`. MEASURED: the role inference already
  // folded case, so space-versus-underscore was the ENTIRE distance between a delivery lead's
  // document and a working Board.
  assert.equal(c.normStateKey('IN_PROGRESS'), c.normStateKey('in progress'));
  assert.equal(c.normStateKey('in-progress'), c.normStateKey('In Progress'));
  assert.equal(c.normStateKey('  TODO  '), 'todo');
  assert.equal(c.normStateKey(null), '');
  // it must NOT collapse distinct states
  assert.notEqual(c.normStateKey('TODO'), c.normStateKey('DONE'));
  assert.notEqual(c.normStateKey('in progress'), c.normStateKey('progress'));
});

test('#1114 the SAME normaliser runs at all three match sites, or Board lights up useless', () => {
  // Fixing only the inference would mark the column `status`, open Board, and then bucket every
  // card into the trailing "No state" lane - a view that looks right and is not, which is worse
  // than the honest refusal it replaced. All three must agree.
  assert.match(fnBody(_src, 'sequenceForKeyword'), /normStateKey\(/, 'the sequence lookup folds');
  assert.match(fnBody(_src, 'inferColRolesFromModel'), /lc\.has\(normStateKey\(cell\)\)/, 'the role inference folds');
  assert.match(fnBody(_src, 'boardLanes'), /lanes\.find\(l => normStateKey\(l\.kw\) === v\)/, 'the lane bucketing folds');
  // and the behaviour that proves it: a lowercase spaced cell finds its declared lane
  const seqs = [{ key: 'f', name: 'Flow', states: ['TODO', 'IN_PROGRESS', 'DONE'], doneFrom: 2, heldFrom: 2 }];
  const model = { rows: [['Task', 'Status'], ['A', 'in progress'], ['B', 'DONE'], ['C', 'todo']] };
  const { seq, lanes } = c.boardLanes(model, 1, seqs, 3);
  assert.equal(seq.name, 'Flow');
  const byKw = Object.fromEntries(lanes.map(l => [l.kw ?? 'none', l.rows.length]));
  assert.deepEqual(byKw, { TODO: 1, IN_PROGRESS: 1, DONE: 1 }, 'all three cards land in real lanes: ' + JSON.stringify(byKw));
  assert.ok(!nonEmpty(lanes, 'the board lanes').some(l => l.kw === null), 'nothing falls into the No state lane');

  // DELIBERATELY CONSERVATIVE, and pinned so nobody "fixes" it: the fold turns _ - and space into
  // ONE space, it does not DELETE separators. So `in progress` answers to IN_PROGRESS (both fold to
  // "in progress"), but `to do` does NOT answer to TODO - there is no separator in TODO to fold, and
  // deleting separators instead would start collapsing states a user meant to keep apart.
  const strict = c.boardLanes({ rows: [['T', 'S'], ['A', 'to do']] }, 1, seqs, 1);
  assert.equal(strict.lanes.find(l => l.kw === null)?.rows.length, 1, '`to do` stays unmatched, by design');
});

test('#1114 boardBlockReason — the refusal names WHICH half is missing', () => {
  const states = new Set(['TODO', 'NEXT', 'WAITING', 'DONE']);
  // his case: a column HEADED Status, filled, every value outside every sequence. The old single
  // message read as an instruction he had already followed.
  const his = c.boardBlockReason(['Task', 'Status', 'Owner'], -1, ['in progress', 'blocked', 'done'], states);
  assert.equal(his.reason, 'unknown-values');
  assert.match(his.msg, /not states yet/);
  assert.match(his.msg, /in progress/, 'it names the values it could not place');
  assert.match(his.msg, /\{seq /, 'and names the in-fence fix: declare them');
  // #1148: with NO sequence declared, the generic example is right -- there is no vocabulary to name.
  assert.equal(his.seqNamed, null, 'nothing declared, so nothing to point at');

  // #1148: THE SEQUENCE IS THE VOCABULARY. Once the author HAS declared one, the generic example is
  // the wrong advice -- it tells them to do a thing they have already done. Measured on the planner's
  // own setup: one unknown value collapses the column to no role, so the chip picker that would have
  // shown him the vocabulary never appears. Discovery was gated on having already discovered.
  const flow = { key: 'flow', name: 'Flow', states: ['TODO', 'IN_PROGRESS', 'DONE'] };
  const seqs = [{ key: 'default', name: 'To-do', states: ['TODO', 'NEXT', 'WAITING', 'DONE'] }, flow];
  const wide = new Set([...states, 'IN_PROGRESS']);
  const withSeq = c.boardBlockReason(['Task', 'Status'], -1, ['in progress', 'blocked'], wide, seqs);
  assert.equal(withSeq.reason, 'unknown-values');
  assert.equal(withSeq.seqNamed, 'Flow', 'it names the sequence the author is evidently using');
  assert.match(withSeq.msg, /“blocked”/, 'still names what it could not place');
  assert.doesNotMatch(withSeq.msg, /“in progress”/,
    'and NOT the value that already matches — normStateKey folds it onto IN_PROGRESS (#1114)');
  assert.match(withSeq.msg, /Flow offers TODO, IN_PROGRESS, DONE/, 'it spells out the vocabulary that exists');
  assert.match(withSeq.msg, /add it to that sequence/, 'and the way to widen it');
  assert.doesNotMatch(withSeq.msg, /\{seq /,
    'the generic example must NOT appear once a real sequence can be named — that is the whole fix');
  // Plural reads correctly, and the sequence chosen is the one covering the MOST of the column's
  // values (a measure, not a guess): Ops matches nothing here, Flow matches one, so Flow wins.
  const ops = { key: 'ops', name: 'Ops', states: ['OPEN', 'SHIPPED'] };
  const two = c.boardBlockReason(['Task', 'Status'], -1, ['IN_PROGRESS', 'blocked', 'stuck'], wide, [seqs[0], ops, flow]);
  assert.equal(two.seqNamed, 'Flow', 'the sequence covering the most of the column wins');
  assert.match(two.msg, /add them to that sequence/, 'plural when more than one value fell outside');
  // The DEFAULT sequence is never named as "the vocabulary": nobody declared it, so pointing at it
  // would be the same not-followable advice in a new costume.
  const onlyDefault = c.boardBlockReason(['Task', 'Status'], -1, ['blocked'], states, [seqs[0]]);
  assert.equal(onlyDefault.seqNamed, null, 'the built-in To-do sequence is not a declared vocabulary');
  assert.match(onlyDefault.msg, /\{seq /, 'so it falls back to teaching how to declare one');
  // Nothing is REJECTED anywhere in here: this offers a vocabulary, it never constrains an editor.
  // That is what keeps it inside the base-views-vision §0.5 fence (which defers a role that offers
  // its values AND constrains the editor, needing a new value-set cache -- none of which is here).
  for (const m of [withSeq.msg, two.msg, onlyDefault.msg])
    assert.doesNotMatch(m, /not allowed|invalid|must be one of|rejected/i,
      'the cue offers and never forbids — freeform still wins (product-identity §3b)');
  // named but never marked - the role is what counts, not the header text
  const named = c.boardBlockReason(['Task', 'Status'], -1, ['TODO', 'DONE'], states);
  assert.equal(named.reason, 'named-not-marked');
  assert.match(named.msg, /Column menu, Show as/, 'it names the door');
  assert.match(named.msg, /Alt\+R/, 'and the keyboard door');
  // nothing that looks like a status column: the original message, unchanged
  const none = c.boardBlockReason(['Task', 'Owner'], -1, [], states);
  assert.equal(none.reason, 'none');
  assert.equal(none.msg, 'Mark a column as Status first (Column menu, Show as); its states become the lanes.');
  // already marked: no refusal at all
  assert.equal(c.boardBlockReason(['Task', 'Status'], 1, ['TODO'], states), null);
  // `State` counts too, and matching is case-insensitive
  assert.equal(c.boardBlockReason(['Task', 'state'], -1, ['TODO'], states).reason, 'named-not-marked');
});

test('#1114 /TODO selects the STATE, like its three siblings', () => {
  // MEASURED on main: blockCmdsPool() splices BLOCK_CMDS before stateCmds(), and the checkbox
  // command's id is literally `todo`, so it won at index 0. /next, /waiting and /done all landed
  // correctly - one word, four meanings, three of them consistent. There was no test at all.
  const pool = c.blockCmdsPool();
  assert.ok(pool.length > 20, `the pool must be non-empty or every assertion below is vacuous (got ${pool.length})`);
  // THE APP'S ranking, not a copy of it. The first version of this test re-implemented the
  // findIndex here and SURVIVED its own mutation - it proved my idea, not the code. That is the
  // #1133 vacuity class in its purest form, so the ranking was extracted to slashActiveIdx and this
  // now calls it.
  const pick = (q) => {
    const matches = nonEmpty(
      pool.filter(x => x.id.startsWith(q) || x.label.toLowerCase().includes(q) || (x.keys || []).some(k => k.startsWith(q))),
      `the /${q} matches`);
    return matches[c.slashActiveIdx(matches, q, false)];
  };
  for (const q of ['todo', 'next', 'waiting', 'done']) {
    assert.equal(pick(q).id, 'state:' + q.toUpperCase(), `/${q} must select the state`);
  }
  // THE REGRESSION: the checkbox must stay reachable. It carries keys ['task','tick'].
  assert.equal(pick('task').id, 'todo', 'the markdown checkbox is still one word away');
  assert.equal(pick('tick').id, 'todo');
  const todoMatches = pool.filter(x => x.id.startsWith('todo') || x.label.toLowerCase().includes('todo') || (x.keys || []).some(k => k.startsWith('todo')));
  assert.ok(nonEmpty(todoMatches, 'the /todo matches').some(x => x.id === 'todo'), 'and it is still the next row under /todo');
  // the pre-existing rule the extraction must not lose: a typed ":value" keeps its exact verb
  const argRows = [{ id: 'note' }, { id: 'due' }];
  assert.equal(c.slashActiveIdx(argRows, 'due', true), 1, 'a /due:tomorrow keeps the due verb selected');
  assert.equal(c.slashActiveIdx(argRows, 'nope', true), 0, 'an unknown arg verb falls back to the first row');
  assert.equal(c.slashActiveIdx([], 'todo', false), 0, 'no matches, no crash');
});

test('#1114 the wiring: the gate consults the reason, and the tooltip names its door', () => {
  const sv = fnBody(_src, 'mtSetView');
  // #1148 widened this call: the refusal now also receives the DECLARED sequences, so it can name the
  // vocabulary this document already has instead of a generic example. Updated rather than loosened --
  // the point of the line is that the gate passes everything the core needs to be specific.
  assert.match(sv, /flashHint\(boardBlockReason\(hdr, gi, cells, knownStates\(\), allSequences\(\)\)\.msg\)/,
    'the board gate must ask WHICH half is missing, and hand over the declared sequences to say so');
  assert.match(sv, /\/\^\(status\|state\)\$\/i/, 'and find the named column to ask about');
  // the dimmed button is what a user reads FIRST, and often the only thing they read
  assert.match(fnBody(_src, 'mtViewSwitcherHtml'), /Mark a column as Status to use Board \(Column menu, Show as\)/,
    'the tooltip names its own door');
  assert.doesNotMatch(_src, /'Mark a column as Status to use Board'/, 'the doorless tooltip is gone');

  // PIN THE CALL SITE, not only the core (#1133 / UXP-260). Replacing this call with a literal 0
  // failed NOTHING until this line existed - the ranking core was perfectly tested and perfectly
  // ignorant of whether the menu consulted it. Third time this session; the rule is in the DoD and
  // the habit is still the thing lagging.
  assert.match(_src, /const activeIdx = slashActiveIdx\(matches, matchWord, hasArg\);/,
    'the slash menu must consult the ranking core, not re-derive or ignore it');
  assert.doesNotMatch(fnBody(_src, 'slashActiveIdx'), /document|querySelector/, 'and the core stays DOM-free');
});

test('bases round 1 — B4 read sites + write sites stay split (source pins)', () => {
  // every colRole READ site consults mtColRoles: the cell paint, the switcher, the view gates,
  // and the number right-align in the row loop
  assert.ok(/const roles = (_colRoles \|\| )?mtColRoles\(node\);\n\s*const role = roles && roles\[c\];/.test(fnBody(_src, 'mtCellHtml')), 'mtCellHtml reads via the accessor');
  assert.ok(/const roles = mtColRoles\(node\) \|\| \[\];/.test(fnBody(_src, 'mtViewSwitcherHtml')), 'the switcher ready-state reads via the accessor');
  const sv = fnBody(_src, 'mtSetView');
  assert.equal((sv.match(/mtColRoles\(node\)/g) || []).length, 2, 'both view gates (board + calendar) read via the accessor');
  // #1475 moved the rule itself into effectiveAlign; the invariant this pins is unchanged — the
  // right-align decision reads the HOISTED roles, never a per-cell mtColRoles(node) call.
  assert.ok(/effectiveAlign\(model\.aligns\[c\], _colRoles\[c\]\)/.test(_src), 'the right-align check reads the hoisted roles');
  // write sites stay authored-only: mtSetColRole writes node.colRole (never a qbase) and, per #922,
  // SEEDS the array from the current inference on first touch so promoting one column to explicit
  // mode doesn't drop the others' auto-detected roles.
  const scr = fnBody(_src, 'mtSetColRole');
  assert.ok(/node\.colRole \|\| inferredColRoles\(node\)\.slice\(\)/.test(scr), 'the role writer seeds from inference on first touch (#922)');
  assert.ok(/node\.colRole = arr\.every\(x => x == null\) \? undefined : arr;/.test(scr), 'the role writer still writes node.colRole directly (authored-only)');
});

test('bases round 1 — B1/B2/B3 wiring (source pins)', () => {
  // #955 extracted the cell edit/nav handlers into mtWireCells so a non-table view could call
  // them. They are one unit of behaviour that now lives in two functions, so the slice is both
  // — these pins are about what the handlers DO, not which function declares them.
  const btw = fnBody(_src, 'buildTableWidget') + fnBody(_src, 'mtWireCells');
  // B1/B2 (via the round-2 extraction): BOTH commit chokepoints run the shared epilogue —
  // prune orphaned records, re-bump the generation past the promotion, re-run the recipe —
  // and the focusout repaints sibling cells when it says so (recompute OR projecting varbase)
  const epi = fnBody(_src, 'mtCommitEpilogue');
  assert.ok(/pruneArtifacts\(node\);\s*\n\s*markDirty\(\);\s*\n\s*const recomputed = mtRecompute\(node\)/.test(epi),
    'the epilogue prunes, re-bumps the generation, then recomputes — in that order');
  assert.ok(/recomputed \? 'full' : \(isVarBase\(node\) \? 'tokens' : false\)/.test(epi),
    'the epilogue names the repaint: full on recompute, token cells on a projecting varbase');
  assert.ok(/if \(repaint\) mtPatchCells\(node, cell, repaint === 'tokens'\)/.test(btw), 'the cell focusout runs the epilogue and patches in place');
  // ...and the token scope skips pill-less cells (round 4, the measured 870ms-at-5k fix)
  assert.ok(/onlyTokenCells && !raw\.includes\('\[\['\)/.test(fnBody(_src, 'mtPatchCells')), 'token scope patches only pill cells');
  // B1b: cross-outline refs repaint via the deferred, focus-aware render — only on a real change
  assert.ok(/raw !== enteredWith && isVarBase\(node\)\) scheduleVarBaseRender\(host\)/.test(btw), 'focusout schedules the outline repaint');
  const svr = fnBody(_src, 'scheduleVarBaseRender');
  assert.ok(/contains\(document\.activeElement\)/.test(svr) && /_pendingVarBaseRender = true/.test(svr) && /render\(\)/.test(svr),
    'the deferred render is focus-aware and hands off to a live editor');
  const ee = fnBody(_src, 'exitEdit');
  assert.ok(/_pendingFullRender \|\| _pendingVarBaseRender/.test(ee), 'exitEdit consumes the pending varbase render (non-base tail)');
  assert.ok(/else if \(_pendingVarBaseRender\)/.test(ee), 'exitEdit consumes it on the base local-rebuild path too');
  // B1c: the markdown-edit path of a projecting varbase re-renders the whole outline
  assert.ok(/isVarBase\(node\)/.test(ee), 'exitEdit base branch forks on a projecting varbase');
  // B2: the base branch runs the same epilogue (prune + generation re-bump + recompute)
  assert.ok(/mtCommitEpilogue\(node\)/.test(ee), 'exitEdit base branch runs the shared epilogue');
  assert.ok(/pruneArtifacts\(node\)/.test(ee), 'the prose path keeps its own prune');
  // ...but never in the per-keystroke input handler (would shed a record mid-typing)
  const inputIdx = btw.indexOf("addEventListener('input'");
  if (inputIdx >= 0) {
    const inputChunk = btw.slice(inputIdx, btw.indexOf('addEventListener', inputIdx + 10));
    assert.ok(!/pruneArtifacts|mtCommitEpilogue/.test(inputChunk), 'no prune/epilogue in the input handler');
  }
  // B3: markdown-edit promotes typed {…} per cell — never the whole serialized text (#788)
  assert.ok(/promoteCellShorthand\(node, row\[c\]\)/.test(ee), 'the base exitEdit branch promotes per cell');
});

// ── Bases round 2: model memo, perf quick wins, vocabulary ───────────────────
test('round 2 — isVarBase + mtModelRead (the paint-path parse memo)', () => {
  assert.equal(c.isVarBase({ type: 'base', varbase: {} }), true);
  assert.equal(c.isVarBase({ type: 'base', varbase: {}, qbase: { expr: 'x', cols: [] } }), false, 'query bases never project');
  assert.equal(c.isVarBase({ type: 'ul', varbase: {} }), false, 'only a base projects');
  assert.equal(c.isVarBase({ type: 'base' }), false);
  assert.equal(c.isVarBase(null), false);
  // mtModelRead: unchanged text serves the SAME shared model object; a text change invalidates
  const n = { id: 'mm1', type: 'base', text: '| A | B |\n| --- | --- |\n| 1 | 2 |' };
  const m1 = c.mtModelRead(n);
  assert.equal(c.mtModelRead(n), m1, 'unchanged text hits the memo');
  n.text = '| A | B |\n| --- | --- |\n| 9 | 2 |';
  const m2 = c.mtModelRead(n);
  assert.notEqual(m2, m1, 'a text change misses (self-invalidating, no bump needed)');
  assert.equal(m2.rows[1][0], '9');
  // the WRITE path stays fresh-parse — mutation-safe by construction
  assert.notEqual(c.mtModel(n), c.mtModel(n), 'mtModel returns a fresh parse every call');
});

test('round 2 — perf wiring + canonical vocabulary (source pins)', () => {
  // the variables-panel rebuild is debounced out of markDirty (it ran synchronously per keystroke)
  const md = fnBody(_src, 'markDirty');
  assert.ok(/scheduleVarPanelUpdate\(\)/.test(md) && !/updateVarPanelContent\(\)/.test(md), 'markDirty defers the panel rebuild');
  assert.ok(/setTimeout/.test(fnBody(_src, 'scheduleVarPanelUpdate')), 'the panel update is a trailing debounce');
  assert.ok(/updateVarPanelContent\(\)/.test(fnBody(_src, 'openVarPanel')), 'opening the panel still updates synchronously');
  // the per-keystroke cell handler reuses the session parse, self-invalidating via the committed text
  // #955 extracted the cell edit/nav handlers into mtWireCells so a non-table view could call
  // them. They are one unit of behaviour that now lives in two functions, so the slice is both
  // — these pins are about what the handlers DO, not which function declares them.
  const btw = fnBody(_src, 'buildTableWidget') + fnBody(_src, 'mtWireCells');
  assert.ok(/_mtEditSession && _mtEditSession\.id === node\.id && _mtEditSession\.text === node\.text/.test(btw),
    'the input handler reuses the last-commit parse, text-keyed');
  // the column-total matcher compiles once per base.col
  assert.ok(/_aggColReCache/.test(fnBody(_src, 'aggregateVarBaseColumn')), 'the aggregate regex is cached');
  // paint paths read through the memo; write paths stay on mtModel
  assert.ok(/const m = mtModelRead\(node\)/.test(fnBody(_src, 'mtPatchCells')), 'mtPatchCells reads via the memo');
  assert.ok(/const model = mtModelRead\(node\)/.test(btw), 'the widget paint reads via the memo');
  assert.ok(!/mtModelRead/.test(fnBody(_src, 'mtRecompute')), 'recompute (a write path) stays on the fresh parse');
  // the base menu section header speaks the canonical term (ux-discipline §1: base, not table)
  assert.ok(/SECTION_ORDER = \['Base',/.test(_src) && !/sec:'Table'/.test(_src), "the base menu section says 'Base'");
});

// ── Bases round 3: UX coherence ──────────────────────────────────────────────
test('round 3 — collectPillActions cell scope (the cell-menu pill door)', () => {
  const n = c.mkNode('| A |\n| --- |\n| [[dice:k1]] |');
  n.dice = [{ key: 'k1', expr: '2d6', total: 7 }];
  const all = host(c.collectPillActions(n));
  assert.ok(all.some(r => /Re-roll dice/.test(r.label)), 'node scope surfaces the dice actions');
  const scoped = host(c.collectPillActions(n, '[[dice:k1]]'));
  assert.ok(scoped.some(r => /Re-roll dice/.test(r.label)), 'the owning cell scope surfaces them too');
  assert.equal(host(c.collectPillActions(n, '5')).length, 0, 'a pill-less cell scope surfaces nothing');
  // clocks are node-ordinal actions — never under a cell scope
  const cn = c.mkNode('| A |\n| --- |\n| x |\n\n[o 2/6]');
  assert.ok(host(c.collectPillActions(cn)).some(r => /clock/i.test(r.label)), 'node scope keeps clocks');
  assert.equal(host(c.collectPillActions(cn, 'x')).length, 0, 'cell scope skips them');
});

// ── QP-2 Phase B: cap, show-all, row identity ────────────────────────────────
test('Phase B — queryTableRows uncapped; qbaseModel wiring (pins)', () => {
  const root = { children: Array.from({ length: 150 }, (_, i) => ({ id: 'n' + i, text: '#TODO t' + i, children: [] })) };
  const capped = host(c.queryTableRows('is:todo', [{ name: 'P', field: 'title' }], root, null, 100));
  assert.equal(capped.rows.length, 100);
  assert.equal(capped.total, 150);
  assert.equal(capped.truncated, true);
  const all = host(c.queryTableRows('is:todo', [{ name: 'P', field: 'title' }], root, null, Infinity));
  assert.equal(all.rows.length, 150);
  assert.equal(all.truncated, false);
  // rows carry their source id — the identity the widget stamps per <tr>
  assert.equal(all.rows[0].id, 'n0');
  // source pins: the conditional cap, the qids channel, the strip toggle, the tr stamp
  const qm = fnBody(_src, 'qbaseModel');
  assert.ok(/node\.qbase\.showAll \? Infinity : QBASE_ROW_CAP/.test(qm), 'showAll lifts the cap');
  assert.ok(/let qids = \[null, \.\.\.q\.rows\.map\(r => r\.id\)\]/.test(qm), 'the model carries row identity, header slot null');
  // SV-2: the configured sort reorders rows and qids TOGETHER (identity survives ordering)
  assert.ok(/order\.map\(i => rows\[i\]\)/.test(qm) && /order\.map\(i => qids\[i\]\)/.test(qm), 'the sort keeps rows and qids aligned');
  assert.ok(/data-nid="\$\{escQ\(nid\)\}"/.test(fnBody(_src, 'buildTableWidget')), 'each query row is stamped with its source id');
  assert.ok(/Show all \$\{escHtml\(String\(qm\.total\)\)\}/.test(_src) && /Cap at \$\{QBASE_ROW_CAP\}/.test(_src), 'the strip toggle names both states');
  assert.ok(/node\.qbase\.showAll = !node\.qbase\.showAll/.test(_src), 'the toggle flips the persisted flag');
  assert.ok(/\.\.\.\(node\.qbase\.showAll \? \{ showAll: true \} : \{\}\)/.test(_src), 'editing the query preserves showAll');
  // focus restore across the widget rebuild re-finds the SAME source row by id.
  // REWRITTEN for #1383, not loosened: the restore moved out of refreshTable's own body into the
  // baseRefocusSelector / baseFocusDescriptor pair, which handles the row link AND every other
  // control the widget stamps (the view buttons, the chrome, a cell, a card) — refreshTable used to
  // restore exactly one of them and drop the rest to <body>. What Phase B needs guarded is unchanged
  // and is asserted here directly: the row is still found by SOURCE ID, not by index, because result
  // order may have shifted; and the id is still CSS.escape'd.
  const rt = fnBody(_src, 'refreshTable');
  const bfd = fnBody(_src, 'baseFocusDescriptor');
  assert.ok(/baseRefocusSelector\(baseFocusDescriptor\(document\.activeElement\)\)/.test(rt),
    'refreshTable still resolves a restore target before the rebuild');
  assert.ok(/closest\('tr\[data-nid\]'\)/.test(bfd) && /CSS\.escape\(row\.dataset\.nid\)/.test(bfd),
    'refreshTable restores focus by source id');
  assert.equal(c.baseRefocusSelector({ nid: 'n7' }), 'tr[data-nid="n7"] .node-link',
    'and the id resolves to the same row link it always did');
});

// ── QP-2 Phase C: write-through cells ────────────────────────────────────────
test('Phase C — qbaseColList/qbaseFieldWritable + the write-through wiring (pins)', () => {
  // the shared rendered-column filter (roles, paint, and edit stay index-aligned)
  const cols = [{ name: 'P', field: 'title' }, null, { field: '  ' }, { name: 'D', field: 'due' }, { name: 'X', field: '= a + 1' }];
  const list = host(c.qbaseColList(cols));
  assert.deepEqual(list.map(x => x.field), ['title', 'due', '= a + 1']);
  // writable = a plain property key; title (a link) and '=' (computed) stay read-only
  assert.equal(c.qbaseFieldWritable('due'), true);
  assert.equal(c.qbaseFieldWritable(' Cost '), true);
  assert.equal(c.qbaseFieldWritable('title'), false);
  assert.equal(c.qbaseFieldWritable('= daysuntil(due)'), false);
  assert.equal(c.qbaseFieldWritable(''), false);
  assert.equal(c.qbaseFieldWritable(null), false);
  // the shared filter is consumed at all three sites
  assert.ok(/const colList = qbaseColList\(cols\)/.test(fnBody(_src, 'queryTableRows')), 'queryTableRows shares the filter');
  assert.ok(/qbaseColList\(cols\)\.map/.test(fnBody(_src, 'qbaseColRoles')), 'qbaseColRoles shares the filter');
  // #955 extracted the cell edit/nav handlers into mtWireCells so a non-table view could call
  // them. They are one unit of behaviour that now lives in two functions, so the slice is both
  // — these pins are about what the handlers DO, not which function declares them.
  const btw = fnBody(_src, 'buildTableWidget') + fnBody(_src, 'mtWireCells');
  assert.ok(/qbaseColList\(node\.qbase\.cols\)\.map\(x => x\.field\.trim\(\)\)/.test(btw), 'the paint shares the filter');
  // paint: writable qbase cells are contenteditable and badged; others stay read-only
  assert.ok(/qEdit = _qFields && qbaseFieldWritable\(_qFields\[c\]\)/.test(btw), 'only writable columns edit');
  assert.ok(/mt-qcell/.test(btw) && /write to the matching point's/.test(btw), 'editable cells carry the class + explaining title');
  // the wiring: raw swap on focus, source-prop write + undo + flash + membership check on blur
  const w = fnBody(_src, 'mtWireQBaseEdit');
  assert.ok(/mtModelRead\(node\)\.rows/.test(w), 'focusin swaps the chip for the raw value');
  // #1123: the write is ROUTED now — a reserved date goes to its validated writer — so this pins
  // the contract (undo-local, then write, then markDirty) rather than one literal call.
  assert.ok(/pushUndo\(\);\s*\n\s*if \(route === 'date'\) setDateProp\(src, field\.trim\(\)\.toLowerCase\(\), raw\);\s*\n\s*else setProp\(src, field, raw\);\s*\n\s*markDirty\(\)/.test(w),
    'blur writes the source prop with undo-locality, routing a reserved date to setDateProp');
  assert.ok(w.indexOf("route === 'baddate'") > 0 && w.indexOf("route === 'baddate'") < w.indexOf('pushUndo()'),
    'a refused date returns BEFORE pushUndo, so no undo entry exists for a write that never happened');
  assert.ok(/Not a valid date: ' \+ raw \+ '\. ' \+ dateFormsHint\(\)/.test(w),
    'the refusal reuses the shared date voice (#407 P4 parity), not new copy');
  assert.ok(/const shown = \(src\.props \|\| \[\]\)\.find/.test(w),
    'the cell repaints from what was STORED, so a normalized date does not disagree with the model');
  assert.ok(/qids\.includes\(nid\)/.test(w) && /no longer matches this query/.test(w), 'a membership-breaking edit is announced, never silent');
  assert.ok(/scheduleVarBaseRender\(host\)/.test(w), 'the repaint is deferred + focus-aware');
  assert.ok(/qbaseFieldWritable\(field\)/.test(w), 'the commit re-checks writability');
  assert.ok(/mtWireQBaseEdit\(host, node\)/.test(btw), 'wired before the readOnly return');
  // P1 nav parity: Enter/Shift+Enter move by column, Tab by cell, inside the wiring
  assert.ok(/e\.key !== 'Tab' && e\.key !== 'Enter'/.test(w) && /x\.dataset\.c === cell\.dataset\.c/.test(w), 'Enter/Tab mirror the authored-cell grammar');
});

// ── SV-1: one-shot role-aware row sort ───────────────────────────────────────
test('mtSortRows — role-aware, blanks sink, pinned edges, stable (SV-1)', () => {
  const SEQS = [{ key: 'default', name: 'To-do', states: ['TODO', 'NEXT', 'WAITING', 'DONE'], doneFrom: 3 }];
  const rows = [
    ['Task', 'Cost', 'Due', 'State'],
    ['a', '10',  '2199-02-01', 'DONE'],
    ['b', '2',   '',           'TODO'],
    ['c', '',    '2199-01-05', 'NEXT'],
    ['d', '9.5', '2199-01-20', 'banana'],
    ['TOTAL', '21.5', '', ''],
  ];
  const last = 4;   // TOTAL is the pinned footer
  // number: numeric, not lexicographic (2 < 9.5 < 10); blank + non-numeric sink
  const byCost = host(c.mtSortRows(host(rows), 1, 'asc', 'number', host(SEQS), last));
  assert.deepEqual(byCost.map(r => r[0]), ['Task', 'b', 'd', 'a', 'c', 'TOTAL']);
  // desc reverses values but blanks STILL sink
  const byCostD = host(c.mtSortRows(host(rows), 1, 'desc', 'number', host(SEQS), last));
  assert.deepEqual(byCostD.map(r => r[0]), ['Task', 'a', 'd', 'b', 'c', 'TOTAL']);
  // date: epoch order, blank sinks
  const byDue = host(c.mtSortRows(host(rows), 2, 'asc', 'date', host(SEQS), last));
  assert.deepEqual(byDue.map(r => r[0]), ['Task', 'c', 'd', 'a', 'b', 'TOTAL']);
  // status: the owning sequence's DECLARED order, unknown keyword sinks
  const bySt = host(c.mtSortRows(host(rows), 3, 'asc', 'status', host(SEQS), last));
  assert.deepEqual(bySt.map(r => r[0]), ['Task', 'b', 'c', 'a', 'd', 'TOTAL']);
  // plain text: locale, case-insensitive; ties keep document order (stable)
  const tie = [['H', 'V'], ['x', 'same'], ['y', 'same'], ['z', 'alpha']];
  const byTxt = host(c.mtSortRows(host(tie), 1, 'asc', null, host(SEQS), 3));
  assert.deepEqual(byTxt.map(r => r[0]), ['H', 'z', 'x', 'y']);
  // purity: the input array order is untouched
  assert.equal(rows[1][0], 'a');
  // wiring: the menu door exists, the applier guards qbase, commits + pushes undo
  const sb = fnBody(_src, 'mtSortBase');
  assert.ok(/if \(node\.qbase\) return/.test(sb), 'a query base never sorts here (SV-2 owns that)');
  assert.ok(/pushUndo\(\);/.test(sb) && /mtCommit\(node, m\)/.test(sb) && /mtCommitEpilogue\(node\)/.test(sb),
    'the sort is an undoable data operation through the shared commit tail');
  const scp = fnBody(_src, 'showColPanel');
  assert.ok(/addSection\(`Sort rows \(\$\{sortCopy\.as\}\)`, true\)/.test(scp) && /mtSortBase\(node, colIdx, 'asc'\)/.test(scp), 'the Column menu door exists');
});

// ── SV-2: persisted sort on query bases ─────────────────────────────────────
// ── #875 units: a declarable convert() table ─────────────────────────────────
test('units — parse decls, convert, normalize, and the substitution (SR-6)', () => {
  // built-in ratio conversions (factors exact); unitTable(null) hands back the built-in table
  const B = host(c.unitTable(null));
  assert.equal(Math.round(c.convertUnits(10, 'km', 'mi', B) * 100) / 100, 6.21);
  assert.equal(c.convertUnits(1, 'kg', 'g', B), 1000);
  assert.equal(c.convertUnits(2, 'day', 'hr', B), 48);
  assert.equal(c.convertUnits(1, 'km', 'kg', B), null, 'dimension mismatch → null');
  assert.equal(c.convertUnits(1, 'km', 'furlong', B), null, 'unknown unit → null');
  assert.equal(c.convertUnits('x', 'km', 'mi', B), null, 'non-number → null');
  // declared units: a bare base, a chain, and extending a built-in dimension
  const { value: t, warnings } = c.parseUnitDecls('cp\nsp = 10 cp\ngp = 10 sp\nleague = 3 mi\nbad = five sp\nglorp = 2 nope');
  assert.equal(t.cp.ratio, 1); assert.equal(t.cp.dim, 'cp');
  assert.equal(t.sp.ratio, 10); assert.equal(t.gp.ratio, 100);
  assert.equal(t.gp.dim, 'cp', 'the chain shares the base dimension');
  assert.equal(t.league.dim, 'length', 'a declared unit extends a built-in dimension');
  assert.equal(Math.round(t.league.ratio), 4828);
  assert.ok(warnings.some(w => /bad/.test(w)) && warnings.some(w => /nope/.test(w)), 'malformed lines warn, not throw');
  // convert across a declared chain
  const merged = { ...B, ...t };
  assert.equal(c.convertUnits(1, 'gp', 'cp', merged), 100);
  assert.equal(c.convertUnits(100, 'cp', 'gp', merged), 1);
  // normalize drops garbage; keeps valid
  assert.equal(c.normalizeUnits({ gp: { dim: 'coin', ratio: 100 }, bad: { dim: 'x', ratio: -1 }, junk: 5 }).gp.ratio, 100);
  assert.ok(!('bad' in c.normalizeUnits({ gp: { dim: 'coin', ratio: 100 }, bad: { dim: 'x', ratio: -1 } })));
  assert.equal(c.normalizeUnits({ bad: { ratio: 0 } }), null, 'all-garbage → null');
  // splitArgsTopLevel keeps nested commas
  assert.deepEqual(host(c.splitArgsTopLevel('max(a,b), km, mi')), ['max(a,b)', ' km', ' mi']);
  // replaceConvert substitutes to a number; the value arg is evaluated; nesting composes; bad → #ERR
  const ev = s => ({ '10': 10, '2*5': 10, '(1000)': 1000 }[s.trim()] ?? Number(s));
  assert.equal(c.replaceConvert('convert(10, km, mi)', ev, B).startsWith('('), true);
  assert.match(c.replaceConvert('convert(10, km, kg)', ev, B), /#ERR/);
  assert.match(c.replaceConvert('convert(2*5, m, cm)', v => eval(v), B), /\(1000\)/, 'value arg evaluated: 10 m = 1000 cm');
  // end-to-end through expandAggExpr + evalMath (built-ins, no root needed)
  assert.equal(c.evalMath(c.expandAggExpr('convert(1000, m, km) + 5', null), {}), 6);
  // unitsToText reconstructs editable declarations (round-trip for the dialog): a new base is a
  // bare line; a derived unit reads "name = ratio base"; a built-in-dimension extension names m/etc.
  const { value: rt } = c.parseUnitDecls('cp\nsp = 10 cp\nleague = 3 mi');
  const txt = c.unitsToText(host(rt));
  assert.match(txt, /^cp$/m, 'a new base is a bare line');
  assert.match(txt, /^sp = 10 cp$/m, 'a derived unit names its base');
  assert.match(txt, /^league = 4828\.032 m$/m, 'a built-in-dimension extension names the built-in base');
  assert.equal(c.unitsToText(null), '', 'no units → empty text');
});

// ── #1500: convert() has four failure modes and reported the fourth for all of them ──────────
// `convert(10, blorp, kg)` and `convert(12, m2, ft2)` both read "a conversion between two different
// kinds of units (like a length and a mass)" — and there is no area dimension at all, so m2/ft2
// fails by the identical unknown-unit path as blorp. convertUnits collapses the causes into one
// null and replaceConvert substitutes a bare sentinel, so by the time the message is chosen the
// call is gone. The marker now says which, on BOTH surfaces that read it (the pill and the edit
// dialog the user opens to repair it).
test('#1500 convertFailKind says WHICH failure, and stays silent when the units are fine', () => {
  const T = host(c.unitTable(null));   // the built-in table, the way the #875 test gets it
  assert.deepEqual(host(c.convertFailKind('blorp', 'kg', T)), { why: 'unit', unit: 'blorp' });
  assert.deepEqual(host(c.convertFailKind('km', 'blorp', T)), { why: 'unit', unit: 'blorp' });
  assert.deepEqual(host(c.convertFailKind('nope', 'alsonope', T)), { why: 'unit', unit: 'nope' },
    'the FIRST unknown one is the one to name');
  assert.deepEqual(host(c.convertFailKind('m2', 'ft2', T)), { why: 'unit', unit: 'm2' },
    'there is no area dimension, so m2 is an unknown unit — not the mismatch it used to report');
  assert.deepEqual(host(c.convertFailKind('km', 'kg', T)), { why: 'dim' }, 'the real mismatch keeps its name');
  assert.equal(c.convertFailKind('km', 'm', T), null, 'units fine → not this function\'s failure');
  assert.equal(c.convertFailKind(' KM ', 'M', T), null, 'case and whitespace are normalised, like convertUnits');
});

test('#1500 the marker carries the unit name, fenced to what a unit may be called', () => {
  assert.equal(c.convertUnitErrToken('blorp'), '#ERR_UNIT_blorp');
  assert.equal(c.convertUnitErrToken('m2'), '#ERR_UNIT_m2');
  // nothing a user typed can ride into a label: an unfenced name degrades to the bare marker
  assert.equal(c.convertUnitErrToken('a b'), '#ERR_UNIT');
  assert.equal(c.convertUnitErrToken('"><img>'), '#ERR_UNIT');
  assert.equal(c.convertUnitErrToken('9lives'), '#ERR_UNIT', 'a unit name starts with a letter (parseUnitDecls\'s rule)');
  assert.equal(c.convertUnitErrToken(''), '#ERR_UNIT');
});

test('#1500 replaceConvert leaves a DIFFERENT marker for each of the four failures', () => {
  const B = host(c.unitTable(null));
  const ev = s => { const n = Number(String(s).trim()); return Number.isFinite(n) ? n : null; };
  const marks = {
    ok:       c.replaceConvert('convert(10, km, m)', ev, B),
    unknown:  c.replaceConvert('convert(10, blorp, kg)', ev, B),
    area:     c.replaceConvert('convert(12, m2, ft2)', ev, B),
    mismatch: c.replaceConvert('convert(10, km, kg)', ev, B),
    amount:   c.replaceConvert('convert(budgt, km, m)', ev, B),
    parts:    c.replaceConvert('convert(10, km)', ev, B),
  };
  assert.equal(marks.ok, '(10000)', 'a good conversion still substitutes its number');
  assert.equal(marks.unknown, '#ERR_UNIT_blorp');
  assert.equal(marks.area, '#ERR_UNIT_m2');
  assert.equal(marks.mismatch, '#ERR', 'the true mismatch keeps the original marker, so its wording is untouched');
  assert.equal(marks.amount, '#ERR_CONVAMT');
  assert.equal(marks.parts, '#ERR_CONVARGS');
  // every marker must still read as the engine's error sentinel, or {= convert(…)} stops promoting
  // to a loud pill and silently becomes prose (#889).
  for (const [k, v] of Object.entries(marks)) {
    if (k === 'ok') continue;
    assert.ok(String(v).includes('#ERR'), `${k} must keep the #ERR prefix mathPrepassErrs looks for`);
    assert.equal(c.mathPrepassErrs(({ unknown: 'convert(10, blorp, kg)', area: 'convert(12, m2, ft2)',
      mismatch: 'convert(10, km, kg)', amount: 'convert(budgt, km, m)', parts: 'convert(10, km)' })[k]), true,
      `${k} must still promote to a loud #ERR pill`);
  }
});

test('#1500 each marker reaches its own reason and its own sentence', () => {
  const R = e => c.mathErrorReason(c.expandAggExpr(e, null), {});
  assert.equal(R('convert(10, blorp, kg)'), 'unknown unit');
  assert.equal(R('convert(12, m2, ft2)'), 'unknown unit');
  assert.equal(R('convert(10, km, kg)'), 'convert', 'the true mismatch is unchanged');
  assert.equal(R('convert(budgt, km, m)'), 'convert amount');
  assert.equal(R('convert(10, km)'), 'convert parts');
  assert.equal(c.mathErrorReason('#ERR', {}), 'convert', 'a bare sentinel still means the mismatch');

  // the four sentences are distinct, and only the mismatch one talks about two kinds of units
  const say = e => c.mathReasonPhrase(R(e), c.expandAggExpr(e, null));
  const four = nonEmpty([say('convert(10, blorp, kg)'), say('convert(10, km, kg)'),
                         say('convert(budgt, km, m)'), say('convert(10, km)')], 'convert phrases');
  assert.equal(new Set(four).size, 4, 'four failures, four sentences');
  assert.equal(four.filter(p => /different kinds of units/.test(p)).length, 1,
    'exactly one of them claims a dimension mismatch, and it is the one that has one');
  // the unknown-unit sentence names the unit and the door that was driven end to end before being cited
  assert.match(say('convert(10, blorp, kg)'), /"blorp"/, 'it names the unit it did not know');
  assert.match(say('convert(12, m2, ft2)'), /"m2"/);
  assert.match(say('convert(10, blorp, kg)'), /\/units/, 'and the remedy the app actually ships');
  // no marker may reach a reader
  for (const p of four) assert.doesNotMatch(p, /#ERR/, `an internal marker reached the sentence: ${JSON.stringify(p)}`);
});

test('#889 — a deterministically-erroring {= …} (cross-dimension convert) becomes a loud #ERR pill', () => {
  // mathPrepassErrs: the pre-pass INTRODUCED a #ERR (cross-dim convert), so it is a real
  // calculation that errors, not prose. Same-dim convert does NOT (it resolves to a number).
  assert.equal(c.mathPrepassErrs('convert(10, km, kg)'), true, 'cross-dimension → deterministic #ERR');
  assert.equal(c.mathPrepassErrs('convert(10, km, mi)'), false, 'same-dimension resolves, no #ERR');
  assert.equal(c.mathPrepassErrs('not math'), false, 'prose with no convert → not our #ERR');
  assert.equal(c.mathPrepassErrs('2 + I love #ERR'), false, 'a literally-typed #ERR is not the pre-pass sentinel');
  // classifyBraceBody: the cross-dim convert now classifies 'artifact' (was 'invalid' → raw braces on load)
  assert.equal(c.classifyBraceBody('= convert(10, km, kg)', {}, {}), 'artifact');
  assert.equal(c.classifyBraceBody('= convert(10, km, mi)', {}, {}), 'artifact');   // same-dim still promotes
  assert.equal(c.classifyBraceBody('= not math', {}, {}), 'invalid');               // prose escape hatch intact
  // makeMathResult creates the record so a pill exists to render #ERR
  const roll = c.makeMathResult('convert(10, km, kg)', {});
  assert.ok(roll && roll.key, 'a record is created for the deterministic error');
  assert.equal(roll.result, '#ERR');
  assert.equal(c.makeMathResult('not math', {}), null, 'genuine prose still returns null (stays literal)');
  // the rendered reason names the real cause, not a missing variable (km/kg would read as bad refs)
  assert.equal(c.mathErrorReason('#ERR', {}), 'convert');
  assert.match(c.mathReasonPhrase('convert'), /different kinds of units/);
});

test('parseQBaseSort + the qbase sort wiring (SV-2)', () => {
  const cols = [{ name: 'Point', field: 'title' }, { name: 'Due', field: 'due' }, { name: 'Left', field: '= cost * 2' }];
  // blank = document order; label OR field matches, case-insensitive; desc optional
  assert.equal(c.parseQBaseSort('', cols), null);
  assert.deepEqual(host(c.parseQBaseSort('Due desc', cols)), { col: 1, dir: 'desc' });
  assert.deepEqual(host(c.parseQBaseSort('due', cols)), { col: 1, dir: 'asc' });
  assert.deepEqual(host(c.parseQBaseSort('left ASC', cols)), { col: 2, dir: 'asc' });
  assert.equal(c.parseQBaseSort('nosuch', cols), undefined, 'unknown column is invalid, not silent');
  // mtSortOrder is the shared core; SV-1's mtSortRows delegates to it
  assert.deepEqual(host(c.mtSortOrder(host([['H'], ['b'], ['a'], ['c']]), 0, 'asc', null, host([]), 3)), [2, 1, 3]);
  assert.ok(/mtSortOrder\(rows, col, dir, role, seqs, lastDataRow\)/.test(fnBody(_src, 'mtSortRows')), 'one comparator, two consumers');
  // qbaseModel applies the configured sort inside the generation memo, rows+qids together
  const qm = fnBody(_src, 'qbaseModel');
  assert.ok(/node\.qbase\.sort/.test(qm) && /qbaseColRoles\(node\.qbase\.cols\)\[srt\.col\]/.test(qm),
    'the sort is role-aware, formula columns included');
  // the editor field round-trips + preserves showAll; the create path threads it; the strip names it
  assert.ok(/parseQBaseSort\(v\.sort, parseQBaseCols\(v\.cols\)\) !== undefined/.test(fnBody(_src, 'openQBaseDialog')),
    'an unknown sort column blocks the save with an explaining preview');
  const eq = fnBody(_src, 'editQBase');
  assert.ok(/\.\.\.\(sort \? \{ sort \} : \{\}\)/.test(eq) && /showAll: true/.test(eq), 'saving keeps sort AND showAll');
  assert.ok(/qbaseCreateAt\(nodeId, expr, cols, sort\)/.test(_src), 'the create dialog threads the sort');
  assert.ok(/mt-qbase-sort/.test(fnBody(_src, 'mtBaseChromeHtml')), 'the strip names an active sort');
});

// ── #1475: the Alignment section reported a state the grid was not in ───────
// After Show as > Number the cells render right-aligned, and the menu still showed "Left ✓" —
// because it coerced the model's UNSET alignment to 'left', while the renderer spelled the
// number-column rule a second time and rendered right. Clicking Left then worked, and there was no
// way back to the state the column had a moment earlier.
test('#1475 effectiveAlign is the one answer the menu and the grid share', () => {
  // an explicit alignment is the user's word, whatever the role says
  for (const role of nonEmpty([null, 'number', 'status', 'date'], 'column roles'))
    for (const a of nonEmpty(['left', 'center', 'right'], 'explicit alignments'))
      assert.equal(c.effectiveAlign(a, role), a, `${a} stands under role ${role}`);
  // UNSET is not 'left': a Number column renders right, which is the whole bug
  assert.equal(c.effectiveAlign(null, 'number'), 'right');
  assert.equal(c.effectiveAlign(undefined, 'number'), 'right');
  assert.equal(c.effectiveAlign('', 'number'), 'right');
  // and unset on anything else is left
  assert.equal(c.effectiveAlign(null, null), 'left');
  assert.equal(c.effectiveAlign(null, 'status'), 'left');
  assert.equal(c.effectiveAlign(null, 'date'), 'left');
  // a junk value is not passed through as a class name
  assert.equal(c.effectiveAlign('sideways', 'number'), 'right');
  assert.equal(c.effectiveAlign('sideways', null), 'left');

  // CALL SITES — one decision, two consumers, which is what makes the tick honest.
  const w = fnBody(_src, 'buildTableWidget');
  assert.match(w, /aCls\(effectiveAlign\(model\.aligns\[c\], _colRoles\[c\]\)\)/,
    'the cell renderer asks the shared core rather than re-spelling the rule');
  assert.ok(!/_colRoles\[c\] === 'number' && !model\.aligns\[c\]/.test(_src),
    'the second copy of the rule is gone');
  const scp = fnBody(_src, 'showColPanel');
  assert.match(scp, /const curAlign = model\.aligns\[colIdx\] \|\| null;/,
    'unset is its own state in the menu, not folded into left');
  assert.match(scp, /addItem\(`Automatic \(\$\{effectiveAlign\(null, curRole\)\}\)`/,
    'the auto row says what it resolves to, from the same core the grid uses');
  assert.match(scp, /\{ active: curAlign == null, onApply: \(\) => mtSetAlign\(node, colIdx, null\) \}/,
    'and selecting it is the route back that did not exist');
  // the confirmation copes with the unset case rather than saying "aligned null"
  assert.match(fnBody(_src, 'baseStructMessage'), /aligned automatically\. Undo restores it\./);
  // serializeTable already round-trips an unset alignment as `---`, which is what makes the
  // route back a real state and not a third explicit value
  assert.equal(host(c.serializeTable({ aligns: [null, 'left', 'right'], rows: [['a', 'b', 'c']] })).split('\n')[1],
    '| --- | :--- | ---: |');
});

// ── #1469: Sort and Calculate read the same column the same way ─────────────
// The reported symptom: a Cost column of 10 / 3 / 99 / 100 with no role set. Calculate →
// Sum answered 212; Sort → Ascending answered 10, 100, 3, 99. Both commands live in the
// same column menu, and they disagreed about whether the column held numbers or words.
test('#1469 an un-roled column of numbers sorts as numbers, and agrees with Calculate', () => {
  const rows = [['Item', 'Cost', 'Qty'],
                ['Rope', '10', '2'], ['Torch', '3', '5'], ['Anvil', '99', '1'], ['Lamp', '100', '7']];
  const col = (rr, cIdx, dir, role = null) =>
    host(c.mtSortOrder(host(rr), cIdx, dir, role, host([]), rr.length - 1)).map(i => rr[i][cIdx]);
  // the issue's own repro, both directions — numeric order, not 10 / 100 / 3 / 99
  assert.deepEqual(col(rows, 1, 'asc'), ['3', '10', '99', '100']);
  assert.deepEqual(col(rows, 1, 'desc'), ['100', '99', '10', '3']);
  // and the total over that same column, from the OTHER command in the menu
  const totalled = host(computeTable({ aligns: [null, null, null], rows: [...host(rows), ['', '', '']] },
    '@6$2=vsum(@2$2..@5$2)'));
  assert.equal(totalled[5][1], '212', 'Calculate reads 10+3+99+100; Sort now reads the same cells');

  // the gate is all-or-nothing: one word and the column keeps its text sort, where
  // alphabetical is the defensible answer (a partial numeric order would be a guess)
  const mixed = [['H', 'C'], ['a', '10'], ['b', '3'], ['c', 'apple']];
  assert.deepEqual(col(mixed, 1, 'asc'), ['10', '3', 'apple'], 'mixed stays text');
  // a plain text column is untouched by the change
  const words = [['H', 'C'], ['x', 'Torch'], ['y', 'Anvil'], ['z', 'Rope']];
  assert.deepEqual(col(words, 1, 'asc'), ['Anvil', 'Rope', 'Torch']);
  // blanks still sink in BOTH directions (missing data is not a small number)
  const blanks = [['H', 'C'], ['a', '10'], ['b', ''], ['c', '3']];
  assert.deepEqual(col(blanks, 1, 'asc'), ['3', '10', '']);
  assert.deepEqual(col(blanks, 1, 'desc'), ['10', '3', '']);

  // cellNum is Calculate's reading, lifted out unchanged: parseFloat, so "10 gold" is 10
  // (Calculate totals it as 10 too) and "$10" is nothing; blanks and null are nothing.
  assert.deepEqual([c.cellNum('10'), c.cellNum('  10.5 '), c.cellNum('10 gold'), c.cellNum('-2')],
    [10, 10.5, 10, -2]);
  assert.deepEqual([c.cellNum('$10'), c.cellNum(''), c.cellNum('   '), c.cellNum(null), c.cellNum(undefined)],
    [null, null, null, null, null]);
  // colIsNumeric: every non-empty cell must read, and an all-blank column is NOT numeric
  assert.equal(c.colIsNumeric(host(rows), 1, 4), true);
  assert.equal(c.colIsNumeric(host(mixed), 1, 3), false);
  assert.equal(c.colIsNumeric(host(blanks), 1, 3), true, 'blanks are skipped, not disqualifying');
  assert.equal(c.colIsNumeric(host([['H', 'C'], ['a', ''], ['b', '']]), 1, 2), false, 'no values, no claim');

  // CALL SITES — a tested core proves nothing about whether anything calls it right.
  // One numeric reading, two consumers: Calculate's literal() and Sort's gate.
  assert.match(fnBody(_src, 'computeTable'), /const literal = \(r, c\) => cellNum\(/,
    'Calculate reads cells through the shared rule, not a private copy');
  const so = fnBody(_src, 'mtSortOrder');
  assert.match(so, /const numericCol = !role && sortReading\(rows, col, role, lastDataRow\) === 'number'/,
    'Sort infers numeric ONLY when the user has set no role');
  assert.match(so, /if \(numericCol\) return cellNum\(v\)/, 'and keys those cells with the shared rule');
  // an explicit `number` role keeps Number(), because mtCellHtml FORMATS with Number():
  // sort order and displayed value must agree about the same column
  assert.match(so, /if \(role === 'number'\) \{ const n = Number\(v\)/);
  assert.match(fnBody(_src, 'mtCellHtml'), /role === 'number'\) \{\s*\n\s*const n = Number\(s\)/);
  // the sort door passes the roles through, so `role` is genuinely null on an un-roled base
  assert.match(fnBody(_src, 'mtSortBase'), /\(mtColRoles\(node\) \|\| \[\]\)\[colIdx\] \|\| null/);
});

// The issue's aggravator, and the reason it mattered: "Ascending" of WHAT? The two items said
// the same thing whichever reading was about to be applied, so the user had no way to know
// whether 100 would land above or below 3 — and for a while the answer was the wrong one.
test('#1469 the Sort menu names the reading it is about to apply, and the flash confirms it', () => {
  const nums  = [['H', 'C'], ['a', '10'], ['b', '3']];
  const words = [['H', 'C'], ['a', 'Rope'], ['b', 'Anvil']];
  // the decision: a set role is the user's word; with none, the data decides
  assert.equal(c.sortReading(host(nums), 1, null, 2), 'number');
  assert.equal(c.sortReading(host(words), 1, null, 2), 'text');
  assert.equal(c.sortReading(host(nums), 1, 'status', 2), 'status', 'a set role is never overridden');
  assert.equal(c.sortReading(host(nums), 1, 'date', 2), 'date');
  assert.equal(c.sortReading(host(words), 1, 'number', 2), 'number');
  // every reading has copy, and each reading's two directions differ — the whole point
  const readings = ['number', 'date', 'status', 'text'];
  const seen = new Set();
  for (const r of nonEmpty(readings, 'sort readings')) {
    const cp = host(c.sortReadingCopy(r));
    assert.ok(cp.as && cp.asc && cp.desc, `${r} names itself and both directions`);
    assert.notEqual(cp.asc, cp.desc, `${r}: the two items must not read identically`);
    for (const s of [cp.as, cp.asc, cp.desc]) {
      assert.ok(!/—|–/.test(s), 'AP punctuation only in user copy');
      assert.equal(seen.has(s), false, `"${s}" names exactly one thing`);
      seen.add(s);
    }
  }
  // an unknown reading degrades to text rather than rendering "undefined" at the user
  assert.deepEqual(host(c.sortReadingCopy('nonesuch')), host(c.sortReadingCopy('text')));
  // capFirst turns the mid-sentence phrase into a menu tooltip, and leaves "A to Z" alone
  assert.equal(c.capFirst('smallest number first'), 'Smallest number first');
  assert.equal(c.capFirst('A to Z'), 'A to Z');

  // CALL SITES — the menu names it BEFORE, the flash names it AFTER, from the same record
  const scp = fnBody(_src, 'showColPanel');
  assert.match(scp, /const sortCopy = sortReadingCopy\(sortReading\(model\.rows, colIdx, curRole, lastDataRow\)\)/);
  assert.match(scp, /addSection\(`Sort rows \(\$\{sortCopy\.as\}\)`, true\)/, 'the section names the reading');
  // CENSUS RATCHET over the family: a direction-only label ("Ascending" of what?) is exactly the
  // defect, so every menu item labelled with a bare direction must carry the reading beside it.
  // A third sort door added later without one fails here instead of shipping.
  const dirItems = [..._src.matchAll(/addItem\('(Ascending|Descending)',\s*\{([^}]*)\}/g)];
  assert.equal(nonEmpty(dirItems, 'direction-labelled menu items').length, 2,
    'the two Sort items are the whole family; a new one must be named too');
  for (const m of dirItems)
    assert.match(m[2], /title: capFirst\(sortCopy\.(asc|desc)\)/, `${m[1]} must say what it will do`);
  const sb = fnBody(_src, 'mtSortBase');
  assert.match(sb, /sortReadingCopy\(sortReading\(m\.rows, colIdx, \(mtColRoles\(node\) \|\| \[\]\)\[colIdx\] \|\| null, lastDataRow\)\)/);
  assert.match(sb, /Sorted rows by \$\{colName\}, \$\{dir === 'desc' \? sc\.desc : sc\.asc\}\./,
    'the confirmation names the reading that was applied, not just the direction');
  // the label stays the accessible NAME; the reading is a description beside it (P3-1: never
  // `title` alone), so "Ascending" still reads as "Ascending" to a screen reader
  const mb = fnBody(_src, 'mtMenuBuilder');
  assert.match(mb, /if \(title\) \{ item\.title = title; item\.setAttribute\('aria-description', title\); \}/);
  assert.match(mb, /item\.innerHTML = '<span class="mt-col-item-label">' \+ escHtml\(label\)/,
    'the visible label is still the name');

  // THE NEGATIVE CASE, pinned so the set is not "completed" by reflex. The other sort door is the
  // query base's, and it needs no reading beside it: it is a STATUS chip reporting an order already
  // applied to a rendering, naming its column and direction, not a pair of commands you choose
  // between without knowing what they mean. It routes through the same fixed core, so the ORDER it
  // produces was corrected by this change; only the naming is not its problem.
  assert.match(fnBody(_src, 'mtBaseChromeHtml'),
    /class="mt-qbase-sort">by \$\{escHtml\([\s\S]*?\)\} \$\{node\.qbase\.sort\.dir === 'desc' \? '↓' : '↑'\}/,
    'the query base reports its sort, it does not offer an unexplained choice');
  assert.match(fnBody(_src, 'qbaseModel'), /mtSortOrder\(rows, srt\.col,/, 'and it shares the corrected core');
});

// ── var: over projections (the last §7b deferral bar shadow markers) ─────────
test('var: matches projecting bases, hierarchically on dots', () => {
  // parser: dots admitted; still never a free-form key:value
  const t1 = host(c.parseSearchQuery('var:orc.hp'));
  assert.deepEqual(t1, [{ neg: false, kind: 'var', value: 'orc.hp' }]);
  assert.equal(host(c.parseSearchQuery('-var:orc'))[0].neg, true);
  // a projecting base matches by exact dotted name AND by segment prefix
  const vb = mkVarBase('| Name | HP |\n| --- | --- |\n| Orc | 12 |', 'Monsters');
  const hitExact = c.termMatchesNode({ neg: false, kind: 'var', value: 'monsters.orc.hp' }, vb);
  const hitPrefix = c.termMatchesNode({ neg: false, kind: 'var', value: 'monsters' }, vb);
  const miss = c.termMatchesNode({ neg: false, kind: 'var', value: 'goblin' }, vb);
  assert.equal(hitExact, true, 'exact dotted projection matches the base');
  assert.equal(hitPrefix, true, 'a name segment matches hierarchically (the #tag rule)');
  assert.equal(miss, false);
  // a plain declared variable still matches exactly; a reference pill (empty expr) never does
  const decl = c.mkNode('x [[var:k1]]'); decl.vars = [{ key: 'k1', name: 'strength', expr: '5' }];
  assert.equal(c.termMatchesNode({ neg: false, kind: 'var', value: 'strength' }, decl), true);
  const ref = c.mkNode('x [[var:k2]]'); ref.vars = [{ key: 'k2', name: 'strength', expr: '' }];
  assert.equal(c.termMatchesNode({ neg: false, kind: 'var', value: 'strength' }, ref), false);
});

// ── FR-1 per-role cell editors ───────────────────────────────────────────────
test('FR-1 editors — popover + menu doors + commit routing (source pins)', () => {
  const pop = fnBody(_src, 'showCellEditorPop');
  // roles gate the popover; anything else hides it (typing stays the primary path)
  assert.ok(/role !== 'date' && role !== 'status'/.test(pop), 'only Date/Status cells get a popover');
  assert.ok(/buildDatePicker\(/.test(pop), 'a date cell reuses the Schedule dialog calendar');
  assert.ok(/boardLanes\(/.test(pop) && /seq\.states/.test(pop), 'a status cell offers its owning sequence states');
  // the caret invariant: picks act on mousedown + preventDefault, focus BEFORE write
  assert.ok(/addEventListener\('mousedown', e => \{ e\.preventDefault\(\); write\(/.test(pop), 'state picks keep the cell focused');
  assert.ok(/cell\.focus\(\);\s*\/\/ focus FIRST|cell\.focus\(\);\s*\n\s*cell\.textContent = v/.test(pop.replace(/focus FIRST[^\n]*/, 'focus FIRST')), 'write focuses the cell before setting the value (a query focusin re-reads the model)');
  // both edit paths show it on focusin and hide it, deferred, on focusout
  // #955 extracted the cell edit/nav handlers into mtWireCells so a non-table view could call
  // them. They are one unit of behaviour that now lives in two functions, so the slice is both
  // — these pins are about what the handlers DO, not which function declares them.
  const btw = fnBody(_src, 'buildTableWidget') + fnBody(_src, 'mtWireCells');
  assert.ok(/showCellEditorPop\(node, cell\)/.test(btw), 'authored focusin shows the popover');
  assert.ok(/scheduleCellPopHide\(cell\)/.test(btw), 'authored focusout schedules the hide');
  const w = fnBody(_src, 'mtWireQBaseEdit');
  assert.ok(/showCellEditorPop\(node, cell\)/.test(w) && /scheduleCellPopHide\(cell\)/.test(w), 'query cells get the same treatment');
  assert.ok(/_focusGrid/.test(w), 'a query date cell has a keyboard door into the grid');
  // the keyboard doors in the cell context menu route through the ONE cell writer
  const scp = fnBody(_src, 'showColPanel');
  assert.ok(/addSection\('Set to', true\)/.test(scp) && /mtSetCellValue\(node, rowIdx, colIdx, kw\)/.test(scp), 'a status cell lists its states in the menu');
  assert.ok(/Pick a date \(calendar\)/.test(scp), 'a date cell opens the calendar from the menu');
  // the menu writer routes by base kind: authored -> model + epilogue; query -> Phase C
  const sv = fnBody(_src, 'mtSetCellValue');
  assert.ok(/mtCommit\(node, m\);\s*\n\s*mtCommitEpilogue\(node\)/.test(sv), 'authored writes commit + run the epilogue');
  assert.ok(/qbaseFieldWritable\(field\)/.test(sv) && /setProp\(src, field, val\)/.test(sv) && /pushUndo/.test(sv), 'query writes go through the Phase C path, undo-local');
  // #1123: the context menu is a SECOND, independent write site. Fixing the focusout commit does
  // not fix this one, so it carries its own routing pins.
  assert.ok(/const route = propWriteRoute\(field, val\)/.test(sv), 'the menu writer routes a reserved date too');
  assert.ok(/if \(route === 'date'\) setDateProp\(src, field\.trim\(\)\.toLowerCase\(\), val\)/.test(sv), 'a date reaches the validated writer');
  assert.ok(sv.indexOf("route === 'baddate'") > 0 && sv.indexOf("route === 'baddate'") < sv.indexOf('pushUndo()'),
    'the menu refusal also returns before pushUndo');
  assert.ok(/no longer matches this query/.test(sv), 'a membership-breaking menu write is announced');
});

// ── IA-1: a base converts back to text (freedom of form) ─────────────────────
test('baseToStaticText — authored base round-trips as a static table; wiring (IA-1)', () => {
  // authored base: cells + the #+TBLFM recipe are preserved (the static table still computes)
  const authored = { type: 'base', text: '| A | B |\n| --- | --- |\n| 1 | 2 |\n#+TBLFM: @>$2=vsum(@2$2..@2$2)' };
  const out = c.baseToStaticText(authored);
  assert.ok(/\| A \| B \|/.test(out) && /\| 1 \|/.test(out), 'the grid survives');
  assert.ok(/#\+TBLFM:/.test(out), 'the formula recipe is kept, so the static table still computes');
  // a base with no recipe: just the grid, no trailing tblfm line
  const plain = { type: 'base', text: '| X |\n| --- |\n| a |' };
  assert.ok(!/#\+TBLFM:/.test(c.baseToStaticText(plain)), 'no recipe, no tblfm line');
  // authored path is pure (delegates to baseRecipeMarkdown); the qbase arm is browser-verified
  assert.ok(/node\.qbase \? serializeTable\(mtModel\(node\)\) : baseRecipeMarkdown\(node\.text\)/.test(fnBody(_src, 'baseToStaticText')),
    'qbase freezes its projection; authored keeps its cells + recipe');
  // the mutator drops every base view-state field, re-derives the type, prunes, is undoable
  const cbt = fnBody(_src, 'convertBaseToText');
  assert.ok(/pushUndo\(\)/.test(cbt), 'undoable — one Ctrl/Cmd+Z restores the base');
  assert.ok(/delete node\.qbase; delete node\.varbase; delete node\.view;/.test(cbt)
    && /delete node\.colRole; delete node\.colW; delete node\.colFmt; delete node\.baseRows;/.test(cbt),
    'every base view-state field is dropped');
  assert.ok(/node\.type = deriveTypeFromText\(node\.text\) \|\| 'ul'/.test(cbt), 'the node becomes a normal point');
  assert.ok(/pruneArtifacts\(node\)/.test(cbt), 'orphaned sidecar records are shed; frozen pill records stay');
  // the door: a primary base-menu action wired to the mutator (leaving is as discoverable as entering)
  assert.ok(/sec:'Base', prim:true, icon: \{ fa:'fa-solid fa-file-lines'.*\n?\s*label: 'Convert to text'/.test(_src)
    || /label: 'Convert to text',\s*\n\s*fn: \(\) => \{ hideBpop\(\); convertBaseToText\(nodeId\); \}/.test(_src),
    'the Convert to text door exists and calls convertBaseToText');
});

