test('DIAL: STANDARD + LEAN strip the teaching text (hints, search legend, pill tooltips); guided keeps it', () => {
  // 1. empty-state hints track the dial (agent-review: Standard dropped its short whisper too, so
  // this is now a two-way Guided-only split — Standard and Lean both show nothing).
  assert.ok(_src.includes("const entryHint = isGuided() ? 'Write, format with /, insert with @, or make a live pill with {' : '';"),
    'the entry hint must be Guided-only (Standard/Lean show nothing)');
  assert.ok(/const paraHint\s+= isGuided\(\) \? 'Prose block\. Enter = line break/.test(_src),
    'the para hint must be Guided-only (Standard/Lean show nothing)');
  assert.ok(!_src.includes("'Write, or / to format'"), 'the old Standard-tier whisper must be gone, not just unreachable');
  // 2. the search legend rows strip in standard + lean; saved searches / cross-doc matches (data) stay.
  // #586: the gate is written fail-OPEN (name the tiers that hide, not "not guided"), so a classless
  // fresh boot shows the guided aid instead of hiding all rows on a body that has no v-* class yet.
  assert.ok(_src.includes('body.v-standard #search-hint .sh-row, body.v-lean #search-hint .sh-row{display:none}'),
    'the legend rows must strip in standard + lean, via the fail-open v-standard/v-lean gate (#586)');
  assert.ok(!/#search-hint \.sh-row\{display:none\}/.test(_src.replace('body.v-standard #search-hint .sh-row, body.v-lean #search-hint .sh-row{display:none}', '')),
    'the strip gate must be tier-scoped, never an unconditional hide');
  assert.ok(!/\.v-(standard|lean)\s+#sh-saved/.test(_src), 'must NOT hide saved searches — only the .sh-row legend');
  // #586: the default (guided) verbosity class is painted at boot, so the cheatsheet shows on a
  // fresh boot (no autosave to trigger the restore-arm sync). Pin the boot call.
  assert.ok(/ensureDocId\(root\);\s*\n\s*syncVerbosityClass\(\);/.test(_src),
    'syncVerbosityClass() must run at boot (next to ensureDocId), or a fresh boot has no v-* class');
  // 3. pill tooltips (title=) strip in standard + lean via the post-render sweep; scoped to PILL classes
  assert.ok(_src.includes('if (isStandardOrLean()) {') && _src.includes("[class$=\"-edit\"][title]"), 'the pill-tooltip strip sweep is missing');
  assert.ok(_src.includes('.node-content .dice-roll[title]'), 'the tooltip sweep must target the pill classes');
  // 4. the 'Section label…' placeholder is a LABEL not a helper — it survives every tier (over-strip guard)
  assert.ok(_src.includes("isDivider ? 'Section label…' : node.type === 'para' ? paraHint"), 'the Section label placeholder must survive (it names the field, not a helper)');
  // 5. agent-review: the floating help pill (#sc-toggle) follows .bm-help's own Lean-only-hides rule
  assert.ok(_src.includes('body.v-lean #sc-toggle{display:none}'), 'the floating help pill must hide in Lean, like .bm-help');
  // 6. Lean is framed as the reading mode: its Settings-card desc names the reading surface (the toolbar
  // recede + hidden chrome IS the distraction-free read; no separate reading mode, no new affordance).
  assert.ok(/data-tier="lean"[\s\S]{0,200}?fm-choice-desc">A quiet reading surface:/.test(_src),
    "the Lean tier's Settings-card description frames it as a reading surface");
  assert.ok(/body\.v-lean #toolbar\{\s*transform:translateY/.test(_src),
    'the Lean toolbar-recede that makes it a reading surface is present (the copy describes real behavior)');
});

test('spellcheck policy: prose surfaces underline, syntax/query/data fields do not (src pins)', () => {
  // PROSE editors spellcheck ON: the point editor (off only for a base/table point, which holds
  // data), the footnote editor, the per-point note, and the capture/journal/chronicle quick-adds.
  assert.ok(_src.includes('content.spellcheck = !isTable'), 'the point editor spellchecks prose, not a base/table point (data)');
  assert.ok(_src.includes('contentEl.spellcheck = true'), 'the footnote editor (prose) must spellcheck');
  assert.ok(_src.includes('noteEl.spellcheck = true'), 'the per-point note (prose) must spellcheck explicitly, not by inherited default');
  assert.ok((_src.match(/input\.spellcheck = true/g) || []).length >= 3, 'the capture / journal / chronicle prose inputs spellcheck');
  // SYNTAX / QUERY / NAME fields stay OFF (a red underline on hp, gp, {= …} or is:todo is noise).
  assert.ok(/id="search-box"[^>]*spellcheck="false"/.test(_src), 'the search box (a query) does not spellcheck');
  assert.ok(/id="file-name"[^>]*spellcheck="false"/.test(_src), 'the file name does not spellcheck');
  assert.ok(_src.includes('exprInp.spellcheck = false'), 'a math/expression field does not spellcheck');
  assert.ok(_src.includes('rulesIn.spellcheck = false') && _src.includes('varsIn.spellcheck = false'), 'grammar/variable syntax fields do not spellcheck');
});

// item 3 (modes batch): the search-hint card opens only with content (never an empty rectangle),
// is gone entirely in Lean, and its example chips are clickable in Guided.
test('modes batch — search-hint tiered display + clickable examples', () => {
  // Guided (and a classless fresh boot) always open the panel on focus (the cheatsheet is content).
  assert.ok(_src.includes('body:not(.v-standard):not(.v-lean) #search-wrap:focus-within #search-hint{display:block}'),
    'Guided/classless must open the search-hint on focus');
  // Standard AND Lean open ONLY with live data (saved searches or cross-doc hits) — no empty rectangle,
  // and no cheatsheet, but saved searches stay reachable (a user must be able to recall what they saved).
  // #sh-invalid joins both gates: a filter the app cannot read is a FACT, not a helper you can
  // silence by switching tier. Omitting it here would hide the explanation in two tiers of three,
  // which is the same shape as the bug it explains.
  assert.ok(_src.includes('body.v-standard #search-wrap:focus-within #search-hint:has(#sh-saved:not([hidden]),#sh-workspace:not([hidden]),#sh-invalid:not([hidden]))'),
    'Standard must open the panel only when saved searches, cross-doc hits or an invalid filter exist (no empty rectangle)');
  assert.ok(_src.includes('body.v-lean #search-wrap:focus-within #search-hint:has(#sh-saved:not([hidden]),#sh-workspace:not([hidden]),#sh-invalid:not([hidden]))'),
    'Lean must still open the panel for saved searches / cross-doc data / an invalid filter');
  // the old UNCONDITIONAL opener (a bare selector, no body-class prefix) is retired: every opener now
  // leads with a body tier gate, so the cheatsheet never pops in Standard/Lean.
  assert.ok(!/(^|\n)#search-wrap:focus-within #search-hint\{display:block\}/.test(_src),
    'the old unconditional focus-within opener must be gone (the cheatsheet never pops in Standard/Lean)');
  // the example chips are clickable in Guided (pointer-events re-enabled on the kbd), border-highlight on hover.
  // #1511 scoped this to the FILTER chips: five trailing rows document authoring syntax and are not
  // doors, so they must not read as clickable. Same claim, narrower subject.
  assert.ok(_src.includes('body:not(.v-standard):not(.v-lean) #search-hint .sh-row kbd:not([data-doc]){pointer-events:auto;cursor:pointer}'),
    'Guided example chips must be clickable (pointer-events re-enabled on the kbd)');
  assert.ok(_src.includes('#search-hint .sh-row kbd[data-doc]{cursor:default'),
    'and a documentation sample must not look like one of them');
  // the applier stacks the token onto the search box and keeps focus (the saved-chip mousedown model).
  // fnBody, not a byte window: the old pin sliced a fixed 1100 bytes, which is exactly the brittle
  // shape this file's header warns about — the roving-tabindex keydown pushed the assertions past
  // the cut and turned a behaviour-preserving insert into a false red.
  const wire = fnBody(_src, 'wireSearchExamples');
  assert.ok(wire, 'wireSearchExamples must exist');
  // #1513 split the applier in two: the stacking is unchanged (`head` is the old inline
  // `cur ? cur + ' ' : ''`), and an OPERATOR chip still runs the search at once. The template
  // branch is pinned separately, below; this assertion keeps the operator claim it always made.
  assert.ok(wire.includes("const head = cur ? `${cur} ` : ''") && wire.includes('sb.value = head + tok')
            && wire.includes('applySearch(sb.value)'),
    'clicking an example must add its token to the search box and run the search');
  assert.ok(wire.includes("e.preventDefault()") && wire.includes("k.setAttribute('role', 'button')"),
    'example chips must keep the caret (mousedown preventDefault) and carry role=button');
  // the apply path the chips exist for stays keyboard-reachable alongside the pointer path
  assert.ok(/if \(e\.key !== 'Enter' && e\.key !== ' '\) return;[\s\S]{0,200}applyExample\(k\.textContent\)/.test(wire),
    'Enter/Space on a chip must still insert its token');
});

// ROVING TABINDEX on the search legend. 48 chips used to each carry tabindex="0", so a Guided
// keyboard user Tabbing off the search box walked 48 stops to reach the next real control, with no
// arrow alternative and no Escape (measured: Escape from a chip did nothing at all). One tab stop
// now; arrows move within the group. Source pins prove the wiring is PRESENT — the focus movement
// itself was driven in a headless browser (the #1021 lesson).
test('search legend chips are ONE tab stop with arrow navigation (roving tabindex)', () => {
  const wire = fnBody(_src, 'wireSearchExamples');
  // THE FIX: exactly one chip seeded 0, every other -1. A plain `'0'` for all is the bug.
  assert.ok(wire.includes("k.setAttribute('tabindex', i === 0 ? '0' : '-1')"),
    'only the FIRST chip may be a tab stop; the rest must be tabindex="-1"');
  assert.ok(!/k\.setAttribute\('tabindex', '0'\)/.test(wire),
    'no unconditional tabindex="0" seeding may survive (that is the 48-stop bug)');
  // the swap: leaving chip drops to -1, arriving chip takes 0 and focus. Without the swap the
  // group loses its tab stop entirely and Tab can never re-enter it.
  assert.ok(/const rove = \(from, to\) => \{[\s\S]{0,260}from\.setAttribute\('tabindex', '-1'\)[\s\S]{0,120}to\.setAttribute\('tabindex', '0'\)[\s\S]{0,60}to\.focus\(\)/.test(wire),
    'rove() must move the tab stop (-1 on the old, 0 on the new) and focus the new chip');
  // all six keys are handled on the container
  for (const k of ['ArrowRight', 'ArrowLeft', 'ArrowDown', 'ArrowUp', 'Home', 'End']) {
    assert.ok(wire.includes(`'${k}'`), `${k} must be handled in the legend keydown`);
  }
  assert.ok(wire.includes("if (e.key === 'ArrowRight') to = all[i + 1]") && wire.includes("else if (e.key === 'ArrowLeft') to = all[i - 1]"),
    'Left/Right walk the FLAT document order (the rows are ragged, so there is no column count)');
  assert.ok(wire.includes("else if (e.key === 'Home') to = all[0]") && wire.includes("else if (e.key === 'End') to = all[all.length - 1]"),
    'Home/End reach the ends of the whole group, matching the calendar grid and the builder');
  assert.ok(/rows\[r \+ \(e\.key === 'ArrowDown' \? 1 : -1\)\]/.test(wire) && wire.includes(".querySelector('kbd')"),
    'Up/Down must jump to the first chip of the adjacent .sh-row');
  assert.ok(wire.includes('rove(k, to)'), 'every arrow move must go through rove()');
  // ESCAPE RESOLVES OUTWARD, ONE LEVEL (P1-3): chip -> search box WITHOUT clearing. A second
  // Escape then hits the search box's own handler, which clears and restoreChromeReturn()s. If
  // this branch ever cleared, the two-level resolution would collapse and the query would be lost.
  const esc = wire.slice(wire.indexOf("if (e.key === 'Escape')"));
  assert.ok(/if \(e\.key === 'Escape'\) \{ e\.preventDefault\(\); document\.getElementById\('search-box'\)\.focus\(\); return; \}/.test(wire),
    'Escape on a chip must return focus to the search box and nothing else');
  assert.ok(!/if \(e\.key === 'Escape'\)[\s\S]{0,160}(value = ''|applySearch\(''\)|restoreChromeReturn)/.test(esc),
    'Escape on a chip must NOT clear the query — that is the SECOND Escape, on the search box');
  // the seeding pass must not spread the NodeList: it runs at load, and the headless harness's
  // document stub is forEach-able but NOT iterable, so a spread throws mid-file and strands every
  // later `let` in TDZ (14 unrelated-looking failures, none pointing at this line).
  // #1511 moved the selector into CHIP_SEL (documentation rows are excluded); the forEach claim is
  // unchanged and is the half that matters here.
  assert.ok(wire.includes("hint.querySelectorAll(CHIP_SEL).forEach((k, i) =>"),
    'the load-time seeding pass must use forEach on the NodeList, not a spread');
  assert.match(wire, /const CHIP_SEL = '\.sh-row kbd:not\(\[data-doc\]\)';/,
    'and the one selector every reader shares, so a door and a sample cannot be confused again');
});

// #1513: TWELVE legend chips are TEMPLATES, not operators. Their labels carry a placeholder only
// the author can fill (`key:value`, `#tag`, `-term`, `start:<date`, `a | b`, ...), and the blanket
// wiring pasted each literally with a COLLAPSED caret and ran it -- so the app wrote a teaching
// string and then delivered a verdict on it. Eight answered "0 matching points" and blanked the
// outline; `-term` and `a | b` answered a confident "3 matching points" (every point, by accident);
// `start:<date` blamed the user for the string it had just typed for them. The @ Query dialog's own
// chips already had the right idiom -- paste, SELECT the placeholder, run nothing -- and `#tag`
// exists on both surfaces byte-for-byte, which is the P1 breach on its own.
//
// The map is explicit because no heuristic separates `has:key` (template) from `has:tag`
// (operator) or `key:value` (template) from `priority:A` (operator). The census below is the
// ratchet: every interactive chip must be classified one way or the other.
test('#1513 a legend chip whose label carries a placeholder is a template, not a query', () => {
  const { chipTemplateSpan, chipTemplateSay, chipAriaLabel, chipTemplateLabels } = c;
  // ---- 1. the twelve, by value. slice(start,end) is the placeholder, so the span is usable.
  const EXPECT = {
    '#tag': 'tag', '#tag/sub': 'tag/sub', 'start:<date': 'date', '-term': 'term',
    '"a b"': 'a b', 'a | b': 'a', 'has:key': 'key', 'key:value': 'key', 'key:>N': 'key',
    'key:<=N': 'key', 'state:value': 'value', 'var:name': 'name',
  };
  for (const [label, ph] of Object.entries(EXPECT)) {
    const t = chipTemplateSpan(label);
    assert.ok(t, `${label} must be recognised as a template`);
    assert.equal(t.ph, ph, `${label} selects the wrong placeholder`);
    assert.equal(label.slice(t.start, t.end), ph, `${label}: the span must cover the placeholder`);
  }
  // MEASURE THE NEGATIVE CASE. These read like metasyntax to a heuristic and are complete
  // operators; converting one would stop a working filter from filtering.
  for (const op of ['is:todo', 'has:tag', 'priority:A', 'priority:none', 'due:week', 'is:leaf',
                    'is:duplicate-title', 'has:dice', 'due:overdue', 'is:unscheduled']) {
    assert.equal(chipTemplateSpan(op), null, `${op} is a complete operator and must still filter`);
  }
  assert.equal(chipTemplateSpan(''), null, 'an empty label is not a template');
  assert.equal(chipTemplateSpan(null), null, 'a missing label is not a template');
  assert.equal(chipTemplateSpan('key:value '), null, 'lookup is exact, not fuzzy');

  // ---- 2. CENSUS RATCHET. Every interactive chip in the legend is classified. A new row that is
  // neither listed here nor in CHIP_TEMPLATES fails this, which is the only thing that stops the
  // next placeholder chip from shipping with the old behaviour.
  const legend = nonEmpty([..._src.matchAll(/<div class="sh-row">([\s\S]*?)<\/div>/g)]
    .flatMap(m => [...m[1].matchAll(/<kbd(\s[^>]*)?>([\s\S]*?)<\/kbd>/g)])
    .filter(m => !(m[1] || '').includes('data-doc'))
    .map(m => m[2].replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&amp;/g, '&')),
    'the legend must have interactive chips to classify');
  const OPERATORS = new Set([
    'has:tag', 'is:todo', 'is:done', 'is:note', 'is:failing', 'is:passing', 'is:scheduled',
    'is:unscheduled', 'is:overdue', 'is:held', 'is:leaf', 'is:parent', 'is:collapsed',
    'is:expanded', 'is:pill', 'is:random', 'has:dice', 'has:children', 'has:footnote', 'has:link',
    'has:backlink', 'is:broken', 'is:empty', 'is:orphan', 'is:duplicate-title',
    'is:recently-edited', 'due:today', 'due:overdue', 'due:week', 'due:month', 'priority:A',
    'priority:none',
  ]);
  const templates = new Set(chipTemplateLabels());
  const unclassified = legend.filter(l => !templates.has(l) && !OPERATORS.has(l));
  assert.deepEqual(unclassified, [],
    'every interactive legend chip must be classified as a template or a complete operator');
  const dead = [...templates].filter(l => !legend.includes(l));
  assert.deepEqual(dead, [], 'CHIP_TEMPLATES must not name a chip the legend no longer shows');
  const staleOps = [...OPERATORS].filter(l => !legend.includes(l));
  assert.deepEqual(staleOps, [], 'this operator list must not name a chip the legend no longer shows');
  // and the two halves do not overlap: a chip either filters or teaches, never both.
  assert.deepEqual([...templates].filter(l => OPERATORS.has(l)), [],
    'a chip cannot be a template AND a complete operator');

  // ---- 3. THE DECISIVE P1 EVIDENCE. `#tag` exists on BOTH surfaces byte-for-byte and used to
  // behave two ways: the dialog left [1,4] and ran nothing, the legend left [4,4] and applied it.
  // The dialog's span is `insertAndSelect(el, '#', 'tag', '')` -- head '#', word 'tag' -- so the
  // parity claim is span-for-span, not "both exist".
  const dlg = /\{ label:'#tag',[^\n]*insert: el => insertAndSelect\(el, '(.*?)', '(.*?)', '(.*?)'\)/.exec(_src);
  assert.ok(dlg, "the @ Query dialog's #tag chip must still be an insertAndSelect");
  const legendTag = chipTemplateSpan('#tag');
  assert.equal(legendTag.start, dlg[1].length, '#tag must select at the same offset on both surfaces');
  assert.equal(legendTag.end, dlg[1].length + dlg[2].length, '#tag must select the same length on both surfaces');
  assert.equal(legendTag.ph, dlg[2], '#tag must select the same word on both surfaces');
  // the `key:` family coincides too: the dialog selects `key` first, so the legend does the same.
  const dlgKey = /\{ label:'key:',[^\n]*insert: el => insertAndSelect\(el, '(.*?)', '(.*?)', '(.*?)'\)/.exec(_src);
  assert.ok(dlgKey, "the @ Query dialog's key: chip must still be an insertAndSelect");
  assert.equal(chipTemplateSpan('key:value').ph, dlgKey[2],
    'the legend and the dialog must select the same half of a key:value template first');

  // ---- 4. P4: picking a template says what landed and what to do. Not a silent no-op.
  const say = chipTemplateSay('key:>N');
  assert.ok(say.includes('key:>N'), 'the announcement names what was inserted');
  assert.ok(say.includes('"key"'), 'the announcement names the placeholder to type over');
  assert.match(say, /not a filter yet/, 'the announcement says the search has NOT run');
  assert.equal(chipTemplateSay('is:todo'), null, 'a complete operator has no template announcement');
  // every template can say its own sentence (no map entry produces a broken one)
  for (const label of chipTemplateLabels()) {
    const m = chipTemplateSay(label);
    assert.ok(m && m.includes(label) && m.includes('"' + chipTemplateSpan(label).ph + '"'),
      `${label} must announce its own placeholder`);
  }

  // ---- 5. the door's own name changes with its behaviour: "Add X to the search" was a promise a
  // template chip did not keep.
  assert.equal(chipAriaLabel('is:todo'), 'Add is:todo to the search');
  assert.equal(chipAriaLabel('key:value'), 'Insert the key:value template into the search');
  assert.notEqual(chipAriaLabel('key:value'), chipAriaLabel('is:todo').replace('is:todo', 'key:value'));

  // ---- 6. THE CALL SITES. A classified map proves nothing if the wiring ignores it.
  const wire = fnBody(_src, 'wireSearchExamples');
  assert.ok(wire.includes("k.setAttribute('aria-label', chipAriaLabel(k.textContent))"),
    'the seeding pass must take its aria-label from chipAriaLabel, not a hardcoded template');
  assert.ok(!/aria-label', `Add \$\{k\.textContent\} to the search`/.test(wire),
    'the old unconditional "Add <token> to the search" label must be gone');
  // the exact line, not a window around it: `if (false) k.setAttribute(...)` satisfies any
  // proximity regex while stamping nothing, and its mutant survived until this was tightened.
  assert.ok(wire.includes("const t = chipTemplateSpan(k.textContent);\n    if (t) k.setAttribute('data-tmpl', t.ph);"),
    'a template chip must carry its placeholder in data-tmpl');
  // the applier: template branch selects the placeholder OFFSET BY THE STACKED HEAD, announces,
  // and RETURNS before applySearch. The head offset is the half that breaks when a chip is added
  // to a query that already has terms.
  const applier = between(wire, 'const applyExample = tok =>', '};');
  assert.ok(applier.includes('const t = chipTemplateSpan(tok)'), 'the applier must classify the token');
  assert.ok(applier.includes('sb.setSelectionRange(head.length + t.start, head.length + t.end)'),
    'the template selection must be offset by the already-stacked query, not anchored at 0');
  assert.ok(applier.includes('announce(chipTemplateSay(tok))'), 'a template chip must announce');
  assert.ok(/if \(t\) \{[\s\S]{0,700}return;\s*\}\s*applySearch\(sb\.value\)/.test(applier),
    'the template branch must RETURN before applySearch -- running the template is the bug');
  // and the operator path is untouched: still applies, still collapses the caret at the end.
  assert.ok(/applySearch\(sb\.value\);\s*sb\.focus\(\);\s*const n = sb\.value\.length; sb\.setSelectionRange\(n, n\);/.test(applier),
    'a complete operator must still run the search and leave the caret at the end');
});

// item 8 (modes batch): the { grammar picker matches the lean / and @ commands — a one-line tip.
test('modes batch — lean { picker shows the one-line tip, like / and @', () => {
  assert.ok(_src.includes('function renderLeanBraceTip('), 'renderLeanBraceTip (the lean { tip) is missing');
  // both trigger paths (forms + body) switch to the tip in lean instead of the full DOM menu
  assert.ok(/if \(isLean\(\)\) \{ renderLeanBraceTip\(\); return; \}/.test(_src), 'checkBraceTrigger must show the lean tip instead of the full menu');
  assert.ok(_src.includes('if (isLean()) renderLeanBraceTip(); else renderBraceMenu();'), 'braceMove must update the lean tip in lean');
  // the tip drives the SHARED #lean-slash-tip element (one lean voice across the inline pickers)
  assert.ok(/function renderLeanBraceTip\(\)[\s\S]{0,500}leanSlashTip\.classList\.add\('on'\)/.test(_src),
    'the lean { tip must drive the shared #lean-slash-tip element');
  // key routing works in lean (the DOM menu is not open, so route on state, like the slash menu)
  assert.ok(_src.includes('braceState && (isBraceMenuOpen() || isLean())'), 'brace key routing must work in lean (state-based)');
});

// item 9 (modes batch): the lean bullet hover menu is reduced to four ops; "More" is transient in lean.
test('modes batch — lean bullet menu reduced to four ops, transient More', () => {
  // Anchored on the declaration that FOLLOWS it, not a magic byte count: a fixed window silently
  // drops the tail of the function the day a menu row is added above it (it did, on #955).
  const fn = between(_src, 'function showBulletPopup(', 'function scheduleBpopHide()');
  // the four lean-tier ops are flagged lean:true — Zoom + Collapse(para) + Note + Dates + Delete = 5 markers
  assert.ok((fn.match(/lean:true/g) || []).length >= 5, 'the lean-tier ops must be flagged lean:true (Zoom/Collapse, Note, Dates, Delete)');
  // a lean hover filters to the lean-tier rows; guided/standard keep the primary set
  assert.ok(fn.includes('leanCollapsed ? actions.filter(a => a.lean) : actions.filter(a => a.prim)'),
    'a lean hover must filter to the lean-tier rows');
  // lean ignores the sticky expand flag, and the type switcher is hidden in a lean-collapsed hover
  assert.ok(fn.includes('(bpopExpanded && !isLean())'), 'lean must ignore the sticky bpopExpanded flag');
  // #1116 re-anchored: this matched the condition's exact spelling, and the condition gained a term
  // (`&& !opts.pillScope`, so a pill-scoped menu drops point-level chrome). The INTENT is unchanged
  // and still load-bearing, so it is pinned on `leanCollapsed` gating the switcher, not on the
  // literal conjunction. Third pin in this change to break on spelling rather than behaviour.
  assert.match(fn, /if \(!isBase && !leanCollapsed[^)]*\) \{\s*\n?\s*(\/\/[^\n]*\n\s*)*\/\/ type switcher row/,
    'the type switcher must hide in a lean-collapsed hover');
  // "More" is transient in lean (opts.expand, this-open only), sticky in guided/standard (bpopExpanded)
  assert.ok(fn.includes('if (!isLean()) bpopExpanded = true;') && fn.includes('{ ...opts, expand: true }'),
    'More must be transient in lean (opts.expand) and sticky in guided/standard (bpopExpanded)');
});

test('#616 real bugs: platform MOD in verbosity toasts, conjugated rename announce, Ctrl/Cmd order', () => {
  // Bug 1: VERBOSITY_FLASH builds the chord from the platform MOD, never a hardcoded Mac glyph a
  // non-Mac user can't press. MOD is defined ABOVE the object so the template can reference it.
  assert.ok(_src.includes('${MOD}+⇧+. to quiet them.'), 'the guided toast must use the platform MOD chord');
  assert.ok(_src.includes('${MOD}+⇧+. for Lean.') && _src.includes('${MOD}+⇧+. cycles.'), 'all three toasts use MOD');
  assert.ok(!/'[^']*⌘⇧\. (to quiet them|for Lean|cycles)/.test(_src), 'no hardcoded ⌘⇧. chord survives in a flash string');
  const modAt = _src.indexOf("const MOD = IS_MAC");
  const flashAt = _src.indexOf('const VERBOSITY_FLASH');
  assert.ok(modAt !== -1 && modAt < flashAt, 'MOD must be defined before VERBOSITY_FLASH (no TDZ)');
  // Bug 2: the variable-rename announcements conjugate the verb on the count (no "1 reference now show").
  assert.ok(_src.includes("now show${refs === 1 ? 's' : ''}"), 'the "Updated" announce must conjugate show/shows');
  assert.ok(_src.includes("that reference${refs === 1 ? 's' : ''} ${nm} now show${refs === 1 ? 's' : ''}"),
    'the confirm message must conjugate reference/references and show/shows');
  // Bug 3: cross-platform keybind order is Ctrl/Cmd, not Cmd/Ctrl, in every user-facing string.
  // (Comments may still say Cmd/Ctrl; the guard is on quoted UI copy and outline demo text.)
  assert.ok(!/Ctrl\/Cmd\+B, I or U[\s\S]*?Cmd\/Ctrl/.test(_src), 'the inline-md GUIDE body uses Ctrl/Cmd order');
  assert.ok(!/text="[^"]*Cmd\/Ctrl\+/.test(_src), 'no demo-outline text uses the Cmd/Ctrl order');
});

// ── LEAN FLOOR phase 3: Alt+Arrow moves a base column/row (keyboard, no menu; DOM-bound → src-pinned) ──
test('LEAN-FLOOR p3: the Alt+Arrow column/row move wiring is present in the cell keydown', () => {
  // Alt+Arrow must move the focused column (left/right) or row (up/down) via the existing mtMoveCol/
  // mtMoveRow, then re-focus the moved cell. Bounds are guarded (header row 0 / footer / edges).
  // REWRITTEN for #1400, not loosened. The landing moved INTO the ops, because the MENU doors --
  // the other way to reach the same write -- left focus on <body> and said nothing. The keyboard
  // door keeps its own cross-axis coordinate, so Alt+Arrow still leaves you in your own row/column.
  assert.ok(_src.includes('mtMoveCol(node, c, -1, r)'), 'Alt+Left column-move-left wiring missing');
  assert.ok(_src.includes('mtMoveCol(node, c, 1, r)'), 'Alt+Right column-move-right wiring missing');
  assert.ok(_src.includes('mtMoveRow(node, r, -1, c)'), 'Alt+Up row-move-up wiring missing');
  assert.ok(_src.includes('mtMoveRow(node, r, 1, c)'), 'Alt+Down row-move-down wiring missing');
  const kb = between(NC, "e.altKey && !e.ctrlKey && !e.metaKey && !e.shiftKey && e.key.startsWith('Arrow')",
    "e.altKey && !e.ctrlKey && !e.metaKey && (e.key === 'r'");   // stop before Alt+R, which legitimately stays put
  assert.ok(!/mtFocusCell/.test(kb), 'and the keyboard door keeps no duplicate landing of its own');
  // the guard: Alt+Up only when r > 1 (row 0 is the header, never movable), Alt+Down only below the last data row
  assert.ok(_src.includes("e.key === 'ArrowUp' && r > 1"), 'Alt+Up must protect the header row (r > 1)');
  assert.ok(_src.includes('r < mtLastDataRow(node, m)'), 'Alt+Down must stop above the footer');
});

test('#1420 an undo moves CONTENT, and leaves identity, permission and preference alone', () => {
  // A snapshot is the whole root, so every document-level field rides in it. MEASURED, an undo that
  // reaches back past a field change reverted ALL EIGHT of them:
  //   rollLog · allowWebImages · docId · appearance · calendar · units · seed · a base's colW
  // So the boundary is not "which ones move" -- they all do -- but "which ones should".
  assert.ok(/const SNAPSHOT_PRESERVE = \['docId', 'allowWebImages', 'rollLog'\];/.test(_src),
    'three fields are carried across a restore');
  const rs = fnBody(_src, 'restoreSnapshot');
  assert.ok(/for \(const k of SNAPSHOT_PRESERVE\) if \(k in root\) keep\[k\] = root\[k\];/.test(rs),
    'read from the LIVE root, before it is replaced');
  assert.ok(rs.indexOf('keep[k] = root[k]') < rs.indexOf('root = JSON.parse(snap.root)'),
    'and read BEFORE the assignment, or it would capture the snapshot it is meant to override');
  assert.ok(/Object\.assign\(root, keep\);/.test(rs), 'then put back over the restored root');
  // the three are chosen, not swept: each has a reason no other field has.
  //   docId          identity; autosave + the earlier-version lookup are keyed by it
  //   allowWebImages a security opt-in; Ctrl+Z must never silently re-grant a revoked permission
  //   rollLog        a preference whose toggle deliberately does not pushUndo (#1405)
  for (const f of ['appearance', 'calendar', 'units', 'seed'])
    assert.ok(!new RegExp(`SNAPSHOT_PRESERVE = \\[[^\\]]*'${f}'`).test(_src),
      f + ' is authored CONTENT and must stay undoable');
  // the other half of the rule: content that reshapes the document has to RECORD an undo of its
  // own. #1387 gave every reshaping op one and missed this. Driven before: setting a width and
  // pressing Ctrl+Z took the width AND the edit before it; after, it takes only the width.
  const w = fnBody(_src, 'mtSetColWidth');
  assert.ok(/pushUndo\(\);/.test(w), 'a width change records its own undo');
  assert.ok(w.indexOf('if (!node.colW) { if (cw == null) return; node.colW = []; }') < w.indexOf('pushUndo();'),
    'AFTER the refusal guard, like every #1387 site -- a no-op must not consume an undo slot');
});

test('#1411 the picker gives focus back when it SUCCEEDS, not only when it is cancelled', () => {
  // Driven, the four exits of the two #bpop surfaces. The picker takes focus onto a chip the moment
  // it opens (both doors), so it owes focus back:
  //   to-do picker  Escape -> .node-content    apply -> **document.body**
  //   bullet menu   Escape -> .node-content    apply -> .node-note (the command's own destination)
  // Cancelling kept your place and succeeding did not, which is backwards. The old comment on
  // bpopReturnFocus said it restored "when the popup is closed by keyboard (Escape)" -- the
  // omission, written down beside the variable.
  const restore = fnBody(_src, 'bpopRestoreFocus');
  assert.ok(/const id = bpopReturnFocus; bpopReturnFocus = null;/.test(restore),
    'the restore consumes the armed id, so it can never fire twice');
  assert.ok(/\.node-content\[data-id="\$\{CSS\.escape\(String\(id\)\)\}"\]/.test(restore),
    'it refocuses by ID, because an apply re-renders the row it is about');
  // BOTH exits call it. The apply one is the fix; the Escape one must not regress.
  const tp = fnBody(_src, 'showTodoPicker');
  assert.ok(/bpopRestoreFocus\(rowIdx < 0 \? null : rowIdx\);/.test(tp), 'the apply path restores');
  assert.ok(/render\(\); hideBpop\(\);[\s\S]{0,400}bpopRestoreFocus\(/.test(tp),
    'and does it AFTER the render that rebuilt the row');
  assert.ok(/e\.key === 'Escape'[\s\S]{0,120}hideBpop\(\); bpopRestoreFocus\(\);/.test(NC),
    'the Escape path still restores');
  // deliberately NOT inside hideBpop: an outside-click dismissal must leave the caret where the
  // user just clicked. Driven: it does.
  assert.ok(!/bpopRestoreFocus/.test(fnBody(_src, 'hideBpop')),
    'the restore must not fire on every dismissal, or an outside click would yank the caret back');
  // the row can be GONE by the user's own doing (DONE with Show done off). Landing on <body> there
  // is the #1400 dead end again, so the surviving neighbour takes it.
  assert.ok(/rows\[Math\.min\(fallbackIdx, rows\.length - 1\)\]/.test(restore),
    'a hidden row falls back to the point that now occupies its place');
  assert.ok(/const rowIdx = \[\.\.\.document\.querySelectorAll\('\.node-content\[data-id\]'\)\]/.test(tp),
    'and the index is read BEFORE the render that removes the row');
});

test('#1400 baseStructMessage — six sentences, one shape, each promising the undo #1387 records', () => {
  const m = c.baseStructMessage;
  assert.equal(m('col-insert', { side: 'left', label: 'Owner', n: 2 }),
    'Column inserted to the left of \u201cOwner\u201d. Undo removes it.');
  assert.equal(m('col-insert', { side: 'right', label: '', n: 3 }),
    'Column inserted to the right of column 3. Undo removes it.', 'an unnamed column falls back to its number');
  assert.equal(m('col-move', { dir: -1, label: 'Owner', n: 1 }),
    'Column \u201cOwner\u201d moved left. Undo restores the order.');
  assert.equal(m('col-move', { dir: 1, label: '', n: 3 }), 'Column 3 moved right. Undo restores the order.');
  // the destructive member says how big it was -- that is the half a silent delete cost most
  assert.equal(m('col-delete', { label: 'Status', n: 3, values: 3 }),
    'Column \u201cStatus\u201d deleted, with 3 values. Undo restores it.');
  assert.equal(m('col-delete', { label: 'Status', n: 3, values: 1 }),
    'Column \u201cStatus\u201d deleted, with 1 value. Undo restores it.', 'singular');
  assert.equal(m('col-delete', { label: 'Status', n: 3, values: 0 }),
    'Column \u201cStatus\u201d deleted. Undo restores it.', 'an empty column does not claim a count');
  assert.equal(m('row-insert', { side: 'above', n: 2 }), 'Row inserted above row 2. Undo removes it.');
  assert.equal(m('row-move', { dir: -1, n: 2 }), 'Row 2 moved up. Undo restores the order.');
  assert.equal(m('row-delete', { n: 2, values: 2 }), 'Row 2 deleted, with 2 values. Undo restores it.');
  // #1415: the formatting half of the same menu. Sort spoke; Alignment, Width and Calculate wrote
  // to the document and said nothing at all -- one of four sections speaking.
  assert.equal(m('col-align', { label: 'Owner', align: 'center' }),
    'Column \u201cOwner\u201d aligned center. Undo restores it.');
  assert.equal(m('col-width', { label: 'Owner', width: 'Narrow' }), 'Column \u201cOwner\u201d set to Narrow.');
  assert.equal(m('col-width', { label: 'Owner', width: null }), 'Column \u201cOwner\u201d fits its content.');
  assert.equal(m('col-agg', { label: 'Owner', agg: 'Count' }), 'Column \u201cOwner\u201d totals with Count. Undo restores it.');
  assert.equal(m('col-agg', { label: 'Owner', agg: '' }), 'Column \u201cOwner\u201d stops totalling. Undo restores it.',
    'None reads as stopping, not as totalling with nothing');
  // the undo promise is PER-OP and honest: align and totals push undo (#1387), width does not, so
  // width does not claim it. Driven: setting a width and pressing Ctrl+Z reverts the width AND the
  // edit before it, because the change has no snapshot of its own.
  assert.doesNotMatch(m('col-width', { label: 'Owner', width: 'Wide' }), /Undo/,
    'width must not promise an undo it does not record');
  // the preset names have ONE home, shared with the menu that offers them
  assert.equal(c.colWidthLabel(96), 'Narrow');
  assert.equal(c.colWidthLabel(160), 'Medium');
  assert.equal(c.colWidthLabel(260), 'Wide');
  assert.equal(c.colWidthLabel(null), null, 'auto is the caller\'s phrasing, not a preset name');
  assert.equal(c.colWidthLabel(184), '184px', 'a drag or a keyboard step reports its pixels');
  assert.ok(/COL_W_PRESETS\.forEach\(\(\[label, w\]\) => addItem\(label/.test(NC),
    'the Column menu builds its width rows from the same constant the message reads');
  assert.equal(m('nope'), '', 'an unknown op says nothing rather than something wrong');
  // house rules: AP punctuation, no em dashes, and every one promises the undo
  for (const op of ['col-insert', 'col-move', 'col-delete', 'row-insert', 'row-move', 'row-delete']) {
    const out = m(op, { side: 'left', dir: 1, label: 'X', n: 2, values: 2 });
    assert.doesNotMatch(out, /\u2014/, op + ' must not use an em dash');
    assert.match(out, /Undo /, op + ' promises the undo #1387 records');
  }
  // the counters the delete messages are built from
  const model = { rows: [['Task','Owner','Status'], ['Ship','Ana',''], ['Migrate','','Todo'], ['Docs','Cy','Todo']] };
  assert.equal(c.mtColValueCount(model, 1, 3), 2, 'blank cells do not count');
  assert.equal(c.mtColValueCount(model, 0, 3), 3);
  assert.equal(c.mtRowValueCount(model, 1), 2);
});

test('#1400 every structural base op lands somewhere real and says what it did', () => {
  // Driven on origin/main through the MOUSE door (the header menu, nothing focused first): all ten
  // left focus on <body> and announced NOTHING, while their sibling mtSortBase announced everything.
  // The keyboard door hid it: hideColPanel's #1383 restore only has a target when something in the
  // base held focus before the menu opened, which the pointer path never does.
  const OPS = {
    mtInsertCol: "baseStructMessage('col-insert'", mtMoveCol: "baseStructMessage('col-move'",
    mtDeleteCol: "baseStructMessage('col-delete'", mtInsertRow: "baseStructMessage('row-insert'",
    mtMoveRow: "baseStructMessage('row-move'", mtDeleteRow: "baseStructMessage('row-delete'",
  };
  for (const [fn, msg] of Object.entries(OPS)) {
    const body = fnBody(_src, fn);
    assert.ok(body.includes(msg), fn + ' must build its sentence from the shared core');
    assert.ok(/mtFocusCell\(node,/.test(body), fn + ' must land focus somewhere real');
    assert.ok(/flashHint\(/.test(body), fn + ' must say it (flashHint announces too)');
  }
  // the two deletes read the name and the size BEFORE the splice removes them
  assert.ok(fnBody(_src, 'mtDeleteCol').indexOf("baseStructMessage('col-delete'") < fnBody(_src, 'mtDeleteCol').indexOf('m.aligns.splice'),
    'mtDeleteCol measures the column before deleting it');
  assert.ok(fnBody(_src, 'mtDeleteRow').indexOf("baseStructMessage('row-delete'") < fnBody(_src, 'mtDeleteRow').indexOf('m.rows.splice'),
    'mtDeleteRow measures the row before deleting it');
  // and the menu's close must not yank back focus the op deliberately placed
  assert.ok(fnBody(_src, 'hideColPanel').includes("ae.closest('.md-table-host')"),
    'hideColPanel stands down when an apply already landed focus inside the base');
  // the four formatting siblings in the same menu had the same <body> landing; they stay put now
  for (const fn of ['mtSetAlign', 'mtApplyAggregate', 'mtSortBase'])
    assert.ok(/mtFocusCell\(node, 0, colIdx\)/.test(fnBody(_src, fn)),
      fn + ' stays on the column it acted on (it did not move)');
  // #1415: mtSetColWidth is the exception and it is load-bearing. It has FIVE callers and one is
  // the mouse resize DRAG, so a landing here fired on mouse-up and yanked the caret out of the cell
  // being edited -- measured r1c1 -> r0c0, the caret invariant broken by the fix meant to protect
  // focus. Its three DELIBERATE doors land for themselves.
  assert.ok(!/mtFocusCell\(/.test(fnBody(_src, 'mtSetColWidth')),
    'mtSetColWidth must NOT land focus: a mouse resize drag calls it');
  assert.ok(!/flashHint\(/.test(fnBody(_src, 'mtSetColWidth')),
    'nor speak, for the same reason -- a drag would narrate itself');
  // #1415 CALL SITES. Caught by mutation: the three sentences were pinned as data and NOTHING
  // asserted anything called them, so deleting each flashHint left every assertion green -- the
  // #1133 rule, met again in the same session.
  assert.ok(/flashHint\(baseStructMessage\('col-align'/.test(fnBody(_src, 'mtSetAlign')),
    'Alignment says what it did');
  assert.ok(/flashHint\(baseStructMessage\('col-agg'/.test(fnBody(_src, 'mtApplyAggregate')),
    'Calculate says what it did');
  assert.ok(/flashHint\(baseStructMessage\('col-width'/.test(fnBody(_src, 'showColPanel')),
    'the Width menu rows say what they did, from the deliberate door rather than from the op');
  assert.ok(/const setW = \(w\) => \{ mtSetColWidth\(node, colIdx, w\); mtFocusCell\(node, 0, colIdx\);/.test(NC),
    'and that door lands focus too, which the op can no longer do for them');
});

