test('mergeBodyText: split→merge round-trips a to-do byte-identically (the #818 repro)', () => {
  const orig = '- [ ] alpha beta';
  const { before, after } = c.splitForSibling(orig, 11, '- [ ] ');   // caret after "alpha"
  assert.equal(before, '- [ ] alpha');
  assert.equal(after, '- [ ]  beta');
  const rejoined = c.mergeUpText(before, c.mergeBodyText(c.mkNode(after))).text;
  assert.equal(rejoined, orig);                                       // was "- [ ] alphabeta"
});

// src wiring pins for the DOM-path fixes
const _fix = readFileSync(new URL('../index.html', import.meta.url), 'utf8');
// ── #1109: the computed-dependents sweep must not ride a resettable worklist ──
test('#1109 isComputedNode — which points depend on document-wide state', () => {
  const n = (o) => Object.assign({ text: '', children: [] }, o);
  assert.equal(c.isComputedNode(n({ math: [{ key: 'm' }] })), true, 'a math pill reads the var map');
  assert.equal(c.isComputedNode(n({ vars: [{ key: 'v' }] })), true, 'a var declaration or reference');
  assert.equal(c.isComputedNode(n({ est:  [{ key: 'e' }] })), true, 'an estimate re-derives from expr+seed');
  assert.equal(c.isComputedNode(n({ query:[{ key: 'q' }] })), true, 'a query pill reads the tree');
  assert.equal(c.isComputedNode(n({ text: 'Chapters [/]' })), true, 'a progress cookie counts children');
  assert.equal(c.isComputedNode(n({ text: 'plain point' })), false, 'plain text is not computed');
  assert.equal(c.isComputedNode(n({ est: [] })), false, 'an EMPTY sidecar is not computed');
  assert.equal(c.isComputedNode(null), false, 'no node, no repaint');
  // deliberately absent: dice/grammar/markov/roll. Those freeze until clicked, so repainting them
  // would silently change a value the user is reading. See the comment at the declaration.
  assert.equal(c.isComputedNode(n({ grammar: [{ key: 'g' }] })), false, 'a generative pill is NOT swept');
});

test('#1109 the sweep derives its worklist from mounted rows, never a resettable set', () => {
  // THE REGRESSION. repaintComputedDependents used to iterate `_computedNodeIds`, a Set registered
  // in DOC_CACHES — so resetDocCaches() cleared it. promoteBraceBodyIn calls resetDocCaches() for
  // every declaration it promotes, and that runs inside exitEdit BEFORE the sweep. Editing
  // `{rate := 45 to 75}` therefore emptied the worklist and swept nothing, leaving every dependent
  // showing its old number. Driven before the fix: the set went 3 -> 0 across one commit, and both
  // dependents held their previous values; a full render() showed the correct ones.
  assert.ok(!/_computedNodeIds/.test(_src),
    'the resettable worklist is gone — reintroducing it reintroduces the stale-total bug (#1109)');
  const body = fnBody(_src, 'repaintComputedDependents');
  assert.match(body, /querySelectorAll\('\.node-content\[data-id\]'\)/,
    'the sweep enumerates the mounted rows, which no cache reset can empty');
  assert.match(body, /isComputedNode\(n\)/, 'and gates each row on the shared pure predicate');
  assert.match(body, /el\.dataset\.editing/, 'still never clobbers a live editor (the caret invariant)');
  assert.match(body, /n\.type === 'base'/, 'still leaves bases to their own machinery');
});

test('#1109 sidecar-only pill edits sweep their dependents too', () => {
  // A pill edit rewrites the SIDECAR record and leaves node.text byte-identical (driven: true), so
  // exitEdit's `node.text !== prevText` gate cannot fire for it. Each of these must sweep itself.
  for (const fn of ['editEst', 'editMath']) {
    assert.match(fnBody(_src, fn), /repaintComputedDependents\(node\.id\)/,
      `${fn} must repaint dependents — its edit never changes node.text, so the text gate never fires`);
  }
  assert.match(fnBody(_src, 'rerollEst'), /repaintComputedDependents\(node\.id\)/,
    'a re-sample changes a draw other points may read');
});

// ── commit hygiene: the rule that existed, was written down, and still got broken ──
// CLAUDE.md bans agent attribution and session links. Eight consecutive merged commits carried
// both anyway, because nothing read commit messages: the UX gate reads the PR BODY, and the
// written procedure only described stripping an AUTO-APPENDED link from the PR. An author typing
// the trailer into the commit was an unguarded surface, so the rule was honour-system.
// These tests parse the patterns out of the workflow and run them, so the guard is proven to bite
// rather than assumed to. A CI rule nobody has seen reject anything is not yet a guard.
const _wfHygiene = readFileSync(new URL('../.github/workflows/ux-conformance.yml', import.meta.url), 'utf8');

// ── #1427: the browser smoke, and the two ways it could quietly stop being a gate ───────────────
// tests/browser.mjs drives the real index.html in a real browser, because every DOM pin in THIS
// file proves presence and not behaviour: #1021 shipped a keyboard handler that passed its pin and
// did nothing, since the element it sat on could not take focus.
//
// It can fail open in two directions, and both are silent, so both are pinned here:
//   - CI stops running it at all (nothing else in the repo would notice)
//   - CI runs it and every check SKIPS, because playwright did not resolve, and the job goes green
// The fence against the second is POINTLINER_REQUIRE_BROWSER, and it only works if the workflow
// SETS it and the test file READS it. Pinning either alone is the #1133 vacuity: a tested core
// proves nothing about its call site. Both are asserted below, against the two real files.
const _wfTests = readFileSync(new URL('../.github/workflows/tests.yml', import.meta.url), 'utf8');
const _browserSrc = readFileSync(new URL('./browser.mjs', import.meta.url), 'utf8');

test('#1427 CI runs the browser smoke, and installs what it needs', () => {
  assert.ok(/node --test tests\/browser\.mjs/.test(_wfTests),
    'the browser smoke must actually be invoked by CI, or it rots like any unrun guard');
  assert.ok(/npm install .*playwright@\d+\.\d+\.\d+/.test(_wfTests),
    'playwright is installed at job time and PINNED — .gitignore keeps it out of source, and an ' +
    'unpinned install lets an upstream release turn the gate red with no change here');
  assert.ok(/playwright install .*chromium/.test(_wfTests),
    'and the browser binary too: the module alone launches nothing');
  // The offline job must stay offline. tests/test.mjs is the gate that works with no network, and
  // folding the browser checks into it would put a download on the common path.
  assert.ok(/^  node-tests:$/m.test(_wfTests), 'the offline job still exists');
  const offline = between(_wfTests, '  node-tests:', '  browser-smoke:');
  assert.ok(!/npm install|playwright/.test(offline),
    'and carries no network dependency — that separation is the reason there are two jobs');
});

test('#1557 the fast offline guards do not sit downstream of the suite', () => {
  // node-tests carries timeout-minutes:10 on a step that measures ~15s. When that step WEDGED on
  // #1557 -- 2049 tests in five seconds, then no output for ten minutes -- GitHub killed the job and
  // reported every later step `skipped`. Those steps were two sub-second checks with no relationship
  // to the suite, and one of them (the symbol-index golden file) was ACTUALLY STALE on that PR with
  // nothing to say so. A timed-out job is reported `cancelled` rather than `failure`, so the run did
  // not read as broken either. Hence: their own job.
  const suite = between(_wfTests, '\n  node-tests:', '\n  drift-guards:');
  assert.match(suite, /node --test tests\/test\.mjs/, 'node-tests must still run the suite');
  const CHEAP = nonEmpty(['check-pr-conformance.test.mjs', 'symbol-index.py --check'], 'the fast offline checks');
  for (const c of CHEAP)
    assert.ok(!suite.includes(c),
      `${c} must not sit behind the suite — a wedge there reports it "skipped", which reads as neither pass nor fail`);
  const guards = between(_wfTests, '\n  drift-guards:', '\n  mutation:');
  for (const c of CHEAP) assert.ok(guards.includes(c), `${c} must run in the drift-guards job`);
  // The same mistake one level down: without this, a failing hook self-check skips the index check
  // and hides the drift exactly as the wedge did.
  assert.match(guards, /if: \$\{\{ !cancelled\(\) \}\}\s*\n\s*run: python3 tools\/symbol-index\.py --check/,
    'the index check must still run when the step before it fails');
  // And the split must not have cost the offline property that is node-tests' whole reason to exist.
  assert.ok(!/npm install|playwright/.test(guards), 'drift-guards must stay offline');
});

// A wedged runner is invisible: GitHub's default job timeout is 360 minutes, so a job stuck inside
// its one step reports "in_progress" for hours and reads exactly like a slow suite. #1465's PR sat
// an hour on `mutation`, a job that finishes in six minutes. A census, not a spot check: a NEW job
// added without a timeout is the same hole reopened, and this is the only place that would notice.
test('every CI job in tests.yml is bounded by a timeout', () => {
  const body = _wfTests.slice(_wfTests.indexOf('\njobs:\n'));
  assert.ok(body, 'tests.yml must declare a jobs: block');
  const jobs = nonEmpty([...body.matchAll(/^  ([a-z][a-z0-9-]*):$/gm)].map(m => m[1]),
    'jobs declared in tests.yml');
  assert.ok(jobs.length >= 4, `found only ${jobs.length} jobs — did the workflow move?`);
  const unbounded = jobs.filter(name => {
    const decl = _wfTests.slice(_wfTests.indexOf(`\n  ${name}:\n`));
    const head = decl.slice(0, decl.indexOf('\n    steps:'));
    return !/^ {4}timeout-minutes: \d+/m.test(head);
  });
  assert.deepEqual(unbounded, [],
    'a CI job with no timeout-minutes can wedge for six hours and still look like it is working');
});

test('#1427 a skipped browser smoke cannot pass in CI', () => {
  // Half one: the workflow sets the fence, on the step that runs the smoke rather than anywhere.
  const smokeStep = between(_wfTests, 'node --test tests/browser.mjs', 'POINTLINER_REQUIRE_BROWSER');
  assert.ok(smokeStep.length < 60,
    'POINTLINER_REQUIRE_BROWSER must be set on the step that RUNS the smoke, not elsewhere in the file');
  assert.ok(/POINTLINER_REQUIRE_BROWSER: '1'/.test(_wfTests), 'and set to a truthy value');
  // Half two: the test file reads it, and reading it must DEFEAT the skip rather than merely
  // being mentioned. Revert `REQUIRE_BROWSER ? false : …` to a bare `launchErr || false` and this
  // goes red — proved by mutation, which is the only reason to trust it (#1133).
  assert.ok(/process\.env\.POINTLINER_REQUIRE_BROWSER/.test(_browserSrc),
    'the smoke must read the fence — a workflow setting an env nobody reads is decoration');
  assert.match(_browserSrc, /const skip = \(\) => \(REQUIRE_BROWSER \? false : \(launchErr \|\| false\)\);/,
    'and the fence must override the skip, not sit beside it');
  // A launch failure is never a skip, in either environment: `skip:` is evaluated when a test is
  // DEFINED, so before()'s launch error can never reach it, and failing loudly is what we want.
  assert.ok(/if \(!browser\) assert\.fail\(/.test(_browserSrc),
    'and a browser that never launched must fail the run, not slip through as a skip');
});

test('#1427 the browser smoke still covers every defect class it was built for', () => {
  const checks = nonEmpty(_browserSrc.match(/^test\('[^']+'/gm) || [], 'browser smoke checks');
  // A census ratchet, not a proof. It may shrink deliberately (delete a check and lower the floor,
  // carrying the reason) but it cannot shrink SILENTLY, which is how coverage usually leaves.
  assert.ok(checks.length >= 7,
    `the smoke covers 7 shipped defect classes; found ${checks.length}: ${checks.join(' | ')}`);
  // Every check must route through the shared skip, or a developer without playwright gets a red
  // suite for a dependency this repo deliberately does not commit.
  const guarded = (_browserSrc.match(/\{ skip: skip\(\) \}/g) || []).length;
  assert.equal(guarded, checks.length, 'every check carries { skip: skip() }');
  // The classes themselves, named so a rename that guts one is visible in the diff.
  for (const want of [/boot/, /pill/i, /re-roll/, /Shift\+F10/, /Escape/, /command/, /\+ Add door/])
    assert.ok(checks.some(c => want.test(c)), 'a check still covers ' + want);
});

// ── #1166: the Font Awesome rebuild job ──────────────────────────────────────────────────────────
// Nothing in CI ran tools/build-fa-subset.py, so a script that had stopped working passed every test
// until a human rebuilt by hand -- the gap #1144 and #1155 both shipped through. The job that closes
// it lives on a schedule (its script fetches upstream .ttf sources, and PR CI stays offline), which
// means NOTHING ELSE WOULD NOTICE IF IT WERE DELETED OR NEUTERED. These assertions are that notice.
const _wfFa = readFileSync(new URL('../.github/workflows/fa-embed.yml', import.meta.url), 'utf8');
const _faVerify = readFileSync(new URL('../tools/verify-fa-embed.py', import.meta.url), 'utf8');

test('#1166 the FA rebuild job exists, runs the real script, and is triggerable', () => {
  assert.ok(/on:\s*\n\s*schedule:\s*\n\s*- cron:/.test(_wfFa), 'it must be scheduled, not only manual');
  assert.ok(/workflow_dispatch:/.test(_wfFa), 'and runnable on demand, which is how you check before editing ICONS');
  // The paths filter is the half that makes it bite on the change that matters: a PR editing the
  // build script gets the network check, because that is the change nothing else can see.
  // Read the paths LIST, not the whole file: `tools/build-fa-subset.py` also appears in this
  // workflow's own header comment, so a file-wide match passed with the filter deleted. Caught by
  // mutation, and it is the same comment trap as UXP-280 in a new costume.
  const faPaths = between(_wfFa, '  pull_request:\n    paths:\n', '\n\npermissions:');
  assert.ok(/- 'tools\/build-fa-subset\.py'/.test(faPaths),
    'a PR touching the build script must run this job — that is the change nothing else can see');
  assert.ok(/- 'tools\/verify-fa-embed\.py'/.test(faPaths), 'and a PR touching the verifier itself');
  assert.ok(/python3 tools\/verify-fa-embed\.py/.test(_wfFa), 'the job must actually invoke the verifier');
  assert.ok(/pip install .*fonttools.*brotli|pip install .*brotli.*fonttools/.test(_wfFa),
    'and install what the subsetter needs, or it fails for the wrong reason');
  // It must NOT be on every pull_request: that would put a network fetch on the common path, which
  // is the tradeoff this design deliberately declined (#1166 option A).
  assert.ok(!/^on:[\s\S]*?pull_request:\s*\n\s*(types|branches)?\s*\n?\s*jobs:/m.test(_wfFa),
    'it must not run on every PR — PR CI stays offline by design');
});

test('#1166 the verifier compares MEANING, not bytes, and says why', () => {
  // The design decision that measurement forced. A rebuild here differs from the shipped payloads by
  // 8-28 bytes per face while every face maps identical codepoints: woff2/brotli is not reproducible
  // across tool versions. A byte-diff job would have been red on day one and every day after, which
  // is worse than no job. If someone "tightens" this to a byte comparison, they get a permanently
  // failing check -- so the looseness is pinned, with its reason.
  assert.ok(/getBestCmap\(\)/.test(_faVerify), 'payloads are compared by decoded codepoint coverage');
  assert.ok(/base64\.b64decode\(b\)\[:4\] != b"wOF2"/.test(_faVerify),
    'and each shipped face must still BE woff2 — the #1155 regression, checked directly');
  assert.ok(/PAYLOAD_RE\.sub\("base64,PAYLOAD"/.test(_faVerify),
    'the non-payload text is compared verbatim, which is what catches a stale ICONS list');
  assert.ok(/reproducib/i.test(_faVerify),
    'the limit must be STATED in the file, not implied away (the #1132 precedent)');
  // The two bugs it exists to catch are named, so the next reader meets the evidence.
  for (const ref of ['#1144', '#1155'])
    assert.ok(_faVerify.includes(ref), `the verifier must cite ${ref} as the bug it would have caught`);
});
function hygienePatterns() {
  // BOTH classes: the anywhere-list and the trailer-list. Slicing to the first ']' would silently
  // return only the first list, which is the vacuity trap this file exists to avoid.
  const start = _wfHygiene.indexOf('const BANNED_ANYWHERE = [');
  const end = _wfHygiene.indexOf('const BANNED = [', start);
  const src = _wfHygiene.slice(start, end);
  return [...src.matchAll(/\{ re: \/(.+?)\/([a-z]*),/g)].map(m => new RegExp(m[1], m[2]));
}
const hygieneViolates = (msg) => hygienePatterns().some(re => re.test(msg));
function hygieneAnywherePatterns() {
  const body = _wfHygiene.slice(_wfHygiene.indexOf('const BANNED_ANYWHERE = ['));
  const src = body.slice(0, body.indexOf(']'));
  return [...src.matchAll(/\{ re: \/(.+?)\/([a-z]*),/g)].map(m => new RegExp(m[1], m[2]));
}

test('commit hygiene: the workflow patterns are parseable and non-empty', () => {
  const pats = hygienePatterns();
  assert.ok(pats.length >= 4, `expected the BANNED list to parse, got ${pats.length}`);
  // Guards the guard: if the workflow's BANNED shape changes, this parse yields [] and EVERY
  // assertion below would pass vacuously. Assert the count first, always.
});

test('commit hygiene: the real historical violations are caught', () => {
  assert.ok(hygieneViolates('Claude-Session: https://claude.ai/code/session_01Rxqq'), 'session trailer');
  assert.ok(hygieneViolates('Co-Authored-By: Claude Opus 5 <noreply@anthropic.com>'), 'agent co-author');
  assert.ok(hygieneViolates('see https://claude.ai/code/session_abc for context'), 'a bare session URL anywhere');
  assert.ok(hygieneViolates('fixed the thing\n\nbody\n\nCo-Authored-By: Claude Opus 5 <x@y>'), 'trailer at the end');
});

test('commit hygiene: ordinary messages and HUMAN co-authors pass', () => {
  // The negative matters as much as the positive: if a real pairing trips this, the first thing
  // anyone does is delete the guard. Human co-authorship is normal and must stay legal.
  assert.equal(hygieneViolates('made {roll:} draw from the document\n\nFixes #1107'), false);
  assert.equal(hygieneViolates('fixed a bug\n\nCo-Authored-By: Ada Lovelace <ada@example.com>'), false,
    'a HUMAN co-author is not agent attribution');
  assert.equal(hygieneViolates('add a session timeout to the login flow'), false,
    'the word "session" alone is not a session link');
});

test('commit hygiene: the platform auto-appended footer is caught', () => {
  // THE REAL THREAT, and the first version of this guard sailed past it twice. The platform appends
  // this to a PR body AFTER creation -- verbatim from PR #1135:
  //   _Generated by [Claude Code](https://claude.ai/code/session_01Rxqq...)_
  // Miss 1: the pattern said "Generated WITH", the footer says "Generated BY".
  // Miss 2: the line-start anchoring added to fix a false positive let the URL through, because it
  //         sits mid-line. Fixing a false positive had created a false negative for the exact thing
  //         the guard exists to catch. Hence two classes: URLs and attributions match ANYWHERE,
  //         trailer forms keep the anchor.
  const FOOTER = '\n\n---\n_Generated by [Claude Code](https://claude.ai/code/session_01RxqqMS)_';
  const anywhere = hygieneAnywherePatterns();
  assert.ok(anywhere.length >= 2, `the anywhere-class must parse, got ${anywhere.length}`);
  assert.ok(anywhere.some(re => re.test(FOOTER)), 'the real auto-appended footer must fail the gate');
  // both halves of the miss, independently
  assert.ok(anywhere.some(re => re.test('Generated by [Claude Code](x)')), '"Generated by" is covered, not only "with"');
  assert.ok(anywhere.some(re => re.test('see https://claude.ai/code/session_x mid sentence')),
    'a session URL fails wherever it sits, not only at line start');
  // and discussion still passes, because code spans are stripped before matching
  const prose = (t) => String(t).replace(/```[\s\S]*?```/g, '').replace(/`[^`\n]*`/g, '');
  assert.equal(anywhere.some(re => re.test(prose('the footer is `https://claude.ai/code/session_x`'))), false,
    'quoting the URL in code is still legal');
});

test('commit hygiene: a PR body may DISCUSS the banned trailers without failing', () => {
  // This guard failed its own first PR. The commit was clean; the DESCRIPTION was the only
  // offender, because it quoted the banned trailers in order to explain the bug. Matching raw text
  // cannot tell a violation from a discussion of one -- the same defect as the PR-conformance hook
  // (#1130), which blocks a shell command for merely quoting a command name inside a doc string.
  const bodyViolates = (text) => {
    const prose = String(text || '').replace(/```[\s\S]*?```/g, '').replace(/`[^`\n]*`/g, '');
    return hygienePatterns().some(re => new RegExp('^[ \\t>]*(?:' + re.source + ')', 'im').test(prose));
  };
  assert.equal(bodyViolates('Eight commits carried `Claude-Session:` trailers.'), false, 'inline code');
  assert.equal(bodyViolates('```\nCo-Authored-By: Claude Opus 5 <x@y>\n```'), false, 'fenced block');
  assert.equal(bodyViolates('The commits carried Claude-Session trailers and I removed them.'), false,
    'named mid-sentence, which is how you describe a bug');
  assert.equal(bodyViolates('Fixes #1\n\nCo-Authored-By: Claude Opus 5 <noreply@anthropic.com>'), true,
    'a genuine trailer at line start still fails');
  assert.equal(bodyViolates('  > Claude-Session: https://claude.ai/code/session_abc'), true,
    'indentation and quote markers do not smuggle it past');
});

test('commit hygiene: the workflow reads COMMITS whole, and the BODY narrowly', () => {
  // The whole point. The pre-existing gate only ever saw the PR description, which is why a
  // banned trailer could sit in every commit while that gate reported green.
  assert.match(_wfHygiene, /pulls\.listCommits/, 'the job must enumerate the PR commits');
  assert.match(_wfHygiene, /c\.commit\.message/, 'and test each commit MESSAGE');
  assert.match(_wfHygiene, /const checkCommit = \(where, text\) => \{/, 'commits keep the strict check');
  assert.match(_wfHygiene, /const checkBody = \(text\) => \{/, 'the body has its own, narrower check');
  // The behavioural test above builds its own matcher, so it proves the RULE but not the WORKFLOW.
  // Caught by mutation: reverting the body check to the strict form failed nothing. These two pin
  // the workflow's actual narrowing, so the bug that rejected this very PR cannot come back.
  assert.match(_wfHygiene, /\.replace\(\/```\[\\s\\S\]\*\?```\/g, ''\)/,
    'the body check must drop fenced code before matching');
  assert.match(_wfHygiene, /\^\[ \\\\t>\]\*\(\?:/,
    'and anchor the trailer to line start, or a body that DISCUSSES the rule fails again');
  assert.match(_wfHygiene, /CLAUDE\.md/, "the failure message names the rule's home");
});

// ── #1115: an estimate number a client can read ──
test('#1115 estNumFmt — no scientific notation on money, and thousands group', () => {
  // MEASURED from the consultant's memo: estNumFmt switched to toPrecision(3) at |x| >= 100000, so
  // `total ≈ 7.00e+5 (6.02e+5 – 8.05e+5)`. His verdict: "cannot go in front of a paying client."
  // The rest of the app already had this right -- formatNumDisplay(700000, null) is `700,000` with
  // no configuration at all. The estimate family simply never consulted it.
  assert.equal(c.estNumFmt(700000), '700,000', 'the exact value from the memo');
  assert.equal(c.estNumFmt(403000), '403,000');
  assert.equal(c.estNumFmt(109000), '109,000');
  assert.equal(c.estNumFmt(99999), '99,999', 'below the old cliff, now grouped too');
  assert.equal(c.estNumFmt(100000), '100,000', 'AT the old cliff -- this was 1.00e+5');
  assert.doesNotMatch(c.estNumFmt(700000), /e\+/, 'no exponent reaches a money figure');

  // KEPT DELIBERATELY: the small-number scientific branch, where 1.2e-7 is readable and
  // 0.00000012 is not.
  assert.match(c.estNumFmt(0.00000012), /e-/, 'a genuinely tiny number stays scientific');
});

test('#1115 estNumFmt — the adaptive default keeps its trailing-zero trim', () => {
  // THE REGRESSION THIS ALMOST SHIPPED WITH. Routing the default through formatNumDisplay's
  // decimals path turned `5 (4.1 – 5.9)` into `5.00 (4.10 – 5.90)`, because the old code's
  // `String(+x.toFixed(2))` trimmed trailing zeros and formatNumDisplay does not. Caught by
  // re-measuring the output, not by the suite.
  assert.equal(c.estNumFmt(5), '5', 'not 5.00');
  assert.equal(c.estNumFmt(4.1), '4.1', 'not 4.10');
  assert.equal(c.estNumFmt(5.9), '5.9');
  // ...but an EXPLICIT decimals means the author asked for exactly that many, zeros included.
  assert.equal(c.estNumFmt(5, { decimals: 2 }), '5.00', 'explicit decimals keep their zeros');
});

test('#1115 estNumFmt — currency and percent, via the format record that already existed', () => {
  // parseNumFmt(decimals, prefix, suffix) is the SAME record a math pill and a base column carry.
  // Currency is a prefix, percent is a suffix; no second format model was invented.
  assert.equal(c.estNumFmt(700000, { decimals: 0, prefix: '£' }), '£700,000');
  assert.equal(c.estNumFmt(4.7, { suffix: '%' }), '4.7%');
  assert.equal(c.estNumFmt(1200, { decimals: 2, prefix: '$' }), '$1,200.00', 'matches formatNumDisplay exactly');
  assert.equal(c.estNumFmt(1200, { decimals: 2, prefix: '$' }), c.formatNumDisplay(1200, { decimals: 2, prefix: '$' }),
    'the estimate path and the shared path agree, which is the whole point');
});

test('#1115 distHeadline — one mean (p5 – p95) line, shared by every surface', () => {
  // Eight call sites used to build this string by hand, which is why threading a format through
  // them was worth doing once. The pill, the aria-label, the re-sample announcement, the roll log,
  // the dialog preview and the export all read this.
  const sm = { mean: 700000, p5: 602000, p95: 805000 };
  assert.equal(c.distHeadline(sm), '700,000 (602,000 – 805,000)');
  assert.equal(c.distHeadline(sm, { decimals: 0, prefix: '£' }), '£700,000 (£602,000 – £805,000)');
  assert.equal(c.distHeadline(null), null, 'no summary, no headline');
});

test('#1115 the format reaches the pill AND the export, not just the pill', () => {
  // Driven: with a £ format the pill read £702,141 while the export still read 702,141 -- one
  // value, two displays, which is the bug this change exists to remove. Both arms now pass it.
  assert.match(_src, /formatDist\(samples, e\.fmt \|\| null\)/, 'the est export arm carries the format');
  assert.match(_src, /formatDist\(samples, dRec\.fmt \|\| null\)/, 'and so does the dist-variable arm');
  assert.match(fnBody(_src, 'renderEstPill'), /const fmt = e\.fmt \|\| null;/, 'the pill reads it off the record');
  // #1175: sigfigs became a 4th positional arg, so this now reads `…v.suffix, v.sigfigs)`. Rewritten
  // rather than loosened: the point of the pin is that the dialog uses the ONE shared parser, so it
  // must still name the exact call, and it must name the new argument or a dropped 4th arg would
  // silently stop the estimate dialog honouring a field its own form offers.
  assert.match(_src, /if \(rec\) \{ const f = parseNumFmt\(v\.decimals, v\.prefix, v\.suffix, v\.sigfigs\); if \(f\) rec\.fmt = f; \}/,
    'the dialog writes it with the SHARED parser, lean-or-absent, and passes sigfigs');
});

test('#1115 searching the catalogue for "format" finds the pills that own one', () => {
  // The persona searched for "format" and got NO MATCHES. That was correct behaviour: there is no
  // standalone format command -- the format is a property of a math pill and (now) an estimate.
  // So the fix is not a new command, it is making those two answer to the word people type.
  const pool = c.builderCmdPool(null);
  assert.ok(pool.length > 0, 'the pool must be non-empty or every assertion below is vacuous');
  // #1202 adds the plain-language money words: /money surfaced NOTHING and /budget only reached a
  // check block cmd; both now find the pills that actually do money math, alongside the format words.
  for (const q of ['format', 'currency', 'decimals', 'thousands', 'money', 'budget']) {
    const ids = c.builderFilterCmds(pool, q, '@').map(x => x.id);
    assert.ok(ids.includes('est'), `searching ${q} must find the estimate pill`);
    assert.ok(ids.includes('math'), `searching ${q} must find the math pill`);
  }
});

// ── #1112: a refused picker is not a user cancelling ──
test('#1112 pickerOutcome — a refusal and a cancel are told apart', () => {
  // MEASURED in Chromium, not assumed: a refused showSaveFilePicker rejects with AbortError in
  // **1ms**, message "The user aborted a request", when no user aborted anything. Other refusals
  // arrive as NotAllowedError, which the existing catches already reported. Only the AbortError
  // path was silent, and that silence is why a persona believed Save was broken.
  assert.equal(c.pickerOutcome({ errName: 'AbortError', elapsedMs: 1 }), 'refused', 'the measured case');
  assert.equal(c.pickerOutcome({ errName: 'NotAllowedError', elapsedMs: 0 }), 'refused');
  assert.equal(c.pickerOutcome({ errName: 'SecurityError', elapsedMs: 5 }), 'refused');
  // THE REGRESSION THAT WOULD MAKE THIS WORSE THAN THE BUG: a real dismissal must stay silent.
  assert.equal(c.pickerOutcome({ errName: 'AbortError', elapsedMs: 900 }), 'cancelled',
    'a human reaching for Cancel is not a refusal');
  assert.equal(c.pickerOutcome({ errName: 'AbortError', elapsedMs: 250 }), 'cancelled', 'at the threshold');
  assert.equal(c.pickerOutcome({ errName: 'AbortError', elapsedMs: 249 }), 'refused', 'just under it');
  // the threshold is a judgement call; this pins WHERE it sits so moving it is a deliberate act
  assert.match(_src, /const PICKER_REFUSAL_MS = 250;/, 'the threshold is named, not inlined');
  assert.match(_src, /HEURISTIC/, 'and the code admits it is a heuristic rather than implying precision');
});

test('#1112 the refusal message names the cause and a way out', () => {
  const m = c.pickerRefusedMessage('saving', 'Downloading a copy instead.');
  assert.match(m, /would not open the file picker/, 'names the browser as the cause');
  assert.match(m, /Downloading a copy instead/, 'and what the app did instead');
  assert.match(m, /Private browsing/, 'and why it might be happening');
  assert.doesNotMatch(m, /DOMException|Failed to execute/, 'never echoes a raw exception at the user');
});

test('#1112 every picker routes through the classifier, and Save falls back to the download', () => {
  // The fallback already existed: `if (hasFSA) {…} else dlOpml()`. Firefox and Safari save fine.
  // The bug was that the branch is chosen by PRESENCE, so a refused picker in Chromium took the
  // FSA arm and died there, with a working download three lines away.
  for (const fn of ['saveAsFile', 'openFile', 'connectWorkspace']) {
    assert.match(fnBody(_src, fn), /runPicker\(/, `${fn} must classify its picker failure`);
  }
  assert.match(fnBody(_src, 'saveAsFile'), /outcome === 'refused'[\s\S]{0,160}dlOpml\(\)/,
    'a refused save falls back to the download that already works');
  assert.match(_src, /let fsaOk = hasFSA;/, 'capability is learned, mirroring opfsOk (#1113)');
  assert.match(fnBody(_src, 'runPicker'), /fsaOk = false/, 'and cleared when a picker is refused');
});

test('#1112 reconnectWorkspace stops swallowing a denied permission', () => {
  // Found while mapping this: a bare `catch (_) {}` swallowed EVERY error, and a denied prompt had
  // no branch at all, so "Reconnect folder" could be clicked forever with no response.
  // reopenPendingFile -- the single-file twin -- already did it right; this copies it.
  const rw = fnBody(_src, 'reconnectWorkspace');
  assert.match(rw, /perm !== 'granted'[\s\S]{0,80}flashHint\(/, 'a denied prompt says so');
  assert.doesNotMatch(rw, /catch \(_\) \{ \/\* denied/, 'the bare swallow is gone');
  assert.match(rw, /catch \(_\) \{ flashError\(/, 'and a thrown error is reported');
});

// ── #1113: the storage signals must match what actually survives a reload ──
test('#1113 storageAdvice — names the real failure, and only when there is no durable copy', () => {
  // Driven on a real origin BEFORE the fix: the two-tier fallback works. localStorage blocked alone
  // survives (OPFS covers it) and OPFS blocked alone survives (localStorage covers it). Work is lost
  // only when BOTH fail. In that state two things lied: the message blamed SIZE, and unsavedToDisk()
  // returned false so the dirty dot and the unload guard both reported "safe".
  const blocked = c.storageAdvice({ lsFailed: true, quota: false, opfsOk: false });
  assert.equal(blocked.why, 'blocked');
  assert.equal(blocked.durable, false);
  assert.match(blocked.message, /blocking storage/, 'names the real cause, not size');
  assert.doesNotMatch(blocked.message, /too large/, 'a private window is not a size problem');

  const full = c.storageAdvice({ lsFailed: true, quota: true, opfsOk: false });
  assert.equal(full.why, 'quota');
  assert.match(full.message, /too large/, 'a genuine quota failure keeps the size wording');

  // the cases that must stay QUIET, because the work is genuinely safe
  assert.equal(c.storageAdvice({ lsFailed: true, opfsOk: true }), null, 'OPFS covers a blocked localStorage');
  assert.equal(c.storageAdvice({ lsFailed: true, opfsOk: false, workspaceFile: true }), null, 'the folder file is durable');
  assert.equal(c.storageAdvice({}), null, 'nothing wrong, nothing said');

  // the soft, nearing-the-wall warning survives, and only without a second sink
  assert.equal(c.storageAdvice({ oversize: true, opfsOk: true }), null, 'OPFS has no size cap');
  assert.equal(c.storageAdvice({ oversize: true, opfsOk: false }).level, 'soft');
});

// ── #1136: a failed boot restore stops arriving dressed as a tour ────────────────────────────
test('#1136 restoreFailMessage — four failures, four remedies, none of them silence', () => {
  // DRIVEN on main, all four modes: work LOST, and the only thing on screen was the examples
  // banner - "These are live examples to explore. Click any pill" - which is not a MISSING warning
  // but the opposite of one. Cheerful onboarding copy in place of "we could not read your document".
  const blocked = c.restoreFailMessage('blocked');
  const corrupt = c.restoreFailMessage('corrupt');
  const deep = c.restoreFailMessage('deep');
  for (const [name, m] of [['blocked', blocked], ['corrupt', corrupt], ['deep', deep]]) {
    assert.ok(m && m.length > 40, `${name} must say something substantial`);
    assert.match(m, /could not/i, `${name} names the failure`);
  }
  // and each names its OWN remedy, because a blocked profile and a truncated blob are different
  // problems (the braceAttemptReason house rule: name the fix, not just the miss)
  assert.match(blocked, /blocking storage|Private windows/i, 'blocked names the cause');
  assert.match(blocked, /File then Open/, 'and the way back in');
  assert.match(corrupt, /incomplete or damaged/i);
  assert.match(deep, /nested too deeply/i);
  // the two recoverable cases say the copy survives AND that typing replaces it - the cliff
  assert.match(corrupt, /has not been deleted/i);
  assert.match(corrupt, /before typing|replaces it/i, 'and warns that editing overwrites it');
  assert.match(deep, /has not been deleted/i);
  // three distinct messages, not one wearing three labels
  assert.equal(new Set([blocked, corrupt, deep]).size, 3);
  // an unknown reason yields nothing, so a future arm cannot flash `undefined` at a user
  assert.equal(c.restoreFailMessage('nope'), null);
  assert.equal(c.restoreFailMessage(undefined), null);
});

test('#1136 the restore path separates the four failures instead of one bare catch', () => {
  const fn = between(_src, '(function restoreAutosave()', '// UXP-126: first-run Examples');
  // the bare `catch(_) {}` that swallowed all four is gone
  assert.doesNotMatch(fn, /catch\(_\) \{\}/, 'the swallowing catch must not survive');
  assert.match(fn, /catch\(_\) \{ autosaveRestoreFailed = 'blocked'; return; \}/, 'a throwing getItem is a blocked profile');
  assert.match(fn, /JSON\.parse\(raw\); \} catch\(_\) \{ autosaveRestoreFailed = 'corrupt'/, 'a truncated payload is corrupt');
  assert.match(fn, /if \(!data \|\| !data\.root\) \{ autosaveRestoreFailed = 'corrupt'/, 'a missing root is corrupt');
  assert.match(fn, /if \(treeDepthExceeds\(data\.root\)\) \{ autosaveRestoreFailed = 'deep'/,
    'and a too-deep tree is its OWN reason - applyAutosaveData returns false for both, which is why they were indistinguishable');
  // a genuinely fresh boot must stay silent, or every first run cries wolf
  assert.match(fn, /if \(!raw\) return;/, 'no autosave at all is not a failure');

  // PIN THE CALL SITE, not only the core (#1133 / UXP-260). Sixth time this session that this rule
  // is the one doing the work.
  assert.match(_src, /if \(autosaveRestoreFailed\) flashError\(restoreFailMessage\(autosaveRestoreFailed\)\);/,
    'boot must actually flash the reason');
  // it sits with its embed twin, which is the precedent (#449 / #845)
  const bootIdx = _src.indexOf('if (autosaveRestoreFailed) flashError');
  assert.ok(bootIdx > -1 && _src.indexOf('if (embedRestoreFailed) {') > bootIdx,
    'the autosave message sits beside the embed one it was modelled on');
});

test('#1113 capability is learned, not inferred from the presence of an API', () => {
  // hasOPFS is `navigator.storage && navigator.storage.getDirectory` -- a PRESENCE check. The method
  // exists in a private window and on file://, where calling it throws. Everything that asks "is
  // there a durable copy" must consult opfsOk, which is cleared the first time a real call fails.
  assert.match(_src, /let opfsOk = hasOPFS;/, 'the learned capability flag exists');
  assert.match(fnBody(_src, 'writeOpfsAutosave'), /opfsOk = false;/,
    'a failed OPFS WRITE is what proves the sink unusable');
  assert.doesNotMatch(fnBody(_src, 'readOpfsAutosave'), /opfsOk = false/,
    'but a failed READ must not: a first boot has no autosave.json, and NotFoundError is not a ' +
    'capability failure. Clearing it there raised a false "unsaved" alarm on every fresh start.');
  // the consumers
  assert.match(fnBody(_src, 'unsavedToDisk'), /autosaveDisabled && !opfsOk/,
    'the dirty dot and the beforeunload guard read capability, not presence');
  assert.match(fnBody(_src, 'scheduleAutosave'), /autosaveDisabled && !opfsOk && !workspaceFile/,
    'and so does the autosave bail');
});

// ── #1108: a slash in prose must not eat the paragraph ──
test('#1108 restoreTypedRun — hands back what was typed into the palette', () => {
  // The inverse of stripTriggerRun. A novelist typed "the harbour master / his son, whichever
  // answered."; the slash opened the Guided palette and every character after it landed in the
  // search input, which closeBuilderWindow destroyed with innerHTML = ''. The text never reached
  // the document, so undo could not reach it either. Driven before the fix: node.text ended at
  // "...harbour master /" and the rest was gone for good.
  const r = c.restoreTypedRun('She would ask the harbour master /', 33, 0, ' his son, whichever answered.');
  assert.equal(r.text, 'She would ask the harbour master / his son, whichever answered.');
  assert.equal(r.caret, r.text.length, 'the caret lands where the typing left off');
  const mid = c.restoreTypedRun('a / b', 2, 0, 'X');
  assert.equal(mid.text, 'a /X b', 'splices at the trigger, so text after the run survives');
  // #1466 corrected this one. It encoded the box holding only the UN-typed remainder ('o' after a
  // matched 'tod'), which cannot happen: #1396 seeds the box with the whole matched query, so the
  // box reads 'todo' and the run it hands back REPLACES 'tod' rather than following it. Appending
  // was how `Roll @` + `d` + `ice` came back as `Roll @ddice`.
  assert.equal(c.restoreTypedRun('go /tod', 3, 3, 'todo').text, 'go /todo', 'the box replaces the matched query');
  assert.equal(c.restoreTypedRun('go /tod', 3, 3, 'o').text, 'go /o', 'and it is the box that is authoritative');
  assert.equal(c.restoreTypedRun('a /', 2, 0, '').text, 'a /', 'nothing typed changes nothing');
  assert.equal(c.restoreTypedRun('a /', 2, 0, null).text, 'a /');
});

// ── #1464: where focus goes when a surface closes or acts ───────────────────
// Three of the six symptoms, one shape. Driven censuses, not the issue's samples: B6 named two
// menu rows that dropped focus and there were ELEVEN; B3 named Schedule against Check and Aliases,
// and through the point menu ALL NINE forms lost the caret.
test('#1464 B6: a menu row that acts leaves focus somewhere usable', () => {
  // the restore existed (#1411) and was wired to Escape and the to-do picker only; the ordinary
  // action rows were built with "each fn owns its own dismissal", which quietly meant its focus too
  const sb = fnBody(_src, 'showBulletPopup');
  assert.match(sb, /bpopRestoreAfterAction\(back, rowIdx < 0 \? null : rowIdx\)/,
    'every action row restores after its fn runs');
  assert.match(sb, /const rowIdx = \[\.\.\.document\.querySelectorAll\('\.node-content\[data-id\]'\)\]/,
    'the row index is read BEFORE the action, because Delete removes the row it is about');
  const helper = fnBody(_src, 'bpopRestoreAfterAction');
  // the two conditions that keep it from firing where it should not
  assert.match(helper, /if \(nodeId == null\) return;/,
    'keyboard-opened menus only: .node-content focus enters edit mode, which a mouse user did not ask for');
  assert.match(helper, /if \(ae && ae !== document\.body && !bpop\.contains\(ae\)\) return;/,
    'a row that placed focus deliberately keeps it, and the dismissed menu counts as nowhere');
  assert.match(helper, /bpopRestoreFocus\(fallbackIdx\)/, 'reusing the #1411 restore, fallback included');
});

test('#1464 B3: a dialog never hands focus back to a surface that closed behind it', () => {
  const drt = fnBody(_src, 'dialogReturnTarget');
  assert.match(drt, /bpop\.contains\(a\) && bpopReturnFocus != null/, 'the point-menu case');
  assert.match(drt, /ioCard\.contains\(a\) && builderState && builderState\.content/, 'the builder-card case');
  // ...and the `/` verbs whose dialog opens only AFTER the builder has torn itself down
  assert.match(drt, /_slashApplyContent && _slashApplyContent\.isConnected/, 'the slash-apply case');
  assert.match(drt, /_slashApplyContent\.classList\.contains\('node-content'\)/,
    'and it must still be a live point, not a stale reference');
  assert.match(drt, /\(!a \|\| a === document\.body\)/,
    'consulted only when focus has nowhere better to go, so it never overrides a real target');
  assert.match(fnBody(_src, 'slashApply'), /_slashApplyContent = content \|\| null;/,
    'slashApply records the point it is acting on, before hideSlashMenu nulls the state');
  assert.ok(fnBody(_src, 'slashApply').indexOf('_slashApplyContent = content') <
            fnBody(_src, 'slashApply').indexOf('hideSlashMenu()'),
    'and records it BEFORE that, or there is nothing left to record');
  assert.match(drt, /return a;/, 'and otherwise the active element, unchanged');
  // CENSUS: no capture site may still read activeElement raw, or the rule holds at twelve places
  // and not the thirteenth. This is the ratchet: a new dialog added later joins by construction.
  assert.equal((_src.match(/ioReturnFocus = document\.activeElement/g) || []).length, 0,
    'every capture routes through the helper');
  const captures = (_src.match(/ioReturnFocus = dialogReturnTarget\(\)/g) || []).length;
  assert.ok(captures >= 13, `the capture sites must all still be there, found ${captures}`);
});

test('#1464 B5: Tab stays inside the point-actions menu', () => {
  const kd = between(_src, "bpop.addEventListener('keydown'", "// The node id to restore focus to");
  assert.match(kd, /else if \(e\.key === 'Tab'\) \{ e\.preventDefault\(\);/,
    'Tab is claimed by the menu rather than walking out behind it');
  assert.match(kd, /items\[\(\(e\.shiftKey \? idx - 1 : idx \+ 1\) \+ items\.length\) % items\.length\]\?\.focus\(\)/,
    'and rovers both ways, wrapping, exactly like the arrows above it');
  // Escape is still the way out, which is what a menu is supposed to offer
  assert.match(kd, /e\.key === 'Escape'.*hideBpop\(\); bpopRestoreFocus\(\)/);
});

// ── #1466: the seeded search box counted its own first characters twice ─────
test('#1466 the restored run replaces the seeded query instead of following it', () => {
  const r = c.restoreTypedRun;
  // the report: `Roll @` is punctuation until a word character follows (#1108), so the palette
  // opens on `@d` with the box seeded `d`; finishing the word and pressing Escape wrote `@ddice`
  assert.deepEqual(host(r('Roll @d', 5, 1, 'dice')), { text: 'Roll @dice', caret: 10 });
  // the same defect on `/`, which the report believed immune — it is immune only AT THE START,
  // where nothing is seeded because a bare trigger opens on its own there
  assert.deepEqual(host(r('Roll /h', 5, 1, 'head')), { text: 'Roll /head', caret: 10 });
  assert.deepEqual(host(r('/', 0, 0, 'head')), { text: '/head', caret: 5 }, 'the unseeded case is unchanged');
  assert.deepEqual(host(r('@', 0, 0, 'dice')), { text: '@dice', caret: 5 });
  // the box is authoritative, so EDITING it away from the seed leaves no stale character behind:
  // appending only the remainder would have fixed the report and still written `Roll @dnote`
  assert.equal(r('Roll @d', 5, 1, 'note').text, 'Roll @note');
  assert.equal(r('Roll @d', 5, 1, 'math').text, 'Roll @math');
  // text after the run survives, and the caret lands where the typing left off
  const mid = host(r('a /h b', 2, 1, 'head'));
  assert.equal(mid.text, 'a /head b');
  assert.equal(mid.caret, 7, 'just past what was handed back, not at the end of the line');
  // a longer seed, and a shorter box than the seed (a backspace mid-word)
  assert.equal(r('go /todo', 3, 4, 'to').text, 'go /to');
  assert.equal(r('go /todo', 3, 4, 'todo').text, 'go /todo', 'unchanged when the box still reads the seed');
  // clamped rather than throwing when the recorded query runs past the text
  assert.equal(r('a /x', 2, 99, 'y').text, 'a /y');
  assert.equal(r('a /', 2, 0, '').text, 'a /', 'nothing typed changes nothing');
  assert.equal(r('a /', 2, 0, null).text, 'a /');

  // CALL SITE — one consumer, the dismissal path, and it still passes the state's own query length
  assert.match(fnBody(_src, 'builderReturnTypedText'),
    /restoreTypedRun\(builderSpliceText\(node\), builderSpliceOffset\(node, st\.offset\), st\.query\.length, typed\)/);
  // the invariant the replace rests on: the box is seeded from that same query (#1396)
  assert.match(_src, /let filterQ = \(builderState && builderState\.query\) \|\| '';/);
  assert.match(_src, /if \(filterQ\) searchEl\.value = filterQ;/);
  // and an empty box still returns early, which is why replacing can never delete a seed the user
  // did not touch — the one boundary left deliberately where it was
  assert.match(fnBody(_src, 'builderReturnTypedText'), /const typed = document\.querySelector\('\.builder-search'\)\?\.value \|\| '';\s*\n\s*if \(!typed\) return;/);
});

test('#1108 the trigger stops firing on a bare slash mid-prose', () => {
  // At the start of a point a lone `/` still opens (the Guided command line); mid-text it needs at
  // least one word character. Driven: "three / four" and "email me @ home" no longer open anything,
  // "/tod" mid-line still does, and the novelist's full sentence survives intact.
  // NB: not fnBody(). fnBody does indexOf('function ' + name), which PREFIX-matches -- it returns
  // closeBuilderWindow's body for 'closeBuilder'. Anchor on the source directly (#1131).
  // #1516 widened this by exactly one escape hatch: a BUTTON may say it meant it (`opts.force`).
  // The claim is unchanged for everything the user TYPES, which is what this guard is about, and
  // the census below pins that only a real door can reach the hatch.
  assert.match(_src, /if \(slashOffset !== 0 && !rawQuery && !\(opts && opts\.force\)\) \{ hideSlashMenu\(\); return; \}/,
    'a bare trigger mid-text must not open the palette');
  const forced = nonEmpty([..._src.matchAll(/checkSlash\(([^)]*)\)/g)], 'checkSlash call sites')
    .map(m => m[1]).filter(a => a.includes('force'));
  assert.deepEqual(forced, ["content, id, { force: true }"],
    'exactly one call site may bypass the bare-trigger guard: the "Insert a pill" button (#1516)');
  assert.match(_src, /nodeById\(nodeId\)\?\.type === 'para'\) \{ hideSlashMenu/,
    'the paragraph carve-out stays: Enter means line break there, so an open menu could eat the block');
});

// #1516: the touch edit bar's "Insert a pill" button worked at caret 0 and was DEAD everywhere
// else, silently. UXP-105 shipped it and its verification line reads "Verified: the
// execCommand('@') path opens the insert menu on desktop" -- verified at the one position where it
// happens to work, which is why the regression went unrecorded and `ux-discipline.md` still marked
// the door conformant.
//
// TWO barriers sit between a mid-text '@' and the menu, and only removing both opens it:
//   1. the trigger regex needs `^`, whitespace or `}` before the sigil, so at `Buy milk|` the typed
//      '@' produced `Buy milk@` and matched nothing -- permanently, since the glued sigil stays in
//      the text and every later keystroke re-fails the same match.
//   2. #1108's bare-trigger carve-out then suppresses even a correctly-spaced mid-text '@'.
// Measured: the first barrier is NOT "after a word character" as filed -- `Buy milk,` and `Buy (`
// are dead the same way.
test('#1516 the touch "Insert a pill" button opens the menu wherever the caret is', () => {
  const { insertSigilNeedsSpace } = c;
  // ---- 1. the predicate, by value.
  assert.equal(insertSigilNeedsSpace('Buy milk', 8), true, 'after a word character');
  assert.equal(insertSigilNeedsSpace('Buy milk,', 9), true, 'after punctuation -- WIDER than the filed "word character"');
  assert.equal(insertSigilNeedsSpace('Buy (', 5), true, 'after an opening bracket');
  assert.equal(insertSigilNeedsSpace('Buy milk ', 9), false, 'after a space the regex already matches');
  assert.equal(insertSigilNeedsSpace('{2d6}', 5), false, 'after a closing brace -- #919 made that a command position');
  assert.equal(insertSigilNeedsSpace('', 0), false, 'at the start of an empty point');
  assert.equal(insertSigilNeedsSpace('Buy milk', 0), false, 'at the start of text -- the one case that always worked');
  assert.equal(insertSigilNeedsSpace('Buy milk', 4), false, 'mid-text but after a space');
  // it reads the character BEFORE the caret, not the last character of the text
  assert.equal(insertSigilNeedsSpace('a b', 2), false, 'the caret position is what matters, not the tail');
  // out of range and junk clamp rather than throw
  assert.equal(insertSigilNeedsSpace('ab', 99), true);
  assert.equal(insertSigilNeedsSpace(null, 5), false);
  assert.equal(insertSigilNeedsSpace('ab', null), false);

  // ---- 2. THE PREDICATE TRACKS THE REGEX. This is the pin that matters: the two are separate
  // pieces of source that must agree, and a change to either alone is the way this breaks again.
  // The regex is read out of the app rather than restated here.
  const lit = /const m = before\.match\((\/.*?\/)\);/.exec(_src);
  assert.ok(lit, 'the trigger regex must still be a literal in checkSlash');
  const trig = new RegExp(lit[1].slice(1, -1));
  for (const ch of ['k', '5', ',', '(', ')', '.', '-', '"', '@', ' ', '\t', '\n', '}', '{']) {
    const opens = trig.test(ch + '@');
    assert.equal(insertSigilNeedsSpace(ch, 1), !opens,
      `after ${JSON.stringify(ch)} the predicate and the trigger regex must agree`);
  }

  // ---- 3. THE CALL SITE. A predicate nothing consults is decoration.
  // end-anchored on the NEXT handler, not on '});' -- the forced checkSlash call itself ends in
  // '});' and would truncate the window just before the thing being asserted.
  const src = between(_src, "ebBtn('eb-insert'", "ebBtn('eb-todo'");
  assert.ok(src.includes("insertSigilNeedsSpace(editableText(content), getCaretOffset(content)) ? ' @' : '@'"),
    'the button must space the sigil off the preceding token, or the menu can never open');
  assert.ok(src.includes("document.execCommand('insertText', false, sigil)"),
    'still the TYPED path -- one execCommand, so it is one undo step and slashApply strips it as usual');
  assert.ok(src.includes('checkSlash(content, id, { force: true })'),
    'and the button must say it meant it, or #1108 suppresses the bare mid-text sigil');
  // the order is load-bearing: the input handler's own checkSlash runs first and (correctly) hides.
  assert.ok(src.indexOf("execCommand('insertText'") < src.indexOf('checkSlash(content, id'),
    'the forced re-check must come AFTER the insertion, not before it');
  assert.ok(!/document\.execCommand\('insertText', false, '@'\)/.test(_src),
    'the old unconditional bare-@ insertion must be gone');
});

test('#1108 dismissal is a CANCEL that returns the text; apply is not', () => {
  // The close path had NO test at all before this - not dismissal, not Escape, not text
  // preservation - which is why four sentences could vanish with a green suite.
  assert.match(_src, /function closeBuilder\(cancelled = false\)/,
    'closeBuilder distinguishes cancel from apply');
  assert.match(_src, /else if \(cancelled\) builderReturnTypedText\(\);/,
    'only a cancel restores - an apply already spliced its result, so restoring would double it');
  const rt = fnBody(_src, 'builderReturnTypedText');
  assert.ok(rt.length > 60, 'builderReturnTypedText exists (fnBody returns \'\' on a miss)');
  assert.match(rt, /restoreTypedRun\(/, 'the restore routes through the pure core');
  assert.match(rt, /\.builder-search/, 'and reads the search box, the only place those characters existed');
  assert.match(_src, /ioCancel = \(\) => closeBuilder\(true\)/, 'backdrop dismiss cancels');
  assert.ok((_src.match(/closeBuilder\(true\)/g) || []).length >= 3,
    'the Escape handlers cancel too (search, nav, pane), not just the backdrop');
});

