// ── #565 starters: the embedded example gallery stays well-formed ─────────────
// A source-shape pin (fromOpml needs a real DOMParser, absent in Node): every
// gallery entry is present, each embeds a single `# heading` OPML subtree, and
// the user-facing copy carries no em dash (the house punctuation rule).
const _fStarters = readFileSync(new URL('../index.html', import.meta.url), 'utf8');
test('starters (#565) — gallery entries present, heading-rooted, em-dash-free', () => {
  const start = _fStarters.indexOf('const STARTERS = [');
  const block = _fStarters.slice(start, _fStarters.indexOf('\n];', start));
  assert.ok(start > -1, 'STARTERS array present');
  for (const id of ['campaign-oracle', 'character-sheet', 'project-tracker', 'reading-log', 'life-dashboard', 'meal-planner', 'decision-helper', 'flashcards', 'home-inventory', 'research-notes', 'series-bible', 'household-budget', 'freelance-costing', 'game-workbench'])
    assert.ok(block.includes(`id: '${id}'`), `starter ${id} present`);
  const opmls = block.split('opml: `').slice(1);
  assert.equal(opmls.length, 14, 'one embedded OPML per starter');   // starter overhaul: cut oracle-play/worldbuilding/trip-planner, added series-bible/household-budget/freelance-costing/game-workbench
  for (const o of opmls) assert.match(o, /<outline text="# /, 'each starter roots in a # heading subtree');
  assert.ok(!block.includes('—'), 'no em dashes in starter copy (user-facing)');
});

test('#1196 research-notes starter surfaces {roll:#tag} + written footnotes, and leads the quick-picks', () => {
  // The #1196 deliverable: the two prose lead features (roll on your OWN tagged notes; a written
  // footnote carrying a source) are now LIVE in a starter a first-run user reaches, not palette-only.
  const rn = between(_fStarters, "id: 'research-notes'", "id: 'life-dashboard'");
  assert.match(rn, /\{roll:\s*#openq\}/, 'draws a live question from the user\'s own #openq notes');
  assert.match(rn, /\[\^\w+\]/, 'carries a footnote marker (the prose citation)');
  assert.match(rn, /_footnotes="/, 'and ships the WRITTEN footnote text (first starter to do so)');
  // It is one of the six Welcome quick-picks, so a prose/research user meets it on the first screen.
  const qp = between(_fStarters, 'const WELCOME_QUICK_PICKS = [', '];');
  assert.ok(qp.includes("'research-notes'"), 'research-notes is a Welcome quick-pick (default first-run path)');
  // #1195: it also ships a LIVE prose CHECK (every claim cited) + the #claim tags it asserts over.
  assert.ok((rn.match(/\[\^\w+\] #claim/g) || []).length >= 2,
    '#1195: BOTH footnoted claim lines are tagged #claim, so the check is non-vacuous');
  assert.match(rn, /&quot;key&quot;:&quot;check&quot;/, '#1195: the Claims section ships a check property');
  assert.match(rn, /count\(\\\\&quot;#claim -has:footnote\\\\&quot;\) == 0/,
    '#1195: the check asserts every claim carries a source (double-backslash survives the template literal)');
});

test('starter overhaul: each new/rewritten starter surfaces its assigned hidden power (source pin)', () => {
  // The overhaul thesis: a starter is a finished document that WEAVES IN one engine power by doing a real
  // job, not a feature tour. Each slice below pins that power in source. A source-pin proves the syntax is
  // present, not that it renders live (that is the browser drive) — but a dropped power fails here.
  const slice = (a, b) => between(_fStarters, `id: '${a}'`, `id: '${b}'`);
  // household-budget: THE scoped rollup — a monthly total pointed at a tag, over the whole document, vs a cap check.
  const hh = slice('household-budget', 'freelance-costing');
  assert.match(hh, /sum\(&quot;#august&quot;, cost, document\)/, 'household: scoped month sum over the document');
  assert.match(hh, /sum\(\\\\&quot;#august\\\\&quot;, cost, document\) &lt;= cap/, 'household: the cap check (double-backslash survives the template literal)');
  // freelance-costing: an honest estimate (percentile + chanceover), an hours*rate check, and a written footnote.
  const fc = slice('freelance-costing', 'game-workbench');
  assert.match(fc, /percentile\(estq, 90\)/, 'freelance: the 90th-percentile safe number');
  assert.match(fc, /chanceover\(estq, 25\)/, 'freelance: the odds-of-overrun estimate');
  assert.match(fc, /sum\(\\\\&quot;#task\\\\&quot;, hours, document\) \* rate &lt;= quote/, 'freelance: the over-quote check (double-backslash survives the template literal)');
  assert.match(fc, /_footnotes="/, 'freelance: the rate footnote is written');
  assert.match(fc, /sum\(&quot;#task&quot;, hours, folder\)/,
    '#1242: surfaces the cross-doc rollup (the across-all-jobs total widens the same sum to the folder)');
  // game-workbench: a dice pool with the distribution peek, a scoped card count, and a live embed of the set.
  const gw = slice('game-workbench', 'flashcards');
  assert.match(gw, /\{5d10&gt;=7\}/, 'game: a keep-successes dice pool (the distribution-peek target)');
  assert.match(gw, /count\(&quot;#card cost:&gt;=4&quot;, document\)/, 'game: a scoped card-set count');
  assert.ok(gw.includes('_id="prototypecards"') && gw.includes('[[#prototypecards|]]'), 'game: the card set is mirrored live into the session log');
  // series-bible: a plain cast roll and a live character embed in a scene. The cast pages have children
  // (traits, debts, wants), so the draw MUST be a plain roll: a folder roll reaches descendants and would
  // pick a trait line, and a co-located plain+folder roll on #character also races on promotion. The
  // cross-folder showcase lives in campaign-oracle, whose nodes are childless leaves.
  const sb = slice('series-bible', 'meal-planner');
  assert.match(sb, /\{roll: #character\}/, 'series: the cast draw is a plain roll (picks a whole character page)');
  assert.ok(!/roll folder: #character/.test(sb),
    'series: NO folder roll on #character (it would reach into the trait/debt children, and race the plain roll)');
  assert.ok(sb.includes('_id="sereth"') && sb.includes('[[#sereth|]]'), 'series: a character mirrored into a scene');
  // decision-helper: the estimate lane (percentile + chanceover) and the verdict embed. The acost variable
  // MUST be declared before it is read (the #ERR-declared-later fix) — pin the order so a regression bites.
  const dh = slice('decision-helper', 'series-bible');
  assert.match(dh, /percentile\(acost, 90\)/, 'decision: the 90th-percentile safe cost');
  assert.match(dh, /chanceover\(acost, 33000\)/, 'decision: the odds-of-overrun estimate');
  assert.ok(dh.includes('_id="theverdict"') && dh.includes('[[#theverdict|]]'), 'decision: the verdict is mirrored to the top');
  assert.ok(dh.indexOf('{acost :=') > -1 && dh.indexOf('{acost :=') < dh.indexOf('percentile(acost'),
    'decision: acost is declared BEFORE it is read (else evalMath surfaces #ERR declared-later)');
  // meal-planner: a constraint-aware plan — a scoped week total and filtered night counts, not a slot machine.
  const mp = slice('meal-planner', 'home-inventory');
  assert.match(mp, /sum\(&quot;#thisweek&quot;, cost, document\)/, 'meal: the scoped weekly grocery total');
  assert.match(mp, /count: #dinner -is:done/, 'meal: nights-left-to-cook is a filtered count, not a deck deal');
});

test('starter level-ups: each keeper surfaces its assigned hidden power (source pin)', () => {
  // PR-2 leveled the seven keepers to the same bar as the rebuilt roster, each weaving in one power.
  // Source-pins prove the power is present; the browser drive proved each computes. evalMath query-count
  // and query-sum default to SUBTREE scope, so a cross-section total carries the `, document` widener.
  const slice = (a, b) => between(_fStarters, `id: '${a}'`, `id: '${b}'`);
  // project-tracker: the overdue watch is a doc-scoped query count, mirrored by a doc-scoped check.
  const pt = slice('project-tracker', 'campaign-oracle');
  assert.match(pt, /count\(&quot;is:todo is:overdue&quot;, document\)/, 'project: the overdue watch (doc-scoped query count)');
  assert.match(pt, /count\(\\\\&quot;is:todo is:overdue\\\\&quot;, document\) == 0/, 'project: the all-dates-safe check (doc-scoped)');
  // campaign-oracle: the cross-folder roll. Kept to ONE roll per tag (plain #npc, folder #thread) so the
  // promotion-order race that pollutes a co-located plain+folder roll on the SAME tag cannot occur.
  const co = slice('campaign-oracle', 'reading-log');
  assert.match(co, /\{roll folder: #thread\}/, 'campaign: the cross-folder thread roll');
  assert.ok(!/\{roll folder: #npc\}/.test(co) || !/\{roll: #npc\}/.test(co),
    'campaign: no tag carries both a plain and a folder roll (avoids the promotion-order race)');
  // reading-log: the this-year total is a doc-scoped sum over a year tag, separate from the all-time rollup.
  const rl = slice('reading-log', 'research-notes');
  assert.match(rl, /sum\(&quot;#2026&quot;, pages, document\)/, 'reading: this-year pages (doc-scoped year sum)');
  assert.match(rl, /\{= sum\(pages\)\}/, 'reading: the all-time rollup is a bare child sum');
  // life-dashboard: the today list mirrored to the top via a live embed.
  const ld = slice('life-dashboard', 'character-sheet');
  assert.ok(ld.includes('_id="today"') && ld.includes('[[#today|]]'), 'life: today is mirrored to the top');
  // character-sheet: two derived checks (downed at zero HP; overloaded pack).
  const cs = slice('character-sheet', 'decision-helper');
  assert.match(cs, /hp &gt; 0/, 'character: the downed-at-zero check');
  assert.match(cs, /sum\(weight\) &lt;= might \* 5/, 'character: the encumbrance check reads a stat');
  // home-inventory: doc-scoped category sub-limits and per-room sums, with two written footnotes.
  const hi = slice('home-inventory', 'household-budget');
  assert.match(hi, /sum\(&quot;#jewelry&quot;, value, document\)/, 'home: the jewelry sub-limit sum (doc-scoped)');
  assert.match(hi, /sum\(\\\\&quot;#jewelry\\\\&quot;, value, document\) &lt;= 1500/, 'home: the jewelry sub-limit check');
  assert.match(hi, /sum\(&quot;#bedroom&quot;, value, document\)/, 'home: a per-room sum');
  assert.ok((hi.match(/_footnotes="/g) || []).length >= 2, 'home: both footnotes are written');
  // flashcards: mastery is a pair of filtered counts over the syllabus topics.
  const fc = between(_fStarters, "id: 'flashcards'", '\n];');
  assert.match(fc, /count: #topic is:done/, 'flashcards: mastered count (done topics)');
  assert.match(fc, /count: #topic -is:done/, 'flashcards: still-to-master count (undone topics)');
});

test('#1195 the reveal-offenders affordance is wired (chip + both seams, edit preserved)', () => {
  // The magnifier appears ONLY on a failing query-check and reveals its offenders; a source-pin proves
  // presence, the live-drive proves it works (a handler on an unfocusable node still passes a pin, #1021).
  const chip = fnBody(_src, 'buildCheckChip');
  // Pin the GATE specifically (fail + checkQuery together), not the pre-existing verdict ternaries.
  assert.match(chip, /if \(verdict === 'fail'\) \{\s*\n\s*const q = checkQuery\(expr\);/,
    'the reveal is gated on a FAILING check that embeds a query');
  assert.match(chip, /prop-check-reveal/, 'it builds the reveal control');
  assert.match(chip, /Show the \$\{nn\} this check flags/, 'named for AT (P3)');
  assert.ok(/queryCountIn\(q\.query, node\)/.test(chip) && /queryReduceFolder\('count'/.test(chip),
    'N is counted with the same reducer the pill uses');

  // Props-area chips sit OUTSIDE the .node-content keydown delegate, so the reveal wires its OWN
  // click + keydown (the base-view sub-button pattern). click stopPropagation keeps the chip's edit
  // delegate from also firing; keydown is the Enter/Space twin beside mousedown (P3-2, caret invariant).
  assert.match(chip, /reveal\.addEventListener\('mousedown', e => \{ e\.preventDefault\(\); e\.stopPropagation\(\); \}\)/,
    'mousedown keeps focus put');
  assert.match(chip, /reveal\.addEventListener\('click', e => \{ e\.stopPropagation\(\); revealCheckOffenders\(reveal\); \}\)/,
    'click reveals, and stops the edit delegate from also firing');
  assert.ok(/reveal\.addEventListener\('keydown'[\s\S]{0,160}Enter[\s\S]{0,120}revealCheckOffenders\(reveal\)/.test(chip),
    'Enter/Space is the keyboard twin (P3)');

  // Edit-click regression guard: the chip body still opens the check editor (the outline delegate is
  // unchanged, and a reveal click stops propagation so only the BODY reaches it).
  assert.match(_src, /const chip = e\.target\.closest\('\.prop-chip'\);\n\s*if \(chip\) openPropChip\(chip\)/,
    'the chip body still opens the editor (P1 preserved)');

  // The reveal runs the query in the search box, zooming first for a subtree-scoped check.
  const rc = fnBody(_src, 'revealCheckOffenders');
  assert.ok(rc.includes('applySearch(q)') && rc.includes("getElementById('search-box')") && rc.includes('sb.focus()'),
    'reveal runs the embedded query in the search box (tag-browser precedent)');
  assert.match(rc, /revealScope === 'subtree'[\s\S]{0,80}zoomTo\(id\)/, 'a subtree-scoped check zooms in so the search scopes to it');
});

test('#1196 drift guard: every [^footnote] shipped in a starter is WRITTEN (has _footnotes text)', () => {
  // Sibling of #1107 (which guards {roll:} pools). A starter that ships a bare [^ref] marker with no
  // matching _footnotes text renders "Nothing written here yet", a dead demo of the very feature we
  // are surfacing. This asserts every marker has a written footnote, so that can never ship.
  const start = _fStarters.indexOf('const STARTERS = [');
  const block = _fStarters.slice(start, _fStarters.indexOf('\n];', start));
  // Scan only rendered text (text="…"), not comments/attribute names, since a [^key] in a code comment is
  // documentation, not a shipped marker.
  const texts = [...block.matchAll(/text="([^"]*)"/g)].map(m => m[1]);
  const markers = nonEmpty(texts.flatMap(t => [...t.matchAll(/\[\^(\w+)\]/g)].map(m => m[1])), 'shipped starter footnote markers');
  // _footnotes attributes are &quot;-escaped JSON in source; a written entry has non-empty text.
  const written = new Set();
  for (const m of block.matchAll(/&quot;key&quot;:&quot;(\w+)&quot;,&quot;text&quot;:&quot;([^&]+)&quot;/g))
    if (m[2].trim()) written.add(m[1]);
  for (const k of markers)
    assert.ok(written.has(k), `starter footnote [^${k}] has no written _footnotes text, so it would render "Nothing written here yet"`);
});

test('#1196 the prose recipe pairs a roll on your notes with a footnote (guide surfacing)', () => {
  const rec = between(_src, "id:'recipe-research'", '] }');
  assert.match(rec, /cat:'recipes'/, 'recipe-research is a Put-it-together recipe');
  assert.match(rec, /\{roll:\s*#openq\}/, 'pairs a roll on your own tagged notes');
  assert.match(rec, /\[\^ref\]/, 'with a footnote that pins the source');
});

// ─── workspace sync-safety batch (#840/#842/#845 items 1+2) ───────────────────
const _fSync = readFileSync(new URL('../index.html', import.meta.url), 'utf8');
test('#840 — the size fingerprint is anchored wherever the mtime anchor is set', () => {
  // one shared declaration next to the mtime anchor
  assert.ok(_fSync.includes('let _wsKnownSize = 0;'), '_wsKnownSize declared');
  // anchorWorkspaceFile captures both from ONE getFile() (post-write, connect, writeH)
  assert.match(_fSync, /async function anchorWorkspaceFile\(\) \{\s*\n\s*if \(!workspaceFile\) \{ _wsKnownModified = 0; _wsKnownSize = 0; return; \}[\s\S]{0,400}_wsKnownSize = f\.size \|\| 0;/,
    'anchorWorkspaceFile must reset + capture the size with the mtime');
  // every direct `_wsKnownModified = file.lastModified` anchor site carries the size twin
  const direct = _fSync.split('_wsKnownModified = file.lastModified || 0;').length - 1;
  const twins  = _fSync.split('_wsKnownSize = file.size || 0;').length - 1;
  assert.ok(direct >= 5, 'expected the reopen/switch/reload/theirs/copy direct anchor sites, saw ' + direct);
  assert.equal(twins, direct, 'every direct mtime anchor site must set _wsKnownSize from the same File');
  // teardown resets both
  assert.match(_fSync, /function stopWorkspaceWatch\(\) \{[\s\S]{0,200}_wsKnownModified = 0;\s*\n\s*_wsKnownSize = 0;/, 'stopWorkspaceWatch must drop the size anchor too');
});
test('#840 — the flush pre-write gate and the change detector pass both fingerprints', () => {
  assert.match(_fSync, /let diskModified = _wsKnownModified, diskSize = _wsKnownSize;\s*\n\s*try \{ const f = await workspaceFile\.getFile\(\); diskModified = f\.lastModified \|\| 0; diskSize = f\.size \|\| 0; \} catch \(_\) \{\}\s*\n\s*const action = reconcileAction\(\{ diskModified, knownModified: _wsKnownModified, diskSize, knownSize: _wsKnownSize, dirty: true \}\);/,
    'flushWorkspaceFile pre-write staleness gate must compare size too');
  assert.match(_fSync, /catch \(_\) \{ return; \}\s*\n\s*const action = reconcileAction\(\{ diskModified, knownModified: _wsKnownModified, diskSize, knownSize: _wsKnownSize, dirty \}\);/,
    'checkExternalChange must compare size too');
});
test('#842 — BOTH mid-session losing-copy branches stash the local copy before adopting (the #729/#746 doctrine)', () => {
  const fn = between(_fSync, 'async function handleExternalChange(', 'function openReconcileDialog(');
  // the silent 'reload' branch: capture pre-adopt, stash, and point at the restore door
  const reload = fn.slice(0, fn.indexOf('_wsReconciling = true;'));
  assert.match(reload, /localPayload = localStorage\.getItem\(AUTOSAVE_KEY\);[\s\S]{0,700}adoptDoc\(fromOpml\(await file\.text\(\)\)[\s\S]{0,400}stashPayloadAsPrev\(localPayload, localId\)/,
    'reload branch must capture the payload pre-adopt and stash it');
  assert.ok(reload.includes("(stashed ? ' Your previous copy: File menu, Restore earlier version.' : '')"), 'reload flash must carry the restore pointer when stashed');
  // the 'theirs' choice: same capture-pre-adopt + stash + pointer
  const theirs = between(fn, "if (choice === 'theirs')", "else if (choice === 'copy')");
  assert.match(theirs, /localPayload = localStorage\.getItem\(AUTOSAVE_KEY\);[\s\S]{0,700}adoptDoc\(fromOpml\(await file\.text\(\)\)[\s\S]{0,400}stashPayloadAsPrev\(localPayload, localId\)/,
    "'theirs' must capture the payload pre-adopt and stash it");
  assert.ok(theirs.includes("(stashed ? ' Your previous copy: File menu, Restore earlier version.' : '')"), "'theirs' flash must carry the restore pointer when stashed");
  // the recorded asymmetry: 'mine' deliberately does NOT stash the foreign disk tree
  const mine = fn.slice(fn.indexOf("// 'mine' (or dismissed)"));
  assert.ok(!mine.includes('stashPayloadAsPrev'), "'mine' must not stash (recorded asymmetry)");
});
test('#845 item 1 — every boot losing-copy path flashes, honestly, whether or not the stash stuck', () => {
  const fn = between(_fSync, 'async function reopenWorkspaceDoc(', 'function unmarkedFilesNote(');
  // sameDocDiverged: the old code gated the whole hint on stash success — silence exactly when storage is full
  assert.ok(!fn.includes('sameDocDiverged && stashPayloadAsPrev'), 'the success-gated hint must be gone');
  // (the stash is awaited since #846 made stashPayloadAsPrev async under the prev-store lock)
  assert.match(fn, /if \(sameDocDiverged\) \{\s*\n\s*const stashed = await stashPayloadAsPrev\(localPayload, localId\);/, 'sameDocDiverged must stash then branch the flash');
  // three honest failure variants (sameDocDiverged, identity-unknown, provably-different)
  const failures = fn.split('could not be kept as a restore point; storage may be full.').length - 1;
  assert.equal(failures, 3, 'all three losing-copy paths must name a failed stash');
  // the provably-different-document branch (flashed nothing at all before) now speaks
  assert.match(fn, /\} else if \(localId\) \{[\s\S]{0,600}The document open before was kept; open it and use File menu, Restore earlier version\./,
    'the different-document branch must flash');
});
test('#845 item 2 — unmarkedFilesNote (pure): the no-docId scan skip is named, not silent', () => {
  assert.equal(c.unmarkedFilesNote(0), '');
  assert.equal(c.unmarkedFilesNote(null), '');
  assert.equal(c.unmarkedFilesNote(-2), '');
  assert.equal(c.unmarkedFilesNote(1), '1 file in the folder carries no identity mark yet, so links and search skip it; open it to stamp it.');
  assert.equal(c.unmarkedFilesNote(3), '3 files in the folder carry no identity mark yet, so links and search skip them; open one to stamp it.');
  assert.ok(!c.unmarkedFilesNote(1).includes('—') && !c.unmarkedFilesNote(2).includes('—'), 'user-facing copy carries no em dash');
});
test('#845 item 2 — scanWorkspace counts the skips and the broken-links report surfaces them', () => {
  // §5.2: the count is now tallied from the cache states ('unmarked' = parsed, no docId), still
  // riding the returned index; a 'bad' (unreadable) entry stays a silent skip like the old catch.
  assert.match(_fSync, /else if \(c\.state === 'unmarked'\) unmarked\+\+;/, 'the scan must count an unmarked (no-docId) file, not silently continue');
  assert.match(_fSync, /r\.docId \?[^:]*state: 'doc'[\s\S]*?\{ lastModified, size, state: 'unmarked' \}/, 'a parsed file with no docId caches as unmarked');
  assert.match(_fSync, /const idx = buildWorkspaceIndex\(docs\);\s*\n\s*idx\.unmarked = unmarked;\s*\n\s*return idx;/, 'the count must ride the returned index');
  assert.match(_fSync, /const unmarkedMsg = unmarkedFilesNote\(workspaceIndex \? workspaceIndex\.unmarked : 0\);/, 'the broken-links report must consume the count');
});

// ─── Builder window: retroactive pins (measure/pin/wire, applied after the fact) ───────
// The builder window (Guided-only unified command browser, PR #1011 + the #1014–#1019
// remediation batch) shipped ~850 lines with ZERO coverage — the discipline was skipped
// because the CLAUDE.md rewrite (ae3b5b1) narrowed the pin trigger to "parser / eval core"
// and the DOM-wiring arm lived only in a load-cores comment. These pins close that gap:
// the shared trigger-strip math (the double-strip / form-overwrite bug locus) and the two
// pure pool/lookup cores get behavior pins; the DOM dispatch/guards get source-pins.

test('stripTriggerRun — removes the trigger run (trigger char + query) and reports the caret', () => {
  // "abc" + "/due" (trigger "/" + query "due") → strip the 4-char run at offset 3.
  assert.deepEqual(host(c.stripTriggerRun('abc/due', 3, 3)), { text: 'abc', caret: 3 });
  // bare trigger (queryLen 0) removes just the one trigger char.
  assert.deepEqual(host(c.stripTriggerRun('abc/', 3, 0)), { text: 'abc', caret: 3 });
  // trigger at the very start.
  assert.deepEqual(host(c.stripTriggerRun('/todo', 0, 4)), { text: '', caret: 0 });
  // surrounding text on both sides is preserved (the strip is a splice, not a truncate).
  assert.deepEqual(host(c.stripTriggerRun('hi /due there', 3, 3)), { text: 'hi  there', caret: 3 });
});

test('stripTriggerRun — with an insert, splices it in and lands the caret AFTER it', () => {
  // "hi {2d" (trigger "{" + query "2d") → replace the 3-char run with the "{2d6}" scaffold.
  assert.deepEqual(host(c.stripTriggerRun('hi {2d', 3, 2, '{2d6}')), { text: 'hi {2d6}', caret: 8 });
  // dialog-result insert: caret sits at offset + result.length.
  const r = c.stripTriggerRun('x@link', 1, 4, '[[url|text]]');
  assert.equal(r.text, 'x[[url|text]]');
  assert.equal(r.caret, 1 + '[[url|text]]'.length);
});

test('stripTriggerRun — one call removes exactly rawLen chars (the double-strip guard)', () => {
  // The shipped double-strip bug ran this math twice. A SINGLE call must remove exactly
  // 1 + queryLen characters; a second application on the already-stripped text would eat
  // real content — so we pin that one pass is lossless for the surrounding text.
  const once = c.stripTriggerRun('keep /verb keep', 5, 4);   // strip "/verb"
  assert.equal(once.text, 'keep  keep');                     // both "keep"s survive
  assert.equal(once.text.length, 'keep /verb keep'.length - 5);
});

test('builderCmdPool — the summoning trigger’s section leads, all three triggers present', () => {
  for (const [trig, want] of [['/', '/'], ['@', '@'], ['{', '{']]) {
    const pool = c.builderCmdPool(trig);
    assert.ok(pool.length > 0, `pool for ${trig} is non-empty`);
    // every command is fully shaped (a section + a trigger + a label).
    assert.ok(pool.every(cmd => cmd._section && cmd.trigger && cmd.label != null), `${trig} cmds are shaped`);
    // the FIRST command belongs to the summoning trigger (its section was hoisted first).
    assert.equal(pool[0].trigger, want, `${trig}: first command is a ${want} command`);
    // all three trigger families are represented in one pool (the builder absorbs /, @, {).
    const trigs = new Set(pool.map(cmd => cmd.trigger));
    assert.ok(trigs.has('/') && trigs.has('@') && trigs.has('{'), `${trig}: all trigger families present`);
  }
});

// ── #1106 — the builder search speaks /verb:value, and Enter fires the verb you typed ──
// In Guided (the DEFAULT tier) `/` opens the builder immediately, so its search box IS the command
// line: everything after the trigger is typed there, not into the point. Before this it matched the
// raw string as one substring over label+desc+section+keys, so every documented `/verb:value` form
// filtered to nothing and Insert greyed out.
test('#1106: builderFilterCmds splits verb from value, so /prop:owner=zeo still finds Property', () => {
  const pool = c.builderCmdPool('/');
  const bare = c.builderFilterCmds(pool, 'prop', '/');
  assert.ok(bare.some(x => x.id === 'prop'), 'bare verb finds the command');
  // The value must not be part of the haystack probe. Use a value that does NOT appear in any
  // desc — /prop:owner=zeo is quoted verbatim inside prop's own desc, so it would pass by accident.
  const withArg = c.builderFilterCmds(pool, 'prop:owner=Priya', '/');
  assert.ok(withArg.some(x => x.id === 'prop'), 'a real value still finds Property');
  assert.ok(c.builderFilterCmds(pool, 'due:2026-08-14', '/').some(x => x.id === 'due'), 'due keeps its date');
  assert.ok(c.builderFilterCmds(pool, 'check:sum(cost) <= budget', '/').some(x => x.id === 'check'),
    'a space-bearing value still resolves');
  // An empty query is the whole pool (the browse case), not an empty list.
  assert.equal(c.builderFilterCmds(pool, '', '/').length, pool.length);
});

test('#1106: builderFilterCmds matches a command by its own id', () => {
  const pool = c.builderCmdPool('/');
  // `id` was absent from the haystack, so a command matched only via label/desc/keys.
  const only = c.builderFilterCmds(pool, 'savetemplate', '/');
  assert.ok(only.some(x => x.id === 'savetemplate'), 'id is searchable');
});

test('#1106: builderBestIdx fires the exact-id verb, not the first fuzzy description hit', () => {
  const pool = c.builderCmdPool('/');
  const vis = c.builderFilterCmds(pool, 'prop', '/');
  // The regression this pins: `prop` matches querybase/math/meter first (their descriptions
  // mention properties), so Enter applied a TABLE BUILDER when the user typed /prop.
  assert.notEqual(vis[0].id, 'prop', 'precondition: the exact command is not first in pool order');
  assert.equal(vis[c.builderBestIdx(vis, 'prop', '/')].id, 'prop', 'Enter fires Property');
  // Same with a value attached, and for a second verb.
  const visArg = c.builderFilterCmds(pool, 'prop:owner=Priya', '/');
  assert.equal(visArg[c.builderBestIdx(visArg, 'prop:owner=Priya', '/')].id, 'prop');
  const visDue = c.builderFilterCmds(pool, 'due:tomorrow', '/');
  assert.equal(visDue[c.builderBestIdx(visDue, 'due:tomorrow', '/')].id, 'due');
  // A hidden `keys` synonym still wins over an unrelated description hit.
  const visDate = c.builderFilterCmds(pool, 'deadline', '/');
  assert.equal(visDate[c.builderBestIdx(visDate, 'deadline', '/')].id, 'due', 'a keys synonym resolves');
  // No query → the first row, unchanged.
  assert.equal(c.builderBestIdx(pool, '', '/'), 0);
});

// ── #1474: the builder's zero-result state ──────────────────────────────────
// Typing until the list emptied announced nothing, so the live region kept naming a command that
// was no longer in the list, over an empty list where Enter does nothing (P3/P4). The app already
// had the words: it painted "No commands match your search." and, on Enter, announced a DIFFERENT
// sentence, "No matching commands" — two strings for one state.
test('#1474 the list emptying is announced, once, in the words already on screen', () => {
  const sync = between(_src, '  function syncActive() {', '  function applyBuilder() {');
  // the branch that was missing: a list with no selectable command says so
  assert.match(sync, /\} else if \(!_builderWasEmpty\) \{/, 'the empty list has a branch of its own');
  assert.match(sync, /announce\(builderEmptyMessage\(\)\);/, 'and it speaks');
  // ...on the TRANSITION only. announce() clears and re-sets to force a re-read, so an
  // unconditional call would stutter the same sentence on every further keystroke.
  assert.match(sync, /_builderWasEmpty = true;/);
  assert.match(sync, /_builderWasEmpty = false;/, 'and re-arms as soon as something matches again');
  assert.ok(sync.indexOf('_builderWasEmpty = false') < sync.indexOf('_builderWasEmpty = true'),
    'the re-arm sits on the has-a-command branch, not after the announce');
  // per-session, so re-opening the builder onto an empty list is news again
  assert.match(_src, /let _builderWasEmpty = false;/);

  // ONE sentence for one state, read off the rendered node so it cannot drift from the screen
  // (the announceOverlayCount precedent). The old Enter-time string is gone.
  assert.match(fnBody(_src, 'builderEmptyMessage'), /nav\.querySelector\('\.builder-no-results'\)\?\.textContent/);
  assert.equal((_src.match(/No commands match your search\./g) || []).length, 2,
    'the sentence is spelled once in the markup and once as the fallback, nowhere else');
  assert.equal((_src.match(/'No matching commands'/g) || []).length, 0,
    'the second, different sentence for the same state is gone');
  // and Enter at zero uses the same reader rather than its own copy
  assert.match(_src, /if \(visibleCmds\(\)\.length\) applyBuilder\(\);\s*\n\s*else announce\(builderEmptyMessage\(\)\);/);
});

// ── #1472: typing a command's whole NAME selects that command ────────────────
// `Variable` selected `Variables panel` — a side-panel toggle whose id happens to start with the
// word — while the command actually named Variable sat third, so Enter opened a panel and left the
// point alone. The ranking put an id PREFIX above an exact label.
test('#1472 an exact label beats a prefix of someone else\'s id', () => {
  const pool = c.builderCmdPool('/');
  const pick = (q) => { const vis = c.builderFilterCmds(pool, q, '/'); return vis[c.builderBestIdx(vis, q, '/')]; };
  // the report, in both cases the user can type it
  assert.equal(pick('Variable').id, 'var', 'the command named Variable, not the panel named variables');
  assert.equal(pick('variable').id, 'var');
  // the precondition, so this cannot pass for the wrong reason: the loser is still IN the list and
  // still earlier in pool order, which is exactly why first-in-list would get it wrong
  const vis = Array.from(c.builderFilterCmds(pool, 'Variable', '/'));
  const ids = vis.map(x => x.id);
  assert.ok(ids.includes('variables'), 'precondition: Variables panel still matches the query');
  assert.ok(ids.indexOf('variables') < ids.indexOf('var'), 'precondition: and still sorts ahead of it');
  // an exact id still outranks an exact label, which is the tie-break for /todo vs a #TODO state row
  assert.equal(pick('todo').id, 'todo');
  assert.equal(pick('TODO').id, 'todo', 'exact id wins the one collision the pool actually has');
  // and every rank below the change is untouched: id prefix, then a hidden keys synonym, then label
  assert.equal(pick('prop').id, 'prop', 'exact id');
  assert.equal(pick('deadline').id, 'due', 'a keys synonym still resolves');
  // an id prefix still resolves to an id-prefix match (two commands share `quer`, and which of
  // them wins is pool order, untouched by this change — the point is that it is not a desc hit)
  assert.ok(pick('quer').id.startsWith('quer'), 'an id prefix still resolves');
});

// The ratchet. Enumerated from the pool rather than a hand list, so a command added later whose id
// prefixes another command's label fails HERE instead of being reported by a user.
test('#1472 census: every command in every pool is selected by its own name', () => {
  const wrong = [], byExactId = [];
  let checked = 0;
  for (const trig of nonEmpty(['/', '@', '{'], 'builder triggers')) {
    const pool = Array.from(c.builderCmdPool(trig));
    for (const cmd of nonEmpty(pool, `the ${trig} command pool`)) {
      const label = String(cmd.label || '');
      if (!label) continue;
      checked++;
      const vis = Array.from(c.builderFilterCmds(pool, label, trig));
      const got = vis[c.builderBestIdx(vis, label, trig)];
      if (!got) { wrong.push(`${trig} ${label}: nothing selected`); continue; }
      if (got.id === cmd.id) continue;
      // Two pool entries legitimately share a label (a brace form `math` beside the insert command
      // `Math`); either is the right answer, so compare by IDENTITY, not by the string typed.
      if (String(got.label || '').toLowerCase() === label.toLowerCase()) continue;
      // The one sanctioned loss: this label is exactly ANOTHER command's id, and an exact id is the
      // stronger signal. Collected rather than waved through, so the exemption is proven to fire.
      if (String(got.id || '').toLowerCase() === label.toLowerCase()) { byExactId.push(`${trig} ${label} → ${got.id}`); continue; }
      wrong.push(`${trig} ${JSON.stringify(label)} (id=${cmd.id}) selected ${JSON.stringify(got.label)} (id=${got.id})`);
    }
  }
  assert.ok(checked > 200, `the census must cover the real pools, covered ${checked}`);
  assert.deepEqual(wrong, [], 'a command that its own name does not select is the #1472 defect');
  // Measure the negative case too: the exemption is real, and it is ONLY the #TODO state row.
  assert.ok(byExactId.length > 0, 'the exact-id exemption must actually fire, or it is dead code in the test');
  assert.deepEqual([...new Set(byExactId.map(s => s.split(' ')[1]))], ['TODO'],
    'exactly one label in the pool is another command id, and it is the one measured');
});

test('#1106: the guided builder delegates every / command to slashApply, ungated', () => {
  // The delegation existed but was gated on `slashState`, which checkSlash's guided fork always
  // nulls (hideSlashMenu) before opening the builder — so from the DEFAULT tier it never ran and
  // /verb:value fell through to applyBlockCmd, which has no arg concept and ends `node.type = id`.
  assert.ok(_src.includes("if (cmd.trigger === '/') {"), 'the / delegation is ungated');
  assert.ok(!_src.includes("if (cmd.trigger === '/' && slashState) {"), 'the slashState gate is gone');
  // It must run BEFORE the shared strip, because slashApply strips its own text.
  const del = _src.indexOf("if (cmd.trigger === '/') {\n      // stripLen is the NODE-text query length");
  const strip = _src.indexOf('// Strip the trigger text from the node (non-dialog commands)');
  assert.ok(del > 0 && strip > 0 && del < strip, 'delegation precedes the strip (no double-strip)');
  // stripLen decouples how much text to remove from what the query says.
  // REWRITTEN for #1396, not loosened. The strip now runs against node.text at the FOLDED offset,
  // because the builder has taken focus by then and the row refolded: editableText returned the
  // pill's rendered glyphs and slashOffset indexed a string that no longer existed. stripLen's
  // decoupling -- what this pin is about -- is unchanged.
  assert.ok(_src.includes('stripTriggerRun(currentText, spliceAt, stripLen ?? query.length'),
    'slashApply honours an explicit stripLen');
  assert.ok(_src.includes('const spliceAt = node ? builderSpliceOffset(node, slashOffset) : slashOffset;'),
    'and takes its offset through the folded translator');
  // The search box feeds its own fields; builderState.query stays the NODE-text query, because it
  // drives the strip math — overwriting it would eat the arg's length out of the user's sentence.
  assert.ok(_src.includes('builderState.argQuery = psq.query'), 'the typed value rides in argQuery');
  assert.ok(!_src.includes('builderState.query = psq.query'), 'node-text query is not overwritten');
  // A colon after a NON-opted-in verb is plain text (§3: /quote:x → quote, `:x` stays). In Standard
  // that is free (the tail is in the node); typed into the builder's search box it has to be
  // carried back, or the same keystrokes mean different things per tier.
  assert.ok(_src.includes("builderState.argTail = (!psq.hasArg && colon >= 0) ? filterQ.slice(colon) : ''"),
    'a non-arg colon tail is preserved');
  assert.ok(_src.includes("tailInsert: st.argTail || ''"), 'the tail reaches slashApply');
  assert.ok(_src.includes("stripTriggerRun(currentText, spliceAt, stripLen ?? query.length, tailInsert || '')"),
    'the tail is re-inserted at the trigger position (#1396: in FOLDED coordinates)');
});

test('#1396 a builder apply splices node.text at the FOLDED offset, never the DOM', () => {
  // The builder TAKES FOCUS, so the row it was opened from has already left edit mode and refolded
  // by the time a command applies. Two faults compounded there:
  //   editableText(content) -> the pill's RENDERED glyphs (display HTML carries no data-token)
  //   st.offset             -> measured in the UNFOLDED edit-mode space
  // so the splice cut a different string at a meaningless index and wrote the glyphs back as text.
  // Driven: `Damage [[dice:k]]` + a typed `/todo` became `- [ ] Damage 2d641=`, record pruned.
  //
  // CORRECTS THE ISSUE: it is not mid-line-specific. The same thing happened with the trigger at
  // the START of the point, and ONLY through this door -- the bullet menu applying the same command
  // kept the pill. So the offset guard (#1108) is not the cause; the text space is.
  assert.ok(/function builderSpliceText\(node\) \{ return node\.text; \}/.test(_src),
    'the splice reads the model, not the DOM');
  assert.ok(/function builderSpliceOffset\(node, offset\) \{ return foldedOffsetFor\(node, offset\); \}/.test(_src),
    'and translates the offset with the file\'s existing translator');
  // ONE rule for both states: foldedOffsetFor is the identity while the node is still unfolded
  // (no [[type:key]] tokens to walk), so no caller has to branch on whether the row still edits.
  const fo = fnBody(_src, 'foldedOffsetFor');
  assert.ok(/const RE = \/\\\[\\\[\(dice\|math\|var\|grammar\|est\|markov\|seq\|query\)/.test(fo),
    'it walks folded tokens, of which an unfolded node has none');
  // EVERY builder apply path, and the inline one they delegate to. A door left on editableText
  // would keep destroying pills on that door alone, which is exactly how this shipped.
  for (const fn of ['builderFormApply', 'showNestedDialog', 'slashApply'])
    assert.ok(/builderSplice(Text|Offset)\(/.test(fnBody(_src, fn)),
      fn + ' must splice through the shared reader');
  // and no builder apply may go back to reading the DOM
  assert.ok(!/stripTriggerRun\(editableText\(/.test(NC),
    'no strip may take its text straight from the DOM');
  assert.equal((NC.match(/editableText\(st\.content\)/g) || []).length, 0,
    'and no builder site reads the row\'s DOM for its splice text');
});

test('builderGuideEntry — null/unknown guard; a covered command resolves to its GUIDE entry', () => {
  // the null-cmd guard (a shipped bug, added in the remediation batch) and the unknown-id path.
  assert.equal(c.builderGuideEntry(null), null);
  assert.equal(c.builderGuideEntry({ id: '__no_such_command__' }), null);
  // at least one real pool command maps to a GUIDE entry via the `covers` lookup, and when it
  // does the entry genuinely covers that command id (the wiring, not just a truthy result).
  const pool = c.builderCmdPool('/');
  const covered = pool.find(cmd => c.builderGuideEntry(cmd));
  assert.ok(covered, 'some builder command is covered by a GUIDE entry');
  const entry = c.builderGuideEntry(covered);
  assert.ok(entry.covers.includes(covered.id) || (covered._brace && covered._brace.guide === entry.id),
    'the resolved entry actually covers the command');
});

test('builder DOM wiring — source-pins for the dispatch, the guards, and the shared strip', () => {
  // Guided still routes / and @ into the builder.
  assert.ok(_src.includes("if (isGuided()) { hideSlashMenu(); builderState = { nodeId, content, trigger, offset: slashOffset, query, rawArg }; openBuilder(trigger); return; }"),
    'checkSlash dispatches to openBuilder in Guided mode');
  // `{` NO LONGER does. The builder takes focus, so the point left edit mode and every keystroke
  // after the brace was eaten — typing {2d6}, the app's own placeholder example, left "{" alone on
  // a blank point and mid-line alike. Guided now gets the same inline menu as Standard, and reaches
  // the picker through the explicit Browse row. This assertion is inverted deliberately: it must
  // stay ZERO, or the keystroke-eating bug is back.
  assert.equal((_src.match(/if \(isGuided\(\)\) \{ hideBraceMenu\(\); builderState = /g) || []).length, 0,
    'checkBraceTrigger must NOT hand `{` to the focus-stealing builder in any brace mode');
  // openBuilder re-entrancy guard (an input event while the builder is open must not rebuild it).
  assert.ok(_src.includes("if (ioCard.classList.contains('builder-open')) return;"),
    'openBuilder has the re-entrancy guard');
  // UXP-177: closeIo() delegates to closeBuilderWindow so builder state never leaks across sessions.
  assert.ok(_src.includes("if (ioCard.classList.contains('builder-open')) { closeBuilderWindow(); return; }"),
    'closeIo delegates to closeBuilderWindow (UXP-177)');
  // the strip math is centralized: the old inline `currentText.slice(0, st.offset)` pattern is gone.
  assert.ok(!_src.includes('currentText.slice(0, st.offset)'),
    'no builder site re-implements the trigger strip inline — all route through stripTriggerRun');
});

// The default tier made the app's own headline syntax untypeable. `{` handed the point to the
// full-screen picker, which takes focus, so the point left edit mode and every keystroke after the
// brace was eaten: `{2d6}` left `"{"` on a blank point AND mid-line. Four personas hit it
// independently. Standard and Lean were always fine, so it was invisible to anyone past onboarding.
test('Guided types pills inline; the picker is a door, not an ambush', () => {
  // The inline menu is now the path for every tier. Lean keeps its own one-liner, reached in BOTH
  // brace modes (forms + body), so narrowing the guided branch cannot have swallowed it.
  assert.equal((_src.match(/if \(isLean\(\)\) \{ renderLeanBraceTip\(\); return; \}/g) || []).length, 2,
    'both brace modes still reach the Lean tip');
  assert.ok(_src.includes('renderBraceMenu()'), 'and every other tier reaches the inline menu');
  // The Browse row is the replacement door: offered only on a bare `{`, appended at the call site so
  // filterBraceForms stays a straight map over BRACE_FORMS (its own tests pin exactly that).
  assert.ok(/if \(!prefix\) matches\.push\(BRACE_BROWSE_ROW\);/.test(_src),
    'a bare { offers the full picker as an explicit last row');
  assert.ok(/const BRACE_BROWSE_ROW = \{ group: 'browse'/.test(_src), 'the row exists');
  assert.ok(/BM_GROUP_LABELS = \{ browse:/.test(_src), 'and renders under its own header');
  // braceApply routes it to the picker instead of inserting text
  const ba = fnBody(_src, 'braceApply');
  assert.ok(/if \(chosen\.group === 'browse'\) \{[\s\S]*openBuilder\('\{'\);[\s\S]*return;/.test(ba),
    'choosing Browse opens the picker rather than inserting a scaffold');
});

test('dismissing the picker returns the caret where it was, and only once', () => {
  // Escape used to land focus on the point via closeIo's plain ioReturnFocus.focus(), which
  // re-enters edit with the caret at offset 0 — so typing PREPENDED: "Roll {" + Esc + "2d6}" gave
  // "2d6}Roll {". armChromeReturn() already captured the live offset; nothing consumed it.
  const cbw = fnBody(_src, 'closeBuilderWindow');
  assert.ok(/if \(restoreChromeReturn\(\)\) ioReturnFocus = null;/.test(cbw),
    'the chrome-return restores the caret AND suppresses the plain focus');
  assert.ok(cbw.indexOf('restoreChromeReturn()') < cbw.indexOf('closeIo()'),
    'suppression must happen before closeIo reads ioReturnFocus');
  // Why suppression rather than both: closeIo is synchronous, restoreChromeReturn defers to a rAF,
  // so running both lands the caret at 0 first and corrects it a frame later.
  assert.ok(/requestAnimationFrame/.test(fnBody(_src, 'restoreChromeReturn')), 'restore is deferred to a frame');
  assert.ok(/const ret = ioReturnFocus; ioReturnFocus = null;/.test(fnBody(_src, 'closeIo')), 'closeIo focuses synchronously');
  // The nested-dialog path sets its own caret, so it must disarm rather than be overwritten.
  assert.ok(_src.includes('if (_restoreState) { builderRestoreTrigger(); chromeReturn = null; }'),
    'builderRestoreTrigger owns the caret on its path and disarms the chrome-return');
});

test('builder keyboard + form a11y — roving tabindex, label association, required announce', () => {
  // The keyboard-nav fix: options carry tabindex="-1" so item.focus() in the nav/search
  // handlers actually moves focus (without it the whole Arrow/Home/End handler is dead).
  assert.ok(/class="builder-item'[^;]*tabindex="-1"/.test(_src) || _src.includes('tabindex="-1" data-i="'),
    'builder-item options are programmatically focusable (tabindex=-1)');
  // Form fields: <label for> <-> <input id> association + aria-required on required fields.
  assert.ok(_src.includes("const fid = 'bf-' + f.name;"), 'form fields build a stable id');
  assert.ok(_src.includes('<label class="builder-field-label" for="\' + fid + \'">'),
    'the field label is associated with its input via for=');
  assert.ok(_src.includes("id=\"' + fid + '\"") && _src.includes("f.required ? ' aria-required=\"true\" required'"),
    'required fields carry aria-required + required');
  // P4: an empty required submit announces the reason, never a silent refocus.
  assert.ok(_src.includes("announce(f.label + ' is required')"), 'required-empty submit announces');
  // placeholder uses escAttr (attribute-safe), matching the codebase convention.
  assert.ok(_src.includes("placeholder=\"' + escAttr(f.placeholder || f.label)"),
    'placeholder attribute is escaped with escAttr');
});

test('builder front door (UXP-178) — launcher wiring + all-commands pool', () => {
  // launchBuilder exists, is the toolbar button's handler, and re-targets the caret at end
  // (the caret-at-end trick that makes the existing strip a no-op — no synthetic flag needed).
  assert.ok(_src.includes('function launchBuilder()'), 'launchBuilder defined');
  assert.ok(_src.includes("getElementById('btn-builder').addEventListener('click', launchBuilder)"),
    'toolbar button opens the builder');
  assert.ok(/const end = editableText\(el\)\.length;[\s\S]{0,120}offset: end, query: ''/.test(_src),
    'launchBuilder sets the caret at end-of-point and query to empty (no trigger to strip)');
  // openBuilder(null) → the "All commands" title; builderCmdPool(null) leads with point cmds.
  assert.ok(_src.includes("trigger === '{' ? 'Pill picker' : 'All commands'"),
    'openBuilder titles the no-trigger launch "All commands"');
  const pool = c.builderCmdPool(null);
  assert.ok(pool.length > 0, 'builderCmdPool(null) returns the full pool');
  const trigs = new Set(pool.map(cmd => cmd.trigger));
  assert.ok(trigs.has('/') && trigs.has('@') && trigs.has('{'), 'all three trigger families present');
  // #1202 (was: `/` commands lead): the front door now OPENS ON THE ENGINE. The one "everything" door
  // used to open on twelve formatting rows with dice/math/oracle below the fold, presenting the app as
  // a text formatter (product-identity §1/§8b: the {…} engine IS the product). Lead with the
  // generative + computational sections, the same thesis the @ menu opens on (#915).
  // #1267: the front door now LEADS WITH PATTERNS — the ready-made {…} recipe lines a person lifts
  // instead of authoring syntax cold. This still honours #1202 (engine first, not formatting): a
  // pattern IS the engine, pre-assembled, and Generate/Compute/Trackers follow immediately.
  assert.equal(pool[0]._section, 'Patterns', '#1267: the front door leads with ready-made Patterns');
  const frontSecs = [...new Set(pool.map(c => c._section))];
  assert.deepEqual(frontSecs.slice(0, 4), ['Patterns', 'Generate', 'Compute', 'Trackers'], '#1267/#1202: patterns then the engine sections lead the front door');
  assert.ok(frontSecs.indexOf('Generate') < frontSecs.indexOf('Lists'), 'the engine is above the block/formatting sections');
  // block types are NOT demoted — still present, one short scroll down, and still resolve by search
  assert.ok(pool.some(c => c.id === 'h2') && pool.some(c => c.id === 'ul'), 'block types stay in the pool (reachable, not removed)');
  // Door B: /builder verb — a BLOCK_CMDS action entry (no `turn`) + a slashApply branch that
  // launches and returns before the applyBlockCmd fallthrough (writes nothing).
  assert.ok(/id:'builder',[^}]*label:'All commands'/.test(_src), 'BLOCK_CMDS has a builder entry');
  // The command surface names one thing consistently (was a 3-way split: button "Command browser",
  // window aria "Command builder", header "Commands"). All three now say "All commands".
  assert.ok(/id="btn-builder"[^>]*aria-label="All commands"/.test(_src), 'the toolbar button says All commands');
  assert.ok(_src.includes("ioCard.setAttribute('aria-label', 'All commands')"), 'the builder window aria says All commands');
  assert.ok(/title:'All commands'/.test(_src), 'the concept-guide entry title says All commands');
  assert.ok(!_src.includes('Command browser') && !_src.includes('Command builder'), 'no stray Command browser/builder name remains');
  assert.ok(!/id:'builder',[^}]*turn:true/.test(_src), "the builder verb is an action, not a type-transform (no turn)");
  assert.ok(/cmd\.id === 'builder'\) \{\s*launchBuilder\(\);\s*return;/.test(_src),
    'slashApply routes /builder to launchBuilder');
  // Door C: concept-guide entry (covers the verb id) + right-click map.
  assert.ok(/id:'builder', cat:'getting-around'[\s\S]{0,1500}covers:\['builder'\]/.test(_src),
    'GUIDE has a builder entry covering the verb id');
  assert.ok(_src.includes("'btn-builder': 'builder'"), 'right-click the button opens its guide');
  // Door D: Ctrl/Cmd+K + its shortcuts-page row.
  assert.ok(/ctrl && \(e\.key==='k' \|\| e\.key==='K'\)[\s\S]{0,90}launchBuilder\(\)/.test(_src),
    'Ctrl/Cmd+K launches the builder');
  assert.ok(/essSection:'Insert', keys:\[`\$\{MOD\}\+K`\]/.test(_src), 'the shortcut is on the shortcuts page');
});

